function fmtNum(v){
  if(v==null||isNaN(v)) return '—';
  if(v>=1000000) return 'R$'+(v/1000000).toFixed(1)+'M';
  if(v>=1000) return 'R$'+(v/1000).toFixed(0)+'K';
  return 'R$'+Math.round(v).toLocaleString('pt-BR');
}
function fmtFull(v){return 'R$ '+Math.round(v).toLocaleString('pt-BR');}
function fmtVol(v){return v?v.toLocaleString('pt-BR')+' un':'—';}

function getIntocavel(nome){
  if(!nome) return null;
  var n=nome.toUpperCase();
  if(n.includes('OFF')&&n.includes('KIDS')) return 'kids200';
  var isOFF=n.includes('OFF');
  var hasLocao=n.includes('LOCAO')||n.includes('LOÇÃO')||n.includes('LOC');
  var has200=n.includes('200');
  var hasSpray=n.includes('SPRAY')||n.includes('AERO')||n.includes('170')||n.includes('165');
  if(isOFF&&hasLocao&&has200&&!n.includes('KIDS')) return 'locao200';
  if(isOFF&&hasSpray&&!n.includes('KIDS')&&!(hasLocao&&has200)) return 'spray170';
  return null;
}

/* ===== COMPONENTES ===== */
/* renderRankBars — ranking de produto com Un. e R$ sempre visíveis */
function renderRankBars(containerId, rows, sortBy){
  // rows: [nome, vol, rec, color]  ou  [nome, vol, color] (sem rec)
  var el=document.getElementById(containerId);
  if(!el) return;
  var hasRec = rows[0] && rows[0].length >= 4;
  var sorted=rows.slice().sort(function(a,b){
    return sortBy==='vol' ? b[1]-a[1] : (hasRec ? b[2]-a[2] : b[1]-a[1]);
  });
  var maxVal=sorted[0]? (sortBy==='vol'?sorted[0][1]:(hasRec?sorted[0][2]:sorted[0][1])) :1;
  var medals=['🥇','🥈','🥉'];
  var html='';
  sorted.forEach(function(r,i){
    var nome=r[0], vol=r[1], rec=hasRec?r[2]:null, color=hasRec?r[3]:r[2];
    var barVal=sortBy==='vol'?vol:(hasRec?rec:vol);
    var pct=maxVal>0?Math.round((barVal/maxVal)*100):0;
    var intoc=getIntocavel(nome);
    var rowStyle=intoc?'background:rgba(251,191,36,0.04);border-left:2px solid rgba(251,191,36,0.3);':'';
    var intocBadge=intoc?'<span class="intoc-badge" style="margin-left:4px;">🏆</span>':'';
    var rankBadge=i<3?medals[i]:(i+1);
    html+='<div class="bar-item" style="'+rowStyle+'">';
    html+='<div class="bar-item-header">';
    html+='<span class="bar-rank" style="background:'+color+'22;color:'+color+';">'+rankBadge+'</span>';
    html+='<span class="bar-name">'+nome+intocBadge+'</span>';
    // Sempre mostrar Un. e R$ lado a lado
    if(hasRec){
      html+='<span style="font-size:10px;color:#94A3B8;margin-right:4px;">'+vol.toLocaleString('pt-BR')+' un</span>';
      html+='<span class="bar-val" style="color:'+color+'">R$'+Math.round(rec/1000)+'K</span>';
    } else {
      html+='<span class="bar-val" style="color:'+color+'">'+vol.toLocaleString('pt-BR')+' un</span>';
    }
    html+='</div>';
    html+='<div class="bar-track"><div class="bar-fill" style="width:0%;background:'+color+';box-shadow:0 0 6px '+color+'55;" data-pct="'+pct+'"></div></div>';
    html+='</div>';
  });
  el.innerHTML=html;
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width=bar.getAttribute('data-pct')+'%';
    });
  },80);
}

/* renderBarsVol — igual renderBars mas mostra valores como unidades (sem R$) */
function renderBarsVol(containerId, items){
  var el=document.getElementById(containerId);
  if(!el) return;
  var maxVal=Math.max.apply(null,items.map(function(x){return x.val||0;}));
  var medals=['🥇','🥈','🥉'];
  var html='';
  items.forEach(function(item,i){
    var pct=maxVal>0?Math.round((item.val/maxVal)*100):0;
    var color=item.color||LOJA_COLORS[i]||'#3b82f6';
    var rankBadge=i<3?medals[i]:(i+1);
    var expandHtml='';
    if(item.extraFields&&item.extraFields.length){
      expandHtml='<div class="bar-expand">';
      item.extraFields.forEach(function(f){
        expandHtml+='<div class="expand-item">'+f.label+'<span class="expand-val" style="color:'+color+'">'+f.val+'</span></div>';
      });
      expandHtml+='</div>';
    }
    html+='<div class="bar-item" onclick="this.classList.toggle(\'selected\')">';
    html+='<div class="bar-item-header">';
    html+='<span class="bar-rank" style="background:'+color+'22;color:'+color+';">'+rankBadge+'</span>';
    html+='<span class="bar-name">'+item.nome+'</span>';
    html+='<span class="bar-val" style="color:'+color+'">'+item.val.toLocaleString('pt-BR')+' un</span>';
    html+='</div>';
    html+='<div class="bar-track"><div class="bar-fill" style="width:0%;background:'+color+';box-shadow:0 0 6px '+color+'55;" data-pct="'+pct+'"></div></div>';
    html+=expandHtml+'</div>';
  });
  el.innerHTML=html;
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width=bar.getAttribute('data-pct')+'%';
    });
  },80);
}

function renderBars(containerId, items, opts){
  var el = document.getElementById(containerId);
  if(!el) return;
  var maxVal = opts.maxVal || Math.max.apply(null, items.map(function(x){return x.val||0;}));
  var globalIsVol = opts.isVol || false;
  var isHBar = opts.hbar || false;
  var medals = ['🥇','🥈','🥉'];
  var html = '';

  if(isHBar){
    items.forEach(function(item, i){
      var pct = maxVal>0 ? Math.round((item.val/maxVal)*100) : 0;
      var color = item.color || LOJA_COLORS[i] || '#3b82f6';
      var isVol = item.isVol !== undefined ? item.isVol : globalIsVol;
      var dispVal = isVol ? item.val.toLocaleString('pt-BR')+' un' : fmtNum(item.val);
      html += '<div class="hbar-row">';
      html += '<span class="hbar-label">'+item.nome+'</span>';
      html += '<div class="hbar-outer"><div class="hbar-inner" style="width:0%;background:'+color+'44;border-left:4px solid '+color+';color:'+color+';text-shadow:0 0 8px '+color+'88;" data-pct="'+pct+'">'+dispVal+'</div></div>';
      html += '</div>';
    });
    el.innerHTML = html;
    setTimeout(function(){
      el.querySelectorAll('.hbar-inner').forEach(function(bar){
        bar.style.width = bar.getAttribute('data-pct') + '%';
      });
    }, 80);
    return;
  }

  items.forEach(function(item, i){
    var pct = maxVal>0 ? Math.round((item.val/maxVal)*100) : 0;
    var color = item.color || LOJA_COLORS[i] || '#3b82f6';
    var intoc = item.intoc || getIntocavel(item.nome);
    var isVol = item.isVol !== undefined ? item.isVol : globalIsVol;
    var rowStyle = intoc ? 'background:rgba(251,191,36,0.04);border-left:2px solid rgba(251,191,36,0.3);' : '';
    var intocBadge = intoc ? '<span class="intoc-badge">🏆 '+(intoc==='locao200'?'Loção 200':intoc==='spray170'?'Spray 170':'Kids 200')+'</span>' : '';
    var ufBadge = item.uf ? '<span class="uf-badge" style="background:'+((UF_COLORS[item.uf]||'#888')+'22')+';color:'+(UF_COLORS[item.uf]||'#888')+';">'+item.uf+'</span>' : '';
    var shareBadge = item.share ? '<span style="font-size:9px;font-weight:700;padding:1px 5px;border-radius:3px;background:'+color+'18;color:'+color+';">'+item.share+'%</span>' : '';
    var rankBadge = i<3 ? medals[i] : (i+1);
    var dispVal = isVol ? item.val.toLocaleString('pt-BR')+' un' : fmtNum(item.val);
    var expandHtml = '';
    if(item.extraFields && item.extraFields.length){
      expandHtml = '<div class="bar-expand">';
      item.extraFields.forEach(function(f){
        expandHtml += '<div class="expand-item">'+f.label+'<span class="expand-val" style="color:'+color+'">'+f.val+'</span></div>';
      });
      expandHtml += '</div>';
    }
    html += '<div class="bar-item" style="'+rowStyle+'" onclick="this.classList.toggle(\'selected\')">';
    html += '<div class="bar-item-header">';
    html += '<span class="bar-rank" style="background:'+color+'22;color:'+color+';">'+rankBadge+'</span>';
    html += '<span class="bar-name">'+item.nome+intocBadge+'</span>';
    html += ufBadge + shareBadge;
    html += '<span class="bar-val" style="color:'+color+'">'+dispVal+'</span>';
    html += '</div>';
    html += '<div class="bar-track"><div class="bar-fill" style="width:0%;background:'+color+';box-shadow:0 0 6px '+color+'55;" data-pct="'+pct+'"></div></div>';
    html += expandHtml;
    html += '</div>';
  });
  el.innerHTML = html;
  el.querySelectorAll('button[data-key]').forEach(function(b){
    b.addEventListener('click',function(){
      var k2=this.getAttribute('data-key');
      var f2=this.getAttribute('data-fn');
      if(f2==='setGAMDNIntocSku') setGAMDNIntocSku(k2,this);
      else setGCHDNIntocSku(k2,this);
    });
  });
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width = bar.getAttribute('data-pct') + '%';
    });
  }, 80);
}

function renderDonut(svgId, legendId, items){
  var svg = document.getElementById(svgId);
  var legEl = document.getElementById(legendId);
  if(!svg) return;
  var total = items.reduce(function(s,x){return s+x.val;},0);
  var cx=100,cy=100,R=88,r=62,gap=0.025;
  var circ=2*Math.PI*R;

  function arcPath(sa,ea,or_,ir_){
    var x1=cx+or_*Math.cos(sa),y1=cy+or_*Math.sin(sa);
    var x2=cx+or_*Math.cos(ea),y2=cy+or_*Math.sin(ea);
    var x3=cx+ir_*Math.cos(ea),y3=cy+ir_*Math.sin(ea);
    var x4=cx+ir_*Math.cos(sa),y4=cy+ir_*Math.sin(sa);
    var lg=ea-sa>Math.PI?1:0;
    return 'M'+x1+','+y1+' A'+or_+','+or_+',0,'+lg+',1,'+x2+','+y2+' L'+x3+','+y3+' A'+ir_+','+ir_+',0,'+lg+',0,'+x4+','+y4+' Z';
  }

  function fmtV(v){return v!=null?v.toLocaleString('pt-BR'):'-';}
  function fmtR(v){return 'R$'+(v/1000).toFixed(0)+'K';}

  var startAngle = -Math.PI/2;
  var arcs = items.map(function(item){
    var frac=item.val/total;
    var sweep=frac*2*Math.PI-gap;
    var ea=startAngle+sweep;
    var arc={item:item,sa:startAngle,ea:ea,frac:frac};
    startAngle+=frac*2*Math.PI;
    return arc;
  });

  // Centro label
  var cvEl=document.getElementById(svgId+'-cv');
  var csEl=document.getElementById(svgId+'-cs');
  var tipEl=document.getElementById(svgId+'-tip');
  if(cvEl){cvEl.textContent=total.toLocaleString('pt-BR');}
  if(csEl){csEl.textContent='total';}

  svg.innerHTML='';

  arcs.forEach(function(arc,i){
    var isIntoc=getIntocavel(arc.item.nome);
    var outerR=R,innerR=r;
    var pathEl=document.createElementNS('http://www.w3.org/2000/svg','path');
    pathEl.setAttribute('d',arcPath(arc.sa,arc.ea,outerR,innerR));
    pathEl.setAttribute('fill',arc.item.color);
    pathEl.setAttribute('opacity','0.85');
    pathEl.style.cursor='pointer';
    pathEl.style.transition='transform 0.2s cubic-bezier(.4,0,.2,1),opacity 0.2s';
    pathEl.style.transformOrigin=cx+'px '+cy+'px';

    if(isIntoc){
      var glow=document.createElementNS('http://www.w3.org/2000/svg','path');
      glow.setAttribute('d',arcPath(arc.sa,arc.ea,outerR+3,innerR-3));
      glow.setAttribute('fill','none');
      glow.setAttribute('stroke','#fbbf24');
      glow.setAttribute('stroke-width','1.5');
      glow.setAttribute('opacity','0.4');
      svg.appendChild(glow);
    }

    pathEl.addEventListener('mouseenter',function(){
      this.style.transform='scale(1.06)';
      this.setAttribute('opacity','1');
      if(cvEl){cvEl.textContent=fmtV(arc.item.val);}
      if(csEl){csEl.textContent=arc.item.nome;}
      if(tipEl){
        tipEl.style.opacity='1';
        document.getElementById(svgId+'-tn').textContent=arc.item.nome;
        document.getElementById(svgId+'-tv').textContent=fmtV(arc.item.val)+' un';
        var recEl=document.getElementById(svgId+'-tr');
        if(recEl) recEl.textContent=arc.item.rec?fmtR(arc.item.rec):'-';
        document.getElementById(svgId+'-ts').textContent=(arc.frac*100).toFixed(1)+'%';
        tipEl.style.top=(cy+R+8)+'px';
        tipEl.style.left='50%';
        tipEl.style.transform='translateX(-50%)';
      }
      if(legEl){legEl.querySelectorAll('.dl-item2').forEach(function(el,j){el.classList.toggle('dli-active',j===i);});}
    });
    pathEl.addEventListener('mouseleave',function(){
      this.style.transform='scale(1)';
      this.setAttribute('opacity','0.85');
      if(cvEl){cvEl.textContent=total.toLocaleString('pt-BR');}
      if(csEl){csEl.textContent='total';}
      if(tipEl){tipEl.style.opacity='0';}
      if(legEl){legEl.querySelectorAll('.dl-item2').forEach(function(el){el.classList.remove('dli-active');});}
    });
    svg.appendChild(pathEl);
  });

  // Legend
  if(legEl){
    legEl.innerHTML='';
    arcs.forEach(function(arc,i){
      var pct=(arc.frac*100).toFixed(1);
      var isIntoc=getIntocavel(arc.item.nome);
      var badge=isIntoc?'<span style="margin-left:4px;font-size:10px;">🏆</span>':'';
      var recStr=arc.item.rec?(' &middot; R$'+(arc.item.rec/1000).toFixed(0)+'K'):'';
      var el=document.createElement('div');
      el.className='dl-item2';
      el.innerHTML='<div class="dl-color" style="background:'+arc.item.color+'"></div>'
        +'<div class="dl-right">'
        +'<div class="dl-name">'+arc.item.nome+badge+'</div>'
        +'<div class="dl-detail">'
        +'<span class="dl-vol">'+fmtV(arc.item.val)+' un'+recStr+'</span>'
        +'<span class="dl-pct" style="color:'+arc.item.color+'">'+pct+'%</span>'
        +'</div>'
        +'<div class="dl-bar-wrap"><div class="dl-bar-fill" style="background:'+arc.item.color+';" id="dlb-'+svgId+'-'+i+'"></div></div>'
        +'</div>';
      el.addEventListener('mouseenter',function(){
        if(cvEl){cvEl.textContent=fmtV(arc.item.val);}
        if(csEl){csEl.textContent=arc.item.nome;}
        legEl.querySelectorAll('.dl-item2').forEach(function(e,j){e.classList.toggle('dli-active',j===i);});
      });
      el.addEventListener('mouseleave',function(){
        if(cvEl){cvEl.textContent=total.toLocaleString('pt-BR');}
        if(csEl){csEl.textContent='total';}
        legEl.querySelectorAll('.dl-item2').forEach(function(e){e.classList.remove('dli-active');});
      });
      legEl.appendChild(el);
      setTimeout(function(){
        var b=document.getElementById('dlb-'+svgId+'-'+i);
        if(b) b.style.width=pct+'%';
      },100+i*80);
    });
  }
}

function renderLineChart(canvasId, datasets, legendId, isVol){
  var ctx = document.getElementById(canvasId);
  if(!ctx) return;
  var existing = Chart.getChart(ctx);

  var yFmt = isVol
    ? function(v){ return v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':v; }
    : function(v){ return v>=1e6?'R$'+(v/1e6).toFixed(1)+'M':v>=1e3?'R$'+(v/1e3).toFixed(0)+'K':v; };
  var ttFmt = isVol
    ? function(v){ return v!=null?v.toLocaleString('pt-BR')+' un':null; }
    : function(v){ return v!=null?fmtNum(v):null; };

  var GC  = 'rgba(148,163,184,0.12)';
  var TC  = '#475569';
  /* ── Year palette ─────────────────────────────────────────── */
  var COLORS = {'2024':'#3b82f6','2025':'#2dd4bf','2026':'#34d399','2026*':'#34d399'};
  var ALPHAS = {'2024':[0.50,0.03],'2025':[0.38,0.02],'2026':[0.05,0.0],'2026*':[0.05,0.0]};
  var WIDTHS = {'2024':2,'2025':2.5,'2026':2.5,'2026*':2.5};

  /* ── Build datasets using makeAreaGradient (lazy, called at render) ─── */
  var builtDatasets = datasets.map(function(d, i){
    var is26   = d.label==='2026'||d.label==='2026*';
    var is24   = d.label==='2024';
    var col    = d.color || COLORS[d.label] || ['#3b82f6','#2dd4bf','#34d399'][i] || '#fbbf24';
    var alphas = ALPHAS[d.label] || [0.22, 0.0];
    var isDash = is26;   /* 2026 = dashed prominent line, 2024/2025 = solid with fill */
    return {
      label: d.label,
      data:  d.data,
      borderColor: col,
      /* gradient evaluated on first render via function */
      backgroundColor: (function(capCol, capA0, capA1){
        return function(fCtx){
          var ca = fCtx.chart.chartArea;
          if(!ca) return 'transparent';
          var g = fCtx.chart.ctx.createLinearGradient(0, ca.top, 0, ca.bottom);
          g.addColorStop(0,   hexAlpha(capCol, capA0));
          g.addColorStop(0.6, hexAlpha(capCol, (capA0+capA1)/2));
          g.addColorStop(1,   hexAlpha(capCol, capA1));
          return g;
        };
      })(col, alphas[0], alphas[1]),
      borderWidth:  WIDTHS[d.label] || 2,
      borderDash:   isDash ? [6,4] : [],
      tension:      0.42,
      fill:         true,
      pointRadius: d.data ? d.data.map(function(v){
        if(v==null) return 0;
        var valid = d.data.filter(function(x){return x!=null;});
        var peak  = Math.max.apply(null,valid);
        if(is26) return v===peak ? 8 : 4;
        return v===peak ? 6 : 3;
      }) : 4,
      pointBackgroundColor: col,
      pointBorderColor:     '#0a1210',
      pointBorderWidth:     is26 ? 2.5 : 1.5,
      pointHoverRadius:     8,
      pointHoverBorderWidth:2,
      pointHoverBorderColor:'#0a1210',
      spanGaps: false,
      order:    datasets.length - i,
    };
  });

  /* ── tiny hex+alpha helper ── */
  function hexAlpha(hex,a){
    var rgb=hex.replace('#','');
    var r=parseInt(rgb.slice(0,2),16),g=parseInt(rgb.slice(2,4),16),b=parseInt(rgb.slice(4,6),16);
    return 'rgba('+r+','+g+','+b+','+a+')';
  }

  // ── T8: update-or-create ────────────────────────────────────────────
  if(existing){
    existing.data.datasets = builtDatasets;
    existing.options.scales.y.ticks.callback = function(v){ return yFmt(v); };
    existing.options.plugins.tooltip.callbacks.label = function(c){
      if(c.raw == null) return null;
      return ' '+c.dataset.label+': '+ttFmt(c.raw);
    };
    existing.update('none');
    if(legendId){
      var lgU = document.getElementById(legendId);
      if(lgU) lgU.innerHTML = datasets.map(function(d){
        var col = COLORS[d.label] || '#D1D5DB';
        var is26 = d.label==='2026'||d.label==='2026*';
        return '<span style="display:flex;align-items:center;gap:5px;font-size:10px;font-weight:'+(is26?'700':'500')+';color:'+(is26?col:'#D1D5DB')+';">'
        + '<span style="width:'+(is26?'20':'14')+'px;height:'+(is26?'3':'2')+'px;background:'+col+';display:inline-block;border-radius:2px;'+(d.dashed?'background:repeating-linear-gradient(90deg,'+col+' 0px,'+col+' 4px,transparent 4px,transparent 8px);':'')+'"></span>'
        + d.label + '</span>';
      }).join('');
    }
    return;
  }

  // Fix: garantir dimensoes corretas antes de criar chart
  // (removeAttribute pode causar race com reflow; usar tamanho do container diretamente)
  (function(){
    var wrap = ctx.parentElement;
    var wh   = (wrap && wrap.offsetHeight > 10) ? wrap.offsetHeight : 300;
    var ww   = (wrap && wrap.offsetWidth  > 10) ? wrap.offsetWidth  : (ctx.offsetWidth || 600);
    ctx.width  = ww;
    ctx.height = wh;
  })();
  var chart = new Chart(ctx, {
    type: 'line',
    data: { labels: MESES, datasets: builtDatasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#0a1218',
          titleColor: '#e2e8f0',
          bodyColor: '#D1D5DB',
          borderColor: 'rgba(255,255,255,0.1)',
          borderWidth: 1,
          padding: 12,
          callbacks: {
            title: function(items){ return MESES_FULL[items[0].dataIndex] || items[0].label; },
            label: function(c){
              if(c.raw == null) return null;
              var col = COLORS[c.dataset.label] || '#ffffff';
              return ' ' + c.dataset.label + ': ' + ttFmt(c.raw);
            },
            labelColor: function(c){
              var col = COLORS[c.dataset.label] || '#ffffff';
              return { borderColor: col, backgroundColor: col, borderRadius: 3 };
            }
          }
        }
      },
      scales: {
        x: {
          grid: { color: GC, drawTicks: false },
          ticks: { color: '#5a6478', font: { size: 10 }, maxRotation: 0 },
          border: { display: false }
        },
        y: {
          grid: { color: GC, drawTicks: false },
          ticks: { color: '#5a6478', font: { size: 10 }, callback: function(v){ return yFmt(v); } },
          border: { display: false },
          beginAtZero: false
        }
      }
    }
  });

  // Build custom legend
  if(legendId){
    var lg = document.getElementById(legendId);
    if(lg) lg.innerHTML = datasets.map(function(d){
      var col = COLORS[d.label] || '#D1D5DB';
      var is26 = d.label==='2026'||d.label==='2026*';
      return '<span style="display:flex;align-items:center;gap:5px;font-size:10px;font-weight:'+(is26?'700':'500')+';color:'+(is26?col:'#D1D5DB')+';">'
        + '<span style="width:'+(is26?'20':'14')+'px;height:'+(is26?'3':'2')+'px;background:'+col+';display:inline-block;border-radius:2px;'+(d.dashed?'background:repeating-linear-gradient(90deg,'+col+' 0px,'+col+' 4px,transparent 4px,transparent 8px);':'')+'"></span>'
        + d.label + '</span>';
    }).join('');
  }
}

// Full month names for tooltip titles
var MESES_FULL = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho',
                  'Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];

function makeSparkline(data, color, W, H){
  W = W||80; H = H||30;
  var vals = (data||[]).filter(function(v){return v!=null&&v>0;});
  if(vals.length < 2) return '';
  var mn=Math.min.apply(null,vals), mx=Math.max.apply(null,vals);
  var rng = mx - mn || 1;
  var pts = vals.map(function(v,i){
    var x = (i/(vals.length-1))*W;
    var y = H - ((v-mn)/rng)*(H-4) - 2;
    return x.toFixed(1)+','+y.toFixed(1);
  }).join(' ');
  var lx = W, ly = (H - ((vals[vals.length-1]-mn)/rng)*(H-4) - 2).toFixed(1);
  var rgb = color.replace('#','');
  var r=parseInt(rgb.slice(0,2),16), g=parseInt(rgb.slice(2,4),16), b=parseInt(rgb.slice(4,6),16);
  return '<svg width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" style="overflow:visible;" xmlns="http://www.w3.org/2000/svg">'
    +'<defs><linearGradient id="sg'+r+g+b+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.35"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.0"/>'
    +'</linearGradient></defs>'
    +'<polygon points="0,'+H+' '+pts+' '+W+','+H+'" fill="url(#sg'+r+g+b+')" opacity="0.7"/>'
    +'<polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" opacity="0.85"/>'
    +'<circle cx="'+lx+'" cy="'+ly+'" r="2.5" fill="'+color+'" opacity="1"/>'
    +'</svg>';
}

function renderKPIs(containerId, kpis){
  var el=document.getElementById(containerId);
  if(!el) return;
  el.innerHTML=kpis.map(function(k){
    var delta=k.delta?'<div class="kpi-delta '+(k.deltaUp?'delta-up':'delta-down')+'">'+k.delta+'</div>':'';
    var spark=k.spark?'<div style="position:absolute;bottom:8px;right:10px;opacity:0.55;pointer-events:none;">'+makeSparkline(k.spark,k.color,76,30)+'</div>':'';
    return '<div class="kpi-cell" style="--accent:'+k.color+'">'+spark+'<div class="kpi-tag">'+k.label+'</div><div class="kpi-val">'+k.val+'</div><div class="kpi-sub">'+k.sub+'</div>'+delta+'</div>';
  }).join('');
}

function renderUFBar(barId, legendId, items){
  var total=items.reduce(function(s,x){return s+x.rec;},0);
  var byUF={};
  items.forEach(function(x){byUF[x.uf]=(byUF[x.uf]||0)+x.rec;});
  var sorted=Object.entries(byUF).sort(function(a,b){return b[1]-a[1];});
  var bar=document.getElementById(barId);
  var leg=document.getElementById(legendId);
  if(bar) bar.innerHTML=sorted.map(function(e){
    return '<div class="uf-seg" style="flex:'+e[1]+';background:'+(UF_COLORS[e[0]]||'#888')+'"></div>';
  }).join('');
  if(leg) leg.innerHTML=sorted.map(function(e){
    var pct=((e[1]/total)*100).toFixed(0);
    return '<div class="uf-legend-item"><div style="width:8px;height:8px;border-radius:2px;background:'+(UF_COLORS[e[0]]||'#888')+'"></div>'+e[0]+' <span style="color:'+(UF_COLORS[e[0]]||'#888')+';font-weight:700;">'+pct+'%</span></div>';
  }).join('');
}

function renderMetaTable(containerId, meses, rec24, rec25, rec26, isVol){
  var el = document.getElementById(containerId);
  if(!el) return;
  var r24 = rec24||[], r25 = rec25||[], r26 = rec26||[];

  var fmt = isVol
    ? function(v){ return v!=null ? v.toLocaleString('pt-BR') : '–'; }
    : function(v){
        if(v == null) return '–';
        if(v >= 1e6) return 'R$' + (v/1e6).toFixed(2) + 'M';
        if(v >= 1e3) return 'R$' + Math.round(v/1e3) + 'K';
        return 'R$' + v;
      };

  // Find max value across all years for sparkbar scaling
  var allVals = r24.concat(r25).concat(r26).filter(function(v){ return v!=null && v>0; });
  var maxVal = allVals.length ? Math.max.apply(null, allVals) : 1;

  // Calculate totals
  var tot24 = r24.reduce(function(s,v){ return s+(v||0); }, 0);
  var tot25 = r25.reduce(function(s,v){ return s+(v||0); }, 0);
  var tot26 = r26.filter(Boolean).reduce(function(s,v){ return s+v; }, 0);
  var tot_var = (tot25>0 && tot26>0) ? ((tot26-tot25)/tot25*100) : null;

  // Month abbreviations
  var MESES_ABR = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];

  var rows = meses.map(function(m, i){
    var v24 = r24[i]||null, v25 = r25[i]||null, v26 = r26[i]||null;
    var vp25 = (v24&&v24>0&&v25!=null) ? ((v25-v24)/v24*100) : null;
    var vp26 = (v25&&v25>0&&v26!=null) ? ((v26-v25)/v25*100) : null;

    // Sparkbar widths (% of max)
    var w24 = v24 ? Math.max(2, Math.round(v24/maxVal*100)) : 0;
    var w25 = v25 ? Math.max(2, Math.round(v25/maxVal*100)) : 0;
    var w26 = v26 ? Math.max(2, Math.round(v26/maxVal*100)) : 0;

    // Color for var%
    var c26 = vp26===null ? '#3d4451' : (vp26>=0 ? '#34d399' : '#ef4444');
    var icon26 = vp26===null ? '' : (vp26>=10 ? '▲' : vp26>0 ? '↑' : vp26<=-10 ? '▼' : '↓');
    var noData = v26 == null;

    return '<tr class="u-row-hover">'

      // Month
      + '<td style="padding:9px 12px;font-size:11px;font-weight:600;color:#D1D5DB;white-space:nowrap;width:42px;">'
      + (MESES_ABR[i]||m) + '</td>'

      // 2024 col
      + '<td style="padding:9px 8px;min-width:90px;">'
      + '<div class="u-td-old">' + fmt(v24) + '</div>'
      + '<div class="u-prog-track">'
      + '<div style="height:100%;width:' + w24 + '%;background:rgba(59,130,246,0.35);border-radius:2px;"></div>'
      + '</div></td>'

      // 2025 col
      + '<td style="padding:9px 8px;min-width:90px;">'
      + '<div class="u-td-val">' + fmt(v25) + '</div>'
      + '<div class="u-prog-track">'
      + '<div style="height:100%;width:' + w25 + '%;background:rgba(45,212,191,0.5);border-radius:2px;"></div>'
      + '</div></td>'

      // 2026 col
      + '<td style="padding:9px 8px;min-width:90px;">'
      + (noData
        ? '<div style="font-size:10px;color:#2d3748;font-style:italic;text-align:right;">—</div><div style="height:4px;background:rgba(255,255,255,0.03);border-radius:2px;"></div>'
        : '<div style="font-size:12px;font-weight:700;color:#34d399;margin-bottom:4px;text-align:right;">' + fmt(v26) + '</div>'
        + '<div class="u-prog-track">'
        + '<div style="height:100%;width:' + w26 + '%;background:rgba(52,211,153,0.7);border-radius:2px;"></div>'
        + '</div>'
        )
      + '</td>'

      // Var% 25→26
      + '<td class="u-td-r">'
      + (vp26===null
        ? '<span style="color:#2d3748;font-size:10px;">—</span>'
        : '<span style="display:inline-flex;align-items:center;gap:3px;font-size:11px;font-weight:700;color:'+c26+';">'
          + '<span style="font-size:10px;">'+icon26+'</span>'
          + Math.abs(vp26).toFixed(1)+'%'
          + '</span>'
        )
      + '</td>'

      + '</tr>';
  });

  // Totals row
  var tot_c = tot_var===null?'#D1D5DB':(tot_var>=0?'#34d399':'#ef4444');
  var tot_icon = tot_var===null?'':tot_var>=0?'▲':'▼';
  var totRow = '<tr style="border-top:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.02);">'
    + '<td style="padding:10px 12px;font-size:11px;font-weight:700;color:#e2e8f0;">TOTAL</td>'
    + '<td style="padding:10px 8px;font-size:11px;font-weight:600;color:#4a5568;text-align:right;">' + fmt(tot24) + '</td>'
    + '<td style="padding:10px 8px;font-size:11px;font-weight:600;color:#D1D5DB;text-align:right;">' + fmt(tot25) + '</td>'
    + '<td style="padding:10px 8px;font-size:12px;font-weight:800;color:#34d399;text-align:right;">' + fmt(tot26) + '</td>'
    + '<td style="padding:10px 12px;text-align:right;">'
    + (tot_var!==null
      ? '<span style="font-size:12px;font-weight:800;color:'+tot_c+';">'+tot_icon+' '+Math.abs(tot_var).toFixed(1)+'%</span>'
      : '—')
    + '</td></tr>';

  el.innerHTML = '<table style="width:100%;border-collapse:collapse;">'
    + '<thead><tr style="border-bottom:1px solid rgba(255,255,255,0.13);">'
    + '<th style="padding:8px 12px;text-align:left;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">MÊS</th>'
    + '<th style="padding:8px 8px;text-align:right;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3b82f6;">2024</th>'
    + '<th style="padding:8px 8px;text-align:right;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#2dd4bf;">2025</th>'
    + '<th style="padding:8px 8px;text-align:right;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#34d399;">2026</th>'
    + '<th style="padding:8px 12px;text-align:right;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#94A3B8;">VAR% 25×26</th>'
    + '</tr></thead>'
    + '<tbody>' + rows.join('') + totRow + '</tbody>'
    + '</table>';
}

