/* ═══════════ SÃO JOÃO ═══════════ */
var sjBarMode='vol', sjLojaMetric='rec', sjLojaAno='todos';
var sjRankYear='2024', sjRankMetric='rec', sjMetaYear='2024', sjMetaMetric='rec';
var sjDonutYear='2024';
var sjModo = 'total'; // 'total' | 'isadora' | 'caroline'

/* helpers que retornam o array correto conforme sjModo
   SJ_UNID / SJ_REC = TOTAL da rede São João
   SJC_* = dados exclusivos da Compradora Caroline
   isadora = total − caroline  */
function sjGetVol(ano){
  var tot = SJ_UNID[ano]||[];
  var ca  = ano==='2024'?SJC_VOL_24:(ano==='2025'?SJC_VOL:SJC_VOL_26);
  if(sjModo==='total')    return tot;
  if(sjModo==='caroline') return ca;
  /* isadora = total - caroline */
  return tot.map(function(v,i){
    if(v===null) return null;
    return v - (ca[i]||0);
  });
}
function sjGetRec(ano){
  var tot = SJ_REC[ano]||[];
  var ca  = ano==='2024'?SJC_REC_24:(ano==='2025'?SJC_REC:SJC_REC_26);
  if(sjModo==='total')    return tot;
  if(sjModo==='caroline') return ca;
  /* isadora = total - caroline */
  return tot.map(function(v,i){
    if(v===null) return null;
    return v - (ca[i]||0);
  });
}

function initSJ(){
  var v24=sjGetVol('2024'), v25=sjGetVol('2025'), v26=sjGetVol('2026');
  var r24=sjGetRec('2024'), r25=sjGetRec('2025'), r26=sjGetRec('2026');
  var sumV24=v24.reduce(function(s,v){return s+(v||0);},0);
  var sumV25=v25.reduce(function(s,v){return s+(v||0);},0);
  var sumV26=v26.reduce(function(s,v){return s+(v||0);},0);
  var sumR24=r24.reduce(function(s,v){return s+(v||0);},0);
  var sumR25=r25.reduce(function(s,v){return s+(v||0);},0);
  var sumR26=r26.reduce(function(s,v){return s+(v||0);},0);
  var pctV=sumV24>0?((sumV25/sumV24-1)*100):0;
  var pctR=sumR24>0?((sumR25/sumR24-1)*100):0;
  var _mLbl=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  var _last26=v26.reduce(function(m,v,i){return v!=null?i:m;},-1);
  var sub26=sjModo==='caroline'?'2025 parcial':(_last26<0?'parcial':(_last26===0?'Jan parcial':'Jan–'+_mLbl[_last26]+' parcial'));
  renderKPIs('sj-kpis',[
    {label:'Volume 2024',val:sumV24.toLocaleString('pt-BR'),sub:'Total anual',color:'#3b82f6',spark:v24},
    {label:'Volume 2025',val:sumV25.toLocaleString('pt-BR'),sub:'Total anual',color:'#2dd4bf',delta:(pctV>=0?'▲':'▼')+' '+Math.abs(pctV).toFixed(1)+'% vs 2024',deltaUp:pctV>=0,spark:v25},
    {label:'Volume 2026',val:sumV26.toLocaleString('pt-BR'),sub:sub26,color:'#34d399',spark:v26},
    {label:'Receita 2024',val:fmtNum(sumR24),sub:'Total anual',color:'#3b82f6',spark:r24},
    {label:'Receita 2025',val:fmtNum(sumR25),sub:'Total anual',color:'#2dd4bf',delta:(pctR>=0?'▲':'▼')+' '+Math.abs(pctR).toFixed(1)+'% vs 2024',deltaUp:pctR>=0,spark:r25},
    {label:'Receita 2026',val:fmtNum(sumR26),sub:sub26,color:'#34d399',spark:r26},
  ]);
  renderSJAnoBars(); renderDonutSJ(); renderSJLine(); renderSJLojas(); renderSJRank(); renderSJMeta();
  renderSJEstoqueBarras();
  renderEDShare('São João','sj');
  setTimeout(function(){ var el=document.getElementById('ed-sj-wrap'); if(el&&!el.innerHTML.trim()) renderEDShare('São João','sj'); }, 500);
}

function renderSJAnoBars(){
  var isVol = sjBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var sum=function(arr){return arr.reduce(function(s,v){return s+(v||0);},0);};
  var vals = isVol
    ? [sum(sjGetVol('2024')), sum(sjGetVol('2025')), sum(sjGetVol('2026'))]
    : [sum(sjGetRec('2024')), sum(sjGetRec('2025')), sum(sjGetRec('2026'))];
  renderAnoChart('sj-ano-chart', anos, vals, isVol);
}
function setSJBarMode(m,btn){
  sjBarMode=m;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue'); renderSJAnoBars();
}

