function switchSJCompradora(comp,btn){
  /* Chart.js safety: destruir charts ativas antes de re-render */
  (function(){
    var canvases = document.querySelectorAll('#sj-caroline-notice canvas, #sj-isadora-content canvas');
    canvases.forEach(function(cv){
      var ch = (typeof Chart !== 'undefined') && Chart.getChart ? Chart.getChart(cv) : null;
      if(ch){ try{ ch.destroy(); }catch(e){} }
      /* Fix: limpar cache _anoCharts para evitar referencia stale apos destroy */
      if(cv.id && typeof _anoCharts !== 'undefined'){ delete _anoCharts[cv.id]; }
    });
  })();
  /* Atualiza active nos botões do header e nos sub-tabs ocultos */
  document.querySelectorAll('#sj-compradora-row .stab, #panel-saojoao-inner .sub-tabs .stab').forEach(function(b){b.classList.remove('active');});
  btn.classList.add('active');
  /* Sincroniza o botão correspondente no outro grupo */
  var _compIdx={'total':0,'isadora':1,'caroline':2};
  var _hdrBtns=document.querySelectorAll('#sj-compradora-row .stab');
  var _subBtns=document.querySelectorAll('#panel-saojoao-inner .sub-tabs .stab');
  var _idx=_compIdx[comp];
  if(_hdrBtns[_idx]) _hdrBtns[_idx].classList.add('active');
  if(_subBtns[_idx]) _subBtns[_idx].classList.add('active');
  sjModo = comp; // 'total' | 'isadora' | 'caroline'
  document.getElementById('sj-caroline-notice').style.display=comp==='caroline'?'block':'none';
  document.getElementById('sj-isadora-content').style.display=(comp==='isadora'||comp==='total')?'block':'none';
  /* Posicionar card Evolução Acumulada logo ABAIXO da Evolução Mensal da view ativa (padrão dos outros clientes) */
  (function(){
    var acum=document.getElementById('acum-slot-saojoao');
    var anchor=document.getElementById(comp==='caroline'?'sj-evol-mensal-car':'sj-evol-mensal-iso');
    if(acum&&anchor&&acum.previousElementSibling!==anchor){
      anchor.parentNode.insertBefore(acum, anchor.nextSibling);
    }
  })();
  /* move o card de atribuição para o slot correto conforme a aba */
  var _atribCard = document.getElementById('ed-atrib-card');
  var _targetSlotId = comp==='caroline' ? 'ed-atrib-slot-caroline' : 'ed-atrib-slot-sj';
  var _targetSlot  = document.getElementById(_targetSlotId);
  if(_atribCard && _targetSlot) _targetSlot.appendChild(_atribCard);
  /* força re-render: limpa cache de inicialização */
  if(typeof initialized!=='undefined') delete initialized['sellout_saojoao'];
  if(comp==='caroline'){
    setTimeout(function(){
      initCaroline();
      if(window.edAtribShow) window.edAtribShow('sj', null);
      if(window.edAtribSetRede) window.edAtribSetRede('sj');
    }, 30);
  } else {
    /* re-renderiza KPIs e gráficos com o modo correto (total / isadora) */
    setTimeout(function(){
      initSJ();
      if(window.edAtribShow) window.edAtribShow('sj', null);
    }, 30);
  }
  /* Sincroniza card acumulado FY com a compradora do header */
  if(window.acumSetCompradora){
    setTimeout(function(){ window.acumSetCompradora('saojoao', comp, null); }, 80);
  }
}

