  var nd=nsData();
  var pctNV=nd.kpis.u24>0?((nd.kpis.u25/nd.kpis.u24-1)*100):0;
  var pctNR=nd.kpis.r24>0?((nd.kpis.r25/nd.kpis.r24-1)*100):0;
  renderKPIs('ns-kpis',[
    {label:'Volume 2024',val:k.u24.toLocaleString('pt-BR'),sub:'Total anual',color:'#3b82f6',spark:nd.vol['2024']},
    {label:'Volume 2025',val:k.u25.toLocaleString('pt-BR'),sub:'Total anual',color:'#2dd4bf',delta:(pctNV>=0?'▲':'▼')+' '+Math.abs(pctNV).toFixed(1)+'% vs 2024',deltaUp:pctNV>=0,spark:nd.vol['2025']},
    {label:'Volume 2026',val:k.u26.toLocaleString('pt-BR'),sub:'Jan–Abr parcial',color:'#34d399',spark:nd.vol['2026']},
    {label:'Receita 2024',val:fmtNum(k.r24),sub:'Total anual',color:'#3b82f6',spark:nd.rec['2024']},
    {label:'Receita 2025',val:fmtNum(k.r25),sub:'Total anual',color:'#2dd4bf',delta:(pctNR>=0?'▲':'▼')+' '+Math.abs(pctNR).toFixed(1)+'% vs 2024',deltaUp:pctNR>=0,spark:nd.rec['2025']},
    {label:'Receita 2026',val:fmtNum(nd.rec['2026'].filter(Boolean).reduce(function(s,v){return s+v;},0)),sub:'Jan–Abr parcial',color:'#34d399',spark:nd.rec['2026']},
  ]);
  renderNSAnoBars(); renderNSDonut(); renderNSLine(); renderNSLojas(); renderNSRank();
  renderNsEstoqueBarras(); updateNsEstoqueKPIs(); renderNSMeta();
  renderEDShare('Nissei','nissei');
