var clEstoqueView  = 'barras';
var clEstoqueChart = null;

function renderClEstoqueBarras(){
  var el = document.getElementById('cl-estoque-bars');
  if(!el) return;
  var maxEst = Math.max.apply(null, CL_ESTOQUE.map(function(d){return d.estoque;}));
  var h = '';
  CL_ESTOQUE.forEach(function(d,i){
    var cob_real = calcCob(d.estoque, 'clamed');
    var risco_real = calcRisco(cob_real);
    var cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':'#34d399';
    var bg  = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
              risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = Math.min(100,Math.round(d.estoque/maxEst*100));
    var cobLabelStr = cobLabel(cob_real);
    var alerta = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:6px;">'+cobLabelStr+'</span>'):'';
    h += '<div class="bar-item" data-togglesel="1">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(i+1)+'</span>';
    h += '<span class="bar-name">'+d.sku+alerta+'</span>';
    h += '<span class="u-lbl-muted">'+d.estoque.toLocaleString('pt-BR')+' un</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+cobLabelStr+' cob.</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Venda Ref/mês: <span class="expand-val" style="color:#D1D5DB">'+VENDA_REF.clamed.venda_mes.toLocaleString('pt-BR')+' un ('+VENDA_REF.clamed.periodo+')</span></div>';
    h += '<div class="expand-item">Cobertura Real: <span class="expand-val" style="color:'+cor+'">'+cobLabelStr+'</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function renderClEstoqueLinha(){
  var ctx = document.getElementById('cl-estoque-chart');
  if(!ctx) return;
  if(clEstoqueChart) clEstoqueChart.destroy();
  var skus = CL_ESTOQUE.filter(function(d){return d.venda>0;}).slice(0,12);
  var labels = skus.map(function(d){return d.sku.length>20?d.sku.substring(0,20)+'…':d.sku;});
  var cores  = skus.map(function(d){return d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';});
  clEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque Atual (un)',data:skus.map(function(d){return d.estoque;}),backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Cobertura (dias)',data:skus.map(function(d){return d.cob>=999?null:Math.min(d.cob,250);}),type:'line',borderColor:'#2dd4bf',backgroundColor:'transparent',pointBackgroundColor:cores,pointRadius:6,pointBorderWidth:2,borderWidth:2,tension:0.3,yAxisID:'y2'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{
      legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
        callbacks:{label:function(c){if(c.datasetIndex===0)return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';return ' Cobertura: '+(c.raw!=null?c.raw+'d':'-');}}},
      annotation:{annotations:{
        linha30:{type:'line',yMin:30,yMax:30,yScaleID:'y2',borderColor:'#fbbf24',borderWidth:1.5,borderDash:[6,4],label:{content:'30d',display:true,color:'#fbbf24',font:{size:9},position:'start'}},
        linha15:{type:'line',yMin:15,yMax:15,yScaleID:'y2',borderColor:'#06b6d4',borderWidth:1.5,borderDash:[6,4],label:{content:'15d crítico',display:true,color:'#06b6d4',font:{size:9},position:'end'}}
      }}
    },
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},title:{display:true,text:'Estoque (un)',color:'#475569',font:{size:9}}},
      y2:{position:'right',grid:{display:false},ticks:{color:'#2dd4bf',font:{size:9},callback:function(v){return v+'d';}},title:{display:true,text:'Cobertura (dias)',color:'#2dd4bf',font:{size:9}},min:0,max:250}
    }
  }});
}

/* ═══════════ COBERTURA REAL — CRUZAMENTO COM VENDAS ═══════════ */
/*
 * Referência: Abril/2026 em diante
 * Venda mensal = média do período disponível mais recente por cliente
 * Lógica: cob(dias) = (estoque / venda_media_mes) * 30
 * Atualizar VENDA_REF_MES ao carregar novo arquivo de estoque
 */
const VENDA_REF = {
  // Referência: Jun/2025 — comparação estoque Jun/2026 vs venda Jun/2025
  // Fonte: planilha Estoque_Geral col 'Venda Ref (un/mês)' — atualizado 07/07/2026

  panvel:   { venda_mes: 1310,  periodo: 'Jun/2025' },
  clamed:   { venda_mes: 1420,  periodo: 'Jun/2025' },
  ddgam:    { venda_mes: 5853,  periodo: 'Jun/2025' },
  ddgaucha: { venda_mes: 2346,  periodo: 'Jun/2025' },
  nissei:   { venda_mes: 1817,  periodo: 'Jun/2025' },
  caroline: { venda_mes: 9844,  periodo: 'Jun/2025' },
};

function calcCob(estoque, clienteKey) {
  // Distribui venda mensal total proporcionalmente ao estoque do SKU
  // Retorna cobertura em dias
  var ref = VENDA_REF[clienteKey];
  if(!ref || ref.venda_mes === 0) return 999;
  return Math.round((estoque / ref.venda_mes) * 30);
}

function calcRisco(cob) {
  if(cob === 0) return 'critico';
  if(cob < 15)  return 'critico';
  if(cob < 30)  return 'atencao';
  return 'ok';
}

function cobLabel(cob) {
  if(cob >= 999) return 'sem giro';
  return cob + 'd';
}

/* ═══════════════════════════════════════════════════════════════
   DATA NORMALIZATION LAYER
   Garante datasets completos antes de renderizar qualquer gráfico.
   normalizeDataset(data, baseKeys) — retorna array com todos os
   campos esperados preenchidos com valor default (null ou 0).
   ═══════════════════════════════════════════════════════════════ */
function normalizeDataset(data, baseKeys){
  if(!Array.isArray(data)) return [];
  return data.map(function(row){
    var out = {};
    baseKeys.forEach(function(k){
      out[k] = (row[k] !== undefined && row[k] !== null) ? row[k] : null;
    });
    return out;
  });
}

/* ═══════════════════════════════════════════════════════════════
   FUNÇÃO UNIFICADA: renderCoberturaSKUBarsUnified
   Utilizada por TODOS os clientes na view "Cobertura por SKU".
   Parâmetros:
     containerId  — id do elemento alvo
     data         — array [{sku, lojas, total, pct, estoque, risco?}]
     clientLabel  — texto descritivo ex: "São João (Jun/26)"
   ═══════════════════════════════════════════════════════════════ */
﻿function renderCoberturaSKUBarsUnified(containerId, data, clientLabel){
  var el = document.getElementById(containerId);
  if(!el) return;
  var safeData = normalizeDataset(data, ['sku','lojas','total','pct','estoque','risco','marca'])
    .filter(function(d){ return d.sku; });
  if(!safeData.length){
    el.innerHTML='<p style="color:#94A3B8;font-size:11px;padding:16px;">Dados de cobertura não disponíveis.</p>';
    return;
  }
  var totalLojas = safeData[0] ? (safeData[0].total || 0) : 0;
  var skusOk   = safeData.filter(function(d){ return (d.pct||0) >= 80; }).length;
  var skusAtenc= safeData.filter(function(d){ return (d.pct||0) >= 50 && (d.pct||0) < 80; }).length;
  var skusCrit = safeData.filter(function(d){ return (d.pct||0) < 50; }).length;
  var html = '';
  html += '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#E4EAF2;border-radius:10px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(94,153,208,0.45);box-shadow:0 2px 8px rgba(10,40,80,0.08);">';
  html += _cobKpi('TOTAL LOJAS', totalLojas.toLocaleString('pt-BR'), 'base', '#60a5fa');
  html += _cobKpi('SKUs OK (≥80%)', skusOk, '', '#34d399');
  html += _cobKpi('SKUs ATENÇÃO (50-79%)', skusAtenc, '', '#fbbf24');
  html += _cobKpi('SKUs CRÍTICO (<50%)', skusCrit, '', '#06b6d4');
  html += '</div>';
  if(clientLabel){
    html += '<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:#475569;margin-bottom:10px;text-transform:uppercase;">🏪 Cobertura por SKU — '+clientLabel+'</div>';
  }
  var ORDEM_MARCAS = ['OFF','EXPOSIS','RAID','GLADE','PATO','LYSOFORM','OUTROS'];
  var CORES_MARCA  = {OFF:'#3b82f6',EXPOSIS:'#34d399',RAID:'#f97316',GLADE:'#a78bfa',PATO:'#fbbf24',LYSOFORM:'#22d3ee',OUTROS:'#94A3B8'};
  var grupos = {};
  safeData.forEach(function(d){ var m=d.marca||'OUTROS'; if(!grupos[m]) grupos[m]=[]; grupos[m].push(d); });
  Object.keys(grupos).forEach(function(m){ grupos[m].sort(function(a,b){ return (b.pct||0)-(a.pct||0); }); });
  html += '<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  html += '<thead><tr style="border-bottom:1px solid rgba(255,255,255,0.13);">'
    + '<th style="text-align:left;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">SKU</th>'
    + '<th style="text-align:center;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;white-space:nowrap;">LOJAS C/ ESTOQUE</th>'
    + '<th style="padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">COBERTURA</th>'
    + '<th style="text-align:right;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">ESTOQUE</th>'
    + '</tr></thead><tbody>';
  ORDEM_MARCAS.forEach(function(marca){
    var itens = grupos[marca];
    if(!itens || !itens.length) return;
    var cor = CORES_MARCA[marca] || '#94A3B8';
    var mkOk=itens.filter(function(d){return (d.pct||0)>=80;}).length;
    var mkAt=itens.filter(function(d){return (d.pct||0)>=50&&(d.pct||0)<80;}).length;
    var mkCrit=itens.filter(function(d){return (d.pct||0)<50;}).length;
    html += '<tr style="background:'+cor+'18;border-top:2px solid '+cor+'40;">'
      + '<td colspan="4" style="padding:6px 8px;">'
      + '<span style="font-size:11px;font-weight:800;color:'+cor+';letter-spacing:0.08em;">'+marca+'</span>'
      + '<span style="font-size:9px;color:#94A3B8;margin-left:10px;">'+itens.length+' SKUs</span>'
      + (mkOk   ? '<span style="font-size:9px;color:#34d399;margin-left:10px;">✓ '+mkOk+' OK</span>' : '')
      + (mkAt   ? '<span style="font-size:9px;color:#fbbf24;margin-left:8px;">⚠ '+mkAt+' ATENÇÃO</span>' : '')
      + (mkCrit ? '<span style="font-size:9px;color:#22d3ee;margin-left:8px;">⚡ '+mkCrit+' CRÍTICO</span>' : '')
      + '</td></tr>';
    itens.forEach(function(d,i){
      var pct=d.pct||0;
      var pctColor=pct>=80?'#34d399':pct>=50?'#fbbf24':'#22d3ee';
      var rowBg=i%2===0?'rgba(255,255,255,0.025)':'transparent';
      var riscoBadge=(d.risco==='critico'||d.risco==='atencao')
        ? '<span style="font-size:8px;font-weight:700;margin-left:5px;padding:1px 4px;border-radius:3px;background:'+(d.risco==='critico'?'rgba(251,113,113,0.15)':'rgba(251,191,36,0.15)')+';color:'+(d.risco==='critico'?'#06b6d4':'#fbbf24')+';">'+(d.risco==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'
        : '';
      html += '<tr style="background:'+rowBg+';border-bottom:1px solid rgba(255,255,255,0.04);">'
        + '<td style="padding:5px 8px 5px 16px;color:#1E293B;font-weight:500;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+d.sku+'">'+d.sku+riscoBadge+'</td>'
        + '<td style="text-align:center;padding:5px 8px;color:#1E293B;font-weight:700;font-variant-numeric:tabular-nums;">'+(d.lojas||0)+' / '+(d.total||0)+'</td>'
        + '<td style="padding:5px 12px;min-width:140px;"><div style="display:flex;align-items:center;gap:8px;"><div style="flex:1;background:rgba(245,225,164,0.07);border-radius:4px;height:8px;"><div style="width:'+Math.min(100,pct)+'%;background:'+pctColor+';border-radius:4px;height:8px;"></div></div><span style="color:'+pctColor+';font-weight:700;min-width:38px;text-align:right;font-size:11px;">'+pct+'%</span></div></td>'
        + '<td style="text-align:right;padding:5px 8px;color:#1E293B;font-weight:600;font-variant-numeric:tabular-nums;">'+(d.estoque||0).toLocaleString('pt-BR')+'</td>'
        + '</tr>';
    });
  });
  html += '</tbody></table>';
  el.innerHTML = html;
}


function _cobKpi(label, val, sub, color){
  return '<div style="background:#E4EAF2;padding:12px 14px;border-left:1px solid rgba(94,153,208,0.35);border-right:1px solid rgba(94,153,208,0.35);border-bottom:1px solid rgba(94,153,208,0.35);">'
    + '<div class="u-kpi-lbl">'+label+'</div>'
    + '<div style="font-size:20px;font-weight:800;color:'+color+';line-height:1;">'+val+'</div>'
    + (sub?'<div style="font-size:10px;color:#64748B;margin-top:4px;">'+sub+'</div>':'')
    + '</div>';
}
/* ═══════════ CLAMED ═══════════ */
var clRankKey='2026';
var clLineMode = 'vol';
var clLineChart = null;
var clBarMode = 'vol';

function renderCLLine(){
  var ctx = document.getElementById('cl-line');
  if(!ctx) return;
  if(clLineChart) clLineChart.destroy();
  var isVol = clLineMode === 'vol';
  var d24 = isVol ? CL_VOL_2024 : CL_REC_2024;
  var d25 = isVol ? CL_VOL_2025 : CL_REC_2025;
  var d26 = isVol ? CL_VOL_2026 : CL_REC_2026;
  renderLineChart('cl-line',[
    {label:'2024', data:d24, color:'#3b82f6'},
    {label:'2025', data:d25, color:'#2dd4bf'},
    {label:'2026', data:d26, color:'#34d399', dashed:true},
  ],'cl-line-legend', isVol);
}
function setCLLineMode(m,btn){clLineMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderCLLine();}

function renderCLAnoBars(){
  var isVol = clBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var vals = isVol ? [90534,95951,59987] : [3137722,3058207.54,2149873.0100000002];
  renderAnoChart('cl-ano-chart', anos, vals, isVol);
}
function setCLBarMode(m,btn){clBarMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderCLMesBars();}

function renderCLMesBars(){
  var isVol = clBarMode === 'vol';
  var anos = [
    {label:'2024', data: isVol?CL_VOL_2024:CL_REC_2024, color:'#3b82f6'},
    {label:'2025', data: isVol?CL_VOL_2025:CL_REC_2025, color:'#2dd4bf'},
    {label:'2026', data: isVol?CL_VOL_2026:CL_REC_2026, color:'#34d399'},
  ];
  var items = [];
  var mLabels = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  anos.forEach(function(a){
    a.data.forEach(function(v,i){
      if(v!=null && v>0){
        items.push({nome:mLabels[i]+'/'+a.label.slice(2), val:v, color:a.color});
      }
    });
  });
  renderBars('cl-mes-bars', items, {isVol: isVol});
  renderCLAnoBars();
}

function initClamed(){
  setTimeout(renderCLAnoBars, 100);
  renderKPIs('cl-kpis',[
    {label:'Volume 2024',val:'88.571',sub:'Mar–Dez (parcial)',color:'#3b82f6',spark:CL_VOL_2024},
    {label:'Volume 2025',val:'95.951',sub:'Total anual',color:'#2dd4bf',delta:'▲ 6,0% vs 2024',deltaUp:true,spark:CL_VOL_2025},
    {label:'Volume 2026',val:'53.526',sub:'Jan–Mai parcial',color:'#34d399',spark:CL_VOL_2026},
    {label:'Receita 2024',val:'R$ 3,14M',sub:'Mar–Dez (parcial)',color:'#3b82f6',spark:CL_REC_2024},
    {label:'Receita 2025',val:'R$ 3,06M',sub:'Total anual',color:'#2dd4bf',delta:'▼ 2,5% vs 2024',deltaUp:false,spark:CL_REC_2025},
    {label:'Receita 2026',val:'R$ 1,91M',sub:'Jan–Mai parcial',color:'#34d399',spark:CL_REC_2026},
  ]);
  renderCLLine(); renderCLMesBars(); renderCLDonut(); renderCLLojas(); renderCLRank();
  renderClEstoqueBarras();
  renderCLMeta();
  renderEDShare('Clamed','clamed');
  setTimeout(function(){ var el=document.getElementById('ed-clamed-wrap'); if(el&&!el.innerHTML.trim()) renderEDShare('Clamed','clamed'); }, 500);
}

function renderCLDonut(){
  var rows=(CL_RANK[clRankKey]||CL_RANK['2026']).slice(0,6);
  renderDonut('cl-donut','cl-donut-legend',rows.map(function(r){return{nome:r[0],val:r[1],color:r[2]};}));
}
function setCLRankKey(k,btn){clRankKey=k;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderCLDonut();renderCLRank();}

function renderCLLojas(){
  var items=CL_LOJAS.map(function(l,i){
    return{nome:l.nome,val:l.tot,color:LOJA_COLORS[i],
      extraFields:[{label:'Jan: ',val:l.jan},{label:'Fev: ',val:l.fev},{label:'Mar: ',val:l.mar}]};
  });
  renderBars('cl-loja-bars',items,{isVol:true,hbar:true});
}

function renderCLRank(){
  var rows=(CL_RANK[clRankKey]||CL_RANK['2026']);
  renderRankBars('cl-rank-bars',rows,'vol');
}

