var pvEstoqueView  = 'barras';
var pvEstoqueChart = null;

function renderPVEstoqueBarras(){
  var el = document.getElementById('pv-estoque-bars');
  if(!el) return;
  var maxEst = Math.max.apply(null, PV_ESTOQUE.map(function(d){return d.estoque;}));
  var h = '';
  PV_ESTOQUE.slice().sort(function(a,b){return b.estoque-a.estoque;}).forEach(function(d,i){
    var cob_real = calcCob(d.estoque, 'panvel');
    var risco_real = calcRisco(cob_real);
    var cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':'#34d399';
    var bg  = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
              risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = d.estoque===0?0:Math.max(1,Math.round(d.estoque/maxEst*100));
    var estLabel = d.estoque===0?'ZERADO':d.estoque.toLocaleString('pt-BR')+' un';
    var pendBadge = d.pend>0?('<span style="font-size:9px;font-weight:700;background:rgba(251,191,36,0.15);color:#fbbf24;border-radius:3px;padding:1px 5px;margin-left:6px;">⏳ '+d.pend.toLocaleString('pt-BR')+' pend.</span>'):'';
    var alertaBadge = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:4px;">'+(d.risco==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'):'';
    h += '<div class="bar-item" data-togglesel="1" style="'+bg+'">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(i+1)+'</span>';
    h += '<span class="bar-name">'+d.sku+alertaBadge+pendBadge+'</span>';
    h += '<span class="u-lbl-muted">'+estLabel+'</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+d.marca+'</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque Total: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">CD RS: <span class="expand-val" style="color:#D1D5DB">'+d.cdRS.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">CD PR: <span class="expand-val" style="color:#D1D5DB">'+d.cdPR.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Lojas: <span class="expand-val" style="color:#D1D5DB">'+d.lojas.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Pendências: <span class="expand-val" style="color:'+(d.pend>0?'#fbbf24':'#5a6478')+'">'+d.pend.toLocaleString('pt-BR')+' un</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function renderPVEstoqueLinha(){
  var ctx = document.getElementById('pv-estoque-chart');
  if(!ctx) return;
  if(pvEstoqueChart) pvEstoqueChart.destroy();
  var skus = PV_ESTOQUE.filter(function(d){return d.estoque>0;}).sort(function(a,b){return b.estoque-a.estoque;}).slice(0,14);
  var labels = skus.map(function(d){return d.sku.length>22?d.sku.substring(0,22)+'…':d.sku;});
  var cores  = skus.map(function(d){return d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';});
  pvEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque Total (un)',data:skus.map(function(d){return d.estoque;}),backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Pendências (un)',data:skus.map(function(d){return d.pend>0?d.pend:null;}),type:'line',borderColor:'#fbbf24',backgroundColor:'transparent',pointBackgroundColor:'#fbbf24',pointRadius:7,pointBorderWidth:2,borderWidth:2,tension:0.3,yAxisID:'y'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{
      legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
        callbacks:{label:function(c){if(c.datasetIndex===0)return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';return ' Pendência: '+c.raw.toLocaleString('pt-BR')+' un';}}}
    },
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},title:{display:true,text:'Estoque (un)',color:'#475569',font:{size:9}}}
    }
  }});
}

/* ═══════════ PANVEL ═══════════ */
var pvBarMode='rec', pvDonutYear='2024', pvRankYear='2024';
function initPanvel(){
  /* ── Atualizar KPIs dinâmicos de Panvel ── */
  (function(){
    var totalPend = PV_ESTOQUE.reduce(function(s,d){return s+(d.pend||0);},0);
    var skusPend  = PV_ESTOQUE.filter(function(d){return (d.pend||0)>0;}).length;
    var raidEst   = PV_ESTOQUE.filter(function(d){return (d.marca||'').toUpperCase()==='RAID';})
                              .reduce(function(s,d){return s+(d.estoque||0);},0);
    var raidAlert = PV_ESTOQUE.filter(function(d){
      return (d.marca||'').toUpperCase()==='RAID' && ['critico','atencao','atenção'].indexOf((d.risco||'').toLowerCase())>=0;
    }).length;
    var pendEl = document.getElementById('pv-kpi-pend');
    if(pendEl){
      var pVal = pendEl.querySelector('div:nth-child(2)');
      var pSub = pendEl.querySelector('div:nth-child(3)');
      if(pVal) pVal.style.color = totalPend>0?'#fbbf24':'#34d399';
      if(pVal) pVal.textContent = totalPend.toLocaleString('pt-BR');
      if(pSub) pSub.textContent = totalPend>0?(skusPend+' SKUs com pedidos abertos'):'Sem pedidos em aberto';
    }
    var raidEl = document.getElementById('pv-kpi-raid');
    if(raidEl){
      var rVal = raidEl.querySelector('div:nth-child(2)');
      var rSub = raidEl.querySelector('div:nth-child(3)');
      var rLbl = raidEl.querySelector('div:nth-child(1)');
      if(rLbl) rLbl.textContent = raidAlert>0?'RAID EM ALERTA':'RAID ESTOQUE';
      if(rVal){ rVal.style.color = raidAlert>0?'#06b6d4':'#2dd4bf'; rVal.textContent = (raidAlert>0?raidAlert:raidEst).toLocaleString('pt-BR'); }
      if(rSub) rSub.textContent = raidAlert>0?(raidAlert+' SKUs RAID abaixo do mínimo'):(raidEst.toLocaleString('pt-BR')+' un em estoque RAID');
    }
  }());
  /* Dias de estoque Panvel */
  (function(){
    var cobArr=PV_ESTOQUE.filter(function(d){return d.cob>0&&d.cob<999;}).map(function(d){return d.cob;});
    var dias=cobArr.length>0?Math.round(cobArr.reduce(function(a,b){return a+b;},0)/cobArr.length):0;
    if(!dias){
      var tEst=PV_ESTOQUE.reduce(function(s,d){return s+(d.estoque||0);},0);
      var tVnd=PV_ESTOQUE.reduce(function(s,d){return s+(d.venda_abr||d.dem||0);},0);
      dias=tVnd>0?Math.round(tEst/tVnd*30):0;
    }
    var el=document.getElementById('pv-kpi-dias');
    if(el){var v=el.querySelector('div:nth-child(2)');var s=el.querySelector('div:nth-child(3)');
      if(v){v.textContent=dias>0?dias+' dias':'—';v.style.color=dias>0&&dias<60?'#06b6d4':dias<120?'#fbbf24':'#34d399';}
      if(s) s.textContent='Cobertura média (dias)';}
  }());
  renderKPIs('pv-kpis', getKpisForClient('pv'));
  renderPVAnoBars(); renderPVDonut(); renderPVLine(); renderPVLojas(); renderPVRank(); renderPVMeta();
  renderPVEstoqueBarras();
  renderEDShare('Panvel','panvel');
  setTimeout(function(){ var el=document.getElementById('ed-panvel-wrap'); if(el&&!el.innerHTML.trim()) renderEDShare('Panvel','panvel'); }, 500);
}

function renderPVAnoBars(){
  var isVol = pvBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var vals = isVol ? [229508,153987,70692] : [8778467,6070553.57,2673528.83];
  renderAnoChart('pv-ano-chart', anos, vals, isVol);
}
function setPVBarMode(m,btn){pvBarMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderPVAnoBars();}

function renderPVDonut(){
  var rows=(PV_RANK[pvDonutYear]||PV_RANK['2024']).slice(0,6);
  renderDonut('pv-donut','pv-donut-legend',rows.map(function(r){return{nome:r[0],val:r[1],color:r[2]};}));
}
function setPVDonutYear(y,btn){pvDonutYear=y;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderPVDonut();}

function renderPVLine(){
  var isVol = pvLineMode === 'vol';
  var d24 = isVol ? PV_VOL['2024'] : PV_REC['2024'];
  var d25 = isVol ? PV_VOL['2025'] : PV_REC['2025'];
  var d26 = isVol ? PV_VOL['2026'] : PV_REC['2026'];
  renderLineChart('pv-line',[
    {label:'2024',data:d24,color:'#3b82f6'},
    {label:'2025',data:d25,color:'#2dd4bf'},
    {label:'2026',data:d26,color:'#34d399',dashed:true},
  ],'pv-line-legend', isVol);
}

var pvLojaMode='rec';
function setPVLojaMode(m,btn){
  pvLojaMode=m;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderPVLojas();
}
function renderPVLojas(){
  var isRec=pvLojaMode==='rec';
  var items=PV_LOJAS.map(function(l,i){
    var val=isRec?l.rec_tot:l.tot;
    var fev=isRec?l.rec_fev:l.fev;
    var mar=isRec?l.rec_mar:l.mar;
    var disp=isRec?fmtNum(val):val.toLocaleString('pt-BR')+' un';
    return{nome:l.nome,val:val||0,color:LOJA_COLORS[i],isVol:!isRec,
      extraFields:[
        {label:'Fev/26: ',val:isRec?fmtNum(fev):fev.toLocaleString('pt-BR')+' un'},
        {label:'Mar/26: ',val:isRec?fmtNum(mar):mar.toLocaleString('pt-BR')+' un'},
        {label:'Total: ',val:disp}
      ]};
  });
  renderBars('pv-loja-bars',items,{hbar:true,isVol:!isRec});
}

function renderPVRank(){
  var rows=(PV_RANK[pvRankYear]||PV_RANK['2024']);
  renderRankBars('pv-rank-bars',rows,'rec');
}
function setPVRankYear(y,btn){pvRankYear=y;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderPVRank();}

