var gamEstoqueView  = 'barras';
var gamEstoqueChart = null;

function renderGAMEstoqueBarras(){
  var el = document.getElementById('gam-estoque-bars');
  if(!el) return;
  var maxEst = Math.max.apply(null, GAM_ESTOQUE.map(function(d){return d.estoque;}));
  var h = '';
  GAM_ESTOQUE.slice().sort(function(a,b){return b.estoque-a.estoque;}).forEach(function(d,i){
    var cob_real = calcCob(d.estoque, 'ddgam');
    var risco_real = calcRisco(cob_real);
    var cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':'#34d399';
    var bg  = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
              risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = d.estoque===0?0:Math.max(1,Math.round(d.estoque/maxEst*100));
    var estLabel = d.estoque===0?'ZERADO':d.estoque.toLocaleString('pt-BR')+' un';
    var pendBadge = d.pend>0?('<span style="font-size:9px;font-weight:700;background:rgba(251,191,36,0.15);color:#fbbf24;border-radius:3px;padding:1px 5px;margin-left:6px;">⏳ '+d.pend.toLocaleString('pt-BR')+' pend.</span>'):'';
    var alertaBadge = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:4px;">'+(d.risco==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'):'';
    h += '<div class="bar-item" data-togglesel="1" style="'+bg+'">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(i+1)+'</span>';
    h += '<span class="bar-name">'+d.sku+alertaBadge+pendBadge+'</span>';
    h += '<span class="u-lbl-muted">'+estLabel+'</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+d.marca+'</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque Total: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Pendências: <span class="expand-val" style="color:'+(d.pend>0?'#fbbf24':'#5a6478')+'">'+d.pend.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Cobertura Real: <span class="expand-val" style="color:'+cor+'">'+cobLabel(cob_real)+' (ref: '+VENDA_REF.ddgam.periodo+')</span></div>';
    h += '<div class="expand-item">Marca: <span class="expand-val" style="color:#D1D5DB">'+d.marca+'</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function renderGAMEstoqueLinha(){
  var ctx = document.getElementById('gam-estoque-chart');
  if(!ctx) return;
  if(gamEstoqueChart) gamEstoqueChart.destroy();
  var skus = GAM_ESTOQUE.filter(function(d){return d.estoque>0;}).sort(function(a,b){return b.estoque-a.estoque;}).slice(0,14);
  var labels = skus.map(function(d){return d.sku.length>22?d.sku.substring(0,22)+'…':d.sku;});
  var cores  = skus.map(function(d){return d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';});
  gamEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque Total (un)',data:skus.map(function(d){return d.estoque;}),backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Pendências (un)',data:skus.map(function(d){return d.pend>0?d.pend:null;}),type:'line',borderColor:'#fbbf24',backgroundColor:'transparent',pointBackgroundColor:'#fbbf24',pointRadius:7,pointBorderWidth:2,borderWidth:2,tension:0.3,yAxisID:'y'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{
      legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
        callbacks:{label:function(c){if(c.datasetIndex===0)return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';return ' Pendência: '+c.raw.toLocaleString('pt-BR')+' un';}}}
    },
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},title:{display:true,text:'Unidades',color:'#475569',font:{size:9}}}
    }
  }});
}

/* ═══════════ DD-GAM ═══════════ */
var gamBarMode='rec', gamDonutYear='2024', gamRankYear='2024', gamLojaMetric='rec', gamCidMetric='rec';
function initGAM(){
  (function(){
    var totalPend = GAM_ESTOQUE.reduce(function(s,d){return s+(d.pend||0);},0);
    var skusPend  = GAM_ESTOQUE.filter(function(d){return (d.pend||0)>0;}).length;
    var atencao   = GAM_ESTOQUE.filter(function(d){return d.estoque>0&&d.estoque<800;}).length;
    var pendEl = document.getElementById('gam-kpi-pend');
    if(pendEl){
      var pVal=pendEl.querySelector('div:nth-child(2)'), pSub=pendEl.querySelector('div:nth-child(3)');
      if(pVal){pVal.style.color=totalPend>0?'#fbbf24':'#34d399'; pVal.textContent=totalPend.toLocaleString('pt-BR');}
      if(pSub) pSub.textContent=totalPend>0?(skusPend+' SKUs com pedidos abertos'):'Sem pedidos em aberto';
    }
    var atEl = document.getElementById('gam-kpi-atenc');
    if(atEl){
      var aVal=atEl.querySelector('div:nth-child(2)');
      if(aVal){aVal.style.color=atencao>0?'#fbbf24':'#34d399'; aVal.textContent=atencao;}
    }
  }());
  /* Dias de estoque GAM */
  (function(){
    var tEst=GAM_ESTOQUE.reduce(function(s,d){return s+(d.estoque||0);},0);
    var tVnd=GAM_ESTOQUE.reduce(function(s,d){return s+(d.venda_abr||d.giro||0);},0);
    var dias=tVnd>0?Math.round(tEst/tVnd*30):0;
    var el=document.getElementById('gam-kpi-dias');
    if(el){var v=el.querySelector('div:nth-child(2)');var s=el.querySelector('div:nth-child(3)');
      if(v){v.textContent=dias>0?dias+' dias':'—';v.style.color=dias>0&&dias<60?'#06b6d4':dias<120?'#fbbf24':'#34d399';}
      if(s) s.textContent='Cobertura média (dias)';}
  }());
  renderKPIs('gam-kpis', getKpisForClient('gam'));
  renderGAMAnoBars(); renderGAMDonut(); renderGAMLine(); renderGAMClientes(); renderGAMCidades(); renderGAMRank(); renderGAMMeta();
  renderGAMEstoqueBarras();

}

function renderGAMAnoBars(){
  var isVol = gamBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var vals = isVol ? [347234,512401,244932] : [6774625,8367723,4216399.430000001];
  renderAnoChart('gam-ano-chart', anos, vals, isVol);
}
function setGAMBarMode(m,btn){gamBarMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGAMAnoBars();}

function renderGAMDonut(){
  var rows=(GAM_RANK[gamDonutYear]||GAM_RANK['2024']).slice(0,6);
  renderDonut('gam-donut','gam-donut-legend',rows.map(function(r){return{nome:r[0],val:r[1],color:r[2]};}));
}
function setGAMDonutYear(y,btn){gamDonutYear=y;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGAMDonut();}

function renderGAMLine(){
  var isVol = gamLineMode === 'vol';
  var d24 = isVol ? GAM_VOL['2024'] : GAM_REC['2024'];
  var d25 = isVol ? GAM_VOL['2025'] : GAM_REC['2025'];
  var d26 = isVol ? GAM_VOL['2026'] : GAM_REC['2026'];
  renderLineChart('gam-line',[
    {label:'2024',data:d24,color:'#3b82f6'},
    {label:'2025',data:d25,color:'#2dd4bf'},
    {label:'2026',data:d26,color:'#34d399',dashed:true},
  ],'gam-line-legend', isVol);
}

function renderGAMClientes(){
  var total=GAM_LOJAS.reduce(function(s,l){return s+l.rec;},0);
  var items=GAM_LOJAS.map(function(l,i){
    var val=gamLojaMetric==='rec'?l.rec:l.vol;
    var share=((l.rec/total)*100).toFixed(1);
    return{nome:l.nome,val:val,color:LOJA_COLORS[i],share:share,
      extraFields:[{label:'Receita: ',val:fmtFull(l.rec)},{label:'Volume: ',val:fmtVol(l.vol)},{label:'Ticket: ',val:'R$ '+(l.rec/l.vol).toFixed(2)}]};
  });
  renderBars('gam-clientes-bars',items,{isVol:gamLojaMetric==='vol',hbar:true});
}
function setGAMLojaMetric(m,btn){gamLojaMetric=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGAMClientes();}

function renderGAMCidades(){
  var total=GAM_CIDADES.reduce(function(s,c){return s+c.rec;},0);
  renderUFBar('gam-uf-bar','gam-uf-legend',GAM_CIDADES.map(function(c){return{uf:c.nome.split('/')[1]||'PR',rec:c.rec};}));
  var items=GAM_CIDADES.map(function(c,i){
    var uf=c.nome.split('/')[1]||'PR';
    var val=gamCidMetric==='rec'?c.rec:c.vol;
    var share=((c.rec/total)*100).toFixed(1);
    return{nome:c.nome.split('/')[0],val:val,uf:uf,color:UF_COLORS[uf]||LOJA_COLORS[i],share:share,
      extraFields:[{label:'Receita: ',val:fmtFull(c.rec)},{label:'Volume: ',val:fmtVol(c.vol)},{label:'Share: ',val:share+'%'}]};
  });
  renderBars('gam-cidades-bars',items,{isVol:gamCidMetric==='vol',hbar:true});
}
function setGAMCidMetric(m,btn){gamCidMetric=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue','purple');});btn.classList.add('active','purple');renderGAMCidades();}

function renderGAMRank(){
  var rows=(GAM_RANK[gamRankYear]||GAM_RANK['2024']);
  renderRankBars('gam-rank-bars',rows,'vol');
}
function setGAMRankYear(y,btn){gamRankYear=y;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGAMRank();}

