var gchEstoqueView  = 'barras';
var gchEstoqueChart = null;

function renderGCHEstoqueBarras(){
  var el = document.getElementById('gch-estoque-bars');
  if(!el) return;
  var maxEst = Math.max.apply(null, GCH_ESTOQUE.map(function(d){return d.estoque;}));
  var MARCA_CORES = {OFF:'#3b82f6', EXPOSIS:'#34d399', RAID:'#f97316', GLADE:'#2dd4bf', LYSOFORM:'#60a5fa', OUTROS:'#D1D5DB'};
  var h = '';
  GCH_ESTOQUE.slice().sort(function(a,b){return b.estoque-a.estoque;}).forEach(function(d,i){
    var cor = MARCA_CORES[d.marca] || '#D1D5DB';
    var cob_real = d.dem > 0 ? Math.round((d.estoque / d.dem) * 30) : 999;
    var risco_real = calcRisco(cob_real);
    var cobStr = cobLabel(cob_real);
    cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':cor;
    var bg = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
             risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = Math.max(1, Math.round(d.estoque/maxEst*100));
    var alertaBadge = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:4px;">'+(risco_real==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'):'';
    var demBadge = d.dem>0?('<span style="font-size:9px;color:#fbbf24;margin-left:6px;">dem: '+d.dem.toLocaleString('pt-BR')+' un</span>'):'';
    h += '<div class="bar-item" style="'+bg+'" data-togglesel="1">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(GCH_ESTOQUE.length-i)+'</span>';
    h += '<span class="bar-name">'+d.sku+alertaBadge+'</span>';
    h += '<span class="u-lbl-muted">'+d.estoque.toLocaleString('pt-BR')+' un'+demBadge+'</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+cobStr+' cob.</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Venda Set/26: <span class="expand-val" style="color:#fbbf24">'+d.dem.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Cobertura: <span class="expand-val" style="color:'+cor+'">'+cobStr+'</span></div>';
    h += '<div class="expand-item">Marca: <span class="expand-val" style="color:#D1D5DB">'+d.marca+'</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function renderGCHEstoqueLinha(){
  var ctx = document.getElementById('gch-estoque-chart');
  if(!ctx) return;
  if(gchEstoqueChart) gchEstoqueChart.destroy();
  var MARCA_CORES = {OFF:'#3b82f6', EXPOSIS:'#34d399', RAID:'#f97316', GLADE:'#2dd4bf', LYSOFORM:'#60a5fa', OUTROS:'#D1D5DB'};
  var skus = GCH_ESTOQUE.filter(function(d){return d.estoque>0;}).sort(function(a,b){return b.estoque-a.estoque;}).slice(0,14);
  var labels = skus.map(function(d){return d.sku.length>22?d.sku.substring(0,22)+'…':d.sku;});
  var cores = skus.map(function(d){return MARCA_CORES[d.marca]||'#D1D5DB';});
  gchEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque (un)',data:skus.map(function(d){return d.estoque;}),backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Cobertura (d)',data:skus.map(function(d){return d.cob>=999?null:Math.min(d.cob,600);}),type:'line',borderColor:'#fbbf24',backgroundColor:'transparent',pointBackgroundColor:cores,pointRadius:5,borderWidth:2,tension:0.3,yAxisID:'y2'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
        callbacks:{label:function(c){if(c.datasetIndex===0)return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';return ' Cobertura: '+(c.raw!=null?c.raw+'d':'-');}}}},
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},title:{display:true,text:'Estoque (un)',color:'#475569',font:{size:9}}},
      y2:{position:'right',grid:{display:false},ticks:{color:'#fbbf24',font:{size:9},callback:function(v){return v+'d';}},title:{display:true,text:'Cobertura (d)',color:'#fbbf24',font:{size:9}},min:0,max:600}
    }
  }});
}

function setGchEstoqueView(view, btn){
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  gchEstoqueView = view;
  document.getElementById('gch-estoque-barras').style.display = view==='barras'?'block':'none';
  document.getElementById('gch-estoque-linha').style.display  = view==='linha'?'block':'none';
  var tendEl_gch = document.getElementById('gch-estoque-tend');
  if(tendEl_gch) tendEl_gch.style.display = view==='tend'?'block':'none';
  if(view==='linha') renderGCHEstoqueLinha(); else renderGCHEstoqueBarras();
}

/* ═══════════ DD-GAÚCHA ═══════════ */
var gchBarMode='rec', gchRankYear='2026';
function initGCH(){
  /* Dias de estoque GCH */
  (function(){
    var tEst=GCH_ESTOQUE.reduce(function(s,d){return s+(d.estoque||0);},0);
    var tVnd=GCH_ESTOQUE.reduce(function(s,d){return s+(d.venda_abr||d.dem||0);},0);
    var dias=tVnd>0?Math.round(tEst/tVnd*30):0;
    var el=document.getElementById('gch-kpi-dias');
    if(el){var v=el.querySelector('div:nth-child(2)');var s=el.querySelector('div:nth-child(3)');
      if(v){v.textContent=dias>0?dias+' dias':'—';v.style.color=dias>0&&dias<60?'#06b6d4':dias<120?'#fbbf24':'#34d399';}
      if(s) s.textContent='Cobertura média (dias)';}
  }());
  renderKPIs('gch-kpis', getKpisForClient('gch'));
  renderGCHAnoBars(); renderGCHDonut(); renderGCHLine(); renderGCHPDVs(); renderGCHCidades(); renderGCHMeta();
  renderGCHEstoqueBarras();
}

function renderGCHAnoBars(){
  var isVol = gchBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var vals = isVol ? [285777,208032,87440] : [5391920,3011631.08,1479401.92];
  renderAnoChart('gch-ano-chart', anos, vals, isVol);
}
function setGCHBarMode(m,btn){gchBarMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGCHAnoBars();}

function renderGCHDonut(){
  var marcas=[
    {nome:'OFF (Family/Kids/Baby)',val:62,color:'#3b82f6'},
    {nome:'EXPOSIS (Inf/Extreme)',val:18,color:'#2dd4bf'},
    {nome:'RAID (Multi/Elétrico)',val:14,color:'#34d399'},
    {nome:'Outros',val:6,color:'#D1D5DB'},
  ];
  renderDonut('gch-donut','gch-donut-legend',marcas);
}

function renderGCHLine(){
  var isVol = gchLineMode === 'vol';
  var d24 = isVol ? GAUCHA_VOL['2024'] : GAUCHA_REC['2024'];
  var d25 = isVol ? GAUCHA_VOL['2025'] : GAUCHA_REC['2025'];
  var d26 = isVol ? GAUCHA_VOL['2026'] : GAUCHA_REC['2026'];
  renderLineChart('gch-line',[
    {label:'2024',data:d24,color:'#3b82f6'},
    {label:'2025',data:d25,color:'#2dd4bf'},
    {label:'2026',data:d26,color:'#34d399',dashed:true},
  ],'gch-line-legend', isVol);
}

var gchLojaMetric = 'rec';
var gchCidMetric  = 'rec';

function renderGCHPDVs(){
  var rows=(GAUCHA_PDVS[gchRankYear]||GAUCHA_PDVS['2026']);
  var isVol = gchLojaMetric === 'vol';
  var items=rows.map(function(r,i){
    var val = isVol ? (r[2]||0) : r[1];
    return{nome:r[0].split('|')[0].trim(), val:val, color:LOJA_COLORS[i],
      extraFields:[{label:'Receita: ',val:fmtFull(r[1])},{label:'Volume: ',val:fmtVol(r[2]||0)}]};
  });
  renderBars('gch-pdv-bars',items,{isVol:isVol,hbar:true});
}
function setGCHRankYear(y,btn){gchRankYear=y;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGCHPDVs();}
function setGCHLojaMetric(m,btn){gchLojaMetric=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderGCHPDVs();}

function renderGCHCidades(){
  renderUFBar('gch-uf-bar','gch-uf-legend',GAUCHA_CIDADES.map(function(c){return{uf:c.uf,rec:c.rec};}));
  var total=GAUCHA_CIDADES.reduce(function(s,c){return s+c.rec;},0);
  var isVol = gchCidMetric === 'vol';
  var items=GAUCHA_CIDADES.slice().sort(function(a,b){return b.rec-a.rec;}).map(function(c,i){
    var share=((c.rec/total)*100).toFixed(1);
    var val = isVol ? (c.vol||0) : c.rec;
    return{nome:c.nome,val:val,uf:c.uf,color:UF_COLORS[c.uf]||LOJA_COLORS[i],share:share,
      extraFields:[{label:'Receita: ',val:fmtFull(c.rec)},{label:'Volume: ',val:fmtVol(c.vol||0)}]};
  });
  renderBars('gch-cid-bars',items,{isVol:isVol,hbar:true});
}
function setGCHCidMetric(m,btn){gchCidMetric=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue','purple');});btn.classList.add('active','purple');renderGCHCidades();}

var gchMetaMode = 'rec';
function setGCHMetaMode(mode, btn){
  gchMetaMode = mode;
  document.querySelectorAll('[onclick*="setGCHMetaMode"]').forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn) btn.classList.add('active','blue');
  renderGCHMeta();
}
function renderGCHMeta(){
  var isVol = gchMetaMode === 'vol';
  renderMetaTable('gch-meta-wrap', MESES,
    isVol ? GAUCHA_VOL['2024'] : GAUCHA_REC['2024'],
    isVol ? GAUCHA_VOL['2025'] : GAUCHA_REC['2025'],
    isVol ? GAUCHA_VOL['2026'] : GAUCHA_REC['2026'],
    isVol);
}

var rioMetaMode = 'rec';
function setRioMetaMode(mode, btn){
  rioMetaMode = mode;
  document.querySelectorAll('[onclick*="setRioMetaMode"]').forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn) btn.classList.add('active','blue');
  renderRioMeta();
}
function renderRioMeta(){
  var isVol = rioMetaMode === 'vol';
  renderMetaTable('rio-meta-wrap', MESES,
    isVol ? RIOMED_VOL_2024 : RIOMED_REC_2024,
    isVol ? RIOMED_VOL_2025 : RIOMED_REC_2025,
    isVol ? RIOMED_VOL_2026 : RIOMED_REC_2026,
    isVol);
}

