var rioEstoqueView  = 'barras';
var rioEstoqueChart = null;

function renderRIOEstoqueBarras(){
  var el = document.getElementById('rio-estoque-bars');
  if(!el) return;
  var maxEst = Math.max.apply(null, RIO_ESTOQUE.map(function(d){return d.estoque;}));
  var MARCA_CORES = {OFF:'#3b82f6', EXPOSIS:'#34d399', RAID:'#f97316', GLADE:'#2dd4bf', LYSOFORM:'#60a5fa', OUTROS:'#D1D5DB'};
  var h = '';
  RIO_ESTOQUE.slice().sort(function(a,b){return b.estoque-a.estoque;}).forEach(function(d,i){
    var cor = MARCA_CORES[d.marca] || '#D1D5DB';
    var cob_real = d.vendaMar > 0 ? Math.round((d.estoque / d.vendaMar) * 30) : 999;
    var risco_real = calcRisco(cob_real);
    var cobStr = cobLabel(cob_real);
    cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':cor;
    var bg = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
             risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = Math.max(1, Math.round(d.estoque/maxEst*100));
    var alertaBadge = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:4px;">'+(risco_real==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'):'';
    var abrBadge = d.vendaAbr>0?('<span style="font-size:9px;color:#fbbf24;margin-left:6px;">abr: '+d.vendaAbr+' un</span>'):'';
    h += '<div class="bar-item" style="'+bg+'" data-togglesel="1">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(RIO_ESTOQUE.length-i)+'</span>';
    h += '<span class="bar-name">'+d.sku+alertaBadge+'</span>';
    h += '<span class="u-lbl-muted">'+d.estoque.toLocaleString('pt-BR')+' un'+abrBadge+'</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+cobStr+' cob.</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque atual: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Venda Jul/26: <span class="expand-val" style="color:#D1D5DB">'+d.vendaMar.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Venda Ago/26 parcial: <span class="expand-val" style="color:#fbbf24">'+d.vendaAbr.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Cobertura: <span class="expand-val" style="color:'+cor+'">'+cobStr+' (ref: Mar/26)</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function renderRIOEstoqueLinha(){
  var ctx = document.getElementById('rio-estoque-chart');
  if(!ctx) return;
  if(rioEstoqueChart) rioEstoqueChart.destroy();
  var MARCA_CORES = {OFF:'#3b82f6', EXPOSIS:'#34d399', RAID:'#f97316', GLADE:'#2dd4bf', LYSOFORM:'#60a5fa', OUTROS:'#D1D5DB'};
  var skus = RIO_ESTOQUE.filter(function(d){return d.estoque>0;}).sort(function(a,b){return b.estoque-a.estoque;}).slice(0,14);
  var labels = skus.map(function(d){return d.sku.length>22?d.sku.substring(0,22)+'…':d.sku;});
  var cores = skus.map(function(d){return MARCA_CORES[d.marca]||'#D1D5DB';});
  rioEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque Abr/26',data:skus.map(function(d){return d.estoque;}),backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Venda Mar/26',data:skus.map(function(d){return d.vendaMar;}),type:'line',borderColor:'#fbbf24',backgroundColor:'transparent',pointBackgroundColor:cores,pointRadius:5,borderWidth:2,tension:0.3,yAxisID:'y'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1}},
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}}}
    }
  }});
}

function setRioEstoqueView(view, btn){
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  rioEstoqueView = view;
  document.getElementById('rio-estoque-barras').style.display = view==='barras'?'block':'none';
  document.getElementById('rio-estoque-linha').style.display  = view==='linha'?'block':'none';
  var tendEl_rio = document.getElementById('rio-estoque-tend');
  if(tendEl_rio) tendEl_rio.style.display = view==='tend'?'block':'none';
  if(view==='linha') renderRIOEstoqueLinha(); else renderRIOEstoqueBarras();
}

/* ═══════════ DD-RIOMED ═══════════ */
var rioLineMode = 'vol';
var rioLineChart = null;
var rioBarMode = 'vol';

function renderRIOLine(){
  var ctx = document.getElementById('rio-line');
  if(!ctx) return;
  if(rioLineChart) rioLineChart.destroy();
  var isVol = rioLineMode === 'vol';
  var d24 = isVol ? RIOMED_VOL_2024 : RIOMED_REC_2024;
  var d25 = isVol ? RIOMED_VOL_2025 : RIOMED_REC_2025;
  var d26 = isVol ? RIOMED_VOL_2026 : RIOMED_REC_2026;
  renderLineChart('rio-line',[
    {label:'2024', data:d24, color:'#3b82f6'},
    {label:'2025', data:d25, color:'#2dd4bf'},
    {label:'2026', data:d26, color:'#34d399', dashed:true},
  ],'rio-line-legend', isVol);
}
function setRIOLineMode(m,btn){rioLineMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderRIOLine();}

function renderRioAnoBars(){
  var isVol = rioBarMode==='vol';
  var anos = ['2024','2025','2026*'];
  var vals = isVol ? [92290,63489,26841] : [3111298,1742145,549396.3400000001];
  renderAnoChart('rio-ano-chart', anos, vals, isVol);
}
function setRIOBarMode(m,btn){rioBarMode=m;btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});btn.classList.add('active','blue');renderRIOMesBars();}

function renderRIOMesBars(){
  var isVol = rioBarMode === 'vol';
  var anos = [
    {label:'2024', data: isVol?RIOMED_VOL_2024:RIOMED_REC_2024, color:'#3b82f6'},
    {label:'2025', data: isVol?RIOMED_VOL_2025:RIOMED_REC_2025, color:'#2dd4bf'},
    {label:'2026', data: isVol?RIOMED_VOL_2026:RIOMED_REC_2026, color:'#34d399'},
  ];
  var items = [];
  var mLabels = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  anos.forEach(function(a){
    a.data.forEach(function(v,i){
      if(v!=null && v>0){
        items.push({nome:mLabels[i]+'/'+a.label.slice(2), val:v, color:a.color});
      }
    });
  });
  renderBars('rio-mes-bars', items, {isVol: isVol});
  renderRioAnoBars();
}
function initRiomed(){
  setTimeout(renderRioAnoBars, 100);
  /* Dias de estoque RIO */
  (function(){
    var tEst=RIO_ESTOQUE.reduce(function(s,d){return s+(d.estoque||0);},0);
    var tVnd=RIO_ESTOQUE.reduce(function(s,d){return s+(d.venda_abr||d.vendaAbr||d.vendaMar||0);},0);
    var dias=tVnd>0?Math.round(tEst/tVnd*30):0;
    var el=document.getElementById('rio-kpi-dias');
    if(el){var v=el.querySelector('div:nth-child(2)');var s=el.querySelector('div:nth-child(3)');
      if(v){v.textContent=dias>0?dias+' dias':'—';v.style.color=dias>0&&dias<60?'#06b6d4':dias<120?'#fbbf24':'#34d399';}
      if(s) s.textContent='Cobertura média (dias)';}
  }());
  renderKPIs('rio-kpis', getKpisForClient('rio'));
  renderRIOLine();
  renderRIOMesBars();
  renderDonut('rio-donut','rio-donut-legend',RIOMED_RANK.slice(0,6).map(function(r){return{nome:r[0],val:r[1],color:r[2]};}));
  renderRankBars('rio-rank-bars',RIOMED_RANK,'rec');
  renderRIOEstoqueBarras();
  renderRioMeta();
}

