function renderPositivMensalTable(containerId, d24, d25, d26, highlightYear){
  var el = document.getElementById(containerId);
  if(!el) return;

  /* ── Normalização: aceita array de números OU objetos {mes:"YYYY-MM", positivas} ── */
  function normalizeYear(arr){
    if(!Array.isArray(arr) || !arr.length) return new Array(12).fill(null);
    if(typeof arr[0]==='object' && arr[0]!==null && arr[0].mes){
      var out = new Array(12).fill(null);
      arr.forEach(function(entry){
        if(!entry||!entry.mes) return;
        var parts = String(entry.mes).split('-');
        var idx = parts.length>=2 ? parseInt(parts[1],10)-1 : -1;
        if(idx>=0 && idx<12 && entry.positivas!=null) out[idx]=entry.positivas;
      });
      return out;
    }
    var out2 = new Array(12).fill(null);
    arr.forEach(function(v,i){ if(i<12) out2[i]=(v!=null&&!isNaN(v))?v:null; });
    return out2;
  }

  var r24 = normalizeYear(d24);
  var r25 = normalizeYear(d25);
  var r26 = normalizeYear(d26);

  /* ── LAYOUT SEMPRE FIXO: 5 colunas independente do filtro de ano ── */
  /* Ano selecionado = destaque; outros = levemente dimmed              */
  var hlNone = !highlightYear || highlightYear==='todos';
  function tdStyle(yr){
    if(hlNone) return '';
    return (highlightYear===yr) ? 'font-weight:700;' : 'opacity:0.45;';
  }
  function thStyle(yr, baseColor){
    var base = 'text-align:right;color:'+baseColor+';';
    if(hlNone) return base;
    return base + ((highlightYear===yr)?'font-weight:700;':'opacity:0.45;');
  }

  var html = '<table class="meta-table"><thead><tr>';
  html += '<th style="text-align:left;">Mês</th>';
  html += '<th style="'+thStyle('2024','#3b82f6')+'">2024</th>';
  html += '<th style="'+thStyle('2025','#2dd4bf')+'">2025</th>';
  html += '<th style="'+thStyle('2026','#34d399')+'">2026</th>';
  html += '<th style="text-align:right;color:#94A3B8;">Var% 24×25</th>';
  html += '<th style="text-align:right;color:#94A3B8;">Var% 25×26</th>';
  html += '</tr></thead><tbody>';

  MESES.forEach(function(m, i){
    var v24=r24[i], v25=r25[i], v26=r26[i];
    var vp2425=(v24!=null&&v25!=null&&v24>0)?((v25-v24)/v24*100):null;
    var vp2526=(v25!=null&&v26!=null&&v25>0)?((v26-v25)/v25*100):null;
    var c2425=vp2425===null?'#3d4451':(vp2425>=0?'#34d399':'#ef4444');
    var c2526=vp2526===null?'#3d4451':(vp2526>=0?'#34d399':'#ef4444');
    var ic2425=vp2425===null?'':vp2425>=0?'▲':'▼';
    var ic2526=vp2526===null?'':vp2526>=0?'▲':'▼';
    html += '<tr>';
    html += '<td style="color:#D1D5DB;font-weight:600;">'+m+'</td>';
    /* 2024 */
    html += '<td style="color:#94A3B8;text-align:right;'+tdStyle('2024')+'">';
    html += (v24!=null?v24.toLocaleString('pt-BR'):'<span style="color:#2d3348">—</span>')+'</td>';
    /* 2025 */
    html += '<td style="color:#D1D5DB;text-align:right;'+tdStyle('2025')+'">';
    html += (v25!=null?v25.toLocaleString('pt-BR'):'<span style="color:#2d3348">—</span>')+'</td>';
    /* 2026 */
    html += '<td style="color:#34d399;text-align:right;'+tdStyle('2026')+'">';
    html += (v26!=null?('<strong>'+v26.toLocaleString('pt-BR')+'</strong>'):'<span style="color:#2d3348">—</span>')+'</td>';
    /* Var% 24×25 */
    html += '<td style="text-align:right;">';
    html += (vp2425!==null
      ? '<span style="color:'+c2425+';font-size:10px;font-weight:700;">'+ic2425+' '+Math.abs(vp2425).toFixed(1)+'%</span>'
      : '<span style="color:#2d3348">—</span>')+'</td>';
    /* Var% 25×26 */
    html += '<td style="text-align:right;">';
    html += (vp2526!==null
      ? '<span style="color:'+c2526+';font-size:10px;font-weight:700;">'+ic2526+' '+Math.abs(vp2526).toFixed(1)+'%</span>'
      : '<span style="color:#2d3348">—</span>')+'</td>';
    html += '</tr>';
  });
  /* Linha de totais */
  var tot24=r24.reduce(function(s,v){return s+(v||0);},0);
  var tot25=r25.reduce(function(s,v){return s+(v||0);},0);
  var tot26=r26.filter(Boolean).reduce(function(s,v){return s+v;},0);
  var tv2425=(tot24>0&&tot25>0)?((tot25-tot24)/tot24*100):null;
  var tv2526=(tot25>0&&tot26>0)?((tot26-tot25)/tot25*100):null;
  var tc2425=tv2425===null?'#5a6478':(tv2425>=0?'#34d399':'#ef4444');
  var tc2526=tv2526===null?'#5a6478':(tv2526>=0?'#34d399':'#ef4444');
  html += '<tr style="border-top:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.02);">';
  html += '<td style="font-weight:700;color:#e2e8f0;">TOTAL</td>';
  html += '<td style="text-align:right;color:#94A3B8;font-weight:600;'+tdStyle('2024')+'">'+tot24.toLocaleString('pt-BR')+'</td>';
  html += '<td style="text-align:right;color:#D1D5DB;font-weight:600;'+tdStyle('2025')+'">'+tot25.toLocaleString('pt-BR')+'</td>';
  html += '<td style="text-align:right;color:#34d399;font-weight:800;'+tdStyle('2026')+'">'+tot26.toLocaleString('pt-BR')+'</td>';
  html += '<td style="text-align:right;">'+(tv2425!==null?'<span style="color:'+tc2425+';font-weight:700;">'+(tv2425>=0?'▲':'▼')+' '+Math.abs(tv2425).toFixed(1)+'%</span>':'—')+'</td>';
  html += '<td style="text-align:right;">'+(tv2526!==null?'<span style="color:'+tc2526+';font-weight:700;">'+(tv2526>=0?'▲':'▼')+' '+Math.abs(tv2526).toFixed(1)+'%</span>':'—')+'</td>';
  html += '</tr>';
  el.innerHTML = html + '</tbody></table>';
}

