var avgMarket = 'farmasul';
var avgChart  = null;

function setAvgMarket(mkt){
  avgMarket = mkt;
  var sel = document.getElementById('avgMarketSel');
  if(sel && sel.value !== mkt) sel.value = mkt;
  renderAvgPriceChart();
  setTimeout(renderAvgInsight, 200);
}

function renderAvgPriceChart(){
  avgSetMeses(avgMarket);
  var ctx = document.getElementById('avgPriceChart');
  if(!ctx) return;
  if(avgChart){ avgChart.destroy(); avgChart = null; }

  var src = AVG_DATA[avgMarket] || AVG_DATA.farmasul;
  var GC = 'rgba(59,130,246,0.10)', TC = '#64748b';
  var datasets = AVG_SELECTED.map(function(prod, i){
    return {
      label: prod, data: src[prod],
      borderColor: AVG_CORES_4[i],
      backgroundColor: (function(capCor){return function(fCtx){var ca=fCtx.chart.chartArea;return makeAreaGradient(fCtx.chart.ctx,ca,capCor);};})(AVG_CORES_4[i]),
      fill: 'start',
      pointBackgroundColor: AVG_CORES_4[i], pointRadius: 5, pointHoverRadius: 7,
      borderWidth: 2.5, tension: 0.35, spanGaps: true,
    };
  });
  avgChart = new Chart(ctx, {
    type: 'line',
    data: { labels: AVG_MESES, datasets: datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#F0F4FA', titleColor: '#1e293b', bodyColor: '#475569',
          borderColor: 'rgba(59,130,246,0.2)', borderWidth: 1, padding: 12,
          callbacks: { label: function(c){ return '  ' + c.dataset.label + ': R$ ' + c.raw.toFixed(2); } }
        }
      },
      scales: {
        x: { grid:{color:GC}, ticks:{color:TC, font:{size:11}} },
        y: { grid:{color:GC}, ticks:{color:TC, font:{size:11}, callback:function(v){return 'R$ '+v.toFixed(0);}},
             title:{display:true, text:'Preço médio (R$/un)', color:TC, font:{size:10}} }
      }
    }
  });
  setTimeout(function(){if(avgChart)avgChart.update('none');},50);
  var leg = document.getElementById('avgPriceLegend');
  if(leg){ leg.innerHTML = AVG_SELECTED.map(function(p,i){
    return '<span style="display:flex;align-items:center;gap:5px;color:#475569;">'
      +'<span style="width:20px;height:2.5px;background:'+AVG_CORES_4[i]+';border-radius:2px;display:inline-block;"></span>'+p+'</span>';
  }).join(''); }
}

