const MSO_MONTHS = ['Jul/25','Ago/25','Set/25','Out/25','Nov/25','Dez/25','Jan/26','Fev/26','Mar/26','Abr/26','Mai/26','Jun/26'];
const MSO_BRANDS = ['OFF!','EXPOSIS','XO INSETO','SUPER REPELEX','SBP','ALL OTHERS CAMP'];
const MSO_COLORS = {'OFF!':'#fbbf24','EXPOSIS':'#3b82f6','XO INSETO':'#ef4444','SUPER REPELEX':'#f97316','SBP':'#06b6d4','ALL OTHERS CAMP':'#94a3b8'};
var msoBarChart = null, msoLineChart = null;

function renderMSO(){
  var mkt = document.getElementById('msoMarketSel').value;
  var d = MKTSHARE_OVERVIEW[mkt];
  if(!d) return;
  var _F = nqFY(mkt);
  var _fyEl=document.getElementById('msoFySel'), _fy=(typeof NQ_FY!=='undefined'?NQ_FY:(_fyEl?_fyEl.value:'FY27')), _lbls=null;
  if(_fyEl) _fyEl.disabled = nqIsOld(mkt);
  if(!nqIsOld(mkt) && typeof NQ_PR!=='undefined' && NQ_PR.mk[mkt]){
    var P=NQ_PR.mk[mkt], TT=P['TOTAL MERCADO'].v, dd={};
    var rng=function(x,y){var r=[];for(var i=x;i<=y;i++)r.push(i);return r;};
    var shr=function(br,ix){var s=0,t=0;ix.forEach(function(i){ if(P[br].v[i]!=null&&TT[i]!=null){s+=P[br].v[i];t+=TT[i];} }); return t?Math.round(s/t*10000)/100:null;};
    MSO_BRANDS.forEach(function(b){ if(!P[b]) return; var prev,cur,idx;
      if(_fy==='CAL'){ var q=nqCalP(); prev=shr(b,q.prev); cur=shr(b,q.cur); idx=q.cur; }
      else if(_fy==='ROLL'){ var q=nqL12(); prev=shr(b,q.prev); cur=shr(b,q.cur); idx=q.cur; }
      else if(_fy==='FY26'){ prev=shr(b,rng(0,11)); cur=shr(b,rng(12,23)); idx=rng(12,23); }
      else { prev=P[b].s26; cur=P[b].s27; idx=rng(24,35); }
      dd[b]={fytd25:prev, fytd26:cur, delta:(prev!=null&&cur!=null)?Math.round((cur-prev)*100)/100:0, roll12:idx.map(function(i){return i<P[b].s.length?P[b].s[i]:null;})};
    });
    d = dd;
    _F = (_fy==='ROLL'||_fy==='CAL') ? nqFY(mkt) : _fy==='FY26' ? {p2:'FY24',p:'FY25',c:'FY26',fp:'FY25',fc:'FY26',per:'Jul–Jun',serie:'Jul/25–Jun/26',base:''}
                      : {p2:'FY25',p:'FY26',c:'FY27',fp:'FYTD26',fc:'FYTD27',per:'Jul–Out',serie:'Jul/26–Jun/27',base:''};
    _lbls = _fy==='CAL' ? nqCalP().cur.map(function(i){return NQ_PR.meses[i];}) : _fy==='ROLL' ? nqL12().cur.map(function(i){return NQ_PR.meses[i];}) : _fy==='FY26' ? NQ_PR.meses.slice(12,24) : ['Jul/26','Ago/26','Set/26','Out/26','Nov/26','Dez/26','Jan/27','Fev/27','Mar/27','Abr/27','Mai/27','Jun/27'];
  }
  var _mb=document.getElementById('mso-bar-lbl'); if(_mb) _mb.textContent=_F.fp+' vs '+_F.fc+(nqIsOld(mkt)?'':' ('+_F.per+')');
  var _ms = document.getElementById('mso-sub'); if(_ms) _ms.textContent = _F.fc+' vs '+_F.fp+' ('+_F.per+') · Série '+_F.serie+' · OFF! · EXPOSIS · XO INSETO · SUPER REPELEX · SBP'+_F.base;
  var _me = document.getElementById('mso-evol-lbl'); if(_me) _me.textContent = 'EVOLUÇÃO MENSAL — '+_F.serie.replace('–',' a ');
  var GC = 'rgba(59,130,246,0.10)', TC = '#64748b';
  var CO = {backgroundColor:'#F0F4FA',titleColor:'#1e293b',bodyColor:'#475569',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,padding:10};

  // ── Headline ──
  var off = d['OFF!']; var exp = d['EXPOSIS'];
  var scj_f25 = Math.round((off.fytd25 + exp.fytd25)*10)/10;
  var scj_f26 = Math.round((off.fytd26 + exp.fytd26)*10)/10;
  var scj_d   = Math.round((scj_f26-scj_f25)*10)/10;
  var headline = '<strong style="color:#e2e8f0;">'+mkt+'</strong> · ';
  headline += 'OFF! <span style="color:'+(off.delta>=0?'#34d399':'#ef4444')+';font-weight:700;">'+(off.delta>=0?'▲':'▼')+Math.abs(off.delta).toFixed(2)+'pp</span>';
  headline += ' &nbsp;|&nbsp; EXPOSIS <span style="color:'+(exp.delta>=0?'#34d399':'#ef4444')+';font-weight:700;">'+(exp.delta>=0?'▲':'▼')+Math.abs(exp.delta).toFixed(2)+'pp</span>';
  headline += ' &nbsp;|&nbsp; SCJ Combined: <span style="color:#fbbf24;font-weight:700;">'+scj_f26+'%</span>';
  headline += ' <span style="color:'+(scj_d>=0?'#34d399':'#ef4444')+';font-size:11px;">'+(scj_d>=0?'▲':'▼')+Math.abs(scj_d).toFixed(1)+'pp vs '+_F.fp+'</span>';
  document.getElementById('mso-headline').innerHTML = headline;

  // ── KPIs ──
  document.getElementById('mso-kpis').innerHTML = MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';}).map(function(b){
    var bd = d[b]; var cor = MSO_COLORS[b];
    var dstr = (bd.delta>=0?'▲':'▼')+Math.abs(bd.delta).toFixed(2)+'pp';
    var dcol = bd.delta>=0?'#34d399':'#ef4444';
    return '<div style="background:#161B22;border-radius:10px;padding:12px 14px;border-top:2px solid '+cor+';">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">'+b+'</div>'
      +'<div style="display:flex;align-items:baseline;gap:6px;">'
        +'<span style="font-size:22px;font-weight:800;color:'+cor+';line-height:1;">'+bd.fytd26+'%</span>'
        +'<span style="font-size:10px;font-weight:700;color:'+dcol+';">'+dstr+'</span>'
      +'</div>'
      +'<div style="font-size:10px;color:#94A3B8;margin-top:3px;">'+_F.fp+': '+bd.fytd25+'%</div>'
    +'</div>';
  }).join('');

  // ── Bar chart FYTD ──
  var chartBrands = MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';});
  if(msoBarChart) msoBarChart.destroy();
  var bCtx = document.getElementById('mso-bar');
  if(bCtx){
    msoBarChart = new Chart(bCtx,{
      type:'bar',
      data:{
        labels: chartBrands,
        datasets:[
          {label:_F.fp, data:chartBrands.map(function(b){return d[b].fytd25;}),
           backgroundColor:'#CBD5E1', borderColor:'#94A3B8', borderWidth:1.5, borderRadius:8},
          {label:_F.fc, data:chartBrands.map(function(b){return d[b].fytd26;}),
           backgroundColor:chartBrands.map(function(b){return MSO_COLORS[b]+'bb';}),
           borderColor:chartBrands.map(function(b){return MSO_COLORS[b];}), borderWidth:1.5, borderRadius:8},
        ]
      },
      options:{responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},
          tooltip:{backgroundColor:'#F0F4FA',titleColor:'#1e293b',bodyColor:'#475569',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,padding:10,callbacks:{label:function(c){return ' '+c.dataset.label+': '+c.raw+'%';}}}},
        scales:{
          x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},
          y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return v+'%';}},min:0}
        }}
    });
  }

  // ── Line chart monthly ──
  if(msoLineChart) msoLineChart.destroy();
  var lCtx = document.getElementById('mso-line');
  if(lCtx){
    var datasets = chartBrands.map(function(b,i){
      var col = MSO_COLORS[b];
      return {label:b, data:(d[b].roll12||d[b].monthly), borderColor:col,
              backgroundColor:function(ctx){var ca=ctx.chart.chartArea;return makeAreaGradient(ctx.chart.ctx,ca,col);},
              pointBackgroundColor:col, pointBorderColor:'#101828', pointBorderWidth:1.5,
              pointRadius:4, pointHoverRadius:7, borderWidth:2.5, tension:0.4, fill:true};
    });
    msoLineChart = new Chart(lCtx,{type:'line',data:{labels:(_lbls||(nqIsOld(mkt)?MSO_MONTHS:NQ_ROLL_LABELS)),datasets:datasets},
      options:{responsive:true,maintainAspectRatio:false,
        interaction:{mode:'index',intersect:false},
        plugins:{legend:{display:false},
          tooltip:{backgroundColor:'#F0F4FA',titleColor:'#1e293b',bodyColor:'#475569',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,padding:10,callbacks:{label:function(c){return ' '+c.dataset.label+': '+c.raw+'%';}}}},
        scales:{
          x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},
          y:{grid:{color:GC},ticks:{color:TC,font:{size:10},callback:function(v){return v+'%';}}}
        }}
    });
    // Custom legend
    var leg = document.getElementById('mso-line-legend');
    if(leg) leg.innerHTML = chartBrands.map(function(b){
      return '<span style="display:flex;align-items:center;gap:4px;font-size:10px;color:#D1D5DB;">'
        +'<span style="width:16px;height:2px;background:'+MSO_COLORS[b]+';display:inline-block;border-radius:1px;"></span>'+b+'</span>';
    }).join('');
  }
  // ── Diagnóstico dinâmico mso-insight ──
  var insEl = document.getElementById('mso-insight');
  if(insEl){
    function _dc(v){ return v>0?'#34d399':v<0?'#ef4444':'#94A3B8'; }
    function _pp(v){ return (v>0?'+':'')+v.toFixed(2)+'pp'; }
    var lines = ['<strong style="color:#1D6FA8;font-size:10px;font-weight:700;">📊 DIAGNÓSTICO · '+mkt+'</strong>'];
    /* OFF! */
    var offDc = _dc(off.delta);
    lines.push('📦 <strong style="color:#fbbf24;">OFF!</strong> '
      +(off.delta>=0?'ganhou':'perdeu')
      +' <strong style="color:'+offDc+';">'+_pp(off.delta)+'</strong>'
      +' de share '+_F.fc+' vs '+_F.fp+' em <strong style="color:#334155;">'+mkt+'</strong>'
      +' — atual: <strong style="color:'+_dc(off.fytd26-off.fytd25)+';">'+off.fytd26+'%</strong>.');
    /* SCJ Combined */
    var scjDc = _dc(scj_d);
    var scjArr = scj_d>=0?'▲':'▼';
    lines.push('🏆 <strong style="color:#fbbf24;">SCJ Combined</strong> (OFF!+EXPOSIS): <strong style="color:#e2e8f0;">'+scj_f26+'%</strong> '+_F.fc
      +' <span style="color:'+scjDc+';">'+scjArr+' '+Math.abs(scj_d).toFixed(1)+'pp</span> vs '+_F.fp+'.');
    /* Maior concorrente por delta absoluto */
    var competitors = MSO_BRANDS.filter(function(b){ return b!=='OFF!'&&b!=='EXPOSIS'&&b!=='ALL OTHERS CAMP'; });
    if(competitors.length>0){
      var topC = competitors.slice().sort(function(a,b){ return Math.abs(d[b].delta)-Math.abs(d[a].delta); })[0];
      var tc = d[topC];
      if(tc){
        var tcc = _dc(tc.delta);
        lines.push((tc.delta>=0?'⚠️':'✅')+' <strong style="color:'+tcc+';">'+topC+'</strong>: '
          +tc.fytd26+'% share '+_F.fc+' — '
          +(tc.delta>=0?'crescendo':'recuando')
          +' <strong style="color:'+tcc+';">'+_pp(tc.delta)+'</strong>'
          +(tc.delta>0?', concorrente em expansão.':'.'));
      }
    }
    insEl.innerHTML = lines.join('<br>');
  }

  renderMSO2();
  renderMSO3();
  // ── Curto Prazo ──
  if(typeof renderShrShortTerm==='function') renderShrShortTerm(mkt);
}

