/* ═══ Filtro de ano fiscal (aba Nielsen) ═══ */
function nqApplyFYData(){
  if(!window._NQ27) window._NQ27={AVG:AVG_DATA,OB:OB_DATA,SKU:SKU_MKT_DATA,SKUM:SKU_MKT_MONTHLY,SKUMM:SKU_SHR_MM,ELET:ELET_MKT_DATA,AD:AREA_DECOMP,TR:SHR_TREND_DATA};
  var A=window._NQ27, f=NQ_FY==='FY26', l=NQ_FY==='ROLL', ca=NQ_FY==='CAL';
  function mix(b,o,o12,ocal){ var s=f?o:(l?o12:(ca?ocal:null)); if(!s) return b; var r={},k; for(k in b) r[k]=b[k]; for(k in s) r[k]=s[k]; return r; }
  AVG_DATA=mix(A.AVG,AVG_DATA_FY26); OB_DATA=mix(A.OB,OB_DATA_FY26); SKU_MKT_DATA=mix(A.SKU,SKU_MKT_DATA_FY26,typeof SKU_MKT_DATA_L12!=='undefined'?SKU_MKT_DATA_L12:null,typeof SKU_MKT_DATA_CAL!=='undefined'?SKU_MKT_DATA_CAL:null);
  SKU_MKT_MONTHLY=mix(A.SKUM,SKU_MKT_MONTHLY_FY26,typeof SKU_MKT_MONTHLY_L12!=='undefined'?SKU_MKT_MONTHLY_L12:null,typeof SKU_MKT_CAL!=='undefined'?SKU_MKT_CAL:null); SKU_SHR_MM=mix(A.SKUMM,SKU_SHR_MM_FY26);
  ELET_MKT_DATA=mix(A.ELET,ELET_MKT_DATA_FY26,typeof ELET_MKT_DATA_L12!=='undefined'?ELET_MKT_DATA_L12:null,typeof ELET_MKT_DATA_CAL!=='undefined'?ELET_MKT_DATA_CAL:null); AREA_DECOMP=mix(A.AD,AREA_DECOMP_FY26,typeof AREA_DECOMP_L12!=='undefined'?AREA_DECOMP_L12:null,typeof AREA_DECOMP_CAL!=='undefined'?AREA_DECOMP_CAL:null);
  if(!f){ SHR_TREND_DATA=A.TR; return; }
  var t={};
  for(var m in A.TR){
    if(nqIsOld(m)){ t[m]=A.TR[m]; continue; }
    var o={}; for(var b in A.TR[m]){ var x=A.TR[m][b]; o[b]={fy24:new Array(12).fill(null),fy25:x.fy24,fy26:x.fy25}; }
    t[m]=o;
  }
  SHR_TREND_DATA=t;
}
function nqSetFY(v){
  NQ_FY=(v==='FY26'||v==='ROLL'||v==='CAL')?v:'FY27';
  nqApplyFYData();
  var sel=document.getElementById('nqFySel'); if(sel && sel.value!==NQ_FY) sel.value=NQ_FY;
  var ms=document.getElementById('msoFySel'); if(ms) ms.value=NQ_FY;
  var inf=document.getElementById('nq-fy-info');
  if(inf) inf.textContent = NQ_FY==='CAL' ? ('Ano-calendário = '+nqCalP().perC+' vs '+nqCalP().perP+' · vale para todos os cards da aba') : NQ_FY==='ROLL' ? ('Últimos 12 meses = '+nqL12().perC+' vs 12 meses anteriores = '+nqL12().perP+' · vale para todos os cards da aba') : NQ_FY==='FY26' ? 'FY26 = Jul/25–Jun/26 (ano fechado) vs FY25 = Jul/24–Jun/25 · vale para todos os cards da aba' : 'FY27 = Jul–Out/26 (parcial) vs mesmo período do FY26 · vale para todos os cards da aba';
  ['renderMSO','renderMSO2','renderMSO3','renderMSOArea','renderShrTrend','renderSkuShrCard','renderMSOSkuJanMar','renderAreaDecomp',
   'renderEletricosCard','renderAvgPriceChart','renderAvgInsight','renderOBShare','renderOBPreco','renderOBVendas','renderOBMercado'].forEach(function(fn){
    try{ if(typeof window[fn]==='function') window[fn](); }catch(e){ console.warn('nqSetFY '+fn, e); }
  });
}
/* ═══ Filtro de mercado global (aba Nielsen) — #nqMktSel move os filtros de todos os cards ═══ */
var NQ_MKT_SELS = {msoMarketSel:'Share por Marca', mso2MarketSel:'Share mensal', mso3MarketSel:'Venda FYTD', msoAreaSel:'Por Área',
  msoSkuJMSel:'SKU média', skuShrMktSel:'Share por SKU', shrTrendMktSel:'Série mensal', eletMarketSel:'Elétricos',
  avgMarketSel:'Preço médio', obMarketSel:'Odor Block · share', obMarketSel2:'Odor Block · preço', obMarketSel4:'Odor Block · mercado'};
function nqMktNorm(t){ return String(t||'').split(' · ')[0].trim(); }
function nqSetMkt(m){
  if(typeof initMSOSkuJM==='function') try{ initMSOSkuJM(); }catch(e){}
  var g=document.getElementById('nqMktSel'); if(g && g.value!==m) g.value=m;
  var falta=[];
  Object.keys(NQ_MKT_SELS).forEach(function(id){
    var s=document.getElementById(id); if(!s) return;
    var os=[].slice.call(s.options);
    var o=os.filter(function(x){return x.value===m;})[0] || os.filter(function(x){return nqMktNorm(x.textContent)===m;})[0];
    if(!o){ falta.push(NQ_MKT_SELS[id]); return; }
    s.value=o.value;
    try{ if(typeof s.onchange==='function') s.onchange.call(s); }catch(e){ console.warn('nqSetMkt '+id, e); }
  });
  var w=document.getElementById('nq-mkt-warn');
  if(w) w.textContent = falta.length ? '⚠ sem dados de '+m+' em: '+falta.join(', ')+' (mantido o mercado anterior)' : '';
}
function nqInitCal(){ try{ var c=nqCalP(); [['nqFySel',' (ano-calendário)'],['msoFySel',' vs '+c.perP]].forEach(function(x){
    var s=document.getElementById(x[0]); if(!s) return; [].forEach.call(s.options,function(o){ if(o.value==='CAL') o.textContent=c.perC+(x[0]==='nqFySel'?x[1]:x[1]); }); }); }catch(e){} }
function nqInitMkt(){
  nqInitCal();
  var g=document.getElementById('nqMktSel'); if(!g) return;
  Object.keys(NQ_MKT_SELS).forEach(function(id){ var s=document.getElementById(id); if(s) s.style.display='none'; });
  nqSetMkt(g.value||'T.BR Farma');
}
window.addEventListener('load', function(){ setTimeout(nqInitMkt, 400); });
/* ═══ Filtro de MARCA global (aba Nielsen) — esconde marcas nos cards de Personal Repellent ═══ */
var NQ_BR_LIST = [['OFF!','OFF!','#fbbf24'],['EXPOSIS','EXPOSIS','#3b82f6'],['XO INSETO','XÔ INSETO','#ef4444'],
  ['SUPER REPELEX','SUPER REPELEX','#f97316'],['SBP','SBP','#06b6d4'],['ALL OTHERS','ALL OTHERS','#94a3b8']];
var NQ_BR_SEL = {}; NQ_BR_LIST.forEach(function(b){ NQ_BR_SEL[b[0]]=true; });
function nqBrOf(t){ /* rótulo (marca, produto, nome de série) → marca canônica; null = não é marca */
  var s=String(t||'').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
  if(!s || s.indexOf('+')>=0) return null;
  if(s.indexOf('OFF')===0) return 'OFF!';
  if(s.indexOf('EXPOSIS')===0) return 'EXPOSIS';
  if(s==='XO' || s.indexOf('XO ')===0 || s.indexOf('XO INSETO')===0) return 'XO INSETO';
  if(s.indexOf('SUPER REPELEX')===0 || s.indexOf('S.REPELEX')===0 || s.indexOf('REPELEX')===0) return 'SUPER REPELEX';
  if(s.indexOf('SBP')===0) return 'SBP';
  if(s.indexOf('ALL OTHERS')===0) return 'ALL OTHERS';
  return null; }
function nqBrOk(t){ var b=nqBrOf(t); return b===null || !!NQ_BR_SEL[b]; }
function nqBrAll(){ return NQ_BR_LIST.every(function(b){ return NQ_BR_SEL[b[0]]; }); }
/* gráficos: séries com nome de marca → hidden; barras com marca no eixo → remove as categorias (arrays mutados no lugar) */
var NQ_BR_CANVAS = /^(mso-bar|mso-line|mso2-line-canvas|mso3-bar-canvas|shr-mini-|sku-shr-bar-|mso-sku-jm-bar-|avgPriceChart)/;
function nqBrCharts(){
  if(typeof Chart==='undefined' || !Chart.getChart) return;
  var panel=document.getElementById('panel-nielsen'); if(!panel) return;
  [].forEach.call(panel.querySelectorAll('canvas[id]'), function(cv){
    if(!NQ_BR_CANVAS.test(cv.id)) return;
    var ch=Chart.getChart(cv); if(!ch || !ch.data) return;
    var ds=ch.data.datasets||[], lb=ch.data.labels||[];
    var dsBr=ds.filter(function(d){ return nqBrOf(d.label); }).length;
    if(dsBr>=1 && dsBr>=ds.length-1){ ds.forEach(function(d){ d.hidden = !nqBrOk(d.label); }); ch.update('none'); return; }
    if(lb.filter(function(l){ return nqBrOf(l); }).length>=2){
      if(!ch.$nqBr || ch.$nqBr.ref!==lb){ lb=lb.slice(); ch.data.labels=lb; }   /* rótulos podem ser compartilhados entre gráficos (SKU esq./dir.) */
      if(!ch.$nqBr || ch.$nqBr.ref!==lb) ch.$nqBr={ref:lb, lb:lb.slice(), ds:ds.map(function(d){ return {data:(d.data||[]).slice(),
        bg:Array.isArray(d.backgroundColor)?d.backgroundColor.slice():null, bc:Array.isArray(d.borderColor)?d.borderColor.slice():null}; })};
      var O=ch.$nqBr, keep=[]; O.lb.forEach(function(l,i){ if(nqBrOk(l)) keep.push(i); });
      var put=function(arr,src){ arr.length=0; keep.forEach(function(i){ arr.push(src[i]); }); };
      put(lb, O.lb);
      ds.forEach(function(d,k){ var o=O.ds[k]; if(!o) return; put(d.data,o.data);
        if(o.bg && Array.isArray(d.backgroundColor)) put(d.backgroundColor,o.bg); if(o.bc && Array.isArray(d.borderColor)) put(d.borderColor,o.bc); });
      ch.update('none');
    }
  });
}
/* KPIs, legendas, tabelas e mini-gráficos por marca */
function nqBrDom(){
  var q=function(sel){ return [].slice.call(document.querySelectorAll(sel)); };
  q('#mso-kpis > *, #mso-kpis > div > *, #mso-line-legend > *').forEach(function(el){
    var t=(el.textContent||'').trim(); if(t.length>90) return;   /* contêiner com várias marcas: não esconder */
    var b=nqBrOf(t.split(/[\d\n]/)[0]); if(b) el.style.display = NQ_BR_SEL[b] ? '' : 'none'; });
  q('#shr-st-table tr, #shr-st-table2 tr, #mso2-table tr, #shr-st-tableSKU tr').forEach(function(tr){
    var c=tr.querySelector('td'); if(!c) return; var b=nqBrOf(c.textContent); if(b) tr.style.display = NQ_BR_SEL[b] ? '' : 'none'; });
  q('#shr-trend-charts canvas[id^="shr-mini-"]').forEach(function(cv){
    var w=cv; while(w.parentElement && w.parentElement.id!=='shr-trend-charts') w=w.parentElement;
    var b=nqBrOf(cv.id.replace('shr-mini-','').replace('XOINSETO','XO INSETO').replace('SUPERREPELEX','SUPER REPELEX'));
    if(b) w.style.display = NQ_BR_SEL[b] ? '' : 'none'; });
}
function nqBrApply(){ try{ nqBrCharts(); nqBrDom(); }catch(e){ console.warn('nqBrApply', e); } }
/* componente: lista suspensa com busca, selecionar todos / limpar / só SCJ, cancelar / aplicar */
var _nqBrTmp=null;
function nqBrRender(){
  var L=document.getElementById('nqBrList'); if(!L) return;
  L.innerHTML=NQ_BR_LIST.map(function(b){ return '<label data-br="'+b[1]+'"><input type="checkbox" value="'+b[0]+'"'+(_nqBrTmp[b[0]]?' checked':'')
    +' onchange="_nqBrTmp[this.value]=this.checked"><span class="nqbr-dot" style="background:'+b[2]+';"></span>'+b[1]+'</label>'; }).join('');
}
function nqBrToggle(ev){ if(ev) ev.stopPropagation(); var w=document.getElementById('nq-br-wrap'); if(!w) return;
  if(w.classList.contains('open')){ nqBrFecha(); return; }
  _nqBrTmp={}; NQ_BR_LIST.forEach(function(b){ _nqBrTmp[b[0]]=!!NQ_BR_SEL[b[0]]; });
  var s=document.getElementById('nqBrSearch'); if(s) s.value=''; nqBrRender(); w.classList.add('open'); }
function nqBrFecha(){ var w=document.getElementById('nq-br-wrap'); if(w) w.classList.remove('open'); }
function nqBrFiltra(v){ var t=String(v||'').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  [].forEach.call(document.querySelectorAll('#nqBrList label'),function(l){
    var n=l.getAttribute('data-br').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g,''); l.style.display = n.indexOf(t)>=0 ? '' : 'none'; }); }
function nqBrMarca(m){ NQ_BR_LIST.forEach(function(b){ _nqBrTmp[b[0]] = m==='todos' ? true : (m==='scj' ? (b[0]==='OFF!'||b[0]==='EXPOSIS') : false); }); nqBrRender();
  var s=document.getElementById('nqBrSearch'); if(s && s.value) nqBrFiltra(s.value); }
function nqBrLabel(){ var on=NQ_BR_LIST.filter(function(b){ return NQ_BR_SEL[b[0]]; });
  var t = on.length===NQ_BR_LIST.length ? 'Todas as marcas' : (on.length===0 ? 'Nenhuma marca' : (on.length<=2 ? on.map(function(b){return b[1];}).join(', ') : on.length+' marcas'));
  var btn=document.getElementById('nqBrBtn'); if(btn) btn.textContent=t; }
function nqBrAplica(){
  if(!NQ_BR_LIST.some(function(b){ return _nqBrTmp[b[0]]; })){ var s=document.querySelector('#nq-br-pop .nqbr-foot span'); if(s){ s.textContent='Marque pelo menos 1 marca'; s.style.color='#dc2626'; } return; }
  NQ_BR_LIST.forEach(function(b){ NQ_BR_SEL[b[0]]=!!_nqBrTmp[b[0]]; });
  var s2=document.querySelector('#nq-br-pop .nqbr-foot span'); if(s2){ s2.textContent='Selecione e aplique'; s2.style.color=''; }
  nqBrLabel(); nqBrFecha(); nqBrApply(); }
document.addEventListener('click', function(e){ var w=document.getElementById('nq-br-wrap'); if(w && w.classList.contains('open') && !w.contains(e.target)) nqBrFecha(); });
/* toda renderização dos cards reaplica o filtro */
function nqBrHook(){
  ['renderMSO','renderMSO2','renderMSO3','nqRenderMSO2','nqRenderMSO3','renderShrTrend','renderShrShortTerm','renderShrShortTerm2',
   'renderSkuShrCard','renderMSOSkuJanMar','renderShrSTSKU','renderAvgPriceChart'].forEach(function(fn){
    var o=window[fn]; if(typeof o!=='function' || o._nqBr) return;
    var w=function(){ var r=o.apply(this, arguments); nqBrApply(); return r; }; w._nqBr=true; window[fn]=w; });
}
window.addEventListener('load', function(){ nqBrHook(); setTimeout(nqBrApply, 600); });
var mso2Mode = 'share'; // 'share' | 'val' | 'un'

function setMSO2Mode(mode, btn){
  mso2Mode = mode;
  ['mso2-mode-share','mso2-mode-val','mso2-mode-un'].forEach(function(id){
    var b = document.getElementById(id);
    if(!b) return;
    var active = (id === 'mso2-mode-'+mode);
    /* toggle classe active (usada pelo CSS !important do NielsenStd) */
    if(active) b.classList.add('active'); else b.classList.remove('active');
    b.style.color      = active ? '#fbbf24' : '#D1D5DB';
    b.style.background = active ? 'rgba(251,191,36,0.12)' : '#161B22';
    b.style.fontWeight = active ? '700' : '600';
  });
  renderMSO2();
}

function renderMSO2(){
  var sel = document.getElementById('mso2MarketSel') || document.getElementById('msoMarketSel');
  var mkt = sel ? sel.value : 'Farma Sul';
  if(!nqIsOld(mkt) && NQ_PR.mk[mkt]){ if(mso2BarChart){try{mso2BarChart.destroy();}catch(e){} mso2BarChart=null;} if(mso2LineChart){try{mso2LineChart.destroy();}catch(e){} mso2LineChart=null;} nqRenderMSO2(mkt); return; }
  var isShare = mso2Mode === 'share';
  var isVal   = mso2Mode === 'val';
  var isUn    = mso2Mode === 'un';

  // Destroy legacy charts
  if(mso2BarChart){ try{mso2BarChart.destroy();}catch(e){} mso2BarChart = null; }
  if(mso2LineChart){ try{mso2LineChart.destroy();}catch(e){} mso2LineChart = null; }

  // Update card labels
  var lbl = document.getElementById('mso2-mkt-lbl');
  if(lbl) lbl.textContent = mkt;
  var titleEl = document.getElementById('mso2-card-title');
  if(titleEl) titleEl.textContent = isShare ? 'MARKET SHARE — JAN · FEV · MAR · ABR · MAI · JUN'
    : (isVal ? 'VENDA VALOR — JAN · FEV · MAR · ABR · MAI · JUN' : 'UNIDADES — JAN · FEV · MAR · ABR · MAI · JUN · JUN');
  var subEl = document.getElementById('mso2-card-sub');
  if(subEl) subEl.innerHTML = (isShare ? 'Acum Jan–Jun/25 vs Jan–Jun/26'
    : (isVal ? 'R$ MM · Jan–Jun/26' : 'Unidades · Jan–Jun/26'))
    + ' · NielsenIQ · <span id="mso2-mkt-lbl">' + mkt + '</span>';
  var h2El = document.getElementById('mso2-card-h2');
  if(h2El) h2El.textContent = isShare ? '$ Share por Marca — 2025 vs 2026'
    : (isVal ? 'Venda R$ MM por Marca — 2025 vs 2026' : 'Volume Unidades por Marca — 2025 vs 2026');

  var brands = MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';});
  var colors = MSO_COLORS;

  /* BUILD VALUE SETS */
  var d25 = {}, d26 = {};
  var GrowthMode = false;

  if(isShare){
    var dS = MKTSHARE_OVERVIEW[mkt]; if(!dS) return;
    brands.forEach(function(b){
      var bd = dS[b]; if(!bd) return;
      var j25 = bd.jan25!=null?bd.jan25:bd.fytd25, f25 = bd.feb25!=null?bd.feb25:bd.fytd25, m25 = bd.mar25!=null?bd.mar25:bd.fytd25, a25 = bd.apr25!=null?bd.apr25:bd.fytd25, mi25 = bd.mai25!=null?bd.mai25:bd.fytd25;
      var j26 = bd.monthly[6], f26 = bd.monthly[7], m26 = bd.monthly[8], a26 = bd.monthly[9]!=null?bd.monthly[9]:0, mi26 = bd.monthly[10]!=null?bd.monthly[10]:0, ju26 = bd.monthly[11]!=null?bd.monthly[11]:mi26;
      d25[b] = {jan:j25, fev:f25, mar:m25, abr:a25, mai:mi25, acum:Math.round((j25+f25+m25+a25+mi25)/5*100)/100};
      d26[b] = {jan:j26, fev:f26, mar:m26, abr:a26, mai:mi26, jun:ju26, acum:Math.round((j26+f26+m26+a26+mi26+ju26)/6*100)/100};
    });
  } else {
    var nbvS = (typeof NIELSEN_BRAND_VAL !== 'undefined') ? NIELSEN_BRAND_VAL[mkt] : null;
    if(!nbvS){ console.warn('No NIELSEN_BRAND_VAL for', mkt); return; }
    brands.forEach(function(b){
      var bd = nbvS[b]; if(!bd) return;
      var j26 = isVal?bd.jan_val:bd.jan_un, f26 = isVal?bd.fev_val:bd.fev_un, m26 = isVal?bd.mar_val:bd.mar_un, ab26 = isVal?(bd.abr_val||0):(bd.abr_un||0), mi26 = isVal?(bd.mai_val||0):(bd.mai_un||0), ju26 = isVal?(bd.jun_val||0):(bd.jun_un||0);
      var fyt25 = isVal?bd.fytd25_val:bd.fytd25_un, fyt26 = isVal?bd.fytd26_val:bd.fytd26_un;
      var a26 = Math.round((j26+f26+m26+ab26+mi26+ju26)*100)/100;
      var hasExact25 = isVal ? (bd.jan25_val!==undefined) : (bd.jan25_un!==undefined);
      var hasAbr25 = isVal ? (bd.abr25_val!==undefined) : (bd.abr25_un!==undefined);
      var hasMai25 = isVal ? (bd.mai25_val!==undefined) : (bd.mai25_un!==undefined);
      var hasJun25 = isVal ? (bd.jun25_val!==undefined) : (bd.jun25_un!==undefined);
      var j25, f25, m25, ab25, mi25, ju25, a25;
      if(hasExact25){
        j25 = isVal?bd.jan25_val:bd.jan25_un;
        f25 = isVal?bd.fev25_val:bd.fev25_un;
        m25 = isVal?bd.mar25_val:bd.mar25_un;
        ab25 = hasAbr25?(isVal?bd.abr25_val:bd.abr25_un):0;
        mi25 = hasMai25?(isVal?bd.mai25_val:bd.mai25_un):0;
        ju25 = hasJun25?(isVal?bd.jun25_val:bd.jun25_un):0;
        a25 = Math.round((j25+f25+m25+ab25+mi25+ju25)*100)/100;
      } else {
        j25 = null; f25 = null; m25 = null; ab25 = null; mi25 = null; ju25 = null;
        var ratio = fyt26>0 ? a26/fyt26 : 1/6;
        a25 = Math.round(fyt25*ratio*100)/100;
        GrowthMode = true;
      }
      d25[b] = {jan:j25, fev:f25, mar:m25, abr:ab25, mai:mi25, jun:ju25, acum:a25, fytd25:fyt25, fytd26:fyt26, hasExact:hasExact25};
      d26[b] = {jan:j26, fev:f26, mar:m26, abr:ab26, mai:mi26, jun:ju26, acum:a26};
    });
  }

  /* HELPERS */
  function fmtV(v){
    if(v===null||v===undefined) return '—';
    if(isShare) return v.toFixed(2)+'%';
    if(isVal) return v>=1?'R$'+v.toFixed(2)+'MM':'R$'+(v*1000).toFixed(0)+'K';
    return v>=1000?(Math.round(v/1000*10)/10)+'MM un':Math.round(v)+'K un';
  }
  function calcDelta(v25, v26){
    if(isShare){
      var dv = Math.round((v26-v25)*100)/100;
      return {str:(dv>=0?'+':'')+dv.toFixed(2)+'pp', col:dv>=0?'#34d399':'#ef4444', up:dv>=0, raw:dv};
    } else {
      var p = v25>0 ? Math.round((v26-v25)/v25*1000)/10 : 0;
      return {str:(p>=0?'+':'')+p.toFixed(1)+'%', col:p>=0?'#34d399':'#ef4444', up:p>=0, raw:p};
    }
  }

  /* MAX VALUE FOR BAR SCALING */
  var allV = [];
  brands.forEach(function(b){ if(d25[b]) allV.push(d25[b].acum); if(d26[b]) allV.push(d26[b].acum); });
  var maxV = Math.max.apply(null, allV) || 1;

  /* KPI CHIPS (mso2-headline) */
  var hdEl = document.getElementById('mso2-headline');
  if(hdEl){
    function kpiChip(borderColor, label, value, valueCss, sub, subCss){
      return '<div style="padding:14px 18px;background:#0D1117;border-top:3px solid '+borderColor+';">'
        +'<div style="font-size:9px;color:#64748b;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px;">'+label+'</div>'
        +'<div style="font-size:24px;font-weight:900;'+valueCss+';line-height:1;">'+value+'</div>'
        +'<div style="font-size:10px;'+subCss+';margin-top:5px;">'+sub+'</div>'
        +'</div>';
    }
    if(isShare){
      /* Chips Share: usa Mar/26 (mes mais recente) — consistente com tooltip do grafico */
      var off26a = d26['OFF!']?d26['OFF!'].jun:0, exp26a = d26['EXPOSIS']?d26['EXPOSIS'].jun:0;
      var off25a = d25['OFF!']?d25['OFF!'].mai:0, exp25a = d25['EXPOSIS']?d25['EXPOSIS'].mai:0;
      var scj26h = Math.round((off26a+exp26a)*10)/10, scj25h = Math.round((off25a+exp25a)*10)/10;
      var scjDh = Math.round((scj26h-scj25h)*10)/10;
      var leaderB = brands.reduce(function(best,b){ return (d26[b]&&(!d26[best]||d26[b].mai>d26[best].mai))?b:best; }, brands[0]);
      var deltasKpi = brands.map(function(b){ return {b:b,raw:d26[b]&&d25[b]?Math.round((d26[b].jun-(d25[b].mai!=null?d25[b].mai:d25[b].acum))*100)/100:0}; });
      deltasKpi.sort(function(a,b){return b.raw-a.raw;});
      var topG = deltasKpi[0], topL = deltasKpi[deltasKpi.length-1];
      /* TOTAL MERCADO chip — Share mode */
      var fytMktShare=(typeof FYTD_MARKET_TOTAL!=='undefined')?FYTD_MARKET_TOTAL[mkt]:null;
      var mktS26=fytMktShare?((fytMktShare.janmar26_val||0)+(fytMktShare.mai26_val||0)):0;
      var mktS25=fytMktShare?((fytMktShare.janmar25_val||0)+(fytMktShare.mai25_val||0)):0;
      var mktDeltaS=mktS25>0?Math.round((mktS26-mktS25)/mktS25*1000)/10:0;
      var mktDeltaStrS=(mktDeltaS>=0?'+':'')+mktDeltaS.toFixed(1)+'% vs /25';
      var mktDeltaCorS=mktDeltaS>=0?'#34d399':'#ef4444';
      var mktValStrS=mktS26>0?'R$'+mktS26.toFixed(2)+'MM':'—';
      hdEl.innerHTML = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:rgba(255,255,255,0.06);">'
        +kpiChip('#fbbf24','TOTAL MERCADO',mktValStrS,'color:#fbbf24',mktDeltaStrS,'color:'+mktDeltaCorS)
        +kpiChip(colors[leaderB]||'#e2e8f0','LÍDER DE SHARE',d26[leaderB]?d26[leaderB].jun.toFixed(2)+'%':'—','color:'+(colors[leaderB]||'#e2e8f0'),leaderB+' · Jun/26','color:#94A3B8')
        +kpiChip(topG.raw>=0?'#34d399':'#f59e0b',topG.raw>=0?'MAIOR GANHO':'MENOR RECUO',(topG.raw>=0?'+':'')+topG.raw.toFixed(2)+'pp','color:'+(topG.raw>=0?'#34d399':'#f59e0b'),topG.b,'color:#94A3B8')
        +kpiChip('#ef4444','MAIOR QUEDA',topL.raw.toFixed(2)+'pp','color:#ef4444',topL.b,'color:#94A3B8')
        +'</div>';
    } else {
      var allDkpi = brands.map(function(b){
        var p25=d25[b],p26=d26[b]; if(!p25||!p26) return null;
        var delta=calcDelta(p25.acum,p26.acum);
        return {b:b,val26:p26.acum,val25:p25.acum,delta:delta};
      }).filter(Boolean);
      var totV26k=allDkpi.reduce(function(s,x){return s+x.val26;},0);
      var totV25k=allDkpi.reduce(function(s,x){return s+x.val25;},0);
      var totDk=calcDelta(totV25k,totV26k);
      allDkpi.sort(function(a,b){return b.val26-a.val26;});
      var topBk=allDkpi[0];
      var byDeltaKpi=allDkpi.slice().sort(function(a,b){return b.delta.raw-a.delta.raw;});
      var topGk=byDeltaKpi[0], topLk=byDeltaKpi[byDeltaKpi.length-1];
      /* SCJ COMBINED share no mercado total (Jan-Jun) */
      var fytMktH2=(typeof FYTD_MARKET_TOTAL!=='undefined')?FYTD_MARKET_TOTAL[mkt]:null;
      var mktTot26k=fytMktH2?(isVal?(fytMktH2.janmar26_val||0):fytMktH2.janmar26_un):0;
      var mktTot25k=fytMktH2?(isVal?(fytMktH2.janmar25_val||0):fytMktH2.janmar25_un):0;
      var scjShr2k=mktTot26k>0?Math.round(totV26k/mktTot26k*1000)/10:0;
      var scjShr1k=mktTot25k>0?Math.round(totV25k/mktTot25k*1000)/10:0;
      var scjShrDtk=Math.round((scjShr2k-scjShr1k)*10)/10;
      var scjShrCork=scjShrDtk>=0?'#34d399':'#ef4444';
      var scjShrSubk=(scjShrDtk>=0?'+':'')+scjShrDtk.toFixed(1)+'pp vs /25';
      /* TOTAL MERCADO para chip Jan-Jun — R$ MM ou Unidades conforme modo */
      var mktTot26kV=fytMktH2?(isVal?((fytMktH2.jan26_val||0)+(fytMktH2.fev26_val||0)+(fytMktH2.mar26_val||0)+(fytMktH2.abr26_val||0)+(fytMktH2.mai26_val||0)):((fytMktH2.jan26_un||0)+(fytMktH2.fev26_un||0)+(fytMktH2.mar26_un||0)+(fytMktH2.abr26_un||0)+(fytMktH2.mai26_un||0))):0;
      var mktTot25kV=fytMktH2?(isVal?((fytMktH2.jan25_val||0)+(fytMktH2.fev25_val||0)+(fytMktH2.mar25_val||0)+(fytMktH2.abr25_val||0)+(fytMktH2.mai25_val||0)):((fytMktH2.jan25_un||0)+(fytMktH2.fev25_un||0)+(fytMktH2.mar25_un||0)+(fytMktH2.abr25_un||0)+(fytMktH2.mai25_un||0))):0;
      var mktDeltaK=mktTot25kV>0?Math.round((mktTot26kV-mktTot25kV)/mktTot25kV*1000)/10:0;
      var mktDeltaStrK=(mktDeltaK>=0?'+':'')+mktDeltaK.toFixed(1)+'% vs /25';
      var mktDeltaCorK=mktDeltaK>=0?'#34d399':'#ef4444';
      var mktValStrK=mktTot26kV>0?(isVal?'R$'+mktTot26kV.toFixed(2)+'MM':(mktTot26kV>=1000?(Math.round(mktTot26kV/1000*10)/10)+'M un':Math.round(mktTot26kV)+'K un')):'—';
      /* HB OFF!+EXPOSIS para chip Jan-Mar */
      var hbK26 = Math.round(((d26['OFF!']?d26['OFF!'].acum:0)+(d26['EXPOSIS']?d26['EXPOSIS'].acum:0))*100)/100;
      var hbK25 = Math.round(((d25['OFF!']?d25['OFF!'].acum:0)+(d25['EXPOSIS']?d25['EXPOSIS'].acum:0))*100)/100;
      var hbKDt = calcDelta(hbK25, hbK26);
      hdEl.innerHTML = '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:rgba(255,255,255,0.06);">'
        +kpiChip('#fbbf24','TOTAL MERCADO',mktValStrK,'color:#fbbf24',mktDeltaStrK,'color:'+mktDeltaCorK)
        +kpiChip('#3b82f6','OFF!+EXPOSIS JAN-JUN',fmtV(hbK26),'color:#3b82f6',hbKDt.str+' vs /25','color:'+hbKDt.col)
        +kpiChip(colors[topBk.b]||'#e2e8f0','MAIOR VOLUME',fmtV(topBk.val26),'color:'+(colors[topBk.b]||'#e2e8f0'),topBk.b,'color:#94A3B8')
        +kpiChip(topGk.delta.raw>=0?'#34d399':'#f59e0b',topGk.delta.raw>=0?'MAIOR CRESCIM.':'MENOR QUEDA',topGk.delta.str,'color:'+(topGk.delta.raw>=0?'#34d399':'#f59e0b'),topGk.b,'color:#94A3B8')
        +kpiChip('#ef4444','MAIOR QUEDA',topLk.delta.str,'color:#ef4444',topLk.b,'color:#94A3B8')
        +'</div>';
    }
  }

  /* HORIZONTAL BARS + SHARE MOVERS — removido (informação disponível no dual chart abaixo) */
  var barsEl = document.getElementById('mso2-bars');
  if(barsEl){ barsEl.innerHTML = ''; }


  /* HB MSO2: OFF! + EXPOSIS — sempre R$MM independente do modo */
  var hbTotalEl2=document.getElementById('mso2-hb-total');
  if(hbTotalEl2){
    /* Valores R$MM: em Share busca direto do NIELSEN_BRAND_VAL; em Val usa d25/d26 acum */
    var hb25k,hb26k;
    function fmtHbVal(v){ return v>=1?'R$'+v.toFixed(2)+'MM':'R$'+(v*1000).toFixed(0)+'K'; }
    if(isShare){
      var nbvHb=(typeof NIELSEN_BRAND_VAL!=='undefined')?NIELSEN_BRAND_VAL[mkt]:null;
      if(nbvHb){
        var offHb=nbvHb['OFF!']||{}, expHb=nbvHb['EXPOSIS']||{};
        hb26k=Math.round(((offHb.jan_val||0)+(offHb.fev_val||0)+(offHb.mar_val||0)+(offHb.abr_val||0)+(offHb.mai_val||0)+(offHb.jun_val||0)
                         +(expHb.jan_val||0)+(expHb.fev_val||0)+(expHb.mar_val||0)+(expHb.abr_val||0)+(expHb.mai_val||0)+(expHb.jun_val||0))*100)/100;
        hb25k=Math.round(((offHb.jan25_val||0)+(offHb.fev25_val||0)+(offHb.mar25_val||0)+(offHb.abr25_val||0)+(offHb.mai25_val||0)+(offHb.jun25_val||0)
                         +(expHb.jan25_val||0)+(expHb.fev25_val||0)+(expHb.mar25_val||0)+(expHb.abr25_val||0)+(expHb.mai25_val||0)+(expHb.jun25_val||0))*100)/100;
      } else { hb25k=0; hb26k=0; }
    } else if(isVal){
      hb25k=Math.round(((d25['OFF!']?d25['OFF!'].acum:0)+(d25['EXPOSIS']?d25['EXPOSIS'].acum:0))*100)/100;
      hb26k=Math.round(((d26['OFF!']?d26['OFF!'].acum:0)+(d26['EXPOSIS']?d26['EXPOSIS'].acum:0))*100)/100;
    } else {
      /* Unidades: usa d25/d26 acum mas formata como units nao R$ */
      hb25k=Math.round(((d25['OFF!']?d25['OFF!'].acum:0)+(d25['EXPOSIS']?d25['EXPOSIS'].acum:0))*100)/100;
      hb26k=Math.round(((d26['OFF!']?d26['OFF!'].acum:0)+(d26['EXPOSIS']?d26['EXPOSIS'].acum:0))*100)/100;
      fmtHbVal=function(v){ return v>=1000?(Math.round(v/1000*10)/10)+'M un':Math.round(v)+'K un'; };
    }
    var hbDpk=hb25k>0?Math.round((hb26k-hb25k)/hb25k*1000)/10:0;
    var hbDstrk=(hbDpk>=0?'+':'')+hbDpk.toFixed(1)+'%';
    var hbCork=hbDpk>=0?'#34d399':'#ef4444';
    var hbUnitLbl=(!isShare&&!isVal)?'Unidades':'R$ MM';
    hbTotalEl2.innerHTML=
      '<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">OFF! + EXPOSIS (HB) &middot; JAN&ndash;JUN &middot; '+hbUnitLbl+'</div>'
      +'<div style="position:relative;height:210px;"><canvas id="mso2-hb-canvas"></canvas></div>';
    var prevHb2=Chart.getChart('mso2-hb-canvas'); if(prevHb2) prevHb2.destroy();
    var cvHb2=document.getElementById('mso2-hb-canvas');
    cvHb2.removeAttribute('width');cvHb2.removeAttribute('height');cvHb2.style.width='';cvHb2.style.height='';
    new Chart(cvHb2,{
      type:'bar',
      data:{labels:['Jan-Jun / 25','Jan-Jun / 26'],datasets:[{data:[hb25k,hb26k],
        backgroundColor:['#94A3B8','#3b82f6'],
        borderColor:['#64748B','#1D4ED8'],
        borderWidth:2,borderRadius:5,barPercentage:0.55}]},
      options:{responsive:true,maintainAspectRatio:false,
        layout:{padding:{top:28,right:16,bottom:4,left:16}},
        plugins:{legend:{display:false},
          tooltip:{callbacks:{label:function(ctx){return '  OFF!+EXPOSIS: '+fmtHbVal(ctx.raw);}}}},
        scales:{
          x:{ticks:{color:'#475569',font:{size:10,weight:'700'}},grid:{display:false},border:{color:'rgba(59,130,246,0.10)'}},
          y:{ticks:{color:'#64748b',font:{size:10},callback:function(v){return fmtHbVal(v);}},grid:{color:'rgba(59,130,246,0.10)'},border:{color:'rgba(59,130,246,0.10)'}}}},
      plugins:[{id:'mso2hbdelta',afterDatasetsDraw:function(chart){
        var ctx5=chart.ctx,meta=chart.getDatasetMeta(0);
        meta.data.forEach(function(bar,i){
          var val=i===0?hb25k:hb26k;
          ctx5.save();ctx5.fillStyle='#94A3B8';ctx5.font='700 10px system-ui,sans-serif';
          ctx5.textAlign='center';ctx5.fillText(fmtHbVal(val),bar.x,bar.y-8);ctx5.restore();
        });
        var bar26k=meta.data[1];
        if(bar26k){
          var cYk=(bar26k.y+bar26k.base)/2+5;
          ctx5.save();ctx5.shadowColor='rgba(0,0,0,0)';ctx5.shadowBlur=0;
          ctx5.fillStyle=hbCork;ctx5.font='900 13px system-ui,sans-serif';
          ctx5.textAlign='center';ctx5.fillText(hbDstrk,bar26k.x,cYk);ctx5.restore();
        }
      }}]
    });
  }

  /* TABLE / LINE CHART */
  var tableEl = document.getElementById('mso2-table');
  var tblTitleEl = document.getElementById('mso2-table-title');
  if(tblTitleEl) tblTitleEl.style.display='none';
  if(tableEl){
    if(isShare){
      /* DUAL CHART — bar (left) + line (right) side by side */
      var dDual = MKTSHARE_OVERVIEW[mkt];
      if(!dDual){ tableEl.innerHTML=''; }
      else {
        tableEl.innerHTML =
          '<div style="display:flex;gap:16px;align-items:flex-start;">'
            /* LEFT: bar chart */
            +'<div style="flex:0 0 36%;min-width:0;">'
              +'<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:8px;">ACUM JAN–JUN &middot; 2025 vs 2026</div>'
              +'<div style="position:relative;height:200px;">'
                +'<canvas id="mso2-bar-canvas"></canvas>'
              +'</div>'
            +'</div>'
            /* RIGHT: line chart + delta table */
            +'<div style="flex:1;min-width:0;">'
              +'<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:8px;">EVOLUÇÃO MENSAL &middot; &Delta;pp vs 2025</div>'
              +'<div style="position:relative;height:200px;">'
                +'<canvas id="mso2-line-canvas"></canvas>'
              +'</div>'
            +'</div>'
          +'</div>';

        /* ── BAR CHART ── */
        var prevBC = Chart.getChart('mso2-bar-canvas');
        if(prevBC) prevBC.destroy();
        var cvBar = document.getElementById('mso2-bar-canvas');
        cvBar.removeAttribute('width'); cvBar.removeAttribute('height');
        cvBar.style.width=''; cvBar.style.height='';
        var chartBrands2 = brands.filter(function(b){return b!=='ALL OTHERS CAMP';});
        var barLabels = chartBrands2.map(function(b){ return b==='SUPER REPELEX'?'S.REP':b==='XO INSETO'?'XO INS':b; });
        var bVals25=[],bVals26=[],bBarColors=[],bBarDeltas=[];
        chartBrands2.forEach(function(b){
          var bd=dDual[b]; if(!bd){ bVals25.push(0);bVals26.push(0);bBarColors.push('#374151');bBarDeltas.push(0);return; }
          var j25=bd.jan25!=null?bd.jan25:bd.fytd25;
          var f25=bd.feb25!=null?bd.feb25:bd.fytd25;
          var m25=bd.mar25!=null?bd.mar25:bd.fytd25;
          var a25v=bd.apr25!=null?bd.apr25:bd.fytd25;
          var mi25v=bd.mai25!=null?bd.mai25:bd.fytd25;
          var a25=Math.round((j25+f25+m25+a25v+mi25v)/5*100)/100;
          var a26=Math.round((bd.monthly[6]+bd.monthly[7]+bd.monthly[8]+(bd.monthly[9]||0)+(bd.monthly[10]||0)+(bd.monthly[11]||0))/6*100)/100;
          bVals25.push(a25); bVals26.push(a26);
          bBarColors.push(colors[b]||'#e2e8f0');
          bBarDeltas.push(Math.round((a26-a25)*100)/100);
        });
        new Chart(cvBar,{
          type:'bar',
          data:{
            labels:barLabels,
            datasets:[
              {label:'2025',data:bVals25,backgroundColor:'rgba(100,116,139,0.28)',borderColor:'rgba(100,116,139,0.4)',borderWidth:1,borderRadius:3,barPercentage:0.7,categoryPercentage:0.8},
              {label:'2026',data:bVals26,backgroundColor:bBarColors.map(function(c){return c+'cc';}),borderColor:bBarColors,borderWidth:1.5,borderRadius:3,barPercentage:0.7,categoryPercentage:0.8}
            ]
          },
          options:{
            responsive:true,maintainAspectRatio:false,
            interaction:{mode:'index',intersect:false},
            layout:{padding:{top:20}},
            plugins:{
              legend:{display:true,position:'top',align:'end',labels:{color:'#64748b',font:{size:9},boxWidth:8,padding:10,usePointStyle:true,pointStyle:'rectRounded'}},
              tooltip:{
                backgroundColor:'#F0F4FA',borderColor:'rgba(255,255,255,0.1)',borderWidth:1,
                titleColor:'#475569',titleFont:{size:10},bodyColor:'#1e293b',bodyFont:{size:10},padding:8,
                callbacks:{
                  title:function(items){return chartBrands2[items[0].dataIndex];},
                  label:function(ctx){
                    if(ctx.datasetIndex===0) return '  2025: '+ctx.parsed.y.toFixed(2)+'%';
                    var d=bBarDeltas[ctx.dataIndex];
                    return '  2026: '+ctx.parsed.y.toFixed(2)+'%  ('+(d>=0?'+':'')+d.toFixed(2)+'pp)';
                  }
                }
              }
            },
            scales:{
              x:{ticks:{color:'#475569',font:{size:9,weight:'700'}},grid:{display:false},border:{color:'rgba(59,130,246,0.10)'}},
              y:{ticks:{color:'#64748b',font:{size:9},callback:function(v){return v+'%';}},grid:{color:'rgba(59,130,246,0.10)'},border:{color:'rgba(59,130,246,0.10)'}}
            }
          },
          plugins:[{
            id:'mso2bdelta',
            afterDatasetsDraw:function(chart){
              var ctx2=chart.ctx,meta2=chart.getDatasetMeta(1);
              meta2.data.forEach(function(bar,i){
                var d=bBarDeltas[i]; if(d===undefined) return;
                var col=d>=0?'#34d399':'#ef4444';
                var lbl=(d>=0?'+':'')+d.toFixed(2)+'pp';
                ctx2.save();ctx2.fillStyle=col;ctx2.font='700 9px system-ui,sans-serif';ctx2.textAlign='center';
                ctx2.fillText(lbl,bar.x,bar.y-5);ctx2.restore();
              });
            }
          }]
        });

        /* ── LINE CHART ── */
        var prevLC = Chart.getChart('mso2-line-canvas');
        if(prevLC) prevLC.destroy();
        var cvLine = document.getElementById('mso2-line-canvas');
        cvLine.removeAttribute('width'); cvLine.removeAttribute('height');
        cvLine.style.width=''; cvLine.style.height='';
        var lineDeltasPP={};
        chartBrands2.forEach(function(b){
          var bd=dDual[b]; if(!bd){lineDeltasPP[b]=[0,0,0];return;}
          var j25=bd.jan25!=null?bd.jan25:bd.fytd25;
          var f25=bd.feb25!=null?bd.feb25:bd.fytd25;
          var m25=bd.mar25!=null?bd.mar25:bd.fytd25;
          var a25L=bd.apr25!=null?bd.apr25:bd.fytd25;
          var mi25L=bd.mai25!=null?bd.mai25:bd.fytd25;
          lineDeltasPP[b]=[
            Math.round((bd.monthly[6]-j25)*100)/100,
            Math.round((bd.monthly[7]-f25)*100)/100,
            Math.round((bd.monthly[8]-m25)*100)/100,
            Math.round(((bd.monthly[9]||0)-a25L)*100)/100,
            Math.round(((bd.monthly[10]||0)-mi25L)*100)/100,
            Math.round(((bd.monthly[11]||0)-mi25L)*100)/100
          ];
        });
        var lineDatasets=chartBrands2.map(function(b){
          var bd=dDual[b]; if(!bd) return null;
          var cor=colors[b]||'#e2e8f0';
          return {label:b,data:[bd.monthly[6],bd.monthly[7],bd.monthly[8],bd.monthly[9]||0,bd.monthly[10]||0,bd.monthly[11]||0],
            borderColor:cor,backgroundColor:cor+'18',
            pointBackgroundColor:cor,pointBorderColor:'rgba(59,130,246,0.2)',pointBorderWidth:1,
            pointRadius:5,pointHoverRadius:8,tension:0.3,borderWidth:2.5,fill:false};
        }).filter(Boolean);
        new Chart(cvLine,{
          type:'line',
          data:{labels:['Jan/26','Fev/26','Mar/26','Abr/26','Mai/26','Jun/26'],datasets:lineDatasets},
          options:{
            responsive:true,maintainAspectRatio:false,
            interaction:{mode:'index',intersect:false},
            layout:{padding:{top:10,right:8,bottom:4,left:4}},
            plugins:{
              legend:{display:false},
              tooltip:{
                backgroundColor:'#F0F4FA',borderColor:'rgba(255,255,255,0.1)',borderWidth:1,
                titleColor:'#475569',titleFont:{size:10},bodyColor:'#1e293b',bodyFont:{size:10},padding:8,
                callbacks:{
                  label:function(ctx){
                    var b=chartBrands2[ctx.datasetIndex];
                    var d=lineDeltasPP[b]?lineDeltasPP[b][ctx.dataIndex]:0;
                    return '  '+b+': '+ctx.parsed.y.toFixed(2)+'%  ('+(d>=0?'+':'')+d.toFixed(2)+'pp vs /25)';
                  }
                }
              }
            },
            scales:{
              x:{ticks:{color:'#475569',font:{size:10,weight:'700'}},grid:{color:'rgba(59,130,246,0.10)'},border:{color:'rgba(59,130,246,0.10)'}},
              y:{ticks:{color:'#64748b',font:{size:10},callback:function(v){return v.toFixed(1)+'%';}},grid:{color:'rgba(59,130,246,0.10)'},border:{color:'rgba(59,130,246,0.10)'}}
            }
          },
          plugins:[]
        });
      }
    } else {
      /* BAR CHART — grouped, accumulated Jan-Mar R$/Units 2025 vs 2026 */
      var barTitle2 = isVal ? 'R$ MM ACUMULADO JAN–JUN · 2025 vs 2026' : 'UNIDADES ACUMULADO JAN–JUN · 2025 vs 2026';
      tableEl.innerHTML = '<div>'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:.13em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">'+barTitle2+'</div>'
        +'<div style="position:relative;height:210px;">'
          +'<canvas id="mso2-bar-canvas"></canvas>'
        +'</div>'
        +(GrowthMode?'<div style="font-size:9px;color:#3d4451;margin-top:6px;">&#9733; Acum Jan-Mai/25 estimado (Jun/25 não disponível).</div>':'')
        +'</div>';
      var prevBChart2 = Chart.getChart('mso2-bar-canvas');
      if(prevBChart2) prevBChart2.destroy();
      var cvBar2 = document.getElementById('mso2-bar-canvas');
      cvBar2.removeAttribute('width'); cvBar2.removeAttribute('height');
      cvBar2.style.width=''; cvBar2.style.height='';
      /* chartBrandsBar2: R$/Unidades inclui ALL OTHERS CAMP; Share usa brands (sem AOC) */
      var chartBrandsBar2 = MSO_BRANDS;
      /* Carregar d25/d26 de ALL OTHERS CAMP a partir de nbvS */
      if(nbvS && nbvS['ALL OTHERS CAMP']){
        var _aoc=nbvS['ALL OTHERS CAMP'];
        var _aocJ26=isVal?_aoc.jan_val:_aoc.jan_un, _aocF26=isVal?_aoc.fev_val:_aoc.fev_un, _aocM26=isVal?_aoc.mar_val:_aoc.mar_un, _aocAb26=isVal?(_aoc.abr_val||0):(_aoc.abr_un||0);
        var _aocA26=Math.round((_aocJ26+_aocF26+_aocM26+_aocAb26)*100)/100;
        var _aocHasEx=isVal?(_aoc.jan25_val!==undefined):(_aoc.jan25_un!==undefined);
        var _aocHasAbr25=isVal?(_aoc.abr25_val!==undefined):(_aoc.abr25_un!==undefined);
        var _aocA25;
        if(_aocHasEx){
          var _aocAb25=_aocHasAbr25?(isVal?_aoc.abr25_val:_aoc.abr25_un):0;
          _aocA25=Math.round(((isVal?_aoc.jan25_val:_aoc.jan25_un)+(isVal?_aoc.fev25_val:_aoc.fev25_un)+(isVal?_aoc.mar25_val:_aoc.mar25_un)+_aocAb25)*100)/100;
        } else {
          var _aocFyt25=isVal?_aoc.fytd25_val:_aoc.fytd25_un, _aocFyt26=isVal?_aoc.fytd26_val:_aoc.fytd26_un;
          _aocA25=Math.round(_aocFyt25*(_aocFyt26>0?_aocA26/_aocFyt26:1/4)*100)/100;
        }
        d25['ALL OTHERS CAMP']={jan:null,fev:null,mar:null,acum:_aocA25};
        d26['ALL OTHERS CAMP']={jan:_aocJ26,fev:_aocF26,mar:_aocM26,acum:_aocA26};
      }
      var barLabels2 = chartBrandsBar2.map(function(b){ return b==='SUPER REPELEX'?'S.REPELEX':b; });
      var bVals25=[],bVals26=[],bColors2=[],bDeltas2=[],bDeltaStrs2=[];
      chartBrandsBar2.forEach(function(b){
        var p25=d25[b],p26=d26[b];
        if(!p25||!p26){ bVals25.push(0);bVals26.push(0);bColors2.push('#374151');bDeltas2.push(0);bDeltaStrs2.push('');return; }
        var cor=colors[b]||'#e2e8f0';
        var delta=calcDelta(p25.acum,p26.acum);
        bVals25.push(p25.acum);
        bVals26.push(p26.acum);
        bColors2.push(cor);
        bDeltas2.push(delta.raw);
        bDeltaStrs2.push(delta.str);
      });
      new Chart(cvBar2, {
        type:'bar',
        data:{
          labels:barLabels2,
          datasets:[
            {
              label:'2025',
              data:bVals25,
              backgroundColor:'rgba(148,163,184,0.7)',
              borderColor:'rgba(148,163,184,0.85)',
              borderWidth:1,
              borderRadius:4,
              barPercentage:0.72,
              categoryPercentage:0.82
            },
            {
              label:'2026',
              data:bVals26,
              backgroundColor:bColors2.map(function(c){return c+'cc';}),
              borderColor:bColors2,
              borderWidth:1.5,
              borderRadius:4,
              barPercentage:0.72,
              categoryPercentage:0.82
            }
          ]
        },
        options:{
          responsive:true,
          maintainAspectRatio:false,
          interaction:{mode:'index',intersect:false},
          layout:{padding:{top:22}},
          plugins:{
            legend:{
              display:true,
              position:'top',
              align:'end',
              labels:{color:'#64748b',font:{size:10},boxWidth:10,padding:14,usePointStyle:true,pointStyle:'rectRounded'}
            },
            tooltip:{
              backgroundColor:'#F0F4FA',
              borderColor:'rgba(255,255,255,0.1)',
              borderWidth:1,
              titleColor:'#475569',
              titleFont:{size:11,weight:'700'},
              bodyColor:'#1e293b',
              bodyFont:{size:11},
              padding:10,
              callbacks:{
                title:function(items){ return chartBrandsBar2[items[0].dataIndex]; },
                label:function(ctx){
                  var b=chartBrandsBar2[ctx.dataIndex];
                  var p25v=d25[b],p26v=d26[b];
                  if(ctx.datasetIndex===0) return '  2025: '+fmtV(p25v?p25v.acum:0);
                  return '  2026: '+fmtV(p26v?p26v.acum:0)+'   ('+bDeltaStrs2[ctx.dataIndex]+' YoY)';
                }
              }
            }
          },
          scales:{
            x:{
              ticks:{color:'#475569',font:{size:10,weight:'700'}},
              grid:{display:false},
              border:{color:'rgba(59,130,246,0.10)'}
            },
            y:{
              ticks:{color:'#64748b',font:{size:10},callback:function(v){return fmtV(v);}},
              grid:{color:'rgba(59,130,246,0.10)'},
              border:{color:'rgba(59,130,246,0.10)'}
            }
          }
        },
        plugins:[{
          id:'mso2delta2',
          afterDatasetsDraw:function(chart){
            var ctx2=chart.ctx;
            var meta2=chart.getDatasetMeta(1);
            meta2.data.forEach(function(bar,i){
              var str=bDeltaStrs2[i];
              if(!str) return;
              var d=bDeltas2[i];
              var col=d>=0?'#34d399':'#ef4444';
              ctx2.save();
              ctx2.fillStyle=col;
              ctx2.font='700 10px system-ui,sans-serif';
              ctx2.textAlign='center';
              ctx2.fillText(str, bar.x, bar.y-6);
              ctx2.restore();
            });
          }
        }]
      });
    }
  }
  /* TOTAL MERCADO — ACUMULADO JAN–MAR 2025 vs 2026 */
  var mktTotalEl = document.getElementById('mso2-mkt-total');
  if(mktTotalEl && typeof NIELSEN_BRAND_VAL !== 'undefined'){
    var nbv = NIELSEN_BRAND_VAL[mkt];
    var fytMkt = (typeof FYTD_MARKET_TOTAL !== 'undefined') ? FYTD_MARKET_TOTAL[mkt] : null;
    if(!nbv && !fytMkt){
      mktTotalEl.innerHTML = '';
    } else {
      // Total real do mercado (todas as marcas, fonte: NielsenIQ 1-Tabela-1)
      // Share mode = Jan-Jun (6 meses); R$MM/Unidades = Jan-Jun (6 meses)
      var acum25v = fytMkt ? ((fytMkt.jan25_val||0)+(fytMkt.fev25_val||0)+(fytMkt.mar25_val||0)+(fytMkt.abr25_val||0)+(fytMkt.mai25_val||0)+(fytMkt.jun25_val||0)) : 0;
      var acum26v = fytMkt ? ((fytMkt.jan26_val||0)+(fytMkt.fev26_val||0)+(fytMkt.mar26_val||0)+(fytMkt.abr26_val||0)+(fytMkt.mai26_val||0)+(fytMkt.jun26_val||0)) : 0;
      var acum25u = fytMkt ? ((fytMkt.jan25_un||0)+(fytMkt.fev25_un||0)+(fytMkt.mar25_un||0)+(fytMkt.abr25_un||0)+(fytMkt.mai25_un||0)+(fytMkt.jun25_un||0)) : 0;
      var acum26u = fytMkt ? ((fytMkt.jan26_un||0)+(fytMkt.fev26_un||0)+(fytMkt.mar26_un||0)+(fytMkt.abr26_un||0)+(fytMkt.mai26_un||0)+(fytMkt.jun26_un||0)) : 0;
      acum25v = Math.round(acum25v*100)/100;
      acum26v = Math.round(acum26v*100)/100;
      acum25u = Math.round(acum25u);
      acum26u = Math.round(acum26u);

      var useVal = (isShare || isVal);
      var a25 = useVal ? acum25v : acum25u;
      var a26 = useVal ? acum26v : acum26u;
      var deltaP = a25>0 ? Math.round((a26-a25)/a25*1000)/10 : 0;
      var deltaStr = (deltaP>=0?'+':'')+deltaP.toFixed(1)+'%';
      var deltaCor = deltaP>=0 ? '#34d399' : '#ef4444';

      function fmtMkt(v){
        if(useVal) return 'R$'+v.toFixed(2)+'MM';
        return v>=1000?(Math.round(v/1000*10)/10)+'M un':v+'K un';
      }

      var mktUnit = useVal ? 'R$ MM' : 'Unidades';
      var mktPeriodLabel = 'JAN&ndash;JUN';
      var mktChartTitle = 'TOTAL MERCADO &middot; ACUM '+mktPeriodLabel+' &middot; '+mktUnit;

      mktTotalEl.innerHTML =
        '<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">'+mktChartTitle+'</div>'
        +'<div style="position:relative;height:210px;">'
          +'<canvas id="mso2-mktotal-canvas"></canvas>'
        +'</div>';

      var prevMkC = Chart.getChart('mso2-mktotal-canvas');
      if(prevMkC) prevMkC.destroy();
      var cvMk = document.getElementById('mso2-mktotal-canvas');
      cvMk.removeAttribute('width'); cvMk.removeAttribute('height');
      cvMk.style.width = ''; cvMk.style.height = '';

      new Chart(cvMk, {
        type: 'bar',
        data: {
          labels: ['JAN–JUN / 25', 'JAN–JUN / 26'],
          datasets: [{
            data: [a25, a26],
            backgroundColor: ['#94A3B8', '#3B82F6'],
            borderColor:      ['#64748B', '#1D4ED8'],
            borderWidth: 1,
            borderRadius: 5,
            barPercentage: 0.55
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: {padding: {top:28, right:16, bottom:4, left:16}},
          plugins: {
            legend: {display: false},
            tooltip: {
              callbacks: {
                label: function(ctx){
                  var idx = ctx.dataIndex;
                  var lines = ['  Total: '+fmtMkt(ctx.raw)];
                  brandAcum.forEach(function(bd){
                    var bv = useVal ? (idx===0?bd.v25:bd.v26) : (idx===0?bd.u25:bd.u26);
                    lines.push('  '+bd.b+': '+fmtMkt(bv));
                  });
                  return lines;
                }
              }
            }
          },
          scales: {
            x: {
              ticks: {color:'#475569', font:{size:11, weight:'700'}},
              grid: {display:false},
              border: {color:'rgba(59,130,246,0.10)'}
            },
            y: {
              ticks: {color:'#64748b', font:{size:10}, callback: function(v){ return fmtMkt(v); }},
              grid: {color:'rgba(59,130,246,0.10)'},
              border: {color:'rgba(59,130,246,0.10)'}
            }
          }
        },
        plugins: [{
          id: 'mso2mktdelta',
          afterDatasetsDraw: function(chart){
            var ctx3 = chart.ctx;
            var meta3 = chart.getDatasetMeta(0);
            /* valor sobre cada barra */
            meta3.data.forEach(function(bar, i){
              var val = i===0 ? a25 : a26;
              /* valor total acima da barra */
              ctx3.save();
              ctx3.fillStyle = '#94A3B8';
              ctx3.font = '700 11px system-ui,sans-serif';
              ctx3.textAlign = 'center';
              ctx3.fillText(fmtMkt(val), bar.x, bar.y - 8);
              ctx3.restore();
            });
            /* delta % no CENTRO da barra 2026 — vermelho/verde */
            var bar26 = meta3.data[1];
            if(bar26){
              var centerY = (bar26.y + bar26.base) / 2 + 5;
              ctx3.save();
              ctx3.shadowColor = 'rgba(0,0,0,0)';
              ctx3.shadowBlur = 0;
              ctx3.fillStyle = deltaCor; /* #34d399 verde / #ef4444 vermelho */
              ctx3.font = '900 14px system-ui,sans-serif';
              ctx3.textAlign = 'center';
              ctx3.fillText(deltaStr, bar26.x, centerY);
              ctx3.restore();
            }
          }
        }]
      });
    }
  }

  renderMSO2Insight();
  if(typeof renderShrShortTerm2==='function') renderShrShortTerm2(mkt);
}

