// All markets ordered for bar charts (all shown simultaneously)
const MSO_AREA_MKTS = ['Farma Indep Sul','Farma Moderno Sul','Farma Sul','INFC Int PR','INFC Int RS','INFC PR','INFC RS','INFC SC','T.BR Farma','T.BR Farma Indep','T.BR Farma Moderno'];
var msoAreaBarVal = null, msoAreaBarVar = null, msoAreaMode = 'val';

function renderMSOArea(){
  var selMkt = document.getElementById('msoAreaSel').value;
  if(!nqIsOld(selMkt) && NQ_PR.mk[selMkt]){ nqRenderMSOArea(selMkt); return; }
  var d = MSO_AREA[selMkt];
  /* sem dados — mostrar aviso no MSO Area (não tocar em outros cards) */
  if(!d){
    var _msoKpi = document.getElementById('mso-area-kpis');
    if(_msoKpi) _msoKpi.innerHTML='<div style="grid-column:1/-1;padding:24px;text-align:center;color:#94A3B8;font-size:13px;">⚠️ Dados não disponíveis para <strong style=\'color:#67e8f9;\'>'+selMkt+'</strong>.<br>Atualize via planilha Excel para carregar este mercado.</div>';
    if(msoAreaBarValChart){msoAreaBarValChart.destroy();msoAreaBarValChart=null;}
    if(msoAreaBarVarChart){msoAreaBarVarChart.destroy();msoAreaBarVarChart=null;}
    if(msoAreaLineChart){msoAreaLineChart.destroy();msoAreaLineChart=null;}
    return;
  }
  ['mso-area-bar-val','mso-area-bar-var'].forEach(function(id){ var c=(typeof Chart!=='undefined'&&Chart.getChart)?Chart.getChart(id):null; if(c) c.destroy(); });
  msoAreaBarValChart=null; msoAreaBarVarChart=null;
  var GC='rgba(59,130,246,0.10)', TC='#64748b';
  var CO={backgroundColor:'#F0F4FA',titleColor:'#1e293b',bodyColor:'#475569',borderColor:'rgba(59,130,246,0.2)',borderWidth:1,padding:10};

  // ── KPIs ──
  var delta_fytd = Math.round((d.fytd26_share - d.fytd25_share)*100)/100;
  var delta_fytd_val = Math.round((d.fytd26_val - d.fytd25_val)*1000)/1000;
  document.getElementById('mso-area-kpis').innerHTML = [
    {l:'OFF! FYTD26 Share', v:d.fytd26_share+'%', s:'FYTD25: '+d.fytd25_share+'%', d:delta_fytd, ac:'#67e8f9'},
    {l:'OFF! Fev/26 (R$ MM)', v:'R$ '+d.fev_val+'MM', s:'Share: '+d.fev_share+'%', d:null, ac:'#fbbf24'},
    {l:'Var Jan→Fev Share', v:(d.var_jan_fev>=0?'+':'')+d.var_jan_fev+'pp', s:'Jan: '+d.jan_share+'% → Fev: '+d.fev_share+'%', d:d.var_jan_fev, ac:d.var_jan_fev>=0?'#34d399':'#ef4444'},
    {l:'FYTD26 Valor OFF!', v:'R$ '+d.fytd26_val+'MM', s:delta_fytd_val>=0?'▲ +R$ '+delta_fytd_val+'MM vs FYTD25':'▼ R$ '+Math.abs(delta_fytd_val)+'MM vs FYTD25', d:delta_fytd_val, ac:'#2dd4bf'},
  ].map(function(k){
    var dcol = (!k.d||k.d===0)?'#D1D5DB':k.d>0?'#34d399':'#ef4444';
    var dstr = k.d===null?'':(k.d>=0?'▲ +':' ▼ ')+Math.abs(k.d)+(typeof k.d==='string'?'':'pp');
    return '<div style="background:#161B22;border-radius:10px;padding:14px;border-top:2px solid '+k.ac+';">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">'+k.l+'</div>'
      +'<div style="font-size:20px;font-weight:800;color:'+k.ac+';line-height:1;letter-spacing:-0.3px;">'+k.v+'</div>'
      +'<div style="font-size:10px;color:#64748B;margin-top:4px;">'+k.s+'</div>'
    +'</div>';
  }).join('');

  // ── Update chart labels ──
  var lbVal = document.getElementById('mso-area-bar-val-label');
  if(lbVal) lbVal.textContent = 'VENDA VALOR OFF! — Fev/26 (R$ MM) — '+selMkt;
  var lbVar = document.getElementById('mso-area-bar-var-label');
  if(lbVar) lbVar.textContent = 'VAR SHARE OFF! — Jan→Fev/26 (pp) — '+selMkt;

  // ── Show only the selected market ──
  var labels   = [selMkt];
  var valData  = [d.fev_val];
  var varData  = [d.var_jan_fev];
  var bgColors = ['#67e8f9cc'];
  var bdColors = ['#67e8f9'];
  var varColors = [d.var_jan_fev>=0?'rgba(52,211,153,0.8)':'rgba(251,113,113,0.8)'];
  var varBd     = [d.var_jan_fev>=0?'#34d399':'#ef4444'];

  // ── Left bar: R$ MM value ──
  if(msoAreaBarVal) msoAreaBarVal.destroy();
  var c1 = document.getElementById('mso-area-bar-val');
  if(c1){
    msoAreaBarVal = new Chart(c1,{type:'bar',
      data:{labels:labels, datasets:[{label:'OFF! Fev/26 (R$ MM)',data:valData,backgroundColor:bgColors,borderColor:bdColors,borderWidth:2,borderRadius:8,barPercentage:0.4,categoryPercentage:0.6}]},
      options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' R$ '+c.raw+'MM';}}}},
        scales:{
          x:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return 'R$'+v;}},title:{display:true,text:'R$ MM',color:TC,font:{size:9}}},
          y:{grid:{display:false},ticks:{color:'#67e8f9',font:{size:10,weight:'bold'}}}
        }}
    });
  }

  // ── Right bar: VAR share pp ──
  if(msoAreaBarVar) msoAreaBarVar.destroy();
  var c2 = document.getElementById('mso-area-bar-var');
  if(c2){
    msoAreaBarVar = new Chart(c2,{type:'bar',
      data:{labels:labels, datasets:[{label:'Var Share Jan→Fev (pp)',data:varData,backgroundColor:varColors,borderColor:varBd,borderWidth:2,borderRadius:8,barPercentage:0.4,categoryPercentage:0.6}]},
      options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' '+(c.raw>=0?'+':'')+c.raw+'pp';}}}},
        scales:{
          x:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return (v>=0?'+':'')+v+'pp';}},title:{display:true,text:'Var pp',color:TC,font:{size:9}}},
          y:{grid:{display:false},ticks:{color:d.var_jan_fev>=0?'#34d399':'#ef4444',font:{size:10,weight:'bold'}}}
        }}
    });
  }

  // ── Highlights ──
  var topGain = MSO_AREA_MKTS.reduce(function(best,m){return MSO_AREA[m].var_jan_fev > (best?MSO_AREA[best].var_jan_fev:-99)?m:best;}, null);
  var topVal  = MSO_AREA_MKTS.reduce(function(best,m){return MSO_AREA[m].fev_val > (best?MSO_AREA[best].fev_val:0)?m:best;}, null);
  var negMkts = MSO_AREA_MKTS.filter(function(m){return MSO_AREA[m].var_jan_fev < 0;});
  var hl = '<strong style="color:#67e8f9;">'+selMkt+'</strong> · ';
  hl += 'Fev/26: R$ <strong style="color:#fbbf24;">'+d.fev_val+'MM</strong> · Share: <strong style="color:#67e8f9;">'+d.fev_share+'%</strong> · Var Jan→Fev: <strong style="color:'+(d.var_jan_fev>=0?'#34d399':'#ef4444')+'">'+(d.var_jan_fev>=0?'+':'')+d.var_jan_fev+'pp</strong><br>';
  hl += '🏆 Maior ganho Jan→Fev: <strong style="color:#34d399;">'+topGain+' (+'+MSO_AREA[topGain].var_jan_fev+'pp)</strong> &nbsp;|&nbsp; ';
  hl += '💰 Maior valor Fev/26: <strong style="color:#fbbf24;">'+topVal+' (R$ '+MSO_AREA[topVal].fev_val+'MM)</strong>';
  if(negMkts.length) hl += '<br>⚠️ Markets com queda Jan→Fev: <span style="color:#06b6d4;">'+negMkts.join(', ')+'</span>';
  document.getElementById('mso-area-highlights').innerHTML = hl;
}

