var wsGauchaView = 'uf';
var wsGauchaCharts = {};

function setWSGauchaView(view, btn){
  wsGauchaView = view;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderWSGaúcha();
}

function renderWSGaúcha(){
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};

  function mk(id, type, data, opts){
    if(wsGauchaCharts[id]) wsGauchaCharts[id].destroy();
    var c=document.getElementById(id);
    if(c) wsGauchaCharts[id]=new Chart(c,{type:type,data:data,options:opts});
  }

  if(wsGauchaView==='uf'){
    var ufs = Object.keys(WS_GAUCHA.by_uf);
    document.getElementById('wsg-t1').textContent = 'ATIVOS vs WHITE SPACE por UF';
    document.getElementById('wsg-t2').textContent = 'NÃO POSITIVADOS FY25 por UF';
    document.getElementById('wsg-t3').textContent = 'RECEITA EM RISCO por UF (R$ K)';
    // Bar1: Ativos vs WS
    mk('ws-gaucha-bar1','bar',{labels:ufs,datasets:[
      {label:'Ativos FY26', data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].ativo;}), backgroundColor:'rgba(52,211,153,0.7)', borderColor:'#34d399', borderWidth:1.5, borderRadius:8},
      {label:'White Space', data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].ws;}),    backgroundColor:'rgba(249,115,22,0.7)', borderColor:'#f97316', borderWidth:1.5, borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}}}}});
    // Bar2: Não Positivados FY25 + FY24
    mk('ws-gaucha-bar2','bar',{labels:ufs,datasets:[
      {label:'Não Positivados FY25', data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].dormido_fy25;}), backgroundColor:'rgba(6,182,212,0.7)', borderColor:'#06b6d4', borderWidth:1.5, borderRadius:8},
      {label:'Não Positivados FY24', data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].dormido_fy24;}), backgroundColor:'rgba(45,212,191,0.7)', borderColor:'#2dd4bf', borderWidth:1.5, borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}}}}});
    // Bar3: Rec perdida + FY26
    mk('ws-gaucha-bar3','bar',{labels:ufs,datasets:[
      {label:'Rec. Perdida FY25 (R$K)', data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].rec_perdida;}), backgroundColor:'rgba(251,191,36,0.7)', borderColor:'#fbbf24', borderWidth:1.5, borderRadius:8},
      {label:'Rec. FY26 (R$K)',         data:ufs.map(function(u){return WS_GAUCHA.by_uf[u].rec_fy26;}),    backgroundColor:'rgba(103,232,249,0.5)',  borderColor:'#67e8f9', borderWidth:1.5, borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false,callbacks:{label:function(c){return ' '+c.dataset.label+': R$ '+c.raw+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return 'R$'+v+'K';}}}}});

  } else if(wsGauchaView==='seg'){
    var segs = Object.keys(WS_GAUCHA.by_seg);
    document.getElementById('wsg-t1').textContent = 'ATIVOS vs WHITE SPACE por Segmento';
    document.getElementById('wsg-t2').textContent = 'WHITE SPACE por Segmento';
    document.getElementById('wsg-t3').textContent = 'RECEITA EM RISCO por Segmento (R$ K)';
    mk('ws-gaucha-bar1','bar',{labels:segs,datasets:[
      {label:'Ativos',      data:segs.map(function(s){return WS_GAUCHA.by_seg[s].ativo;}), backgroundColor:'rgba(52,211,153,0.7)', borderColor:'#34d399', borderWidth:1.5, borderRadius:8},
      {label:'White Space', data:segs.map(function(s){return WS_GAUCHA.by_seg[s].ws;}),   backgroundColor:'rgba(249,115,22,0.7)', borderColor:'#f97316', borderWidth:1.5, borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false}},scales:{x:{grid:{color:GC},ticks:{color:TC}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}}}}});
    mk('ws-gaucha-bar2','doughnut',{labels:segs,datasets:[{data:segs.map(function(s){return WS_GAUCHA.by_seg[s].ws;}),backgroundColor:['rgba(52,211,153,0.8)','rgba(249,115,22,0.8)'],borderColor:['#34d399','#f97316'],borderWidth:2}]},{responsive:true,maintainAspectRatio:false,cutout:'55%',plugins:{legend:{display:true,position:'bottom',labels:{color:'#334155',font:{size:10},boxWidth:10}},tooltip:{...CO}}});
    mk('ws-gaucha-bar3','bar',{labels:segs,datasets:[{label:'Rec. Perdida (R$K)',data:segs.map(function(s){return WS_GAUCHA.by_seg[s].rec_perdida;}),backgroundColor:'rgba(251,191,36,0.7)',borderColor:'#fbbf24',borderWidth:1.5,borderRadius:8}]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' R$ '+c.raw+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return 'R$'+v+'K';}}}}});

  } else { // cidade
    var cidades = WS_GAUCHA.top_cidades;
    var labels  = cidades.map(function(c){return c.cidade;});
    document.getElementById('wsg-t1').textContent = 'TOP CIDADES — Não Positivados FY25';
    document.getElementById('wsg-t2').textContent = 'TOP CIDADES — Receita em Risco (R$ K)';
    document.getElementById('wsg-t3').textContent = 'RELAÇÃO PDVs vs Receita';
    mk('ws-gaucha-bar1','bar',{labels:labels,datasets:[{label:'Não Positivados FY25',data:cidades.map(function(c){return c.ws;}),backgroundColor:'rgba(249,115,22,0.7)',borderColor:'#f97316',borderWidth:1.5,borderRadius:8}]},{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' '+c.raw+' Não Positivados';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},y:{grid:{display:false},ticks:{color:'#475569',font:{size:9}}}}});
    mk('ws-gaucha-bar2','bar',{labels:labels,datasets:[{label:'Rec. Perdida (R$K)',data:cidades.map(function(c){return c.rec;}),backgroundColor:'rgba(251,191,36,0.7)',borderColor:'#fbbf24',borderWidth:1.5,borderRadius:8}]},{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' R$ '+c.raw+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},y:{grid:{display:false},ticks:{color:'#475569',font:{size:9}}}}});
    mk('ws-gaucha-bar3','bubble',{datasets:cidades.map(function(c,i){return{label:c.cidade,data:[{x:c.ws,y:c.rec,r:Math.max(4,Math.sqrt(c.ws))}],backgroundColor:['#f97316','#fbbf24','#34d399','#3b82f6','#2dd4bf','#06b6d4','#67e8f9','#2dd4bf','#e879f9','#facc15'][i%10]+'aa'};})},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{title:function(c){return c[0].dataset.label;},label:function(c){return 'PDVs: '+c.raw.x+' | R$ '+c.raw.y+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}},title:{display:true,text:'Não Positivados',color:TC,font:{size:9}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}},title:{display:true,text:'Rec. Perdida (R$K)',color:TC,font:{size:9}}}}});
  }
}

