function renderWSGAM(){
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};

  function mk(id,type,data,opts){
    if(wsGAMCharts[id]) wsGAMCharts[id].destroy();
    var c=document.getElementById(id);
    if(c) wsGAMCharts[id]=new Chart(c,{type:type,data:data,options:opts});
  }

  if(wsGAMView==='uf'){
    var ufs = Object.keys(WS_GAM.by_uf);
    document.getElementById('wsg-gam-t1').textContent='ATIVOS vs WHITE SPACE por UF';
    document.getElementById('wsg-gam-t2').textContent='NÃO POSITIVADOS FY25 por UF';
    document.getElementById('wsg-gam-t3').textContent='RECEITA EM RISCO por UF (R$ K)';

    mk('ws-gam-bar1','bar',{labels:ufs,datasets:[
      {label:'Ativos FY26',  data:ufs.map(function(u){return WS_GAM.by_uf[u].ativo;}),         backgroundColor:'rgba(52,211,153,0.7)',  borderColor:'#34d399',borderWidth:1.5,borderRadius:8},
      {label:'White Space',  data:ufs.map(function(u){return WS_GAM.by_uf[u].dormido_2025+WS_GAM.by_uf[u].dormido_2024;}), backgroundColor:'rgba(249,115,22,0.7)', borderColor:'#f97316',borderWidth:1.5,borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}}}}});

    mk('ws-gam-bar2','bar',{labels:ufs,datasets:[
      {label:'Não Positivados FY25',data:ufs.map(function(u){return WS_GAM.by_uf[u].dormido_2025;}), backgroundColor:'rgba(6,182,212,0.7)',borderColor:'#06b6d4',borderWidth:1.5,borderRadius:8},
      {label:'Não Positivados FY24',data:ufs.map(function(u){return WS_GAM.by_uf[u].dormido_2024;}), backgroundColor:'rgba(45,212,191,0.7)',borderColor:'#2dd4bf',borderWidth:1.5,borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}}}}});

    mk('ws-gam-bar3','bar',{labels:ufs,datasets:[
      {label:'Rec Perdida 2025',data:ufs.map(function(u){return WS_GAM.by_uf[u].rec_perdida_2025;}),backgroundColor:'rgba(251,191,36,0.7)', borderColor:'#fbbf24',borderWidth:1.5,borderRadius:8},
      {label:'Rec Perdida 2024',data:ufs.map(function(u){return WS_GAM.by_uf[u].rec_perdida_2024;}),backgroundColor:'rgba(45,212,191,0.5)',borderColor:'#2dd4bf',borderWidth:1.5,borderRadius:8},
      {label:'Rec FY26',        data:ufs.map(function(u){return WS_GAM.by_uf[u].rec_fy26;}),         backgroundColor:'rgba(103,232,249,0.5)', borderColor:'#67e8f9',borderWidth:1.5,borderRadius:8},
    ]},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:8}},tooltip:{...CO,mode:'index',intersect:false,callbacks:{label:function(c){return ' '+c.dataset.label+': R$'+c.raw+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:10}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return 'R$'+v+'K';}}}}});

  } else {
    var cidades = WS_GAM.top_cidades;
    var labels  = cidades.map(function(c){return c.cidade;});
    document.getElementById('wsg-gam-t1').textContent='TOP CIDADES — Não Positivados FY25';
    document.getElementById('wsg-gam-t2').textContent='TOP CIDADES — Receita em Risco (R$ K)';
    document.getElementById('wsg-gam-t3').textContent='PDVs vs Receita por Cidade';

    mk('ws-gam-bar1','bar',{labels:labels,datasets:[{label:'Não Positivados FY25',data:cidades.map(function(c){return c.ws;}),backgroundColor:'rgba(249,115,22,0.7)',borderColor:'#f97316',borderWidth:1.5,borderRadius:8}]},{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},y:{grid:{display:false},ticks:{color:'#475569',font:{size:9}}}}});

    mk('ws-gam-bar2','bar',{labels:labels,datasets:[{label:'Rec Perdida (R$K)',data:cidades.map(function(c){return c.rec;}),backgroundColor:'rgba(251,191,36,0.7)',borderColor:'#fbbf24',borderWidth:1.5,borderRadius:8}]},{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){return ' R$'+c.raw+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},y:{grid:{display:false},ticks:{color:'#475569',font:{size:9}}}}});

    mk('ws-gam-bar3','bubble',{datasets:cidades.map(function(c,i){return{label:c.cidade,data:[{x:c.ws,y:c.rec,r:Math.max(4,Math.sqrt(c.ws)*1.5)}],backgroundColor:['#34d399','#fbbf24','#3b82f6','#f97316','#2dd4bf','#06b6d4','#67e8f9','#2dd4bf','#e879f9','#facc15'][i%10]+'aa'};})},{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{...CO,callbacks:{title:function(c){return c[0].dataset.label;},label:function(c){return 'PDVs: '+c.raw.x+' | R$'+c.raw.y+'K';}}}},scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}},title:{display:true,text:'Não Positivados',color:TC,font:{size:9}}},y:{grid:{color:GC},ticks:{color:TC,font:{size:9}},title:{display:true,text:'Rec Perdida (R$K)',color:TC,font:{size:9}}}}});
  }
}

