const SELLIN_MONTHS = ['JUL','AGO','SET','OUT','NOV','DEZ','JAN','FEV','MAR','ABR','MAI','JUN'];
/* ── FY ativo (troca via setSellinFY) ─────────────────────────────────────
   Índices: JUL=0 AGO=1 SET=2 OUT=3 NOV=4 DEZ=5 JAN=6 FEV=7 MAR=8 ABR=9 MAI=10 JUN=11  */
var SELLIN_FY_ATUAL      = 'FY27';
var SELLIN_DATA          = SELLIN_DATA_FY27;
var SELLIN_TOTAL         = SELLIN_TOTAL_FY27;
var SELLIN_MES_ATUAL     = 4;        // NOV/26 (parcial; Meta BI de Nov a definir)
var SELLIN_MES_ATUAL_LBL = 'NOV/26'; // label exibido na coluna
var VERBAS_TOTAL = 2879340;

var sellinFilter  = 'todos';
var sellinMode    = 'abs';
var sellinCharts  = {};
var sellinInit    = false;

var _sellinMensalSeries = {real:true, meta:true, plan:false, hist:true};

function toggleSellinMensalSerie(key, btn){
  _sellinMensalSeries[key] = !_sellinMensalSeries[key];
  btn.classList.toggle('active');
  btn.classList.toggle('blue');
  renderSellinMensalChart();
}

function renderSellinMensalChart(){
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};
  var months = SELLIN_MONTHS;
  var totalReal = months.map(function(_,i){ return SELLIN_DATA.reduce(function(s,d){ return s+(d.real_m[i]||0); },0); });
  var totalMeta = months.map(function(_,i){ return SELLIN_DATA.reduce(function(s,d){ return s+(d.meta_m[i]||0); },0); });
  var totalPlan = months.map(function(_,i){ return SELLIN_DATA.reduce(function(s,d){ return s+(d.plan_m[i]||0); },0); });
  var totalHist = months.map(function(_,i){ return SELLIN_DATA.reduce(function(s,d){ return s+(d.hist_m[i]||0); },0); });
  /* FY27: meses futuros sem Real/Meta ficam vazios (não caem a zero) */
  if(SELLIN_FY_ATUAL==='FY27'){
    totalReal = totalReal.map(function(v,i){ return i<=SELLIN_MES_ATUAL ? v : null; });
    totalMeta = totalMeta.map(function(v,i){ return i<=SELLIN_MES_ATUAL ? v : null; });
  }
  var _hLbl = SELLIN_FY_ATUAL==='FY27' ? 'Histórico FY26' : 'Histórico FY25';
  var _hb = document.getElementById('sellin-mensal-hist-btn'); if(_hb) _hb.textContent = _hLbl;
  var _ms = document.getElementById('sellin-mensal-sub'); if(_ms) _ms.textContent = (SELLIN_FY_ATUAL==='FY27' ? 'JUL/26 → JUN/27' : 'JUL/25 → JUN/26') + ' · todos os clientes';

  var datasets = [];
  if(_sellinMensalSeries.hist)
    datasets.push({label:_hLbl, data:totalHist, backgroundColor:'rgba(148,163,184,0.45)', borderColor:'#94A3B8', borderWidth:1.5, borderRadius:8, order:5});
  if(_sellinMensalSeries.plan)
    datasets.push({label:'Planejado', data:totalPlan, type:'line', borderColor:'#67e8f9', backgroundColor:'rgba(103,232,249,0.08)', borderWidth:2, pointRadius:3, pointBackgroundColor:'#67e8f9', fill:false, tension:0.3, order:3});
  if(_sellinMensalSeries.real)
    datasets.push({label:'Real', data:totalReal, backgroundColor:'rgba(52,211,153,0.65)', borderColor:'#34d399', borderWidth:1.5, borderRadius:8, order:2});
  if(_sellinMensalSeries.meta)
    datasets.push({label:'Meta BI', data:totalMeta, type:'line', borderColor:'#fbbf24', backgroundColor:'rgba(251,191,36,0.1)', borderWidth:2.5, pointRadius:3, pointBackgroundColor:'#fbbf24', fill:false, tension:0.3, order:1});

  var c = document.getElementById('sellin-mensal-chart');
  if(!c) return;
  if(c._chart) c._chart.destroy();
  c._chart = new Chart(c, {
    type:'bar',
    data:{ labels: months, datasets: datasets },
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{
        legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:10}},
        tooltip:{...CO,mode:'index',intersect:false,callbacks:{label:function(c){return c.raw==null?null:' '+c.dataset.label+': '+c.raw.toLocaleString('pt-BR');}}}
      },
      scales:{
        x:{grid:{color:GC},ticks:{color:'#475569',font:{size:10}}},
        y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return v.toLocaleString('pt-BR');}}}
      }
    }
  });
}

function renderSellinResumoTable(){
  var el = document.getElementById('sellin-resumo-table');
  if(!el) return;
  var mIdx = typeof SELLIN_MES_ATUAL !== 'undefined' ? SELLIN_MES_ATUAL : 9;
  var mLbl = typeof SELLIN_MES_ATUAL_LBL !== 'undefined' ? SELLIN_MES_ATUAL_LBL : 'ABR/26';
  /* atualiza subtítulo do card */
  var sub = document.getElementById('sellin-resumo-sub');
  if(sub) sub.textContent = 'Acumulado '+SELLIN_FY_ATUAL+' vs Meta BI · mês atual: ' + mLbl;
  var SEP = 'border-left:2px solid rgba(94,153,208,0.25);';
  var rows = SELLIN_DATA.map(function(d){
    var ating    = d.meta>0     ? (d.real/d.meta*100).toFixed(1)        : '—';
    var planPer  = d.plan_m ? d.plan_m.slice(0,mIdx+1).reduce(function(s,v){return s+(v||0);},0) : d.plan;
    var vsPlan   = planPer>0   ? ((d.real/planPer-1)*100).toFixed(1)   : '—';
    var vsHist   = d.hist_per>0 ? ((d.real/d.hist_per-1)*100).toFixed(1): '—';
    var atingNum = d.meta>0     ? d.real/d.meta*100                     : 0;
    var vsPlanNum= planPer>0   ? (d.real/planPer-1)*100                : 0;
    var vsHistNum= d.hist_per>0 ? (d.real/d.hist_per-1)*100             : 0;
    var cA = atingNum>=100  ? '#34d399':'#ef4444';
    var cP = vsPlanNum>=0   ? '#34d399':'#ef4444';
    var cH = vsHistNum>=0   ? '#34d399':'#ef4444';
    /* colunas do mês atual */
    var metaMes  = (d.meta_m && d.meta_m[mIdx] != null) ? d.meta_m[mIdx] : 0;
    var realMes  = (d.real_m && d.real_m[mIdx] != null && d.real_m[mIdx] > 0) ? d.real_m[mIdx] : null;
    var realMesStr = realMes != null ? realMes.toLocaleString('pt-BR') : '—';
    var cRM = realMes != null ? '#34d399' : '#64748B';
    var atMes = (metaMes > 0 && realMes != null)
                ? '<span style="font-size:9px;color:'+(realMes>=metaMes?'#34d399':'#ef4444')+';margin-left:4px;">'
                  +(realMes>=metaMes?'▲':'▼')+(realMes/metaMes*100).toFixed(0)+'%</span>'
                : '';
    return '<tr style="border-bottom:0.5px solid rgba(94,153,208,0.12);">'
      +'<td style="padding:10px 8px;font-weight:700;color:'+d.cor+';">'+d.nome+'</td>'
      +'<td style="padding:10px 8px;color:#64748B;font-size:10px;">'+d.canal+'</td>'
      +'<td style="padding:10px 8px;text-align:right;color:#fbbf24;font-weight:600;">'+d.meta.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:10px 8px;text-align:right;color:#34d399;font-weight:700;">'+d.real.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:10px 8px;text-align:right;font-weight:700;color:'+cA+';">'+ating+'%</td>'
      +'<td style="padding:10px 8px;text-align:right;color:'+cP+';">'+(vsPlanNum>=0?'+':'')+vsPlan+'%</td>'
      +'<td style="padding:10px 8px;text-align:right;color:'+cH+';">'+(vsHistNum>=0?'+':'')+vsHist+'%</td>'
      +'<td style="padding:10px 8px;text-align:right;color:#fbbf24;'+SEP+'">'+(metaMes>0?metaMes.toLocaleString('pt-BR'):'<span title="Meta BI do mês ainda não definida">—</span>')+'</td>'
      +'<td style="padding:10px 8px;text-align:right;font-weight:700;color:'+cRM+';">'+realMesStr+atMes+'</td>'
    +'</tr>';
  }).join('');
  el.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:11px;">'
    +'<thead><tr style="color:#475569;border-bottom:1px solid rgba(94,153,208,0.20);font-size:10px;font-weight:700;">'
    +'<th style="padding:8px;text-align:left;">CLIENTE</th>'
    +'<th style="padding:8px;text-align:left;">CANAL</th>'
    +'<th style="padding:8px;text-align:right;">META BI</th>'
    +'<th style="padding:8px;text-align:right;">REAL</th>'
    +'<th style="padding:8px;text-align:right;">% ATING</th>'
    +'<th style="padding:8px;text-align:right;">VS PLAN</th>'
    +'<th style="padding:8px;text-align:right;">VS HIST</th>'
    +'<th style="padding:8px;text-align:right;'+SEP+'color:#fbbf24;">META '+mLbl+'</th>'
    +'<th style="padding:8px;text-align:right;color:#34d399;">REAL '+mLbl+'</th>'
    +'</tr></thead>'
    +'<tbody>'+rows+'</tbody>'
    +'</table>';
}


/* ═══ EVOLUCAO YoY POR PROVEDOR v2 ═══ */
var _yoySortKey  = 'delta';
var _yoyShowAll  = false;
var _yoyTotal    = 0;
var _yoySelProv  = null;   // provedor selecionado no filtro interno
var _yoyChart    = null;   // instância Chart.js

function _yoyFiltInput(){ return document.getElementById('yoy-filt-input'); }
function _yoyFiltList(){ return document.getElementById('yoy-filt-list'); }

function yoyFiltKey(e){
  var q = (e.target.value||'').toLowerCase().trim();
  var list = _yoyFiltList();
  if(!list) return;
  var data = (PROV_DATA||[]);
  var matches;
  if(!q){
    // Sem texto: mostrar top 20 ordenado por FY26 PDV-meses
    matches = data.slice().sort(function(a,b){
      var aF=0,bF=0;
      (a.monthly||[]).slice(15,24).forEach(function(v){aF+=v;});
      (b.monthly||[]).slice(15,24).forEach(function(v){bF+=v;});
      return bF-aF;
    }).slice(0,20);
  } else {
    matches = data.filter(function(p){ return p.name.toLowerCase().indexOf(q)>=0; }).slice(0,15);
  }
  var matches = (PROV_DATA||[]).filter(function(p){ return p.name.toLowerCase().indexOf(q)>=0; }).slice(0,10);
  if(!matches.length){ list.style.display='none'; return; }
  list.innerHTML = matches.map(function(p){
    var fy26=0; (p.monthly||[]).slice(15,24).forEach(function(v){fy26+=v;});
    return '<div onclick="yoySelectProv(\''+p.name.replace(/'/g,"\\'")+'\')" style="padding:8px 12px;cursor:pointer;border-bottom:0.5px solid rgba(255,255,255,0.05);font-size:11px;color:#D1D5DB;display:flex;justify-content:space-between;align-items:center;" onmouseover="this.style.background=\'rgba(34,197,94,0.08)\'" onmouseout="this.style.background=\'\'"><span>'+p.name+'</span><span style="font-size:9px;color:#475569;">'+p.scj.toLocaleString('pt-BR')+' SCJ · '+Math.round(p.pct)+'%</span></div>';
  }).join('');
  list.style.display='block';
}

function yoySelectProv(name){
  _yoySelProv = name;
  var inp = _yoyFiltInput();
  if(inp) inp.value = name;
  var list = _yoyFiltList();
  if(list) list.style.display='none';
  renderProvYoYCard();
}

function yoyClearProv(){
  _yoySelProv = null;
  var inp = _yoyFiltInput();
  if(inp) inp.value = '';
  renderProvYoYCard();
}

function setYoYSort(k, btn){
  _yoySortKey = k;
  document.querySelectorAll('#prov-yoy-card .yoy-sort-btn').forEach(function(b){
    b.style.background='transparent'; b.style.color='#64748b'; b.style.borderColor='rgba(255,255,255,0.07)';
  });
  btn.style.background='rgba(251,191,36,0.15)'; btn.style.color='#fbbf24'; btn.style.borderColor='rgba(251,191,36,0.3)';
  if(!_yoySelProv) renderProvYoYCard();
}

function toggleYoYAll(btn){
  _yoyShowAll = !_yoyShowAll;
  btn.textContent = _yoyShowAll ? 'Ver Top 20' : 'Ver todos ('+_yoyTotal+')';
  renderProvYoYCard();
}

/* ── Análise completa de um provedor selecionado ── */
function _yoyRenderDetail(p, bodyEl){
  var M   = p.monthly || [];
  var lbl = ['Jul','Ago','Set','Out','Nov','Dez','Jan','Fev','Mar'];
  // FY25: M[3]-M[11] | FY26: M[15]-M[23]
  var fy25arr=[],fy26arr=[];
  for(var i=3;i<=11;i++)  fy25arr.push(M[i]||0);
  for(var i=15;i<=23;i++) fy26arr.push(M[i]||0);
  var fy25=fy25arr.reduce(function(a,b){return a+b;},0);
  var fy26=fy26arr.reduce(function(a,b){return a+b;},0);
  var q1_25=(M[9]||0)+(M[10]||0)+(M[11]||0);
  var q1_26=(M[21]||0)+(M[22]||0)+(M[23]||0);
  var delta=fy25>0?(fy26-fy25)/fy25*100:null;
  var q1d  =q1_25>0?(q1_26-q1_25)/q1_25*100:null;
  var opp  =p.opp_total||0;
  var reconq=p.reconquista||0;
  var atend=(opp+reconq)>0?Math.round(reconq/(opp+reconq)*100):0;
  var dSign=function(v){return v===null?'—':(v>=0?'+':'')+v.toFixed(1)+'%';};
  var dCol =function(v){return v===null?'#64748b':v>=0?'#34d399':'#ef4444';};

  /* ── KPI strip ── */
  var kpi='<div style="display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:#E4EAF2;border-radius:10px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(94,153,208,0.45);box-shadow:0 2px 8px rgba(10,40,80,0.08);">'
    +_yoyKpi('FY25 Jul→Mar', fy25.toLocaleString('pt-BR'), 'PDV·meses','#3b82f6')
    +_yoyKpi('FY26 Jul→Mar', fy26.toLocaleString('pt-BR'), 'PDV·meses','#22c55e')
    +_yoyKpi('Δ YoY', dSign(delta), 'vs mesmo período','',dCol(delta))
    +_yoyKpi('Q1 FY25 (Jan-Mar)', q1_25.toLocaleString('pt-BR'), 'Jan+Fev+Mar/25','#3b82f6')
    +_yoyKpi('Q1 FY26 (Jan-Mar)', q1_26.toLocaleString('pt-BR'), 'Jan+Fev+Mar/26','#22c55e')
    +_yoyKpi('Δ Q1', dSign(q1d), 'pico temporada','',dCol(q1d))
    +'</div>';

  /* ── CIMED + RB strip ── */
  var cimedRb='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:16px;">'
    +'<div style="background:#161B22;border-radius:8px;padding:12px;border-left:3px solid #a78bfa;">'
      +'<div style="font-size:8px;font-weight:700;color:#475569;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.06em;">CIMED sem SCJ</div>'
      +'<div style="font-size:22px;font-weight:800;color:#a78bfa;line-height:1;">'+(p.opp_ci||0).toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:9px;color:#334155;margin-top:3px;">PDVs com CIMED, sem SCJ</div></div>'
    +'<div style="background:#161B22;border-radius:8px;padding:12px;border-left:3px solid #60a5fa;">'
      +'<div style="font-size:8px;font-weight:700;color:#475569;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.06em;">RB sem SCJ</div>'
      +'<div style="font-size:22px;font-weight:800;color:#60a5fa;line-height:1;">'+(p.opp_rb||0).toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:9px;color:#334155;margin-top:3px;">PDVs com RB, sem SCJ</div></div>'
    +'<div style="background:#161B22;border-radius:8px;padding:12px;border-left:3px solid #f97316;">'
      +'<div style="font-size:8px;font-weight:700;color:#475569;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.06em;">CIMED+RB Consolidado</div>'
      +'<div style="font-size:22px;font-weight:800;color:#f97316;line-height:1;">'+opp.toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:9px;color:#334155;margin-top:3px;">Deduplicado nacional</div></div>'
    +'<div style="background:#161B22;border-radius:8px;padding:12px;border-left:3px solid #34d399;">'
      +'<div style="font-size:8px;font-weight:700;color:#475569;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.06em;">Reconquistados</div>'
      +'<div style="font-size:22px;font-weight:800;color:#34d399;line-height:1;">'+reconq.toLocaleString('pt-BR')+'</div>'
      +'<div style="font-size:9px;color:'+(atend>=50?'#34d399':atend>=25?'#fbbf24':'#ef4444')+';margin-top:3px;font-weight:600;">'+atend+'% taxa conversão</div></div>'
    +'</div>';

  /* ── Canvas gráfico mensal ── */
  var canvas='<div style="background:#0d1117;border-radius:10px;padding:16px;margin-bottom:16px;">'
    +'<div style="font-size:9px;font-weight:700;color:#475569;letter-spacing:0.08em;margin-bottom:10px;text-transform:uppercase;">PDV·meses por mês — FY25 vs FY26 (Jul→Mar)</div>'
    +'<div style="position:relative;height:200px;"><canvas id="yoy-detail-chart"></canvas></div>'
    +'</div>';

  /* ── UF Breakdown ── */
  var ufHtml='';
  if(p.by_uf && p.by_uf.length){
    var sorted=[].concat(p.by_uf).sort(function(a,b){return b[2]-a[2];}).slice(0,10);
    var maxScj=sorted[0][2]||1;
    ufHtml='<div style="background:#0d1117;border-radius:10px;padding:16px;">'
      +'<div style="font-size:9px;font-weight:700;color:#475569;letter-spacing:0.08em;margin-bottom:12px;text-transform:uppercase;">Cobertura por Estado (Top 10)</div>'
      +'<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px;">';
    sorted.forEach(function(u){
      var pct=u[1]>0?Math.round(u[2]/u[1]*100):0;
      var col=pct>=70?'#34d399':pct>=40?'#fbbf24':pct>=20?'#f97316':'#ef4444';
      var bw=u[1]>0?Math.round(u[2]/maxScj*100):0;
      ufHtml+='<div style="display:flex;align-items:center;gap:8px;">'
        +'<span style="font-size:10px;font-weight:700;color:#94a3b8;min-width:22px;">'+u[0]+'</span>'
        +'<div style="flex:1;background:rgba(255,255,255,0.04);border-radius:3px;height:8px;overflow:hidden;">'
          +'<div style="height:100%;background:'+col+';border-radius:3px;width:'+bw+'%;"></div></div>'
        +'<span style="font-size:10px;font-weight:700;color:'+col+';min-width:32px;text-align:right;">'+pct+'%</span>'
        +'<span style="font-size:9px;color:#334155;min-width:60px;">'+u[2].toLocaleString('pt-BR')+'/'+u[1].toLocaleString('pt-BR')+'</span>'
        +'</div>';
    });
    ufHtml+='</div></div>';
  }

  /* ── Diagnóstico dinâmico do provedor ── */
  var dDeltaInterp = delta===null ? 'Dados insuficientes para análise.'
    : delta > 20  ? 'Crescimento acelerado — canal ativo e em forte expansão.'
    : delta > 5   ? 'Crescimento sólido — positivação em alta.'
    : delta >= 0  ? 'Leve crescimento — estabilidade com pequeno ganho.'
    : delta > -10 ? 'Queda leve — monitorar sell-in e rupturas.'
    : delta > -25 ? 'Queda moderada — ação comercial recomendada.'
    :               'Queda expressiva — ação comercial prioritária urgente.';

  var dQ1Interp = q1d===null ? '—'
    : (delta!==null && q1d > delta+5) ? 'Q1 acelerando vs FY — tendência positiva no trimestre.'
    : (delta!==null && q1d < delta-5) ? 'Q1 desacelerando vs FY — atenção ao trimestre atual.'
    : 'Q1 em linha com tendência anual.';

  var oppLevel  = opp>500?'Alta':opp>200?'Média':opp>50?'Baixa':'Mínima';
  var oppColor  = opp>500?'#06b6d4':opp>200?'#22c55e':opp>50?'#fbbf24':'#64748b';
  var reconqLvl = atend>=50?'Alta':atend>=25?'Média':'Baixa';
  var reconqClr = atend>=50?'#34d399':atend>=25?'#fbbf24':'#ef4444';

  var diagHtml =
    '<div style="margin-top:16px;border-radius:10px;background:rgba(34,197,94,0.04);border:0.5px solid rgba(34,197,94,0.18);overflow:hidden;">'
    // header
    +'<div style="padding:10px 16px;background:rgba(34,197,94,0.06);border-bottom:0.5px solid rgba(34,197,94,0.12);">'
    +'<span style="font-size:9px;font-weight:800;letter-spacing:0.12em;color:#22c55e;text-transform:uppercase;">📋 DIAGNÓSTICO — '+p.name+'</span>'
    +'</div>'
    // grid 3 colunas
    +'<div style="padding:14px 16px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;">'

    // ── Col 1 — Evolução Anual ──────────────────────────────────────────
    +'<div style="background:#0D1117;border-radius:8px;padding:12px;border-left:3px solid #22c55e;">'
    +'<div style="font-size:9px;font-weight:800;color:#22c55e;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:10px;">① Evolução Anual</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;">'
    // FY25
    +'<div style="background:#E4EAF2;border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#3b82f6;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:3px;">FY25 · Jul/24–Mar/25</div>'
    +'<div style="font-size:16px;color:#e2e8f0;font-weight:800;">'+fy25.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDV-meses</span></div>'
    +'</div>'
    // FY26
    +'<div style="background:#E4EAF2;border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#22c55e;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:3px;">FY26 · Jul/25–Mar/26</div>'
    +'<div style="font-size:16px;color:#e2e8f0;font-weight:800;">'+fy26.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDV-meses</span></div>'
    +'</div>'
    // Delta
    +'<div style="background:rgba(34,197,94,0.05);border-radius:6px;padding:10px;border:0.5px solid rgba(34,197,94,0.15);">'
    +'<div style="font-size:8px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px;">Δ% FY25 → FY26</div>'
    +'<div style="font-size:22px;font-weight:900;color:'+dCol(delta)+';line-height:1;">'+(delta===null?'—':(delta>=0?'+':'')+delta.toFixed(1)+'%')+'</div>'
    +'<div style="font-size:8px;color:#64748b;margin-top:5px;line-height:1.5;">'+dDeltaInterp+'</div>'
    +'</div>'
    +'</div></div>'

    // ── Col 2 — Q1 & Tendência ─────────────────────────────────────────
    +'<div style="background:#0D1117;border-radius:8px;padding:12px;border-left:3px solid #a78bfa;">'
    +'<div style="font-size:9px;font-weight:800;color:#a78bfa;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:10px;">② Tendência Q1</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;">'
    // Q1 FY25
    +'<div style="background:#E4EAF2;border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#94a3b8;margin-bottom:3px;">Q1 FY25 · Jan–Mar/25</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+q1_25.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDV-meses</span></div>'
    +'</div>'
    // Q1 FY26
    +'<div style="background:rgba(139,92,246,0.07);border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#a78bfa;margin-bottom:3px;">Q1 FY26 · Jan–Mar/26</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+q1_26.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDV-meses</span></div>'
    +'</div>'
    // Delta Q1
    +'<div style="background:rgba(139,92,246,0.06);border-radius:6px;padding:10px;border:0.5px solid rgba(139,92,246,0.18);">'
    +'<div style="font-size:8px;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px;">Δ% Q1 YoY</div>'
    +'<div style="font-size:20px;font-weight:900;color:'+dCol(q1d)+';line-height:1;">'+(q1d===null?'—':(q1d>=0?'+':'')+q1d.toFixed(1)+'%')+'</div>'
    +'<div style="font-size:8px;color:#64748b;margin-top:5px;line-height:1.5;">'+dQ1Interp+'</div>'
    +'</div>'
    +'</div></div>'

    // ── Col 3 — Oportunidade & Reconquista ────────────────────────────
    +'<div style="background:#0D1117;border-radius:8px;padding:12px;border-left:3px solid #f97316;">'
    +'<div style="font-size:9px;font-weight:800;color:#f97316;letter-spacing:0.1em;text-transform:uppercase;margin-bottom:10px;">③ Oportunidade</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;">'
    // CIMED
    +'<div style="background:rgba(167,139,250,0.07);border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#a78bfa;margin-bottom:3px;">CIMED sem SCJ</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+(p.opp_ci||0).toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDVs</span></div>'
    +'</div>'
    // RB
    +'<div style="background:rgba(96,165,250,0.07);border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#60a5fa;margin-bottom:3px;">RB sem SCJ</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+(p.opp_rb||0).toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDVs</span></div>'
    +'</div>'
    // Consolidado + nível
    +'<div style="background:rgba(249,115,22,0.07);border-radius:6px;padding:8px 10px;">'
    +'<div style="font-size:8px;font-weight:700;color:#f97316;margin-bottom:3px;">Consolidado (Dedup.)</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+opp.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDVs</span></div>'
    +'<div style="font-size:8px;margin-top:3px;color:'+oppColor+';font-weight:700;">Nível: '+oppLevel+'</div>'
    +'</div>'
    // Reconquista
    +'<div style="background:rgba(52,211,153,0.07);border-radius:6px;padding:8px 10px;border:0.5px solid rgba(52,211,153,0.12);">'
    +'<div style="font-size:8px;font-weight:700;color:#34d399;margin-bottom:3px;">🔄 Reconquista</div>'
    +'<div style="font-size:14px;color:#e2e8f0;font-weight:700;">'+reconq.toLocaleString('pt-BR')+'<span style="font-size:9px;color:#64748b;margin-left:4px;">PDVs</span></div>'
    +'<div style="font-size:8px;margin-top:3px;color:'+reconqClr+';font-weight:700;">Conv. '+atend+'% — '+reconqLvl+' prioridade</div>'
    +'</div>'
    +'</div></div>'

    +'</div></div>'; // /grid-3-cols, /diagnostico

  bodyEl.innerHTML = kpi + cimedRb + canvas + ufHtml + diagHtml;

  /* ── Renderizar gráfico após DOM estar pronto ── */
  setTimeout(function(){
    var ctx=document.getElementById('yoy-detail-chart');
    if(!ctx) return;
    if(_yoyChart){ _yoyChart.destroy(); _yoyChart=null; }
    _yoyChart=new Chart(ctx,{
      type:'bar',
      data:{
        labels:lbl,
        datasets:[
          {label:'FY25 (Jul/24-Mar/25)', data:fy25arr,
           backgroundColor:'rgba(59,130,246,0.5)', borderColor:'#3b82f6',
           borderWidth:1.5, borderRadius:4, barPercentage:0.4, categoryPercentage:0.8},
          {label:'FY26 (Jul/25-Mar/26)', data:fy26arr,
           backgroundColor:'rgba(34,197,94,0.6)', borderColor:'#22c55e',
           borderWidth:1.5, borderRadius:4, barPercentage:0.4, categoryPercentage:0.8}
        ]
      },
      options:{
        responsive:true, maintainAspectRatio:false,
        plugins:{legend:{labels:{color:'#94a3b8',font:{size:10}}},
          tooltip:{callbacks:{label:function(c){return c.dataset.label+': '+c.raw.toLocaleString('pt-BR')+' PDV·meses';}}}},
        scales:{
          x:{ticks:{color:'#64748b',font:{size:10}}, grid:{color:'rgba(255,255,255,0.04)'}},
          y:{ticks:{color:'#64748b',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},
             grid:{color:'rgba(255,255,255,0.05)'}, beginAtZero:true}
        }
      }
    });
  },80);
}

function _yoyKpi(lbl,val,sub,col,dynCol){
  var c=dynCol||col||'#94a3b8';
  return '<div style="background:#E4EAF2;padding:12px 16px;border-left:1px solid rgba(94,153,208,0.35);border-right:1px solid rgba(94,153,208,0.35);border-bottom:1px solid rgba(94,153,208,0.35);">'
    +'<div style="font-size:8px;font-weight:700;letter-spacing:0.08em;color:#475569;margin-bottom:4px;text-transform:uppercase;">'+lbl+'</div>'
    +'<div style="font-size:18px;font-weight:800;color:'+c+';line-height:1;">'+val+'</div>'
    +'<div style="font-size:8px;color:#64748B;margin-top:3px;">'+sub+'</div>'
    +'</div>';
}

/* ── Ranking geral (todos os provedores) ── */
function _yoyRenderRanking(bodyEl){
  var rows=[];
  (PROV_DATA||[]).forEach(function(p){
    var M=p.monthly||[];
    var fy25=0,fy26=0;
    for(var i=3;i<=11;i++) fy25+=(M[i]||0);
    for(var i=15;i<=23;i++) fy26+=(M[i]||0);
    var q1_25=(M[9]||0)+(M[10]||0)+(M[11]||0);
    var q1_26=(M[21]||0)+(M[22]||0)+(M[23]||0);
    var delta=fy25>0?(fy26-fy25)/fy25*100:null;
    var q1d  =q1_25>0?(q1_26-q1_25)/q1_25*100:null;
    var opp=p.opp_total||0,reconq=p.reconquista||0;
    var atend=(opp+reconq)>0?Math.round(reconq/(opp+reconq)*100):0;
    if(fy25>=100||fy26>=100) rows.push({name:p.name,fy25:fy25,fy26:fy26,delta:delta,
      q1_25:q1_25,q1_26:q1_26,q1d:q1d,opp_ci:p.opp_ci||0,opp_rb:p.opp_rb||0,
      opp:opp,reconq:reconq,atend:atend,monthly:M});
  });
  _yoyTotal=rows.length;

  rows.sort(function(a,b){
    if(_yoySortKey==='opp')    return b.opp-a.opp;
    if(_yoySortKey==='reconq') return b.atend-a.atend;
    if(a.delta===null&&b.delta===null)return 0;
    if(a.delta===null)return 1; if(b.delta===null)return -1;
    return b.delta-a.delta;
  });

  var totFy25=0,totFy26=0,totOpp=0,totReconq=0,totQ1_25=0,totQ1_26=0;
  rows.forEach(function(r){totFy25+=r.fy25;totFy26+=r.fy26;totOpp+=r.opp;totReconq+=r.reconq;totQ1_25+=r.q1_25;totQ1_26+=r.q1_26;});
  var totDelta=totFy25>0?(totFy26-totFy25)/totFy25*100:0;
  var totQ1D  =totQ1_25>0?(totQ1_26-totQ1_25)/totQ1_25*100:0;
  var totAtend=(totOpp+totReconq)>0?Math.round(totReconq/(totOpp+totReconq)*100):0;
  var dSign=function(v){return v===null?'—':(v>=0?'+':'')+v.toFixed(1)+'%';};
  var dCol =function(v){return v===null?'#64748b':v>=0?'#34d399':'#ef4444';};

  /* KPI strip */
  var kpi='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:#E4EAF2;border-radius:10px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(94,153,208,0.45);box-shadow:0 2px 8px rgba(10,40,80,0.08);">'
    +_yoyKpi('PROVEDORES ATIVOS',rows.length+' mapeados','min. 100 PDV·meses','#94a3b8')
    +_yoyKpi('FY25 Jul→Mar',totFy25.toLocaleString('pt-BR'),'PDV·meses consolid.','#3b82f6')
    +_yoyKpi('FY26 Jul→Mar',totFy26.toLocaleString('pt-BR'),'PDV·meses Jul/25→Mar/26','#22c55e')
    +_yoyKpi('Δ YoY TOTAL',dSign(totDelta),'FY26 vs FY25','',dCol(totDelta))
    +_yoyKpi('CIMED+RB · Conv.',totOpp.toLocaleString('pt-BR')+' · '+totAtend+'%','Oport.+Reconq: '+totReconq.toLocaleString('pt-BR'),'#f97316')
    +'</div>';

  var visible=_yoyShowAll?rows:rows.slice(0,20);

  var table='<div style="overflow-x:auto;">'
    +'<table style="width:100%;border-collapse:collapse;font-size:10px;">'
    +'<thead><tr style="border-bottom:1px solid rgba(255,255,255,0.06);">'
    +'<th style="padding:8px 6px;text-align:left;color:#475569;font-size:8px;font-weight:700;letter-spacing:0.06em;">#</th>'
    +'<th style="padding:8px 6px;text-align:left;color:#475569;font-size:8px;font-weight:700;">PROVEDOR</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#3b82f6;font-size:8px;font-weight:700;white-space:nowrap;">FY25<br>Jul→Mar</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#22c55e;font-size:8px;font-weight:700;white-space:nowrap;">FY26<br>Jul→Mar</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#fbbf24;font-size:8px;font-weight:700;white-space:nowrap;">Δ YoY</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#94a3b8;font-size:8px;font-weight:700;white-space:nowrap;">Q1/25</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#94a3b8;font-size:8px;font-weight:700;white-space:nowrap;">Q1/26</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#94a3b8;font-size:8px;font-weight:700;white-space:nowrap;">Δ Q1</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#a78bfa;font-size:8px;font-weight:700;white-space:nowrap;">CIMED<br>sem SCJ</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#60a5fa;font-size:8px;font-weight:700;white-space:nowrap;">RB<br>sem SCJ</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#f97316;font-size:8px;font-weight:700;white-space:nowrap;">CIMED+RB<br>Consol.</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#34d399;font-size:8px;font-weight:700;white-space:nowrap;">Reconq.</th>'
    +'<th style="padding:8px 6px;text-align:right;color:#f97316;font-size:8px;font-weight:700;white-space:nowrap;">Conv.%</th>'
    +'<th style="padding:8px 6px;color:#94a3b8;font-size:8px;font-weight:700;white-space:nowrap;">Trend FY26</th>'
    +'</tr></thead><tbody>';

  visible.forEach(function(r,idx){
    var rank=idx+1;
    var icon=rank===1?'🥇':rank===2?'🥈':rank===3?'🥉':rank;
    var dc=dCol(r.delta), qdc=dCol(r.q1d);
    var isTop=rank<=3&&_yoySortKey==='delta'&&r.delta>0;
    var isBad=r.delta!==null&&r.delta<-20;
    var bg=isTop?'background:rgba(52,211,153,0.04);':isBad?'background:rgba(239,68,68,0.03);':'';
    var aco=r.atend>=50?'#34d399':r.atend>=25?'#fbbf24':'#ef4444';
    // spark
    var sv=[]; for(var i=15;i<=23;i++) sv.push(r.monthly[i]||0);
    var smx=Math.max.apply(null,sv)||1;
    var spark='<div style="display:flex;align-items:flex-end;gap:1px;height:20px;width:80px;">';
    sv.forEach(function(v){
      var h=Math.max(1,Math.round(v/smx*18));
      var c=v>smx*0.7?'#34d399':v>smx*0.4?'#fbbf24':'#94a3b8';
      spark+='<div style="flex:1;height:'+h+'px;background:'+c+';border-radius:1px;opacity:0.8;"></div>';
    });
    spark+='</div>';

    table+='<tr style="border-bottom:0.5px solid rgba(255,255,255,0.04);'+bg+'" '
      +'onmouseover="this.style.background=\'rgba(34,197,94,0.05)\'" onmouseout="this.style.background=\''+bg.replace('background:','').replace(';','')+'\'">'
      +'<td style="padding:7px 6px;color:#475569;font-size:9px;font-weight:700;text-align:center;">'+icon+'</td>'
      +'<td style="padding:7px 6px;font-size:10px;font-weight:600;color:#D1D5DB;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'
        +'<span onclick="yoySelectProv(\''+r.name.replace(/'/g,"\\'")+'\');" style="cursor:pointer;text-decoration:underline;text-decoration-color:#334155;text-underline-offset:3px;" onmouseover="this.style.color=\'#22c55e\'" onmouseout="this.style.color=\'#D1D5DB\'">'+r.name+'</span>'
      +'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#3b82f6;font-size:10px;">'+r.fy25.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#22c55e;font-size:10px;font-weight:600;">'+r.fy26.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;font-size:11px;font-weight:800;color:'+dc+';">'+dSign(r.delta)+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#64748b;font-size:9px;">'+r.q1_25.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#94a3b8;font-size:9px;font-weight:600;">'+r.q1_26.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;font-size:10px;font-weight:700;color:'+qdc+';">'+dSign(r.q1d)+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#a78bfa;font-size:10px;">'+(r.opp_ci>0?r.opp_ci.toLocaleString('pt-BR'):'<span style="color:#1e293b">—</span>')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#60a5fa;font-size:10px;">'+(r.opp_rb>0?r.opp_rb.toLocaleString('pt-BR'):'<span style="color:#1e293b">—</span>')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#f97316;font-size:10px;font-weight:600;">'+(r.opp>0?r.opp.toLocaleString('pt-BR'):'<span style="color:#1e293b">—</span>')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;color:#34d399;font-size:10px;">'+(r.reconq>0?r.reconq.toLocaleString('pt-BR'):'<span style="color:#1e293b">—</span>')+'</td>'
      +'<td style="padding:7px 6px;text-align:right;font-size:10px;font-weight:700;color:'+aco+';">'+(r.opp>0?r.atend+'%':'<span style="color:#1e293b">—</span>')+'</td>'
      +'<td style="padding:7px 6px;">'+spark+'</td>'
      +'</tr>';
  });

  /* Linha total */
  table+='<tr style="border-top:1px solid rgba(251,191,36,0.2);background:rgba(251,191,36,0.03);">'
    +'<td></td>'
    +'<td style="padding:8px 6px;font-size:10px;font-weight:800;color:#fbbf24;">TOTAL GERAL</td>'
    +'<td style="padding:8px 6px;text-align:right;color:#3b82f6;font-weight:700;">'+totFy25.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;color:#22c55e;font-weight:700;">'+totFy26.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;font-size:11px;font-weight:800;color:'+dCol(totDelta)+';">'+dSign(totDelta)+'</td>'
    +'<td style="padding:8px 6px;text-align:right;color:#64748b;font-size:9px;">'+totQ1_25.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;color:#94a3b8;font-size:9px;font-weight:700;">'+totQ1_26.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;font-size:10px;font-weight:800;color:'+dCol(totQ1D)+';">'+dSign(totQ1D)+'</td>'
    +'<td colspan="2"></td>'
    +'<td style="padding:8px 6px;text-align:right;color:#f97316;font-weight:700;">'+totOpp.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;color:#34d399;font-weight:700;">'+totReconq.toLocaleString('pt-BR')+'</td>'
    +'<td style="padding:8px 6px;text-align:right;font-size:10px;font-weight:800;color:#f97316;">'+totAtend+'%</td>'
    +'<td></td>'
    +'</tr>';
  table+='</tbody></table></div>';

  var btnAll='<div style="text-align:center;margin-top:10px;">'
    +'<button onclick="toggleYoYAll(this)" style="font-size:10px;padding:6px 18px;border-radius:8px;border:0.5px solid rgba(255,255,255,0.1);background:transparent;color:#64748b;cursor:pointer;">'
    +(_yoyShowAll?'Ver Top 20':'Ver todos ('+rows.length+')')
    +'</button></div>';

  /* ── Usa ufAgg do cache (computado por _yoyEnsureMap) ── */
  var ufAgg = _yoyUfAgg || {};
  var _activeUFs = Object.keys(ufAgg).filter(function(uf){ return ufAgg[uf].scj > 0; });

  bodyEl.innerHTML=kpi+table+btnAll;
}

/* ═══════════════════════════════════════════════════════════════════════
   YoY Aggregate Map — Leaflet choropleth com dados de todos os provedores
   Instância separada de _gpfMap para evitar conflitos de container.
═══════════════════════════════════════════════════════════════════════ */
var _yoyAggMap     = null;
var _yoyAggMapBrGeo= null;
var _yoyUfAgg      = null;  /* cache do ufAgg — computado uma vez */
var _yoyMapInited  = false; /* flag: mapa fixo já renderizado */
var _yoyCurProv    = '__ALL__'; /* provedor que o mapa exibe atualmente */

function _yoyInitAggMap(ufAgg){
  /* Destruir instância anterior */
  if(_yoyAggMap){ try{_yoyAggMap.remove();}catch(e){} _yoyAggMap=null; _yoyAggMapBrGeo=null; }

  /* Garantir GeoJSON EDM carregado */
  _gpfPreloadEDMData();

  if(typeof window.EDM_BR_GEO === 'undefined' || typeof window.EDM_IBGE === 'undefined'){
    setTimeout(function(){ _yoyInitAggMap(ufAgg); }, 600);
    return;
  }

  var el = document.getElementById('yoy-agg-map');
  if(!el || typeof L === 'undefined') return;

  function stateColor(uf){
    var d = ufAgg[uf];
    if(!d || d.total === 0) return '#1e3a4a';
    var pct = Math.round(d.scj / d.total * 100);
    return pct>=70?'#34d399':pct>=40?'#fbbf24':pct>=20?'#f97316':'#ef4444';
  }

  _yoyAggMap = L.map(el, {center:[-15,-52], zoom:4, zoomControl:false, attributionControl:false});
  L.control.zoom({position:'bottomright'}).addTo(_yoyAggMap);

  var _edmGeo  = window.EDM_BR_GEO;
  var _edmIbge = window.EDM_IBGE;

  _yoyAggMapBrGeo = L.geoJSON(_edmGeo, {
    style: function(f){
      var uf     = _edmIbge[String(f.properties.codarea)];
      var d      = uf && ufAgg[uf];
      var active = d && d.scj > 0;
      return {
        fillColor:   uf ? stateColor(uf) : '#1e3a4a',
        fillOpacity: active ? 0.85 : 0.25,
        color: 'rgba(255,255,255,0.18)',
        weight: 1
      };
    },
    onEachFeature: function(f, lyr){
      var uf  = _edmIbge[String(f.properties.codarea)];
      if(!uf) return;
      var d   = ufAgg[uf];
      var pct = d && d.total > 0 ? Math.round(d.scj / d.total * 100) : null;
      var pctCol = pct!=null ? (pct>=70?'#34d399':pct>=40?'#fbbf24':pct>=20?'#f97316':'#ef4444') : '#334155';
      var active = !!(d && d.scj > 0);

      /* Tooltip — compacto, estado sempre visível no topo */
      var ttip = '<div style="min-width:185px;font-family:inherit;padding:2px;">';
      /* Header: estado + % sempre visível */
      ttip += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;padding-bottom:4px;border-bottom:0.5px solid rgba(255,255,255,0.1);">'
        +'<span style="font-weight:800;font-size:13px;color:#67e8f9;">'+uf+'</span>'
        +(pct!==null?'<span style="font-size:15px;font-weight:900;color:'+pctCol+';">'+pct+'%</span>':'')
        +'</div>';
      if(d && d.total > 0){
        var _yoyTip = d.scj_fy25>0 ? Math.round((d.scj-d.scj_fy25)/d.scj_fy25*100) : null;
        var _yoyC = _yoyTip===null?'#64748b':_yoyTip>5?'#34d399':_yoyTip>=-5?'#fbbf24':'#ef4444';
        ttip += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:3px;">'
          +'<div style="background:rgba(255,255,255,0.04);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">🏪 Universo IQVIA</div>'
            +'<div style="font-size:11px;font-weight:700;color:#D1D5DB;">'+d.total.toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:rgba(52,211,153,0.08);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">✅ Positiv. FY26</div>'
            +'<div style="font-size:11px;font-weight:700;color:#34d399;">'+d.scj.toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:rgba(59,130,246,0.08);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">✅ Positiv. FY25</div>'
            +'<div style="font-size:11px;font-weight:700;color:#93c5fd;">'+d.scj_fy25.toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:rgba(239,68,68,0.06);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">⬜ Disponíveis</div>'
            +'<div style="font-size:11px;font-weight:700;color:#ef4444;">'+(d.white_sp||0).toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:rgba(251,191,36,0.06);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">🔄 Não Comp. FY26</div>'
            +'<div style="font-size:11px;font-weight:700;color:#fbbf24;">'+(d.reconq||0).toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:rgba(148,163,184,0.06);border-radius:3px;padding:3px 5px;">'
            +'<div style="font-size:7.5px;color:#64748b;">📭 Nunca Comprou</div>'
            +'<div style="font-size:11px;font-weight:700;color:#94a3b8;">'+(d.ws_puro||0).toLocaleString('pt-BR')+'</div>'
          +'</div>'
          +'<div style="background:#E4EAF2;border-radius:3px;padding:3px 5px;border-left:2px solid '+_yoyC+';">'
            +'<div style="font-size:7.5px;color:#64748b;">📈 GAP FY25→FY26</div>'
            +'<div style="font-size:11px;font-weight:700;color:'+_yoyC+';">'+(_yoyTip===null?'—':(_yoyTip>=0?'+':'')+_yoyTip+'%')+'</div>'
          +'</div>'
          +'</div>';
        if(active) ttip += '<div style="margin-top:4px;font-size:7.5px;color:#3d6b63;text-align:center;">▶ Clique para ver detalhes e cidades</div>';
      } else {
        ttip += '<div style="font-size:10px;color:#334155;">Fora da área de cobertura</div>';
      }
      ttip += '</div>';

      lyr.bindTooltip(ttip, {sticky:true, opacity:1, className:'gpf-map-tip'});
      lyr.on({
        mouseover: function(e){
          if(active){ e.target.setStyle({fillOpacity:1, weight:2, color:'#06b6d4'}); e.target.bringToFront(); }
        },
        mouseout: function(e){ if(_yoyAggMapBrGeo) _yoyAggMapBrGeo.resetStyle(e.target); },
        click:    function(){ if(active) _yoyAggUfClick(uf, d); }
      });
    }
  }).addTo(_yoyAggMap);

  /* Labels UF + % — branco com badge escuro, legível em qualquer fundo */
  var lblLyr = L.layerGroup();
  _yoyAggMapBrGeo.eachLayer(function(lyr){
    var uf  = _edmIbge[String(lyr.feature.properties.codarea)];
    if(!uf) return;
    var d   = ufAgg[uf];
    var pct = d && d.total > 0 ? Math.round(d.scj / d.total * 100) : null;
    var pctCol = pct!=null ? (pct>=70?'#34d399':pct>=40?'#fbbf24':pct>=20?'#f97316':'#ef4444') : '#94a3b8';
    var center = lyr.getBounds().getCenter();
    L.marker(center, {
      icon: L.divIcon({
        className: '',
        html: '<div style="pointer-events:none;text-align:center;transform:translate(-50%,-50%);white-space:nowrap;">'
          +'<div style="display:inline-block;background:rgba(0,0,0,0.72);'
            +'border-radius:6px;padding:3px 8px 4px 8px;'
            +'border-left:3px solid '+pctCol+';'
            +'box-shadow:0 2px 8px rgba(0,0,0,0.85);">'
            +'<div style="font-size:14px;font-weight:900;color:#fff;line-height:1.2;letter-spacing:.05em;text-shadow:0 1px 2px #000;">'+uf+'</div>'
            +(pct!==null
              ? '<div style="font-size:13px;font-weight:800;color:#fff;line-height:1.1;text-shadow:0 1px 2px #000;">'+pct+'%</div>'
              : '')
          +'</div>'
          +'</div>',
        iconSize:[64,42], iconAnchor:[32,21]
      }),
      interactive:false, keyboard:false
    }).addTo(lblLyr);
  });
  lblLyr.addTo(_yoyAggMap);

  /* Fit bounds — triplo pass para garantir render completo */
  setTimeout(function(){
    if(!_yoyAggMap) return;
    _yoyAggMap.invalidateSize(true);
    if(_yoyAggMapBrGeo) _yoyAggMap.fitBounds(_yoyAggMapBrGeo.getBounds(), {padding:[8,8]});
    setTimeout(function(){
      if(!_yoyAggMap) return;
      _yoyAggMap.invalidateSize(true);
      if(_yoyAggMapBrGeo) _yoyAggMap.fitBounds(_yoyAggMapBrGeo.getBounds(), {padding:[8,8]});
      setTimeout(function(){
        if(!_yoyAggMap) return;
        _yoyAggMap.invalidateSize(true);
        if(_yoyAggMapBrGeo) _yoyAggMap.fitBounds(_yoyAggMapBrGeo.getBounds(), {padding:[8,8]});
      }, 600);
    }, 400);
  }, 300);
}

function _yoyAggUfClick(uf, d){
  var drill = document.getElementById('yoy-agg-drill');
  if(!drill) return;

  var pct    = d.total > 0 ? Math.round(d.scj / d.total * 100) : 0;
  var pct25  = d.total > 0 ? Math.round(d.scj_fy25 / d.total * 100) : 0;
  var pctCol = pct>=70?'#34d399':pct>=40?'#fbbf24':pct>=20?'#f97316':'#ef4444';
  var wsPct  = d.total > 0 ? Math.round(d.white_sp / d.total * 100) : 0;
  var rqPct  = d.total > 0 ? Math.round(d.reconq / d.total * 100) : 0;

  /* YoY real — positivação ano 2024x2025x2026 */
  var scj25  = d.scj_fy25 || 0;
  var scj26  = d.scj       || 0;
  var yoyD   = scj25 > 0 ? Math.round((scj26 - scj25) / scj25 * 100) : null;
  var yoyCol = yoyD===null?'#64748b':yoyD>5?'#34d399':yoyD>=-5?'#fbbf24':'#ef4444';

  /* Cidades top-20 deste estado */
  var _cityCob = (typeof CITY_COB_DATA !== 'undefined') ? (CITY_COB_DATA[uf]||[]) : [];


  var _kpiStyle = 'border-radius:6px;padding:8px 10px;';

  /* ── Tabela cidades ── */
  var _cityRows = '';
  if(_cityCob.length > 0){
    _cityRows = '<table style="width:100%;border-collapse:collapse;font-size:9px;">'
      +'<thead><tr style="border-bottom:0.5px solid rgba(255,255,255,0.08);">'
      +'<th style="text-align:left;padding:3px 4px;color:#64748b;font-weight:600;">Cidade</th>'
      +'<th style="text-align:right;padding:3px 4px;color:#64748b;font-weight:600;">Univ</th>'
      +'<th style="text-align:right;padding:3px 4px;color:#22c55e;font-weight:600;">FY26</th>'
      +'<th style="text-align:right;padding:3px 4px;color:#93c5fd;font-weight:600;">FY25</th>'
      +'<th style="text-align:right;padding:3px 4px;color:#64748b;font-weight:600;">Cob%</th>'
      +'<th style="text-align:right;padding:3px 4px;color:#fbbf24;font-weight:600;">Reconv</th>'
      +'</tr></thead><tbody>';
    _cityCob.forEach(function(c){
      var cPctCol = c.p>=70?'#34d399':c.p>=40?'#fbbf24':c.p>=20?'#f97316':'#ef4444';
      _cityRows += '<tr style="border-bottom:0.5px solid rgba(147,187,235,0.25);">'
        +'<td style="padding:3px 4px;color:#334155;font-size:8.5px;">'+c.n+'</td>'
        +'<td style="text-align:right;padding:3px 4px;color:#64748B;">'+c.u.toLocaleString('pt-BR')+'</td>'
        +'<td style="text-align:right;padding:3px 4px;color:#34d399;font-weight:700;">'+c.f26.toLocaleString('pt-BR')+'</td>'
        +'<td style="text-align:right;padding:3px 4px;color:#93c5fd;">'+c.f25.toLocaleString('pt-BR')+'</td>'
        +'<td style="text-align:right;padding:3px 4px;font-weight:700;color:'+cPctCol+';">'+c.p+'%</td>'
        +'<td style="text-align:right;padding:3px 4px;color:#fbbf24;">'+c.rq.toLocaleString('pt-BR')+'</td>'
        +'</tr>';
    });
    _cityRows += '</tbody></table>';
  }

  var html = '<div style="width:100%;padding:4px;">'

    /* ── Header ── */
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'
      +'<div style="font-size:22px;font-weight:800;color:#1D6FA8;">'+uf+'</div>'
      +'<div style="text-align:right;">'
        +'<div style="font-size:24px;font-weight:900;color:'+pctCol+';">'+pct+'%</div>'
        +'<div style="font-size:7.5px;color:#64748B;">cobertura FY26</div>'
      +'</div>'
    +'</div>'

    /* ── Barra cobertura ── */
    +'<div style="display:flex;height:10px;border-radius:3px;overflow:hidden;gap:1px;margin-bottom:3px;">'
      +'<div style="width:'+pct+'%;background:'+pctCol+';"></div>'
      +'<div style="flex:1;background:#1e3a4a;"></div>'
    +'</div>'
    +'<div style="display:flex;gap:12px;margin-bottom:10px;">'
      +'<span style="font-size:7.5px;color:'+pctCol+';">■ FY26 '+pct+'%</span>'
      +'<span style="font-size:7.5px;color:#93c5fd;">■ FY25 '+pct25+'%</span>'
      +'<span style="font-size:7.5px;color:#4a5568;">■ Disponível '+wsPct+'%</span>'
    +'</div>'

    /* ── 8 KPI cards em grid 2×4 ── */
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-bottom:10px;">'

      /* 1. Universo IQVIA */
      +'<div style="'+_kpiStyle+'background:#E4EAF2;">'
        +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">🏪 Universo IQVIA Ativo</div>'
        +'<div style="font-size:18px;font-weight:800;color:#67e8f9;">'+d.total.toLocaleString('pt-BR')+'</div>'
        +'<div style="font-size:7px;color:#334155;">CNPJs únicos IQVIA</div>'
      +'</div>'

      /* 2. Positivados FY26 */
      +'<div style="'+_kpiStyle+'background:#E4EAF2;">'
        +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">✅ '+(!d._prov_mode?'Positivados FY26':'SCJ Ativos')+'</div>'
        +'<div style="font-size:18px;font-weight:800;color:#34d399;">'+scj26.toLocaleString('pt-BR')+'</div>'
        +'<div style="font-size:7px;color:#334155;">'+pct+'% · '+(d._prov_mode?'deste provedor':'Jul/25–Abr/26')+'</div>'
      +'</div>'

      /* 3. Positivados FY25 — oculto no modo provedor */
      +(!d._prov_mode
        ? '<div style="'+_kpiStyle+'background:#E4EAF2;">'
            +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">✅ Positivados FY25</div>'
            +'<div style="font-size:18px;font-weight:800;color:#93c5fd;">'+scj25.toLocaleString('pt-BR')+'</div>'
            +'<div style="font-size:7px;color:#334155;">'+pct25+'% · Jul/24–Abr/25</div>'
          +'</div>'
        : '')

      /* 4. Disponíveis p/ Atendimento */
      +'<div style="'+_kpiStyle+'background:#E4EAF2;">'
        +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">⬜ Disponíveis p/ Atend.</div>'
        +'<div style="font-size:18px;font-weight:800;color:#ef4444;">'+(d.white_sp||0).toLocaleString('pt-BR')+'</div>'
        +'<div style="font-size:7px;color:#334155;">'+wsPct+'% · '+(d._prov_mode?'estado − SCJ provedor':'universo − FY26')+'</div>'
      +'</div>'

      /* 5. Não Compraram FY26 — só no modo todos provedores */
      +(!d._prov_mode
        ? '<div style="'+_kpiStyle+'background:#E4EAF2;">'
            +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">🔄 Não Compraram FY26</div>'
            +'<div style="font-size:18px;font-weight:800;color:#fbbf24;">'+(d.reconq||0).toLocaleString('pt-BR')+'</div>'
            +'<div style="font-size:7px;color:#334155;">'+rqPct+'% · FY25 sim · FY26 não</div>'
          +'</div>'
        : '')

      /* 6. Nunca Comprou — só no modo todos provedores */
      +(!d._prov_mode
        ? '<div style="'+_kpiStyle+'background:#E4EAF2;">'
            +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">📭 Nunca Comprou SCJ</div>'
            +'<div style="font-size:18px;font-weight:800;color:#94a3b8;">'+(d.ws_puro||0).toLocaleString('pt-BR')+'</div>'
            +'<div style="font-size:7px;color:#334155;">Sem FY25 e sem FY26</div>'
          +'</div>'
        : '')

      /* 7. % Cobertura FY26 */
      +'<div style="'+_kpiStyle+'background:rgba('+( pct>=70?'52,211,153':pct>=40?'251,191,36':pct>=20?'249,115,22':'239,68,68' )+',0.07);">'
        +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">📊 % Cobertura FY26</div>'
        +'<div style="font-size:22px;font-weight:900;color:'+pctCol+';">'+pct+'%</div>'
        +'<div style="font-size:7px;color:#334155;">do universo IQVIA ativo</div>'
      +'</div>'

      /* 8. GAP FY25→FY26 — só no modo todos provedores */
      +(!d._prov_mode
        ? '<div style="'+_kpiStyle+'border-left:2px solid '+yoyCol+';background:#E4EAF2;">'
            +'<div style="font-size:7px;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:2px;">📈 GAP FY25→FY26</div>'
            +'<div style="font-size:22px;font-weight:900;color:'+yoyCol+';line-height:1;">'+(yoyD===null?'—':(yoyD>=0?'+':'')+yoyD+'%')+'</div>'
            +'<div style="font-size:7px;color:#334155;margin-top:2px;">'+(yoyD!==null?(yoyD>5?'▲ Crescimento':yoyD>=-5?'→ Estável':'▼ Queda em positivação'):'Sem dado FY25')+'</div>'
          +'</div>'
        : '')

    +'</div>'

    /* ── Top Cidades — só no modo todos provedores ── */
    +(!d._prov_mode && _cityCob.length > 0
      ? '<div style="margin-top:2px;">'
          +'<div style="font-size:7.5px;font-weight:700;color:#64748b;letter-spacing:.08em;text-transform:uppercase;margin-bottom:6px;">'
            +'📍 TOP CIDADES — '+uf
          +'</div>'
          +_cityRows
          +'<div style="font-size:7px;color:#64748B;margin-top:5px;font-style:italic;">'
            +'Fonte: positivação 2024x2025x2026 · top 20 cidades por universo'
          +'</div>'
        +'</div>'
      : '')

  +'</div>';

  drill.style.cssText = 'background:#FFFFFF;border-radius:8px;padding:14px;'
    +'border:1px solid rgba(94,153,208,0.45);min-height:360px;overflow-y:auto;box-shadow:0 2px 12px rgba(10,40,80,0.10);';
  drill.innerHTML = html;
}


/* ── Computa ufAgg uma vez e mantém em cache ── */
function _yoyBuildUfAgg(provName){
  /* Se provName fornecido: filtra para aquele provedor (usa pv.by_uf do PROV_DATA)
     Se não: usa UF_COB_DATA (todos os provedores, positivação 2024x2025x2026.xlsx) */
  var agg = {};

  if(provName){
    /* ── Modo provedor filtrado ── */
    var pv = null;
    for(var _i=0; _i<(PROV_DATA||[]).length; _i++){
      if(PROV_DATA[_i].name === provName){ pv = PROV_DATA[_i]; break; }
    }
    /* Universo por estado — todos os CNPJs distintos (UF_COB_DATA) */
    var _cobDataPv = (typeof UF_COB_DATA !== 'undefined') ? UF_COB_DATA : {};
    if(pv && pv.by_uf){
      (pv.by_uf).forEach(function(u){
        var uf = u[0], provTot = u[1]||0, scj = u[2]||0;
        if(!provTot) return;
        /* Universo = TODOS os CNPJs distintos do estado (positivação 2024x2025x2026)
           Inclui: SCJ + CIMED + RB + qualquer player — deduplicado por CNPJ
           Fallback para provTot se o estado não estiver em UF_COB_DATA */
        var univTotal = (_cobDataPv[uf] && _cobDataPv[uf].universe) ? _cobDataPv[uf].universe : provTot;
        agg[uf] = {
          total:    univTotal,         /* universo TOTAL estado — todos CNPJs distintos IQVIA */
          scj:      scj,              /* CNPJs SCJ ativos via este provedor */
          scj_fy25: 0,
          reconq:   0,
          ws_puro:  0,
          white_sp: univTotal - scj,  /* disponíveis = universo estado − SCJ deste provedor */
          yoy_gap:  null,
          _prov_mode: true
        };
      });
    }
    return agg;
  }

  /* ── Modo todos os provedores — UF_COB_DATA ── */
  var _cobData = (typeof UF_COB_DATA !== 'undefined') ? UF_COB_DATA : {};
  Object.keys(_cobData).forEach(function(uf){
    var r = _cobData[uf];
    if(!r.universe) return;
    var yoyD = r.fy25 > 0 ? Math.round((r.fy26 - r.fy25) / r.fy25 * 100) : 0;
    agg[uf] = {
      total:    r.universe,
      scj:      r.fy26,
      scj_fy25: r.fy25,
      reconq:   r.reconq,
      ws_puro:  r.ws_puro,
      white_sp: r.white_sp,
      yoy_gap:  yoyD,
      _prov_mode: false
    };
  });
  return agg;
}

/* ── Garante mapa fixo — reconstrói se o filtro de provedor mudou ── */
function _yoyEnsureMap(){
  var _reqProv = _yoySelProv || '__ALL__';
  /* Só recria se não inicializado ou se o provedor mudou */
  if(_yoyMapInited && _yoyCurProv === _reqProv) return;
  if(typeof PROV_DATA === 'undefined') return;

  /* Destruir instância Leaflet anterior se houver */
  if(_yoyAggMap){ try{_yoyAggMap.remove();}catch(e){} _yoyAggMap=null; _yoyAggMapBrGeo=null; }

  _yoyCurProv = _reqProv;
  _yoyUfAgg   = _yoyBuildUfAgg(_yoySelProv || null);

  var mapWrap = document.getElementById('yoy-map-fixed');
  if(!mapWrap) return;

  var _activeUFs = Object.keys(_yoyUfAgg).filter(function(uf){ return _yoyUfAgg[uf].scj > 0; });
  var _isProv = !!_yoySelProv;
  var _headerTitle = _isProv
    ? 'COBERTURA POR ESTADO — <span style="color:#67e8f9;">'+_yoySelProv+'</span>'
    : 'COBERTURA POR ESTADO — TODOS OS PROVEDORES';

  var _yoyLegendItems = [
    {c:'#34d399',l:'≥70%'},{c:'#fbbf24',l:'40–69%'},
    {c:'#f97316',l:'20–39%'},{c:'#ef4444',l:'<20%'},
    {c:'#334155',l:'Fora da área',border:true}
  ];
  var _yoyLegendHtml = '<div style="display:flex;gap:14px;margin-top:10px;flex-wrap:wrap;align-items:center;padding:0 2px;">'
    +_yoyLegendItems.map(function(it){
      return '<span style="display:flex;align-items:center;gap:4px;font-size:9px;color:#94A3B8;">'
        +'<span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:'+it.c+';'+(it.border?'border:1px solid #4a5568;':'')+'"> </span>'+it.l+'</span>';
    }).join('')
    +'<span style="margin-left:auto;font-size:9px;color:#3d6b63;font-style:italic;">Clique em um estado para ver detalhes</span>'
    +'</div>';

  mapWrap.innerHTML =
    '<div style="background:rgba(0,0,0,0.2);border-radius:8px;padding:12px 14px;">'
    +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#94A3B8;margin-bottom:10px;">'
      +_headerTitle
      +'<span style="color:#3d6b63;font-weight:400;"> · '+_activeUFs.length+' estados ativos</span>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1.6fr 1fr;gap:12px;align-items:stretch;">'
      +'<div id="yoy-agg-map" style="height:460px;border-radius:8px;overflow:hidden;background:#0a1218;"></div>'
      +'<div id="yoy-agg-drill" style="background:#161B22;border-radius:8px;padding:14px;border:0.5px solid rgba(103,232,249,0.12);display:flex;align-items:center;justify-content:center;min-height:360px;">'
        +'<span style="font-size:11px;color:#64748B;font-style:italic;text-align:center;">← Clique em um<br>estado para ver<br>os detalhes</span>'
      +'</div>'
    +'</div>'
    +_yoyLegendHtml
    +'</div>';

  mapWrap.style.display = 'block';
  _yoyMapInited = true;
  setTimeout(function(){ _yoyInitAggMap(_yoyUfAgg); }, 120);
}

/* ── Entry point ── */
function renderProvYoYCard(){
  var bodyEl=document.getElementById('prov-yoy-body');
  if(!bodyEl||typeof PROV_DATA==='undefined') return;

  /* Garante mapa fixo — só renderiza na primeira chamada */
  _yoyEnsureMap();

  if(_yoySelProv){
    var p=null;
    for(var i=0;i<PROV_DATA.length;i++){if(PROV_DATA[i].name===_yoySelProv){p=PROV_DATA[i];break;}}
    if(p){ _yoyRenderDetail(p,bodyEl); return; }
  }
  _yoyRenderRanking(bodyEl);
}


function initSellin(){
  if(sellinInit) return;
  sellinInit = true;
  renderSellinKPIs();
  renderSellinBarGeral();
  renderSellinMensalChart();
  renderSellinResumoTable();
  renderSellinCards();
  renderSellinVerbas();
  // Evolução Mensal de Positivação GAM + Gaúcha
  setTimeout(function(){ if(typeof renderMensalPos==='function') renderMensalPos(); }, 150);
}

function setSellinFilter(f, btn){
  sellinFilter = f;
  document.querySelectorAll('#sellin-filter-btns .tgl').forEach(function(b){
    b.classList.remove('active'); b.style.background=''; b.style.color=''; b.style.borderColor='';
  });
  btn.classList.add('active');
  if(f==='todos'){ btn.style.background='rgba(52,211,153,0.15)'; btn.style.color='#34d399'; btn.style.borderColor='rgba(52,211,153,0.4)'; }
  renderSellinCards();
  renderSellinBarGeral();
}

function setSellinChartMode(mode, btn){
  sellinMode = mode;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderSellinBarGeral();
}

function setSellinFY(fy, btn) {
  SELLIN_FY_ATUAL = fy;
  if(fy === 'FY26') {
    SELLIN_DATA  = SELLIN_DATA_FY26;
    SELLIN_TOTAL = SELLIN_TOTAL_FY26;
    SELLIN_MES_ATUAL     = 11;
    SELLIN_MES_ATUAL_LBL = 'JUN/26';
  } else {
    SELLIN_DATA  = SELLIN_DATA_FY27;
    SELLIN_TOTAL = SELLIN_TOTAL_FY27;
    SELLIN_MES_ATUAL     = 4;
    SELLIN_MES_ATUAL_LBL = 'NOV/26';
  }
  // Atualizar botões FY
  document.querySelectorAll('.sellin-fy-btn').forEach(function(b){
    b.classList.remove('active','blue');
    b.style.background = 'rgba(148,163,184,0.10)';
    b.style.color = '#94a3b8';
    b.style.borderColor = 'rgba(148,163,184,0.3)';
  });
  if(btn) {
    btn.classList.add('active','blue');
    btn.style.background = 'rgba(52,211,153,0.15)';
    btn.style.color = '#34d399';
    btn.style.borderColor = 'rgba(52,211,153,0.4)';
  }
  // Mostrar/ocultar botão Peniel
  var pBtn = document.getElementById('sellin-filter-peniel');
  if(pBtn) pBtn.style.display = fy === 'FY26' ? '' : 'none';
  // Atualizar título
  var titleEl = document.getElementById('sellin-main-title');
  if(titleEl) titleEl.textContent = 'Meta BI × Real Acumulado — ' + fy + ' — Sell In por Cliente';
  var subEl = document.getElementById('sellin-main-sub');
  if(subEl) subEl.textContent = fy==='FY26'
    ? 'Histórico FY25 · Planejamento · Meta BI · Real Acumulado · FY26 Jul/25–Jun/26'
    : 'Histórico FY26 · Planejamento · Meta BI · Real Acumulado · FY27 Jul/26–Jun/27';
  // Resetar filtro de cliente para todos
  sellinFilter = 'todos';
  document.querySelectorAll('#sellin-filter-btns .tgl').forEach(function(b,i){
    b.classList.remove('active','blue'); b.style.background=''; b.style.color=''; b.style.borderColor='';
    if(i===0){ b.classList.add('active','blue'); b.style.background='rgba(59,130,246,0.12)'; b.style.color='#1D4ED8'; b.style.borderColor='rgba(59,130,246,0.4)'; }
  });
  // Re-renderizar tudo
  renderSellinKPIs();
  renderSellinBarGeral();
  renderSellinMensalChart();
  renderSellinResumoTable();
  renderSellinCards();
  renderSellinVerbas();
}

function renderSellinKPIs(){
  var t = SELLIN_TOTAL;
  var isF27 = SELLIN_FY_ATUAL==='FY27';
  var fyR = SELLIN_FY_ATUAL, fyH = isF27 ? 'FY26' : 'FY25';
  var meses_decorridos = isF27 ? SELLIN_MES_ATUAL+1 : 11; // FY26: Jul→Jun · FY27: Jul→mês atual
  var _ml = SELLIN_MONTHS[SELLIN_MES_ATUAL]; var perLbl = isF27 ? 'Jul–'+_ml.charAt(0)+_ml.slice(1).toLowerCase() : 'Jul–Jun';
  var meses_totais = 12;

  /* ── Mesmo período: somar hist_m e plan_m dos primeiros 11 meses de cada cliente ── */
  var histPerTotal = SELLIN_DATA.reduce(function(s,d){
    return s + (d.hist_m ? d.hist_m.slice(0, meses_decorridos).reduce(function(a,v){return a+(v||0);},0) : 0);
  }, 0);
  var planPerTotal = SELLIN_DATA.reduce(function(s,d){
    return s + (d.plan_m ? d.plan_m.slice(0, meses_decorridos).reduce(function(a,v){return a+(v||0);},0) : 0);
  }, 0);

  var histBase = isF27 ? histPerTotal : t.hist;
  var planBase = isF27 ? planPerTotal : t.plan;
  var ating    = t.meta > 0 ? t.real / t.meta * 100 : 0;
  var vs_hist  = histBase > 0 ? (t.real - histBase) / histBase * 100 : 0;
  var vs_plan  = planBase > 0 ? (t.real - planBase) / planBase * 100 : 0;
  var vs_meta  = t.meta > 0 ? (t.real - t.meta) / t.meta * 100 : 0;
  var diff_hist = t.real - histBase;
  var diff_plan = Math.round((t.real - planBase)*100)/100;
  var diff_meta = t.real - t.meta;

  document.getElementById('sellin-kpis-total').innerHTML = [
    {l:'Histórico '+fyH,    v:t.hist.toLocaleString('pt-BR'),           s:'Caixas total '+fyH,                      ac:'#3b82f6'},
    {l:'Planejamento '+fyR, v:t.plan.toLocaleString('pt-BR'),           s:'Caixas planejadas '+fyR+' (total)',          ac:'#D1D5DB'},
    {l:'Meta BI '+fyR,      v:t.meta.toLocaleString('pt-BR'),           s:'Meta '+perLbl+' (mesmo período)',            ac:'#fbbf24'},
    {l:'Real '+fyR,         v:t.real.toLocaleString('pt-BR'),           s:'Real '+perLbl+' ('+meses_decorridos+' meses)', ac:t.real>=t.meta?'#34d399':'#ef4444'},
    {l:'Meta BI vs Real',   v:(vs_meta>=0?'+':'')+vs_meta.toFixed(1)+'%', s:(diff_meta>=0?'+':'')+diff_meta.toLocaleString('pt-BR')+' cx · '+perLbl+' mesmo período', ac:vs_meta>=0?'#34d399':'#ef4444'},
    {l:'Hist '+fyH+' vs Real', v:(vs_hist>=0?'+':'')+vs_hist.toFixed(1)+'%', s:(diff_hist>=0?'+':'')+diff_hist.toLocaleString('pt-BR')+' cx · Real vs Hist '+fyH+(isF27?' '+perLbl:'')+' (base '+histBase.toLocaleString('pt-BR')+')', ac:vs_hist>=0?'#34d399':'#ef4444'},
    {l:'Plan '+fyR+' vs Real', v:(vs_plan>=0?'+':'')+vs_plan.toFixed(1)+'%', s:(diff_plan>=0?'+':'')+diff_plan.toLocaleString('pt-BR')+' cx · Real vs Plan '+fyR+(isF27?' '+perLbl:'')+' (base '+(Math.round(planBase*100)/100).toLocaleString('pt-BR')+')', ac:vs_plan>=0?'#34d399':'#ef4444'},
  ].map(function(k){
    return '<div style="background:#E4EAF2;border-radius:12px;padding:16px 18px;border-top:3px solid '+k.ac+';border-left:1px solid rgba(94,153,208,0.3);border-right:1px solid rgba(94,153,208,0.3);border-bottom:1px solid rgba(94,153,208,0.3);box-shadow:0 2px 10px rgba(10,40,80,0.13),0 1px 3px rgba(10,40,80,0.07);">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">'+k.l+'</div>'
      +'<div style="font-size:22px;font-weight:800;color:'+k.ac+';line-height:1;letter-spacing:-0.3px;">'+k.v+'</div>'
      +'<div style="font-size:10px;color:#64748B;margin-top:4px;">'+k.s+'</div>'
    +'</div>';
  }).join('');
}

function renderSellinBarGeral(){
  var items = sellinFilter==='todos' ? SELLIN_DATA : SELLIN_DATA.filter(function(d){return d.nome===sellinFilter;});
  var labels = items.map(function(d){return d.label;});
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};

  var datasets;
  if(sellinMode==='abs'){
    datasets=[
      {label:'Meta BI',     data:items.map(function(d){return d.meta;}), backgroundColor:'rgba(251,191,36,0.5)',  borderColor:'#fbbf24',borderWidth:1.5,borderRadius:8},
      {label:'Planejado',   data:items.map(function(d){return d.plan;}), backgroundColor:'rgba(6,182,212,0.65)',   borderColor:'#0891B2',borderWidth:1.5,borderRadius:8},
      {label:'Real',        data:items.map(function(d){return d.real;}), backgroundColor:items.map(function(d){return d.real>=d.meta?'rgba(52,211,153,0.7)':'rgba(6,182,212,0.7)';}), borderColor:items.map(function(d){return d.real>=d.meta?'#34d399':'#ef4444';}),borderWidth:1.5,borderRadius:8},
      {label:'Hist '+(SELLIN_FY_ATUAL==='FY27'?'FY26':'FY25'),   data:items.map(function(d){return d.hist;}), backgroundColor:'rgba(148,163,184,0.45)', borderColor:'#94A3B8',borderWidth:1.5,borderRadius:8},
    ];
  } else if(sellinMode==='plan'){
    datasets=[
      {label:'Real vs Planejado '+SELLIN_FY_ATUAL+' (%)', data:items.map(function(d){return d.plan>0?Math.round(d.real/d.plan*1000)/10:0;}),
       backgroundColor:items.map(function(d){return d.real>=d.plan?'rgba(103,232,249,0.7)':'rgba(6,182,212,0.7)';}),
       borderColor:items.map(function(d){return d.real>=d.plan?'#67e8f9':'#06b6d4';}),borderWidth:1.5,borderRadius:8},
    ];
  } else if(sellinMode==='pct'){
    datasets=[
      {label:'Real vs Meta BI (%)', data:items.map(function(d){return d.meta>0?Math.round(d.real/d.meta*1000)/10:0;}),
       backgroundColor:items.map(function(d){return d.real>=d.meta?'rgba(52,211,153,0.7)':'rgba(6,182,212,0.7)';}),
       borderColor:items.map(function(d){return d.real>=d.meta?'#34d399':'#ef4444';}),borderWidth:1.5,borderRadius:8},
    ];
  } else {
    datasets=[
      {label:'Real vs Hist '+(SELLIN_FY_ATUAL==='FY27'?'FY26 mesmo período':'FY25')+' (%)', data:items.map(function(d){return d.hist_per>0?Math.round((d.real-d.hist_per)/d.hist_per*1000)/10:0;}),
       backgroundColor:items.map(function(d){return d.real>=d.hist_per?'rgba(52,211,153,0.7)':'rgba(6,182,212,0.7)';}),
       borderColor:items.map(function(d){return d.real>=d.hist_per?'#34d399':'#ef4444';}),borderWidth:1.5,borderRadius:8},
    ];
  }

  if(sellinCharts.geral){ sellinCharts.geral.destroy(); sellinCharts.geral = null; }
  var _oldC = document.getElementById('sellin-bar-geral');
  if(!_oldC) return;
  /* Substituir canvas por um novo elemento limpo — remove atributos width/height
     que o Chart.js possa ter gravado em sessões anteriores (inclusive quando
     renderizado com painel oculto, gerando canvas 0×0 no outerHTML salvo). */
  var _parent = _oldC.parentNode;
  var c = document.createElement('canvas');
  c.id = 'sellin-bar-geral';
  _parent.replaceChild(c, _oldC);
  sellinCharts.geral = new Chart(c,{type:'bar',data:{labels:labels,datasets:datasets},options:{responsive:true,maintainAspectRatio:false,
    plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:10},boxWidth:10}},
      tooltip:{...CO,mode:'index',intersect:false,callbacks:{label:function(ctx){return ' '+ctx.dataset.label+': '+ctx.raw.toLocaleString('pt-BR')+(sellinMode!=='abs'?'%':'');}}}},
    scales:{x:{grid:{color:GC},ticks:{color:'#475569',font:{size:11}}},
      y:{grid:{color:GC},ticks:{color:TC,font:{size:9},callback:function(v){return v.toLocaleString('pt-BR')+(sellinMode!=='abs'?'%':'');}}}}}});
  /* Forçar redimensionamento após o primeiro paint — garante que o canvas
     mede o container corretamente mesmo quando a aba acabou de ficar visível */
  requestAnimationFrame(function(){ if(sellinCharts.geral) sellinCharts.geral.resize(); });
}

function renderSellinCards(){
  var _sb=document.getElementById('sellin-bar-sub');
  var _sfC = (typeof SELLIN_FY_ATUAL!=='undefined' ? SELLIN_FY_ATUAL : 'FY27'), _sfP = 'FY'+(parseInt(_sfC.slice(2),10)-1), _sfN = SELLIN_MES_ATUAL+1, _sfM = SELLIN_MONTHS[_sfN-1].charAt(0)+SELLIN_MONTHS[_sfN-1].slice(1).toLowerCase(); if(_sb) _sb.textContent = 'Caixas · '+_sfC+' acumulado Jul–'+_sfM;
  var items = sellinFilter==='todos' ? SELLIN_DATA : SELLIN_DATA.filter(function(d){return d.nome===sellinFilter;});
  var wrap = document.getElementById('sellin-cards-wrap');
  if(!wrap) return;

  wrap.innerHTML = items.map(function(d){
    var ating = d.meta>0 ? Math.round(d.real/d.meta*100) : 0;
    var cor = d.cor;
    var vs_hist = Math.round((d.real-d.hist_per)/Math.max(d.hist_per,1)*100);
    /* vs Planejado — mesmo período 10 meses */
    var planPer11 = d.plan_m ? d.plan_m.slice(0,_sfN).reduce(function(s,v){return s+(v||0);},0) : d.plan;
    var vs_plan = planPer11>0 ? Math.round((d.real-planPer11)/planPer11*100) : 0;
    var tendencia = vs_plan >= 0 ? '✅ Acima do planejado' : '⚠️ Abaixo do planejado';
    var tend_cor  = vs_plan >= 0 ? '#34d399' : '#ef4444';
    var pct_bar   = Math.min(100, ating);

    // Mini spark line data (real vs meta)
    var canvasId = 'sellin-spark-'+d.nome.replace(/[^a-z]/gi,'');

    return '<div class="card full" style="margin-bottom:12px;">'
      // Header
      +'<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px;">'
        +'<div style="display:flex;align-items:center;gap:10px;">'
          +'<div style="width:38px;height:38px;background:'+cor+'22;border:0.5px solid '+cor+'44;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:20px;">'+(['São João','Nissei','Clamed','Panvel'].indexOf(d.nome)>=0?'💊':'🚚')+'</div>'
          +'<div>'
            +'<div style="font-size:15px;font-weight:700;color:'+cor+';letter-spacing:-0.3px;">'+d.label+'</div>'
            +'<div style="font-size:10px;color:#94A3B8;">'+d.canal+' · '+_sfC+' acumulado · Jul–'+_sfM+'</div>'
          +'</div>'
        +'</div>'
        +'<div style="display:flex;gap:6px;align-items:center;">'
          +'<span style="font-size:11px;font-weight:700;color:'+tend_cor+';">'+tendencia+'</span>'
          +'<span style="font-size:10px;background:'+(vs_plan>=0?'rgba(52,211,153,0.12)':'rgba(6,182,212,0.12)')+';color:'+(vs_plan>=0?'#34d399':'#ef4444')+';border:0.5px solid '+(vs_plan>=0?'rgba(52,211,153,0.3)':'rgba(6,182,212,0.3)')+';border-radius:5px;padding:3px 10px;font-weight:700;">vs Plan: '+(vs_plan>=0?'+':'')+vs_plan+'%</span>'
        +'</div>'
      +'</div>'
      // KPIs
      +'<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin-bottom:14px;">'
        +[
          {l:'Hist '+_sfP,v:d.hist.toLocaleString('pt-BR'),s:'caixas',ac:'#D1D5DB'},
          {l:'Plan '+_sfC,  v:d.plan.toLocaleString('pt-BR'),s:'caixas',ac:'#67e8f9'},
          {l:'Meta BI',   v:d.meta.toLocaleString('pt-BR'),s:'caixas acum',ac:'#fbbf24'},
          {l:'Real',      v:d.real.toLocaleString('pt-BR'),s:'caixas acum',ac:d.real>=d.meta?'#34d399':'#ef4444'},
          {l:'vs Plan %', v:(vs_plan>=0?'+':'')+vs_plan+'%',s:'Real vs Planejado',ac:vs_plan>=0?'#34d399':'#ef4444'},
          (function(){
            var realMonths = _sfN;
            var planAcum   = d.plan_m ? d.plan_m.slice(0,realMonths).reduce(function(s,v){return s+v;},0) : d.plan;
            var faltPlan   = d.real - planAcum;
            return {l:'Cx Falt Plan', v:(faltPlan>=0?'+':'')+faltPlan.toLocaleString('pt-BR'), s:faltPlan<0?'cx abaixo do planejado':'cx acima do planejado', ac:faltPlan>=0?'#34d399':'#ef4444'};
          }()),
          {l:'vs Hist',   v:(vs_hist>=0?'+':'')+vs_hist+'%',s:'Real vs Hist '+_sfP,ac:vs_hist>=0?'#34d399':'#ef4444'},
        ].map(function(k){return '<div style="background:#EAEEF4;border-radius:8px;padding:10px 12px;border-top:2px solid '+k.ac+';border-left:1px solid rgba(94,153,208,0.35);border-right:1px solid rgba(94,153,208,0.35);border-bottom:1px solid rgba(94,153,208,0.35);box-shadow:0 2px 6px rgba(10,40,80,0.08);">'
          +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:4px;">'+k.l+'</div>'
          +'<div style="font-size:17px;font-weight:800;color:'+k.ac+';line-height:1;">'+k.v+'</div>'
          +'<div style="font-size:9px;color:#64748B;margin-top:2px;">'+k.s+'</div>'
        +'</div>';}).join('')
      +'</div>'
      // Progress bar atingimento
      +'<div style="margin-bottom:14px;">'
        +'<div style="display:flex;justify-content:space-between;font-size:10px;color:#94A3B8;margin-bottom:5px;"><span>Atingimento Meta BI</span><span style="color:'+cor+';font-weight:700;">'+ating+'%</span></div>'
        +'<div style="background:rgba(245,225,164,0.07);border-radius:4px;height:8px;overflow:hidden;">'
          +'<div style="height:100%;border-radius:4px;background:'+cor+';width:'+Math.min(pct_bar,100)+'%;transition:width 1s ease;'+(ating>100?'background:linear-gradient(90deg,'+cor+',#34d399);':'')+'"></div>'
        +'</div>'
        +'<div style="display:flex;justify-content:space-between;font-size:9px;color:#3d6b63;margin-top:3px;"><span>0</span><span>Meta: '+d.meta.toLocaleString('pt-BR')+'</span></div>'
      +'</div>'
      // Análise 3 comparações + canvas — mesmo período fixo Jul→Abr (10 meses)
      +(function(){
        var rMths = _sfN; /* Jul → mês de referência do FY ativo */
        var histPer = d.hist_m ? d.hist_m.slice(0,rMths).reduce(function(s,v){return s+(v||0);},0) : 0;
        var metaPer = d.meta_m ? d.meta_m.slice(0,rMths).reduce(function(s,v){return s+(v||0);},0) : 0;
        var planPer = d.plan_m ? d.plan_m.slice(0,rMths).reduce(function(s,v){return s+(v||0);},0) : 0;
        var vsHistAbs = d.real - histPer;
        var vsMetaAbs = d.real - metaPer;
        var vsPlanAbs = d.real - planPer;
        var vsHistPct = histPer>0?Math.round(vsHistAbs/histPer*100):0;
        var vsMetaPct = metaPer>0?Math.round(vsMetaAbs/metaPer*100):0;
        var vsPlanPct = planPer>0?Math.round(vsPlanAbs/planPer*100):0;
        function row(label, abs, pct, base){
          var col = abs>=0?'#34d399':'#ef4444';
          var icon = abs>=0?'✅':'⚠';
          return '<div style="display:flex;align-items:center;justify-content:space-between;padding:5px 0;border-bottom:0.5px solid rgba(94,153,208,0.2);">'
            +'<span style="font-size:11px;color:#334155;">'+icon+' <strong>'+label+'</strong> <span style="color:#64748B;font-size:10px;">('+rMths+' meses · base '+base.toLocaleString('pt-BR')+' cx)</span></span>'
            +'<span style="font-size:12px;font-weight:700;color:'+col+';">'+(abs>=0?'+':'')+abs.toLocaleString('pt-BR')+' cx <span style="font-size:10px;opacity:0.8;">('+( pct>=0?'+':'')+pct+'%)</span></span>'
          +'</div>';
        }
        return '<div style="display:grid;grid-template-columns:1fr 300px;gap:14px;align-items:start;">'
          +'<div style="background:#EAEEF4;border-radius:8px;padding:10px 14px;border:1px solid rgba(94,153,208,0.35);box-shadow:0 2px 6px rgba(10,40,80,0.08);">'
            +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;margin-bottom:8px;">ANÁLISE MESMO PERÍODO · '+_sfC+' · Jul–'+_sfM+'</div>'
            +row('Planejado vs Real', vsPlanAbs, vsPlanPct, planPer)
            +row('Meta BI vs Real',   vsMetaAbs, vsMetaPct, metaPer)
            +row('Histórico vs Real', vsHistAbs, vsHistPct, histPer)
          +'</div>'
          +'<div style="position:relative;height:90px;"><canvas id="'+canvasId+'"></canvas></div>'
        +'</div>';
      }())
    +'</div>';
  }).join('');

  // Render mini sparklines
  items.forEach(function(d){
    var canvasId = 'sellin-spark-'+d.nome.replace(/[^a-z]/gi,'');
    var c = document.getElementById(canvasId);
    if(!c) return;
    var months = SELLIN_MONTHS.filter(function(_,i){return d.real_m[i]>0||d.meta_m[i]>0;});
    var realData = d.real_m.filter(function(_,i){return d.real_m[i]>0||d.meta_m[i]>0;}).slice(0,months.length);
    var metaData = d.meta_m.filter(function(_,i){return d.real_m[i]>0||d.meta_m[i]>0;}).slice(0,months.length);
    if(sellinCharts[canvasId]) sellinCharts[canvasId].destroy();
    sellinCharts[canvasId] = new Chart(c,{type:'line',
      data:{labels:SELLIN_MONTHS.slice(0,9),datasets:[
        {label:'Meta',data:d.meta_m.slice(0,9),borderColor:'#fbbf2488',backgroundColor:'transparent',pointRadius:2,borderWidth:1.5,tension:0.3,borderDash:[3,2]},
        {label:'Real',data:d.real_m.slice(0,9),borderColor:d.cor,
          backgroundColor:function(ctx){var ca=ctx.chart.chartArea;return makeAreaGradient(ctx.chart.ctx,ca,d.cor||'#06b6d4');},
          pointRadius:0,borderWidth:2,tension:0.4,fill:true},
      ]},
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{enabled:false}},
        scales:{x:{display:false},y:{display:false}}}
    });
  });
}

