      +'<td style="padding:6px 8px;text-align:right;color:#60a5fa;font-family:var(--mono);font-size:11px">'+(r.abr_p>0?_fK(r.abr_p):'<span style="color:#94A3B8">\u2014</span>')+'</td>'
      +'<td style="padding:6px 8px;text-align:right;color:#a78bfa;font-family:var(--mono);font-size:11px">'+(r.mai_p>0?_fK(r.mai_p):'<span style="color:#94A3B8">\u2014</span>')+'</td>'
