        +'<div style="font-size:8px;color:#94A3B8;margin-bottom:3px;text-transform:uppercase;letter-spacing:.06em">D\u00edvida Mar/26</div>'
        +'<div style="font-size:17px;font-weight:700;color:#ef4444;font-family:var(--mono)">R$571K</div>'
        +'<div style="font-size:9px;color:#94A3B8;margin-top:1px">R$571.226</div>'
