        +'<div style="font-size:17px;font-weight:700;color:#34d399;font-family:var(--mono)">R$'+_fBR(Math.round(_qR))+'</div>'
        +'<div style="font-size:9px;color:#94A3B8;margin-top:1px">'+_pR+'% do Q4 total</div>'
      +'</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px">'
      +'<div style="background:rgba(255,255,255,0.03);border-radius:8px;padding:10px">'
        +'<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:5px">'
