function renderEDShare(clientKey, panelPrefix) {
  var d = ED_DATA[clientKey];
  if(!d) return;
  var el = document.getElementById('ed-'+panelPrefix+'-wrap');
  if(!el) return; /* card Estudo ED removido dos painéis de Sell Out (20/10/2026) */
  var varCol = d.var >= 0 ? '#34d399' : '#ef4444';
  var varStr = (d.var >= 0 ? '▲ +' : '▼ ') + Math.abs(d.var).toFixed(2) + 'pp';
  var ufs = Object.keys(d.by_uf);

  // KPIs row
  var kpiHtml = '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px;">'
    + [
      {l:'Share FY25 (Med.)',  v:d.shr_ant+'%',  ac:'#D1D5DB'},
      {l:'Share FY26 (Med.)',  v:d.shr_atu+'%',  ac:d.shr_atu>=d.shr_ant?'#34d399':'#ef4444'},
      {l:'Variação Share',     v:varStr,           ac:varCol},
      {l:'PDVs Positivados',   v:d.pos.toLocaleString('pt-BR'), ac:'#67e8f9'},
      {l:'Valor FY26',         v:'R$ '+d.val_atu+'K', ac:'#fbbf24'},
    ].map(function(k){
      return '<div style="background:#E4EAF2;border-radius:9px;padding:12px;border-top:2px solid '+k.ac+';border-left:1px solid rgba(94,153,208,0.35);border-right:1px solid rgba(94,153,208,0.35);border-bottom:1px solid rgba(94,153,208,0.35);box-shadow:0 2px 8px rgba(10,40,80,0.10);">'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#475569;text-transform:uppercase;margin-bottom:5px;">'+k.l+'</div>'
        +'<div style="font-size:18px;font-weight:800;color:'+k.ac+';line-height:1;">'+k.v+'</div>'
      +'</div>';
    }).join('')
  +'</div>';

  // UF table
  var tableHtml = '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:11px;">'
    +'<thead><tr style="color:#94A3B8;border-bottom:0.5px solid rgba(255,255,255,0.13);">'
    +'<th style="text-align:left;padding:6px 8px;">UF</th>'
    +'<th style="text-align:right;padding:6px 8px;">PDVs</th>'
    +'<th style="text-align:right;padding:6px 8px;">Share FY25</th>'
    +'<th style="text-align:right;padding:6px 8px;">Share FY26</th>'
    +'<th style="text-align:right;padding:6px 8px;">Var pp</th>'
    +'<th style="text-align:right;padding:6px 8px;">Val FY26</th>'
    +'<th style="text-align:right;padding:6px 8px;">Opp</th>'
    +'</tr></thead><tbody>';

  ufs.sort(function(a,b){return (d.by_uf[b].val||0)-(d.by_uf[a].val||0);});
  ufs.forEach(function(uf){
    var u = d.by_uf[uf];
    var vd = u.shr_atu - u.shr_ant;
    var vc = vd >= 0 ? '#34d399' : '#ef4444';
    tableHtml += '<tr style="border-bottom:0.5px solid rgba(255,255,255,0.04);hover:background:rgba(255,255,255,0.02);">'
      +'<td class="u-td-hdr">'+uf+'</td>'
      +'<td style="text-align:right;padding:7px 8px;color:#D1D5DB;">'+u.n+'</td>'
      +'<td style="text-align:right;padding:7px 8px;color:#D1D5DB;">'+u.shr_ant+'%</td>'
      +'<td style="text-align:right;padding:7px 8px;font-weight:700;color:'+(u.shr_atu>=u.shr_ant?'#34d399':'#ef4444')+';">'+u.shr_atu+'%</td>'
      +'<td style="text-align:right;padding:7px 8px;color:'+vc+';">'+(vd>=0?'+':'')+vd.toFixed(2)+'pp</td>'
      +'<td style="text-align:right;padding:7px 8px;color:#fbbf24;">R$'+u.val+'K</td>'
      +'<td style="text-align:right;padding:7px 8px;color:#2dd4bf;">R$'+u.opp+'K</td>'
    +'</tr>';
  });
  tableHtml += '</tbody></table></div>';

  el.innerHTML = '<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:#2dd4bf;margin-bottom:12px;">📊 SHARE DE MERCADO · ESTUDO ED · Jul/24–Dez/25</div>'
    + kpiHtml
    + '<div style="font-size:10px;font-weight:700;color:#94A3B8;margin-bottom:8px;letter-spacing:0.08em;">DETALHE POR UF</div>'
    + tableHtml
    + '<div style="margin-top:10px;font-size:11px;color:#94A3B8;">Período: '+d.periodo+' · Fonte: Estudo ED SCJ × IQVIA · Personal Repellent · $ Share</div>';
}

function renderEDCNPJCardFilter(btn){
  var elId = btn.getAttribute('data-elid');
  var uf   = btn.getAttribute('data-uf');
  var el = document.getElementById(elId);
  if(!el || !el._wsData) return;
  el._activeUF = uf;
  // Update button styles
  btn.closest('div').querySelectorAll('button').forEach(function(b){
    b.style.background = 'transparent';
    b.style.color = '#D1D5DB';
    b.style.borderColor = 'rgba(255,255,255,0.12)';
  });
  btn.style.background = 'rgba(251,191,36,0.2)';
  btn.style.color = '#fbbf24';
  btn.style.borderColor = 'rgba(251,191,36,0.5)';

  var filtered = uf === 'TODOS' ? el._wsData : el._wsData.filter(function(p){ return p.uf === uf; });
  var total_opp = filtered.reduce(function(s,p){ return s+p.opp; },0);

  // Update count/opp display
  var info = el.querySelector('div > div > div:last-child');
  if(info) info.innerHTML = filtered.length+' PDVs &middot; Opp: <strong style="color:#fbbf24;">R$ '+Math.round(total_opp).toLocaleString('pt-BR')+'</strong>'+(uf!=='TODOS'?' &middot; UF: <strong style="color:#fbbf24;">'+uf+'</strong>':'');

  // Re-render table rows only
  var tbody = el.querySelector('tbody');
  if(!tbody) return;
  var ufColors = {PR:'#3b82f6',SC:'#34d399',RS:'#f97316',SP:'#2dd4bf',GO:'#fbbf24',MS:'#06b6d4'};
  tbody.innerHTML = filtered.map(function(p,i){
    var shrCol = p.shr_atu > 0 ? '#34d399' : '#ef4444';
    var ufColor = ufColors[p.uf] || '#D1D5DB';
    return '<tr class="u-row-sep">'+'<td style="padding:7px 8px;color:#94A3B8;font-size:10px;">'+(i+1)+'</td>'
      +'<td style="padding:7px 8px;font-family:monospace;font-size:10px;color:#67e8f9;">'+p.cnpj+'</td>'
      +'<td style="padding:7px 8px;font-size:11px;color:#e2e8f0;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+p.bandeira+'">'+p.bandeira+'</td>'
      +'<td style="padding:7px 8px;font-size:10px;color:#D1D5DB;white-space:nowrap;">'+p.cidade+'</td>'
      +'<td style="padding:7px 8px;text-align:center;"><span style="padding:2px 8px;border-radius:4px;font-size:10px;font-weight:700;background:'+ufColor+'18;color:'+ufColor+';border:0.5px solid '+ufColor+'44;">'+p.uf+'</span></td>'
      +'<td style="padding:7px 8px;text-align:right;font-size:10px;color:#D1D5DB;">'+p.shr_ant+'%</td>'
      +'<td style="padding:7px 8px;text-align:right;font-size:10px;font-weight:600;color:'+shrCol+';">'+p.shr_atu+'%</td>'
      +'<td style="padding:7px 8px;text-align:right;font-size:11px;font-weight:700;color:#fbbf24;">R$ '+p.opp.toLocaleString('pt-BR')+'</td>'
      +'</tr>';
  }).join('');
}

/* ═══════════ SELL IN UPLOAD ═══════════ */
function initSellinUploadCards(){
  var wrap = document.getElementById('sellin-client-cards-upload');
  if(!wrap) return;
  var clients = SELLIN_DATA.map(function(d){ return {nome:d.nome, label:d.label, cor:d.cor}; });
  wrap.innerHTML = clients.map(function(c){
    var uid = 'upload-'+c.nome.replace(/[^a-z0-9]/gi,'');
    return '<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:rgba(255,255,255,0.03);border-radius:10px;border:0.5px solid '+c.cor+'22;">'
      +'<div style="width:32px;height:32px;background:'+c.cor+'18;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px;">📦</div>'
      +'<div style="flex:1;">'
        +'<div style="font-size:12px;font-weight:700;color:'+c.cor+';">'+c.label+'</div>'
        +'<div id="'+uid+'-status" style="font-size:10px;color:#475569;">Aguardando arquivo</div>'
      +'</div>'
      +'<label style="cursor:pointer;padding:6px 14px;border-radius:6px;border:0.5px solid '+c.cor+'44;background:'+c.cor+'12;color:'+c.cor+';font-size:11px;font-weight:600;" data-nome="'+c.nome+'" data-uid="'+uid+'">'
        +'Upload'
        +'<input type="file" accept=".xlsx,.xls,.csv" style="display:none;" data-nome="'+c.nome+'" data-uid="'+uid+'" onchange="handleSellinUpload(event)">'
      +'</label>'
    +'</div>';
  }).join('');
}

function handleSellinUpload(event){
  var input = event.target;
  var clientNome = input.getAttribute('data-nome') || '';
  var uid = input.getAttribute('data-uid') || '';
  var file = event.target.files[0];
  if(!file) return;
  var statusEl = document.getElementById(uid+'-status');
  if(statusEl) statusEl.innerHTML = '<span style="color:#34d399;">✅ '+file.name+' carregado · '+new Date().toLocaleTimeString('pt-BR')+'</span>';
  
  // Update last update timestamp
  var lu = document.getElementById('sellin-last-update');
  if(lu) lu.textContent = 'Última atualização: '+new Date().toLocaleDateString('pt-BR')+' '+new Date().toLocaleTimeString('pt-BR');
  
  // Read file and parse (basic implementation)
  var reader = new FileReader();
  reader.onload = function(e){
    // Store file reference for future processing
    if(!window.sellinFiles) window.sellinFiles = {};
    window.sellinFiles[clientNome] = {name: file.name, size: file.size, loaded: new Date()};
    // Visual feedback
    if(statusEl) statusEl.innerHTML = '<span style="color:#34d399;">✅ '+file.name+' · '+Math.round(file.size/1024)+'KB · Dados prontos para análise</span>';
  };
  reader.readAsArrayBuffer(file);
}

// Initialize upload cards when modal opens
document.addEventListener('DOMContentLoaded', function(){
  setTimeout(initSellinUploadCards, 1000);
});

/* ═══════════ OL DIAGNÓSTICO ═══════════ */
function renderOLDiag(area){
  var el = document.getElementById('ol-diag-wrap');
  if(!el) return;
  var d = OL_DATA[area];
  if(!d) return;

  var posVar = d.posit26 - d.posit25;
  var catVar = ((d.catAtual - d.catAnt) / d.catAnt * 100);
  var propVar = ((d.propAtual - d.propAnt) / d.propAnt * 100);
  var posVarPct = (posVar / d.posit25 * 100);

  // Generate diagnostic insights
  var pontos_fortes = [], pontos_atencao = [], oportunidades = [];

  // Share analysis
  if(d.shareVar > 0){
    pontos_fortes.push('Share crescendo +' + d.shareVar.toFixed(1) + 'pp — de ' + d.shareAnt + '% para ' + d.shareAtual + '%');
  } else {
    pontos_atencao.push('Share caindo ' + d.shareVar.toFixed(1) + 'pp — de ' + d.shareAnt + '% para ' + d.shareAtual + '%');
  }

  // Positivação
  if(posVar > 0){
    pontos_fortes.push('Positivação cresceu +' + posVar + ' PDVs (' + posVarPct.toFixed(1) + '%) · ' + d.posit26 + ' PDVs ativos');
  } else if(posVar < 0){
    pontos_atencao.push('Positivação caiu ' + Math.abs(posVar) + ' PDVs (' + posVarPct.toFixed(1) + '%) · ' + d.posit26 + ' PDVs ativos');
  }

  // Valor próprio
  if(propVar < -10){
    pontos_atencao.push('Valor Próprio caiu ' + propVar.toFixed(1) + '% — R$ ' + Math.round(d.propAtual/1e3) + 'K vs R$ ' + Math.round(d.propAnt/1e3) + 'K no período anterior');
  } else if(propVar > 5){
    pontos_fortes.push('Valor Próprio cresceu +' + propVar.toFixed(1) + '% — R$ ' + Math.round(d.propAtual/1e3) + 'K');
  }

  // Categoria vs próprio
  var penetr = (d.propAtual / d.catAtual * 100);
  if(penetr < 30) oportunidades.push('Penetração de ' + penetr.toFixed(0) + '% na categoria — grande espaço para crescimento');
  else pontos_fortes.push('Penetração de ' + penetr.toFixed(0) + '% na categoria');

  // Top opportunities from clients
  var topDrop = d.clientes.filter(function(c){ return c.shareVar < -3; });
  var topGain = d.clientes.filter(function(c){ return c.shareVar > 3; });
  if(topDrop.length) pontos_atencao.push('Queda de share em: ' + topDrop.slice(0,3).map(function(c){return c.nome+' ('+c.shareVar.toFixed(1)+'pp)';}).join(', '));
  if(topGain.length) pontos_fortes.push('Ganho de share em: ' + topGain.slice(0,3).map(function(c){return c.nome+' (+'+c.shareVar.toFixed(1)+'pp)';}).join(', '));

  oportunidades.push('PDVs totais: ' + d.pdvsTotal + ' · ' + (d.pdvsTotal - d.posit26) + ' ainda sem positivação FY26');

  function li(items, col, icon){
    return items.map(function(t){ return '<li style="color:#D1D5DB;font-size:11px;line-height:1.6;margin-bottom:4px;"><span style="color:'+col+';">'+icon+'</span> '+t+'</li>'; }).join('');
  }

  el.innerHTML = '<div class="card full">'
    +'<div class="card-header">'
      +'<div>'
        +'<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:#67e8f9;margin-bottom:4px;">🔍 DIAGNÓSTICO · ' + d.label + '</div>'
        +'<div class="card-title">Análise de Performance & Oportunidades</div>'
        +'<div class="card-sub">Share · Positivação · Valor Próprio · Categoria · Jul/24–Dez/25</div>'
      +'</div>'
      +'<div style="display:flex;gap:8px;align-items:center;">'
        +'<div class="toggle-group" style="display:flex;gap:4px;">'
          +'<button class="tgl'+(area==='prsc'?' active blue':'')+'" onclick="setOLView(\'prsc\',this)" style="font-size:10px;padding:4px 10px;">OL PR/SC</button>'
          +'<button class="tgl'+(area==='rs'?' active blue':'')+'" onclick="setOLView(\'rs\',this)" style="font-size:10px;padding:4px 10px;">OL RS</button>'
        +'</div>'
        +'<span style="padding:4px 12px;border-radius:6px;font-size:10px;font-weight:700;background:rgba(52,211,153,0.1);color:#34d399;border:0.5px solid rgba(52,211,153,0.3);">Share: '+d.shareAtual+'%</span>'
        +'<span style="padding:4px 12px;border-radius:6px;font-size:10px;font-weight:700;background:'+(d.shareVar>=0?'rgba(52,211,153,0.1)':'rgba(6,182,212,0.1)')+';color:'+(d.shareVar>=0?'#34d399':'#ef4444')+';border:0.5px solid '+(d.shareVar>=0?'rgba(52,211,153,0.3)':'rgba(6,182,212,0.3)')+';">'+(d.shareVar>=0?'▲ +':'▼ ')+Math.abs(d.shareVar).toFixed(1)+'pp</span>'
      +'</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;">'
      +'<div><div style="font-size:10px;font-weight:700;color:#34d399;margin-bottom:8px;display:flex;align-items:center;gap:6px;"><span style="width:6px;height:6px;background:#34d399;border-radius:50%;display:inline-block;"></span>PONTOS FORTES</div><ul style="list-style:none;padding:0;margin:0;">'+li(pontos_fortes,'#34d399','✓')+'</ul></div>'
      +'<div><div style="font-size:10px;font-weight:700;color:#06b6d4;margin-bottom:8px;display:flex;align-items:center;gap:6px;"><span style="width:6px;height:6px;background:#06b6d4;border-radius:50%;display:inline-block;"></span>PONTOS DE ATENÇÃO</div><ul style="list-style:none;padding:0;margin:0;">'+li(pontos_atencao,'#06b6d4','⚠')+'</ul></div>'
      +'<div><div style="font-size:10px;font-weight:700;color:#fbbf24;margin-bottom:8px;display:flex;align-items:center;gap:6px;"><span style="width:6px;height:6px;background:#fbbf24;border-radius:50%;display:inline-block;"></span>OPORTUNIDADES & AÇÕES</div><ul style="list-style:none;padding:0;margin:0;">'+li(oportunidades,'#fbbf24','→')+'</ul></div>'
    +'</div>'
  +'</div>';
}

/* ═══════════ TENDÊNCIA ESTOQUE vs VENDAS ═══════════ */
/* ═══════════ ESTOQUE TENDÊNCIA CONTROL ═══════════ */
var ESTOQUE_DATA_MAP = {
  sjc:  function(){ return typeof SJC_ESTOQUE !== 'undefined' ? SJC_ESTOQUE : []; },
  gam:  function(){ return typeof GAM_ESTOQUE  !== 'undefined' ? GAM_ESTOQUE  : []; },
  gch:  function(){ return typeof GCH_ESTOQUE !== 'undefined' ? GCH_ESTOQUE : []; },
  pv:   function(){ return typeof PV_ESTOQUE   !== 'undefined' ? PV_ESTOQUE   : []; },
  ns:   function(){
    /* Respeita aba ativa: Andre (hb) → NS_ESTOQUE_HB | Edmar (ed) → NS_ESTOQUE_ED */
    var tab = (typeof nsEstoqueTab !== 'undefined') ? nsEstoqueTab : 'hb';
    if(tab === 'ed') return typeof NS_ESTOQUE_ED !== 'undefined' ? NS_ESTOQUE_ED : [];
    return typeof NS_ESTOQUE_HB !== 'undefined' ? NS_ESTOQUE_HB : [];
  },
  sj:   function(){ return typeof SJ_ESTOQUE   !== 'undefined' ? SJ_ESTOQUE   : []; },
  cl:   function(){ return typeof CL_ESTOQUE   !== 'undefined' ? CL_ESTOQUE   : []; },
  rio:  function(){ return typeof RIO_ESTOQUE  !== 'undefined' ? RIO_ESTOQUE  : []; },
};

function setEstoqueTend(panel, btn){
  ['barras','linha','tend'].forEach(function(v){
    var el=document.getElementById(panel+'-estoque-'+v);
    if(el) el.style.display='none';
  });
  if(btn && btn.closest){
    btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
    btn.classList.add('active','blue');
  }
  var tendEl=document.getElementById(panel+'-estoque-tend');
  if(tendEl) tendEl.style.display='block';

  /* Nissei: atualiza header e nsEstoqueView para Ruptura */
  if(panel==='ns'){
    nsEstoqueView='tend';
    var hdr=document.getElementById('ns-tend-header');
    if(hdr){
      var comp=(typeof nsEstoqueTab!=='undefined'&&nsEstoqueTab==='ed')
        ?'Edmar — RAID &amp; Elétricos'
        :'Andre — OFF! &amp; EXPOSIS';
      hdr.innerHTML='📈 <strong style="color:#fbbf24;">Projeção de Ruptura</strong> — Comprador <strong style="color:#60a5fa;">'+comp+'</strong> · Sazonalidade Verão';
    }
  }

  var data=ESTOQUE_DATA_MAP[panel]?ESTOQUE_DATA_MAP[panel]():[];
  if(!data.length){
    if(tendEl) tendEl.innerHTML='<div style="color:#94A3B8;padding:20px;text-align:center;">Sem dados de estoque</div>';
    return;
  }

  // Build marcaMap
  function inferM(item){
    if(item.marca) return item.marca;
    var s=(item.sku||'').toUpperCase();
    if(s.indexOf('EXPOSIS')>-1)    return 'EXPOSIS';
    if(s.indexOf('ICARIDINA')>-1)  return 'EXPOSIS';   /* ex: Glicerina Icaridina = EXPOSIS */
    if(s.indexOf('XO ')>-1)        return 'XO INSETO';
    if(s.indexOf('SUPER REPELEX')>-1) return 'SUPER REPELEX';
    if(s.indexOf('OFF')>-1)        return 'OFF!';
    if(s.indexOf('RAID')>-1)       return 'RAID';
    if(s.indexOf('GLADE')>-1)      return 'GLADE';
    if(s.indexOf('LYSOFORM')>-1)   return 'LYSOFORM';
    if(s.indexOf('PATO')>-1)       return 'PATO';
    if(s.indexOf('POVIDINE')>-1){
      if(s.indexOf('SPRAY')>-1) return 'EXPOSIS'; /* POVIDINE TOPICO SPRAY → EXPOSIS */
      return 'OFF!';                               /* POVIDINE TOPICO → OFF! */
    }
    return null;   /* fallback: item sem marca SCJ identificável — ignorar */
  }
  var mm={};
  data.forEach(function(item){
    var m=inferM(item);
    if(!m) return;   /* pula itens sem marca SCJ reconhecida */
    if(!mm[m]) mm[m]={est:0,dem:0,abr25:0};
    mm[m].est+=(item.estoque||0);
    var d=0;
    var _m3=((item.vendaMar||0)+(item.vendaAbr||0)+(item.vendaJun||0))/3; if(_m3>0) d=_m3; /* média Jul–Set/26 */ else if(item.venda_abr>0) d=item.venda_abr;  // Abr/25 — referência sazonalidade real
    else if(item.giro>0)     d=item.giro;
    else if(item.cob>0&&item.cob<999) d=(item.estoque||0)/item.cob*30;
    else if(item.dem>0)      d=item.dem;
    if(!d&&item.venda>0)     d=item.venda;
    if(!d&&item.vendaMar>0)  d=item.vendaMar;
    if(!d&&item.pend>0)      d=item.pend*0.5;
    mm[m].dem+=d;
    mm[m].abr25+=(item.venda_abr||item.vendaAbr||item.venda||item.giro||item.dem||0);
  });
  var marcas=Object.keys(mm).filter(function(m){return mm[m].dem>0;});
  if(!marcas.length){
    var totEst=data.reduce(function(s,i){return s+(i.estoque||0);},0);
    var totDem=data.reduce(function(s,i){return s+(i.giro||i.venda_abr||i.venda||0);},0);
    marcas=['Total']; mm={'Total':{est:totEst,dem:totDem}};
  }

  var saz=(function(){ try{ var u25=SJ_UNID['2025'], u26=SJ_UNID['2026'], b=((u25[6]||0)+(u25[7]||0)+(u25[8]||0))/3||1; return [u25[9],u25[10],u25[11],u26[0],u26[1],u26[2]].map(function(v){ return Math.max(0.2,(v||b)/b); }); }catch(e){ return [1.3,1.8,2.4,2.6,2.4,2.0]; } })(); /* sazonalidade real: Out/25–Mar/26 ÷ média Jul–Set/25 (unidades SJ) */
  var meses=['Set/26','Out/26','Nov/26','Dez/26','Jan/27','Fev/27','Mar/27'];
  var CORES=['#fbbf24','#3b82f6','#34d399','#06b6d4','#2dd4bf','#f97316'];

  // Build series
  var series=marcas.map(function(marca,idx){
    var est=mm[marca].est, dem=mm[marca].dem;
    var pts=[est];
    for(var i=0;i<6;i++){ est=Math.max(0,est-dem*saz[i]); pts.push(Math.round(est)); }
    return {marca:marca,pts:pts,dem:Math.round(dem),cor:CORES[idx%CORES.length]};
  });

  // SVG dimensions
  var W=1400, H=280, PL=60, PR=20, PT=30, PB=40;
  var CW=W-PL-PR, CH=H-PT-PB;
  var maxV=0;
  series.forEach(function(s){s.pts.forEach(function(v){if(v>maxV)maxV=v;});});
  if(!maxV) maxV=1;
  var xStep=CW/(meses.length-1);

  function px(i){ return PL+i*xStep; }
  function py(v){ return PT+CH-(v/maxV*CH); }
  function fmt(v){ return v>=1000?Math.round(v/1000)+'K':v; }

  var svgParts=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" style="width:100%;height:300px;display:block;">'];

  // Grid lines
  for(var g=0;g<=4;g++){
    var gy=PT+CH*(1-g/4);
    var gv=Math.round(maxV*g/4);
    svgParts.push('<line x1="'+PL+'" y1="'+gy+'" x2="'+(W-PR)+'" y2="'+gy+'" stroke="rgba(255,255,255,0.10)" stroke-width="1"/>');
    svgParts.push('<text x="'+(PL-6)+'" y="'+(gy+4)+'" text-anchor="end" fill="#4a6b65" font-size="9" font-family="sans-serif">'+fmt(gv)+'</text>');
  }

  // X axis labels
  meses.forEach(function(m,i){
    svgParts.push('<text x="'+px(i)+'" y="'+(H-PB+16)+'" text-anchor="middle" fill="#4a6b65" font-size="10" font-family="sans-serif">'+m+'</text>');
  });

  // Zero rupture line
  svgParts.push('<line x1="'+PL+'" y1="'+py(0)+'" x2="'+(W-PR)+'" y2="'+py(0)+'" stroke="rgba(6,182,212,0.5)" stroke-width="1.5" stroke-dasharray="6,4"/>');

  // Series lines + area fills
  series.forEach(function(s){
    var pts=s.pts;
    var areaPath='M '+px(0)+' '+py(pts[0]);
    var linePath='M '+px(0)+' '+py(pts[0]);
    for(var i=1;i<pts.length;i++){
      // Smooth curve
      var x0=px(i-1),y0=py(pts[i-1]),x1=px(i),y1=py(pts[i]);
      var cpx=(x0+x1)/2;
      areaPath+=' C '+cpx+' '+y0+' '+cpx+' '+y1+' '+x1+' '+y1;
      linePath+=' C '+cpx+' '+y0+' '+cpx+' '+y1+' '+x1+' '+y1;
    }
    areaPath+=' L '+px(pts.length-1)+' '+py(0)+' L '+px(0)+' '+py(0)+' Z';
    svgParts.push('<path d="'+areaPath+'" fill="'+s.cor+'" fill-opacity="0.10"/>');
    svgParts.push('<path d="'+linePath+'" fill="none" stroke="'+s.cor+'" stroke-width="2.5" stroke-linejoin="round"/>');

    // Points
    pts.forEach(function(v,i){
      var col=v<=0?'#ff4444':v<s.dem*2?'#fbbf24':s.cor;
      var r=v<=0?8:v<s.dem*2?6:4;
      svgParts.push('<circle cx="'+px(i)+'" cy="'+py(v)+'" r="'+r+'" fill="'+col+'" stroke="#1F2937" stroke-width="1.5"/>');
      if(i===0||v<=0){
        svgParts.push('<text x="'+px(i)+'" y="'+(py(v)-r-4)+'" text-anchor="middle" fill="'+col+'" font-size="9" font-family="sans-serif" font-weight="bold">'+fmt(v)+'</text>');
      }
    });
  });

  // Legend
  var legendX=PL;
  series.forEach(function(s,idx){
    svgParts.push('<rect x="'+legendX+'" y="8" width="12" height="3" rx="1" fill="'+s.cor+'"/>');
    svgParts.push('<text x="'+(legendX+16)+'" y="14" fill="#334155" font-size="10" font-family="sans-serif">'+s.marca+'</text>');
    legendX+=s.marca.length*7+30;
  });

  svgParts.push('</svg>');

  // Insight
  var insightHTML='<div style="margin-top:10px;padding:10px 14px;background:rgba(251,191,36,0.05);border-radius:8px;border-left:2px solid #fbbf24;font-size:11px;color:#D1D5DB;">'
    +'<strong style="color:#fbbf24;font-size:10px;">📊 PROJEÇÃO MAR→SET/26 · SAZONALIDADE INVERNO</strong><br><br>';
  series.forEach(function(s){
    var rupMes=null,est2=mm[s.marca].est;
    for(var i=0;i<6;i++){est2-=mm[s.marca].dem*saz[i];if(est2<=0&&!rupMes)rupMes=meses[i+1];}
    var cob=mm[s.marca].dem>0?(mm[s.marca].est/mm[s.marca].dem).toFixed(1):'∞';
    var refAbr = mm[s.marca].abr25 > 0 ? Math.round(mm[s.marca].abr25) : mm[s.marca].dem;
    var pedido = refAbr > 0 ? Math.max(0, Math.round(4 * refAbr - mm[s.marca].est)) : 0;
    var pedidoStr = pedido > 0
      ? '<span style="color:#fbbf24;font-weight:700;">📦 Pedido sugerido: '+pedido.toLocaleString('pt-BR')+' un</span> <span style="color:#94A3B8;font-size:9px;">(4 meses × '+refAbr.toLocaleString('pt-BR')+' ref Abr/25)</span>'
      : '<span style="color:#34d399;font-size:10px;">✅ Estoque suficiente — sem pedido urgente</span>';
    insightHTML+='<strong style="color:'+s.cor+';">'+s.marca+'</strong>: '
      +mm[s.marca].est.toLocaleString('pt-BR')+' un · Dem ~'+s.dem.toLocaleString('pt-BR')+'/mês · '+cob+' meses · '
      +(rupMes?'<span style="color:#ff4444;font-weight:700;">⚠ Ruptura '+rupMes+'</span>':'<span style="color:#34d399;">✅ OK</span>')+'<br>'
      +'<span style="padding-left:10px;">'+pedidoStr+'</span><br>';
  });
  insightHTML+='<div style="font-size:9px;color:#3d6b63;margin-top:6px;">Sazonalidade: Abr↓25% Mai↓45% Jun↓60% Jul-Set↓70% · 🔴 Ruptura · 🟡 Atenção &lt;2 meses</div></div>';

  if(tendEl){
    var chartDiv=document.getElementById(panel+'-tend-chart');
    if(chartDiv){
      chartDiv.parentNode.innerHTML=svgParts.join('');           /* chart only — no height overflow */
      var insEl=document.getElementById(panel+'-tend-insight');
      if(insEl) insEl.innerHTML=insightHTML;                     /* insight in its own div below */
    } else {
      tendEl.innerHTML=svgParts.join('')+insightHTML;
    }
  }
}

/* ═══════════ WHITE SPACE CRUZAMENTO SELL-OUT ═══════════ */
function renderWSCrossover(panel){
  var el = document.getElementById('ws-'+panel+'-cross');
  if(!el) return;

  var wsData  = panel === 'gam' ? WS_GAM : WS_GAUCHA;
  var ufs     = Object.keys(wsData.by_uf).sort();
  var cor = panel === 'gam' ? '#34d399' : '#f97316';

  // Totals from by_uf
  var total_ativo  = ufs.reduce(function(s,u){ return s + (wsData.by_uf[u].ativo||0); }, 0);
  var total_dorm   = ufs.reduce(function(s,u){ return s + (wsData.by_uf[u].dormido_2025||wsData.by_uf[u].dormido_fy25||0); }, 0);
  var total_ws     = ufs.reduce(function(s,u){
    var d = wsData.by_uf[u];
    return s + ((d.dormido_2025||0) + (d.dormido_2024||0) + (d.dormido_fy25||0) + (d.dormido_fy24||0));
  }, 0);
  var total_rec    = ufs.reduce(function(s,u){
    var d = wsData.by_uf[u];
    return s + ((d.rec_perdida_2025||d.rec_perdida||0));
  }, 0);

  var rows = ufs.map(function(uf){
    var d = wsData.by_uf[uf];
    var ativo    = d.ativo || 0;
    var dormido  = (d.dormido_2025||d.dormido_fy25||0);
    var dormido24= (d.dormido_2024||d.dormido_fy24||0);
    var ws_total = dormido + dormido24;
    var rec      = (d.rec_perdida_2025||d.rec_perdida||0);
    var rec_fy26 = (d.rec_fy26||0);
    var pct_ws   = (ativo + ws_total) > 0 ? Math.round(ws_total/(ativo+ws_total)*100) : 0;
    var ufColors = {PR:'#3b82f6',SC:'#34d399',RS:'#f97316',SP:'#2dd4bf',GO:'#fbbf24',MS:'#06b6d4'};
    var ufColor = ufColors[uf] || '#D1D5DB';

    return '<tr class="u-row-sep">'
      +'<td style="padding:8px;"><span style="padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700;background:'+ufColor+'18;color:'+ufColor+';border:0.5px solid '+ufColor+'44;">'+uf+'</span></td>'
      +'<td style="padding:8px;text-align:right;color:#34d399;font-weight:600;">'+ativo.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:8px;text-align:right;color:'+cor+';font-weight:700;">'+ws_total.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:8px;text-align:right;color:#06b6d4;">'+dormido.toLocaleString('pt-BR')+'</td>'
      +'<td style="padding:8px;text-align:right;color:#fbbf24;">R$ '+rec.toLocaleString('pt-BR')+'K</td>'
      +'<td style="padding:8px;text-align:right;">'
        +'<div style="display:flex;align-items:center;gap:6px;justify-content:flex-end;">'
          +'<div style="background:rgba(255,255,255,0.10);border-radius:3px;height:6px;width:60px;overflow:hidden;">'
            +'<div style="height:100%;border-radius:3px;background:'+cor+';width:'+Math.min(100,pct_ws)+'%;"></div>'
          +'</div>'
          +'<span style="color:#D1D5DB;font-size:10px;min-width:28px;">'+pct_ws+'%</span>'
        +'</div>'
      +'</td>'
    +'</tr>';
  }).join('');

  el.innerHTML = '<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:'+cor+';margin-bottom:14px;">&#128279; CRUZAMENTO: SELL-OUT GIOVANO &times; WHITE SPACE IQVIA</div>'
    +'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px;">'
    +[
      {l:'PDVs Sell-Out Ativos', v:total_ativo.toLocaleString('pt-BR'), s:'Base Giovano FY26',    ac:'#34d399'},
      {l:'White Space Total',    v:total_ws.toLocaleString('pt-BR'),    s:'Não Positivados FY25+FY24',   ac:cor},
      {l:'Não Positivados FY25',        v:total_dorm.toLocaleString('pt-BR'),  s:'Compraram FY25, sumiram em FY26',   ac:'#06b6d4'},
      {l:'Receita em Risco',     v:'R$ '+Math.round(total_rec/1e3)+'M', s:'Receita FY25 perdida', ac:'#fbbf24'},
    ].map(function(k){
      return '<div style="background:rgba(0,0,0,0.2);border-radius:9px;padding:12px;border-top:2px solid '+k.ac+';">'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d6b63;margin-bottom:5px;">'+k.l+'</div>'
        +'<div style="font-size:18px;font-weight:800;color:'+k.ac+';line-height:1;">'+k.v+'</div>'
        +'<div style="font-size:10px;color:#94A3B8;margin-top:3px;">'+k.s+'</div>'
      +'</div>';
    }).join('')
    +'</div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:11px;">'
    +'<thead><tr style="color:#94A3B8;border-bottom:0.5px solid rgba(255,255,255,0.13);">'
    +'<th style="padding:8px;text-align:left;">UF</th>'
    +'<th style="padding:8px;text-align:right;">Ativos Sell-Out</th>'
    +'<th style="padding:8px;text-align:right;">White Space</th>'
    +'<th style="padding:8px;text-align:right;">Não Positivados FY25</th>'
    +'<th style="padding:8px;text-align:right;">Rec. Risco</th>'
    +'<th style="padding:8px;text-align:right;">% WS</th>'
    +'</tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div style="font-size:10px;color:#3d6b63;margin-top:10px;">Sell-Out: Base SCJ Giovano FY26 &middot; White Space: IQVIA Estudo ED Jul/24&#8211;Dez/25 &middot; Não Positivados: compraram FY25 e sumiram em FY26</div>';
}

