function setTopCidView(v, btn){
  consTopCidView = v;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderTopCidades();
}

function renderTopCidades(){
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};
  var sortKey = consTopCidView === 'pdvs' ? 'ws' : 'rec';
  var label1 = sortKey==='pdvs' ? 'PDVs Não Positivados' : 'Receita em Risco (R$K)';

  function mkCid(id, data, color){
    if(consCharts[id]) consCharts[id].destroy();
    var sorted = data.slice().sort(function(a,b){return b[sortKey]-a[sortKey];});
    var c = document.getElementById(id);
    if(!c) return;
    consCharts[id] = new Chart(c,{type:'bar',
      data:{labels:sorted.map(function(d){return d.cidade;}),
        datasets:[{
          label:label1,
          data:sorted.map(function(d){return d[sortKey];}),
          backgroundColor:sorted.map(function(d){return d.color+'bb';}),
          borderColor:sorted.map(function(d){return d.color;}),
          borderWidth:1.5, borderRadius:4
        }]},
      options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:false},tooltip:{...CO,callbacks:{label:function(c){
          return sortKey==='pdvs' ? ' '+c.raw+' PDVs' : ' R$'+c.raw+'K';
        }}}},
        scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},
                y:{grid:{display:false},ticks:{color:'#475569',font:{size:9}}}}}
    });
  }
  mkCid('cons-topcid-gam', TOP_CID_GAM, '#34d399');
  mkCid('cons-topcid-gch', TOP_CID_GCH, '#f97316');
}

