function renderMensalPos(){
  if(consCharts['cons-mensal-pos']) consCharts['cons-mensal-pos'].destroy();
  var c = document.getElementById('cons-mensal-pos');
  if(!c) return;
  var GC='rgba(148,163,184,0.12)', TC='#475569';
  var CO={backgroundColor:'#0F172A',titleColor:'#FFFFFF',bodyColor:'#E2E8F0',borderColor:'rgba(148,163,184,0.20)',borderWidth:1,padding:10};
  var labels = CONS_MENSAL.labels;
  var datasets;

  function getGAMArr(yr){ return GAM_POSITIV_MES[yr] ? GAM_POSITIV_MES[yr].map(function(d){return d.positivas;}) : new Array(12).fill(null); }
  function getGCHArr(yr){ return GCH_POSITIV_MES[yr] ? GCH_POSITIV_MES[yr].map(function(d){return d.positivas;}) : new Array(12).fill(null); }
  function addArr(a,b){ return a.map(function(v,i){ return (v==null&&b[i]==null)?null:(v||0)+(b[i]||0); }); }

  if(consMensalView === 'gam'){
    datasets = [
      {label:'2024 GAM',data:getGAMArr('2024'),borderColor:'#5a6478',backgroundColor:'rgba(90,100,120,0.08)',borderWidth:1.5,borderDash:[4,3],pointRadius:3,tension:0.35,fill:false},
      {label:'2025 GAM',data:getGAMArr('2025'),borderColor:'#3b82f6',backgroundColor:'rgba(59,130,246,0.08)',borderWidth:2,pointRadius:3,tension:0.35,fill:false},
      {label:'2026 GAM',data:getGAMArr('2026'),borderColor:'#34d399',backgroundColor:'rgba(52,211,153,0.12)',borderWidth:2.5,pointRadius:5,tension:0.35,fill:true},
    ];
  } else if(consMensalView === 'gaucha'){
    datasets = [
      {label:'2024 Gaúcha',data:getGCHArr('2024'),borderColor:'#5a6478',backgroundColor:'rgba(90,100,120,0.08)',borderWidth:1.5,borderDash:[4,3],pointRadius:3,tension:0.35,fill:false},
      {label:'2025 Gaúcha',data:getGCHArr('2025'),borderColor:'#f97316',backgroundColor:'rgba(249,115,22,0.08)',borderWidth:2,pointRadius:3,tension:0.35,fill:false},
      {label:'2026 Gaúcha',data:getGCHArr('2026'),borderColor:'#fbbf24',backgroundColor:'rgba(251,191,36,0.12)',borderWidth:2.5,pointRadius:5,tension:0.35,fill:true},
    ];
  } else {
    datasets = [
      {label:'2024 (combinado)',data:addArr(getGAMArr('2024'),getGCHArr('2024')),borderColor:'#5a6478',backgroundColor:'rgba(90,100,120,0.05)',borderWidth:1.5,borderDash:[4,3],pointRadius:3,tension:0.35,fill:false},
      {label:'2025 (combinado)',data:addArr(getGAMArr('2025'),getGCHArr('2025')),borderColor:'#2dd4bf',backgroundColor:function(ctx){var ca=ctx.chart.chartArea;return makeAreaGradient(ctx.chart.ctx,ca,'#2dd4bf');},borderWidth:2,pointRadius:3,tension:0.4,fill:true},
      {label:'2026 (combinado)',data:addArr(getGAMArr('2026'),getGCHArr('2026')),borderColor:'#34d399',backgroundColor:function(ctx){var ca=ctx.chart.chartArea;return makeAreaGradient(ctx.chart.ctx,ca,'#34d399');},borderWidth:2.5,pointRadius:5,pointHoverRadius:7,pointBorderColor:'#101828',tension:0.4,fill:true},
    ];
  }

  consCharts['cons-mensal-pos'] = new Chart(c,{type:'line',
    data:{labels:labels, datasets:datasets},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:9},boxWidth:10}},tooltip:{...CO,mode:'index',intersect:false}},
      scales:{x:{grid:{color:GC},ticks:{color:TC,font:{size:9}}},
              y:{grid:{color:GC},ticks:{color:TC,font:{size:9}},title:{display:true,text:'PDVs Ativos',color:TC,font:{size:9}}}}}
  });

  var ins = document.getElementById('cons-mensal-insight');
  if(ins){
    var gam26raw = getGAMArr('2026'); var gch26raw = getGCHArr('2026');
    var comb26raw = addArr(gam26raw, gch26raw);
    var comb26 = comb26raw.filter(function(v){return v!=null;});
    var comb25jan = (getGAMArr('2025')[0]||0)+(getGCHArr('2025')[0]||0);
    /* label dinâmico do último mês confirmado */
    var _mLabels = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
    var _lastIdx = comb26raw.reduce(function(acc,v,i){return v!=null?i:acc;}, 0);
    var _lastLbl = _mLabels[_lastIdx] + '/26';
    ins.innerHTML = '📈 <strong style="color:#34d399;">Jan/26 combinado: '+comb26[0].toLocaleString('pt-BR')+' PDVs</strong> — pico sazonalidade verão · vs Jan/25: '+comb25jan.toLocaleString('pt-BR')+' PDVs '
      +'<span style="color:'+((comb26[0]-comb25jan)>=0?'#34d399':'#ef4444')+';font-weight:700;">'+(comb26[0]-comb25jan>=0?'▲':'▼')+' '+Math.abs(Math.round((comb26[0]-comb25jan)/comb25jan*100))+'%</span>.'
      +' &nbsp;📉 <strong style="color:#06b6d4;">'+_lastLbl+': '+comb26[comb26.length-1].toLocaleString('pt-BR')+' PDVs</strong> — queda esperada pós-verão · sazonalidade repelente.'
      +' &nbsp;⚡ <strong style="color:#fbbf24;">Pico de positivação: Jan–Fev/26</strong> · preparação de estoque necessária a partir de Nov/26.';
  }
}

