/* ═══════════ VOLUME/RECEITA POR ANO — CHART.JS VERTICAL BAR ═══════════ */
var _anoCharts = {};

function renderAnoChart(canvasId, anos, vals, isVol, colors){
  var canvas = document.getElementById(canvasId);
  if(!canvas) return;
  
  var GC = 'rgba(148,163,184,0.12)', TC = '#475569';
  
  // Format value for display
  function fmt(v){
    if(v == null) return '-';
    if(!isVol){
      if(v >= 1e6) return 'R$ ' + (v/1e6).toFixed(2) + 'M';
      if(v >= 1e3) return 'R$ ' + Math.round(v/1e3) + 'K';
      return 'R$ ' + v;
    }
    // Unidades: mostrar número completo com ponto separador
    return v.toLocaleString('pt-BR') + ' un';
  }

  var bgColors = colors || ['rgba(59,130,246,0.75)','rgba(45,212,191,0.75)','rgba(52,211,153,0.75)'];
  var bdColors = colors ? colors.map(function(c){return c.replace('0.75','1');})
                       : ['#3b82f6','#2dd4bf','#34d399'];

  function yTickCb(v){
    if(!isVol){
      if(v >= 1e6) return 'R$ '+(v/1e6).toFixed(1)+'M';
      if(v >= 1e3) return 'R$ '+(v/1e3).toFixed(0)+'K';
      return 'R$ '+v;
    }
    if(v >= 1e6) return (v/1e6).toFixed(1)+'M un';
    if(v >= 1e3) return (v/1e3).toFixed(0)+'K un';
    return v+' un';
  }

  function onCompleteCb(anim){
    var chart = anim.chart;
    var ctx2 = chart.ctx;
    ctx2.save();
    ctx2.font = 'bold 12px Inter, sans-serif';
    ctx2.textAlign = 'center';
    ctx2.textBaseline = 'bottom';
    chart.data.datasets.forEach(function(dataset, i){
      var meta = chart.getDatasetMeta(i);
      meta.data.forEach(function(bar, j){
        var val = dataset.data[j];
        if(val == null) return;
        var colors2 = ['#3b82f6','#2dd4bf','#34d399'];
        ctx2.fillStyle = (dataset.borderColor && dataset.borderColor[j]) || colors2[j] || '#ffffff';
        ctx2.fillText(fmt(val), bar.x, bar.y - 4);
      });
    });
    ctx2.restore();
  }

  // ── T8: update-or-create (skip destroy on re-renders) ────────────────
  // Usar Chart.getChart() que reflete estado real (evita referencia stale pos-destroy)
  var existing = Chart.getChart(canvas) || null;
  if(existing){
    existing.data.labels                              = anos;
    existing.data.datasets[0].data                   = vals;
    existing.data.datasets[0].backgroundColor        = bgColors;
    existing.data.datasets[0].borderColor            = bdColors;
    existing.options.scales.y.ticks.callback         = yTickCb;
    if(existing.options.scales.x && existing.options.scales.x.ticks) existing.options.scales.x.ticks.color = '#1E293B';
    existing.options.plugins.tooltip.callbacks.label = function(ctx){ return '  '+fmt(ctx.raw); };
    existing.options.animation.onComplete            = onCompleteCb;
    existing.update();
    return;
  }

  // Fix: reset canvas para nao herdar height:0px/width:0px do estado salvo
  canvas.removeAttribute('width'); canvas.removeAttribute('height');
  if(canvas.style) { canvas.style.width=''; canvas.style.height=''; }
  _anoCharts[canvasId] = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: anos,
      datasets: [{
        data: vals,
        backgroundColor: bgColors,
        borderColor:     bdColors,
        borderWidth: 2,
        borderRadius: 8,
        borderSkipped: false,
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#0a1a18',
          titleColor: '#e2e8f0',
          bodyColor: '#D1D5DB',
          borderColor: 'rgba(255,255,255,0.13)',
          borderWidth: 1,
          padding: 12,
          callbacks: {
            label: function(ctx) { return '  ' + fmt(ctx.raw); }
          }
        },
        // Inline data labels on bars
        datalabels: undefined,
      },
      scales: {
        x: {
          grid: { display: false },
          ticks: { color: '#1E293B', font: { size: 12, weight: '600' } }
        },
        y: {
          grid: { color: GC },
          ticks: {
            color: TC,
            font: { size: 10 },
            callback: yTickCb
          },
          beginAtZero: true
        }
      },
      animation: {
        duration: 900, easing: 'easeOutQuart',
        onComplete: onCompleteCb
      }
    }
  });
}

// ── MSO2: Diagnóstico automático JAN-JUN YoY ──
function renderMSO2Insight(){
  var el = document.getElementById('mso2-insight');
  if(!el) return;
  var sel = document.getElementById('mso2MarketSel') || document.getElementById('msoMarketSel');
  var mkt = sel ? sel.value : 'Farma Sul';
  if(!nqIsOld(mkt) && NQ_PR.mk[mkt]) return; /* base nova: diagnóstico feito em nqRenderMSO2 */

  function col(v){ return v>=0?'#34d399':'#ef4444'; }
  function sig(v){ return v>=0?'+':''; }
  function arrowTrend(v){ return v>0.1?'↗ ':(v<-0.1?'↘ ':'→ '); }

  if(typeof mso2Mode === 'undefined' || mso2Mode === 'share'){
    var d = MKTSHARE_OVERVIEW[mkt]; if(!d) return;
    var off = d['OFF!'], exp = d['EXPOSIS'];
    if(!off||!exp) return;
    var oj25=off.jan25!=null?off.jan25:off.fytd25, of25=off.feb25!=null?off.feb25:off.fytd25, om25=off.mar25!=null?off.mar25:off.fytd25, oa25=off.apr25!=null?off.apr25:off.fytd25, omi25=off.mai25!=null?off.mai25:off.fytd25;
    var ej25=exp.jan25!=null?exp.jan25:exp.fytd25, ef25=exp.feb25!=null?exp.feb25:exp.fytd25, em25=exp.mar25!=null?exp.mar25:exp.fytd25, ea25=exp.apr25!=null?exp.apr25:exp.fytd25, emi25=exp.mai25!=null?exp.mai25:exp.fytd25;
    var oj26=off.monthly[6], of26=off.monthly[7], om26=off.monthly[8], oa26=off.monthly[9]||0, omi26=off.monthly[10]||0, oju26=off.monthly[11]||0;
    var ej26=exp.monthly[6], ef26=exp.monthly[7], em26=exp.monthly[8], ea26=exp.monthly[9]||0, emi26=exp.monthly[10]||0, eju26=exp.monthly[11]||0;
    var offAcum25=Math.round((oj25+of25+om25+oa25+omi25)/5*100)/100, offAcum26=Math.round((oj26+of26+om26+oa26+omi26+oju26)/6*100)/100;
    var expAcum25=Math.round((ej25+ef25+em25+ea25+emi25)/5*100)/100, expAcum26=Math.round((ej26+ef26+em26+ea26+emi26+eju26)/6*100)/100;
    var scjA25=Math.round((offAcum25+expAcum25)*10)/10, scjA26=Math.round((offAcum26+expAcum26)*10)/10;
    var scjDA=Math.round((scjA26-scjA25)*10)/10;
    var allDeltas2 = MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';}).map(function(b){
      var bd=d[b]; if(!bd) return null;
      var bj25=bd.jan25!=null?bd.jan25:bd.fytd25, bf25=bd.feb25!=null?bd.feb25:bd.fytd25, bm25=bd.mar25!=null?bd.mar25:bd.fytd25, ba25v=bd.apr25!=null?bd.apr25:bd.fytd25, bmi25v=bd.mai25!=null?bd.mai25:bd.fytd25;
      var bj26=bd.monthly[6], bf26=bd.monthly[7], bm26=bd.monthly[8], bab26=bd.monthly[9]||0, bmi26=bd.monthly[10]||0, bju26=bd.monthly[11]||0;
      var ba25=Math.round((bj25+bf25+bm25+ba25v+bmi25v)/5*100)/100, ba26=Math.round((bj26+bf26+bm26+bab26+bmi26+bju26)/6*100)/100;
      var da=Math.round((ba26-ba25)*100)/100;
      return {b:b,a25:ba25,a26:ba26,da:da,j26:bj26,f26:bf26,m26:bm26,ab26:bab26,mi26:bmi26,ju26:bju26,cor:MSO_COLORS[b]||'#e2e8f0'};
    }).filter(Boolean);
    var lines=[];
    lines.push('<span style="color:#fbbf24;font-weight:700;font-size:10px;">★</span> '
      +'<strong style="color:#fbbf24;">SCJ Combined</strong> (OFF!+EXPOSIS): '
      +'Acum Jan-Jun/26 <strong style="color:#fbbf24;">'+scjA26+'%</strong> '
      +'<span style="color:'+col(scjDA)+';font-weight:700;">'+(scjDA>=0?'↑ +':'↓ ')+Math.abs(scjDA).toFixed(1)+'pp vs /25</span>');
    allDeltas2.forEach(function(x){
      var trend=arrowTrend(x.da);
      var monthStr='Jan: <strong style="color:'+x.cor+';">'+x.j26+'%</strong>'
        +' · Fev: <strong style="color:'+x.cor+';">'+x.f26+'%</strong>'
        +' · Mar: <strong style="color:'+x.cor+';">'+(x.m26)+'%</strong>'
        +' · Abr: <strong style="color:'+x.cor+';">'+x.ab26+'%</strong>'
        +' · Mai: <strong style="color:'+x.cor+';">'+x.mi26+'%</strong>'
        +' · Jun: <strong style="color:'+x.cor+';">'+x.ju26+'%</strong>';
      lines.push('<span style="color:'+col(x.da)+';font-weight:700;font-size:10px;">'+trend+'</span>'
        +'<strong style="color:'+x.cor+';">'+x.b+'</strong>'
        +' Acum/26 <strong style="color:'+x.cor+';">'+x.a26.toFixed(2)+'%</strong>'
        +' <span style="color:'+col(x.da)+';"> ('+sig(x.da)+x.da.toFixed(2)+'pp)</span>'
        +' · '+monthStr);
    });
    el.innerHTML='<div style="padding:10px 4px;">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.14em;color:#1D6FA8;text-transform:uppercase;margin-bottom:9px;">📊 DIAGNÓSTICO · '+mkt+' · Jan–Jun/26</div>'
      +'<div style="font-size:11px;color:#1E293B;line-height:1.9;">'
      +lines.join('<br>')
      +'</div></div>';
    return;
  }

  /* R$ MM / UNIDADES MODE — DIAGNOSTICO ENRIQUECIDO */
  var nbvI = (typeof NIELSEN_BRAND_VAL !== 'undefined') ? NIELSEN_BRAND_VAL[mkt] : null;
  if(!nbvI) return;
  var isValI = mso2Mode === 'val';
  function fmtNI(v){ if(isValI) return v>=1?'R$'+v.toFixed(2)+'MM':'R$'+(v*1000).toFixed(0)+'K'; return Math.round(v).toLocaleString('pt-BR')+'K'; }
  function pctI(v26,v25){ return v25>0?Math.round((v26-v25)/v25*1000)/10:0; }
  /* Mercado total Jan-Mar */
  var fytMktI=(typeof FYTD_MARKET_TOTAL!=='undefined')?FYTD_MARKET_TOTAL[mkt]:null;
  var mtI26=fytMktI?(isValI?((fytMktI.jan26_val||0)+(fytMktI.fev26_val||0)+(fytMktI.mar26_val||0)+(fytMktI.abr26_val||0)+(fytMktI.mai26_val||0)):((fytMktI.jan26_un||0)+(fytMktI.fev26_un||0)+(fytMktI.mar26_un||0)+(fytMktI.abr26_un||0)+(fytMktI.mai26_un||0))):0;
  var mtI25=fytMktI?(isValI?((fytMktI.jan25_val||0)+(fytMktI.fev25_val||0)+(fytMktI.mar25_val||0)+(fytMktI.abr25_val||0)+(fytMktI.mai25_val||0)):((fytMktI.jan25_un||0)+(fytMktI.fev25_un||0)+(fytMktI.mar25_un||0)+(fytMktI.abr25_un||0)+(fytMktI.mai25_un||0))):0;
  mtI26=Math.round(mtI26*100)/100; mtI25=Math.round(mtI25*100)/100;
  var mtIDelta=mtI25>0?Math.round((mtI26-mtI25)/mtI25*1000)/10:0;
  var mtICor=mtIDelta>=0?'#34d399':'#ef4444';
  /* SCJ total Jan-Mar (soma das marcas) */
  var scjI26=0, scjI25=0;
  MSO_BRANDS.forEach(function(b){
    if(b==='ALL OTHERS CAMP') return; /* excluir ALL OTHERS do total SCJ */
    var bd=nbvI[b]; if(!bd) return;
    var j26=isValI?(bd.jan_val||0):(bd.jan_un||0);
    var f26=isValI?(bd.fev_val||0):(bd.fev_un||0);
    var m26=isValI?(bd.mar_val||0):(bd.mar_un||0);
    var ab26=isValI?(bd.abr_val||0):(bd.abr_un||0);
    var mi26=isValI?(bd.mai_val||0):(bd.mai_un||0);
    scjI26 += j26+f26+m26+ab26+mi26;
    var hasEx=isValI?(bd.jan25_val!==undefined):(bd.jan25_un!==undefined);
    if(hasEx){
      scjI25 += (isValI?(bd.jan25_val||0):(bd.jan25_un||0))
               +(isValI?(bd.fev25_val||0):(bd.fev25_un||0))
               +(isValI?(bd.mar25_val||0):(bd.mar25_un||0))
               +(isValI?(bd.abr25_val||0):(bd.abr25_un||0))
               +(isValI?(bd.mai25_val||0):(bd.mai25_un||0));
    } else {
      var fyt25=isValI?bd.fytd25_val:bd.fytd25_un, fyt26=isValI?bd.fytd26_val:bd.fytd26_un;
      var ratio=fyt26>0?(j26+f26+m26+ab26+mi26)/fyt26:1/5;
      scjI25 += fyt25*ratio;
    }
  });
  scjI26=Math.round(scjI26*100)/100; scjI25=Math.round(scjI25*100)/100;
  var scjIDelta=scjI25>0?Math.round((scjI26-scjI25)/scjI25*1000)/10:0;
  var scjICor=scjIDelta>=0?'#34d399':'#ef4444';
  /* Share SCJ no mercado */
  var shrI26=mtI26>0?Math.round(scjI26/mtI26*1000)/10:0;
  var shrI25=mtI25>0?Math.round(scjI25/mtI25*1000)/10:0;
  var shrIDelta=Math.round((shrI26-shrI25)*10)/10;
  var shrICor=shrIDelta>=0?'#34d399':'#ef4444';
  var vsMarketI=Math.round((scjIDelta-mtIDelta)*10)/10;
  var vsCorkI=vsMarketI>=0?'#34d399':'#ef4444';
  var vsLabelI=vsMarketI>0.5?'SCJ superou o mercado':vsMarketI<-0.5?'SCJ ficou abaixo do mercado':'SCJ acompanhou o mercado';
  /* HB OFF!+EXPOSIS — variaveis para bloco diagnostico MSO2 */
  var hbI25=0, hbI26=0;
  MSO_BRANDS.forEach(function(b){
    if(b!=='OFF!'&&b!=='EXPOSIS') return;
    var bd=nbvI[b]; if(!bd) return;
    var j26=isValI?(bd.jan_val||0):(bd.jan_un||0);
    var f26=isValI?(bd.fev_val||0):(bd.fev_un||0);
    var m26=isValI?(bd.mar_val||0):(bd.mar_un||0);
    var ab26=isValI?(bd.abr_val||0):(bd.abr_un||0);
    var mi26=isValI?(bd.mai_val||0):(bd.mai_un||0);
    hbI26 += j26+f26+m26+ab26+mi26;
    var hasEx=isValI?(bd.jan25_val!==undefined):(bd.jan25_un!==undefined);
    if(hasEx){
      hbI25 += (isValI?(bd.jan25_val||0):(bd.jan25_un||0))
              +(isValI?(bd.fev25_val||0):(bd.fev25_un||0))
              +(isValI?(bd.mar25_val||0):(bd.mar25_un||0))
              +(isValI?(bd.abr25_val||0):(bd.abr25_un||0))
              +(isValI?(bd.mai25_val||0):(bd.mai25_un||0));
    } else {
      var fyt25b=isValI?bd.fytd25_val:bd.fytd25_un, fyt26b=isValI?bd.fytd26_val:bd.fytd26_un;
      var ratio=fyt26b>0?(j26+f26+m26+ab26+mi26)/fyt26b:1/5;
      hbI25 += fyt25b*ratio;
    }
  });
  hbI25=Math.round(hbI25*100)/100; hbI26=Math.round(hbI26*100)/100;
  var hbIDelta=hbI25>0?Math.round((hbI26-hbI25)/hbI25*1000)/10:0;
  var hbICorD=hbIDelta>=0?'#34d399':'#ef4444';
  var shrHbI26=mtI26>0?Math.round(hbI26/mtI26*1000)/10:0;
  var shrHbI25=mtI25>0?Math.round(hbI25/mtI25*1000)/10:0;
  var shrHbIDelta=Math.round((shrHbI26-shrHbI25)*10)/10;
  var shrHbICor=shrHbIDelta>=0?'#34d399':'#ef4444';
  var vsHbI=Math.round((hbIDelta-mtIDelta)*10)/10;
  var vsHbICor=vsHbI>=0?'#34d399':'#ef4444';
  var vsHbILabel=vsHbI>0.5?'HB superou o mercado':vsHbI<-0.5?'HB ficou abaixo do mercado':'HB acompanhou o mercado';
  /* Por marca */
  /* lines2: inclui ALL OTHERS CAMP em val/un; exclui em share (cálculos SCJ intactos) */
  var lines2 = (mso2Mode!=='share' ? MSO_BRANDS : MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';})).map(function(b){
    var bd=nbvI[b]; if(!bd) return null;
    var cor=MSO_COLORS[b]||'#e2e8f0';
    var j26=isValI?(bd.jan_val||0):(bd.jan_un||0);
    var fv26=isValI?(bd.fev_val||0):(bd.fev_un||0);
    var m26=isValI?(bd.mar_val||0):(bd.mar_un||0);
    var ab26b=isValI?(bd.abr_val||0):(bd.abr_un||0);
    var mi26b=isValI?(bd.mai_val||0):(bd.mai_un||0);
    var v26b=Math.round((j26+fv26+m26+ab26b+mi26b)*100)/100;
    var fyt25=isValI?bd.fytd25_val:bd.fytd25_un, fyt26=isValI?bd.fytd26_val:bd.fytd26_un;
    var hasEx=isValI?(bd.jan25_val!==undefined):(bd.jan25_un!==undefined);
    var v25b;
    if(hasEx){
      v25b=Math.round(((isValI?(bd.jan25_val||0):(bd.jan25_un||0))
                      +(isValI?(bd.fev25_val||0):(bd.fev25_un||0))
                      +(isValI?(bd.mar25_val||0):(bd.mar25_un||0))
                      +(isValI?(bd.abr25_val||0):(bd.abr25_un||0))
                      +(isValI?(bd.mai25_val||0):(bd.mai25_un||0)))*100)/100;
    } else {
      var ratio2=fyt26>0?v26b/fyt26:1/5;
      v25b=Math.round(fyt25*ratio2*100)/100;
    }
    var pct=pctI(v26b,v25b);
    var cc=pct>=0?'#34d399':'#ef4444';
    var trend=pct>2?'↗':(pct<-2?'↘':'→');
    var shrB=mtI26>0?Math.round(v26b/mtI26*1000)/10:0;
    return '<div style="display:flex;align-items:center;gap:5px;padding:3px 0;border-bottom:0.5px solid rgba(147,187,235,0.25);">'
      +'<span style="width:5px;height:5px;border-radius:50%;background:'+cor+';flex-shrink:0;"></span>'
      +'<span style="color:'+cor+';font-weight:700;min-width:95px;font-size:11px;">'+b+'</span>'
      +'<span style="color:#e2e8f0;font-size:11px;">Jan-Jun/26: <strong>'+fmtNI(v26b)+'</strong></span>'
      +'<span style="color:#475569;margin:0 3px;">·</span>'
      +'<span style="color:#64748b;font-size:11px;">Jan-Mai/25: '+fmtNI(v25b)+'</span>'
      +'<span style="color:'+cc+';font-weight:700;font-size:11px;margin-left:5px;">'
        +'<span style="font-size:10px;">'+trend+'</span> '+(pct>=0?'+':'')+pct.toFixed(1)+'%'
      +'</span>'
      +'<span style="color:#334155;font-size:10px;margin-left:auto;background:rgba(45,90,142,0.08);padding:1px 5px;border-radius:3px;">shr '+shrB.toFixed(1)+'%</span>'
      +'</div>';
  }).filter(Boolean);
  el.innerHTML=
    '<div style="padding:10px 4px;">'
    +'<div style="font-size:9px;font-weight:700;letter-spacing:.14em;color:#1D6FA8;text-transform:uppercase;margin-bottom:12px;">📊 DIAGNÓSTICO · '+mkt+' · '+(isValI?'R$ MM':'Unidades')+' JAN–JUN/26</div>'
    /* Bloco 1: Mercado Total */
    +'<div style="margin-bottom:10px;padding-bottom:9px;border-bottom:0.5px solid rgba(147,187,235,0.30);">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:5px;">🌎 Mercado Total (todas as marcas)</div>'
      +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
        +'<span style="font-size:11px;color:#94a3b8;">Jan-Mai/25: <strong style="color:#e2e8f0;">'+fmtNI(mtI25)+'</strong></span>'
        +'<span style="color:#334155;">→</span>'
        +'<span style="font-size:11px;color:#94a3b8;">Jan-Jun/26: <strong style="color:#e2e8f0;">'+fmtNI(mtI26)+'</strong></span>'
        +'<span style="background:'+mtICor+'1a;color:'+mtICor+';font-weight:700;font-size:11px;padding:2px 8px;border-radius:4px;border:0.5px solid '+mtICor+'44;">'
          +(mtIDelta>=0?'▲ +':'▼ ')+Math.abs(mtIDelta).toFixed(1)+'%'
        +'</span>'
      +'</div>'
    +'</div>'
    /* Bloco 2: SCJ vs Mercado */
    +'<div style="margin-bottom:10px;padding-bottom:9px;border-bottom:0.5px solid rgba(147,187,235,0.30);">'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:5px;">&#128293; OFF! + EXPOSIS (HB) &middot; JAN&ndash;MAI &middot; '+(isValI?'R$ MM':'Unidades')+'</div>'
      +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;">'
        +'<span style="font-size:11px;color:#94a3b8;">Jan-Mai/25: <strong style="color:#3b82f6;">'+fmtNI(hbI25)+'</strong></span>'
        +'<span style="color:#334155;">→</span>'
        +'<span style="font-size:11px;color:#94a3b8;">Jan-Jun/26: <strong style="color:#3b82f6;">'+fmtNI(hbI26)+'</strong></span>'
        +'<span style="background:'+hbICorD+'1a;color:'+hbICorD+';font-weight:700;font-size:11px;padding:2px 8px;border-radius:4px;border:0.5px solid '+hbICorD+'44;">'
          +(hbIDelta>=0?'▲ +':'▼ ')+Math.abs(hbIDelta).toFixed(1)+'%'
        +'</span>'
      +'</div>'
      +'<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:5px;">'
        +'<span style="font-size:11px;color:#64748b;">Share Jan-Mai/25: <strong style="color:#cbd5e1;">'+shrHbI25.toFixed(1)+'%</strong></span>'
        +'<span style="color:#1e293b;">|</span>'
        +'<span style="font-size:11px;color:#64748b;">Share Jan-Jun/26: <strong style="color:#3b82f6;">'+shrHbI26.toFixed(1)+'%</strong></span>'
        +'<span style="color:'+shrHbICor+';font-weight:700;font-size:11px;">'
          +(shrHbIDelta>=0?'▲ +':'▼ ')+Math.abs(shrHbIDelta).toFixed(1)+'pp'
        +'</span>'
      +'</div>'
          +'</div>'
    /* Bloco 3: Por Marca */
    +'<div>'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">📈 Por Marca · participacao no mercado total</div>'
      +'<div style="font-size:11px;color:#D1D5DB;">'+lines2.join('')+'</div>'
    +'</div>'
    +'</div>';
}

/* ═══════════ CURTO PRAZO — Card 2 (Jan·Fev·Mar·Abr) ═══════════ */
function renderShrShortTerm2(mkt){
  var wrap=document.getElementById('shr-st-wrap2');
  if(!wrap)return;
  var d=SHR_TREND_DATA[mkt];
  if(!d){wrap.style.display='none';return;}
  wrap.style.display='block';
  var brands=['OFF!','EXPOSIS','XO INSETO','SUPER REPELEX','SBP'];
  function _ser(br){var bd=d[br];if(!bd||!bd.fy26)return [];return (bd.fy25||new Array(12).fill(null)).concat(bd.fy26);}
  function gv(br,idx){var s=_ser(br);return (idx>=0&&s[idx]!=null)?s[idx]:null;}
  var _ref=_ser('OFF!').length?_ser('OFF!'):_ser('XO INSETO'); var JUN=_ref.reduce(function(a,v,i){return v!=null?i:a;},11);
  var MAI=JUN-1,ABR=JUN-2,MAR=JUN-3; var _L=nqSeriesLabels(mkt); var _l=function(i){return (_L[i]||'').toUpperCase();};
  function dc(v){return v==null?'#64748B':(v>0?'#16a34a':v<0?'#dc2626':'#94A3B8');}
  function fp(v){return v!=null?v.toFixed(2)+'%':'—';}
  function fd(v){if(v==null)return'—';return(v>=0?'+':'')+v.toFixed(2)+'pp';}
  var rows=brands.map(function(br){
    var a=gv(br,JUN),m=gv(br,MAI),f=gv(br,ABR),j=gv(br,MAR);
    var mom=(a!=null&&m!=null)?a-m:null;
    var bi26=(a!=null&&m!=null)?(a+m)/2:null;
    var bi25=(f!=null&&j!=null)?(f+j)/2:null;
    var d2m=(bi26!=null&&bi25!=null)?bi26-bi25:null;
    return{br:br,a:a,m:m,mom:mom,bi26:bi26,bi25:bi25,d2m:d2m};
  });
  // SCJ = OFF! + EXPOSIS
  var scja=0,scjm=0,scjf=0,scjj=0,ok=true;
  ['OFF!','EXPOSIS'].forEach(function(br){
    var a=gv(br,JUN),m=gv(br,MAI),f=gv(br,ABR),j=gv(br,MAR);
    if(a==null||m==null||f==null||j==null){ok=false;return;}
    scja+=a;scjm+=m;scjf+=f;scjj+=j;
  });
  if(ok){
    var smom=scja-scjm,sbi26=(scja+scjm)/2,sbi25=(scjf+scjj)/2,sd2m=sbi26-sbi25;
    rows.push({br:'SCJ (OFF!+EXPOSIS)',a:scja,m:scjm,mom:smom,bi26:sbi26,bi25:sbi25,d2m:sd2m,isSCJ:true});
  }
  var h='<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  h+='<thead><tr style="border-bottom:1.5px solid rgba(45,90,142,0.35);">';
  h+='<th style="padding:5px 8px;text-align:left;color:#64748b;font-size:9px;font-weight:700;letter-spacing:.08em;">MARCA</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1D6FA8;font-size:9px;font-weight:700;">'+_l(JUN)+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#64748b;font-size:9px;font-weight:700;">'+_l(MAI)+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1E293B;font-size:9px;font-weight:700;">Δ MoM</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1D6FA8;font-size:9px;font-weight:700;border-left:1px solid rgba(45,90,142,0.25);">'+_L[JUN].split('/')[0]+'+'+_L[MAI].split('/')[0]+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#64748b;font-size:9px;font-weight:700;">'+_L[ABR].split('/')[0]+'+'+_L[MAR].split('/')[0]+'</th>';
  h+='<th style="padding:5px 8px;text-align:right;color:#1E293B;font-size:9px;font-weight:700;">Δ 2M</th>';
  h+='</tr></thead><tbody>';
  rows.forEach(function(r){
    var scjStyle=r.isSCJ?'border-top:1.5px solid rgba(45,90,142,0.35);background:rgba(45,90,142,0.07);':'';
    var brc=r.isSCJ?'#2D5A8E':(_shrBrandColors[r.br]||'#1E293B');
    h+='<tr style="'+scjStyle+'">';
    h+='<td style="padding:4px 8px;font-weight:700;color:'+brc+';font-size:11px;">'+r.br+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#1E293B;font-weight:700;">'+fp(r.a)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#64748B;">'+fp(r.m)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;font-weight:800;color:'+dc(r.mom)+';">'+fd(r.mom)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#1E293B;font-weight:700;border-left:1px solid rgba(45,90,142,0.25);">'+fp(r.bi26)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;color:#64748B;">'+fp(r.bi25)+'</td>';
    h+='<td style="padding:4px 8px;text-align:right;font-weight:800;color:'+dc(r.d2m)+';">'+fd(r.d2m)+'</td>';
    h+='</tr>';
  });
  h+='</tbody></table>';
  h+='<div style="font-size:9px;color:#475569;margin-top:6px;">Δ MoM = '+_L[JUN]+' − '+_L[MAI]+' &nbsp;|&nbsp; Δ 2M = média ('+_L[JUN]+' + '+_L[MAI]+') − média ('+_L[ABR]+' + '+_L[MAR]+')'+nqFY(mkt).base+'</div>';
  var tEl=document.getElementById('shr-st-table2');
  if(tEl)tEl.innerHTML=h;
}
function toggleShrST2(){
  var t=document.getElementById('shr-st-table2');
  var btn=document.getElementById('shr-st-btn2');
  if(!t||!btn)return;
  var open=t.style.display!=='none';
  t.style.display=open?'none':'block';
  btn.innerHTML=open?'&#9658; Análise Curto Prazo':'&#9660; Análise Curto Prazo';
}

