/* ═══════════ MSO3 — VISAO FISCAL FYTD Jul-Mar ═══════════ */
var mso3Mode = 'val'; // 'val' | 'un'

function setMSO3Mode(mode, btn){
  mso3Mode = mode;
  ['mso3-mode-share','mso3-mode-val','mso3-mode-un'].forEach(function(id){
    var b = document.getElementById(id);
    if(!b) return;
    var active = (id === 'mso3-mode-'+mode);
    if(active) b.classList.add('active'); else b.classList.remove('active');
    b.style.color      = active ? '#fbbf24' : '#D1D5DB';
    b.style.background = active ? 'rgba(251,191,36,0.12)' : '#161B22';
    b.style.fontWeight = active ? '700' : '600';
  });
  renderMSO3();
}

function renderMSO3_OLD_REPLACED(){}

function renderMSO3(){
  var sel = document.getElementById('mso3MarketSel');
  var mkt = sel ? sel.value : 'T.BR Farma';
  if(!nqIsOld(mkt) && NQ_PR.mk[mkt]){ nqRenderMSO3(mkt); return; }
  if(mso3Mode === 'share') mso3Mode = 'val';
  var isVal = mso3Mode === 'val';
  var brands = MSO_BRANDS.filter(function(b){return b!=='ALL OTHERS CAMP';});
  var colors = MSO_COLORS;

  /* Atualizar títulos */
  var titleEl = document.getElementById('mso3-card-title');
  if(titleEl) titleEl.textContent = isVal ? 'VENDA VALOR FYTD · JUL–JUN' : 'UNIDADES FYTD · JUL–JUN';
  var h2El = document.getElementById('mso3-card-h2');
  if(h2El) h2El.textContent = 'Visão consolidada por Marca em ' + (isVal ? 'Valor (R$ MM)' : 'Unidades');
  var subEl = document.getElementById('mso3-card-sub');
  if(subEl) subEl.innerHTML = 'NielsenIQ · Jul/25–Jun/26 · <span id="mso3-mkt-lbl">' + mkt + '</span>';

  /* Helpers */
  function fmtV3(v){
    if(v===null||v===undefined) return '—';
    if(isVal) return v>=1?'R$'+v.toFixed(2)+'MM':'R$'+(v*1000).toFixed(0)+'K';
    return v>=1000?(Math.round(v/1000*10)/10)+'M un':Math.round(v)+'K un';
  }
  function calcDelta3(v25,v26){
    var p=v25>0?Math.round((v26-v25)/v25*1000)/10:0;
    return {str:(p>=0?'+':'')+p.toFixed(1)+'%',col:p>=0?'#34d399':'#ef4444',up:p>=0,raw:p};
  }

  /* Dados FYTD */
  var nbv=(typeof NIELSEN_BRAND_VAL!=='undefined')?NIELSEN_BRAND_VAL[mkt]:null;
  var mt=(typeof FYTD_MARKET_TOTAL!=='undefined')?FYTD_MARKET_TOTAL[mkt]:null;
  var d25={},d26={};
  brands.forEach(function(b){
    if(!nbv||!nbv[b]) return;
    d25[b]=isVal?nbv[b].fytd25_val:nbv[b].fytd25_un;
    d26[b]=isVal?nbv[b].fytd26_val:nbv[b].fytd26_un;
  });
  var totV25=0,totV26=0;
  brands.forEach(function(b){totV25+=d25[b]||0;totV26+=d26[b]||0;});
  totV25=Math.round(totV25*100)/100; totV26=Math.round(totV26*100)/100;

  /* KPI chips */
  var brandsW=brands.filter(function(b){return d26[b]&&d25[b];});
  var topB=brandsW.reduce(function(best,b){return (d26[b]||0)>(d26[best]||0)?b:best;},brandsW[0]||brands[0]);
  var deltas3=brandsW.map(function(b){return {b:b,d:calcDelta3(d25[b]||0,d26[b]||0)};});
  deltas3.sort(function(a,b){return b.d.raw-a.d.raw;});
  var topG3=deltas3[0],topL3=deltas3[deltas3.length-1];
  var totalDt=calcDelta3(totV25,totV26);

  function kpiChip3(borderColor,label,value,valueCss,sub,subCss){
    return '<div style="padding:14px 18px;background:#0D1117;border-top:3px solid '+borderColor+';">'
      +'<div style="font-size:9px;color:#64748b;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:6px;">'+label+'</div>'
      +'<div style="font-size:24px;font-weight:900;'+valueCss+';line-height:1;">'+value+'</div>'
      +'<div style="font-size:10px;'+subCss+';margin-top:5px;">'+sub+'</div>'
      +'</div>';
  }
  var hdEl=document.getElementById('mso3-headline');
  /* SCJ COMBINED share no mercado total */
  var mt26h = mt ? (isVal ? mt.fytd26_val : mt.fytd26_un) : 0;
  var mt25h = mt ? (isVal ? mt.fytd25_val : mt.fytd25_un) : 0;
  var scjShr26 = mt26h > 0 ? Math.round(totV26 / mt26h * 1000) / 10 : 0;
  var scjShr25 = mt25h > 0 ? Math.round(totV25 / mt25h * 1000) / 10 : 0;
  var scjShrDt = Math.round((scjShr26 - scjShr25) * 10) / 10;
  var scjShrCor = scjShrDt >= 0 ? '#34d399' : '#ef4444';
  var scjShrSub = (scjShrDt >= 0 ? '+' : '') + scjShrDt.toFixed(1) + 'pp vs /25';
  /* TOTAL MERCADO para chip do cabecalho */
  var mktDelta3 = mt25h > 0 ? Math.round((mt26h - mt25h) / mt25h * 1000) / 10 : 0;
  var mktDeltaStr3 = (mktDelta3 >= 0 ? '+' : '') + mktDelta3.toFixed(1) + '% vs /25';
  var mktDeltaCor3 = mktDelta3 >= 0 ? '#34d399' : '#ef4444';
  var mktValStr3 = mt26h > 0 ? (isVal ? 'R$'+mt26h.toFixed(2)+'MM' : (mt26h>=1000?(Math.round(mt26h/10)/100)+'M un':Math.round(mt26h)+'K un')) : '—';
  /* HB OFF!+EXPOSIS para chip do cabecalho */
  var hbH26 = Math.round(((d26['OFF!']||0)+(d26['EXPOSIS']||0))*100)/100;
  var hbH25 = Math.round(((d25['OFF!']||0)+(d25['EXPOSIS']||0))*100)/100;
  var hbHDt = calcDelta3(hbH25, hbH26);

  if(hdEl){
    hdEl.innerHTML='<div style="display:grid;grid-template-columns:repeat(5,1fr);border-bottom:0.5px solid rgba(147,187,235,0.30);">'
      +kpiChip3('#fbbf24','TOTAL MERCADO',mktValStr3,'color:#fbbf24',mktDeltaStr3,'color:'+mktDeltaCor3)
      +kpiChip3('#3b82f6','OFF!+EXPOSIS FYTD',fmtV3(hbH26),'color:#3b82f6',hbHDt.str+' vs FYTD /25','color:'+hbHDt.col)
      +kpiChip3(colors[topB]||'#e2e8f0','MAIOR VOLUME',fmtV3(d26[topB]||0),'color:'+(colors[topB]||'#e2e8f0'),topB,'color:#94A3B8')
      +(topG3?kpiChip3(topG3.d.raw>=0?'#34d399':'#f59e0b',topG3.d.raw>=0?'MAIOR CRESCIM.':'MENOR QUEDA',topG3.d.str,'color:'+(topG3.d.raw>=0?'#34d399':'#f59e0b'),topG3.b,'color:#94A3B8'):'')
      +(topL3?kpiChip3('#ef4444','MAIOR QUEDA',topL3.d.str,'color:#ef4444',topL3.b,'color:#94A3B8'):'')
      +'</div>';
  }

  /* TOTAL MERCADO — 2 barras FYTD/25 vs FYTD/26 */
  var mtTotalEl=document.getElementById('mso3-mkt-total');
  if(mtTotalEl){
    var a25=mt?(isVal?mt.fytd25_val:mt.fytd25_un):totV25;
    var a26=mt?(isVal?mt.fytd26_val:mt.fytd26_un):totV26;
    /* calcular delta ANTES do arredondamento (alinha com KPI chip mktDelta3) */
    var dP3=a25>0?Math.round((a26-a25)/a25*1000)/10:0;
    a25=Math.round(a25*100)/100; a26=Math.round(a26*100)/100;
    var dStr3=(dP3>=0?'+':'')+dP3.toFixed(1)+'%';
    var dCor3=dP3>=0?'#34d399':'#ef4444';
    function fmtMkt3(v){return isVal?'R$'+v.toFixed(2)+'MM':(v>=1000?(Math.round(v/1000*10)/10)+'M un':Math.round(v)+'K un');}
    mtTotalEl.innerHTML=
      '<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">TOTAL MERCADO &middot; FYTD JUL&ndash;JUN &middot; '+(isVal?'R$ MM':'Unidades')+'</div>'
      +'<div style="position:relative;height:210px;"><canvas id="mso3-mktotal-canvas"></canvas></div>';
    var prevC=Chart.getChart('mso3-mktotal-canvas'); if(prevC) prevC.destroy();
    var cvMk=document.getElementById('mso3-mktotal-canvas');
    cvMk.removeAttribute('width');cvMk.removeAttribute('height');cvMk.style.width='';cvMk.style.height='';
    new Chart(cvMk,{
      type:'bar',
      data:{labels:['FYTD / 25','FYTD / 26'],datasets:[{data:[a25,a26],
        backgroundColor:['#94A3B8','#3B82F6'],
        borderColor:['#64748B','#1D4ED8'],
        borderWidth:2,borderRadius:5,barPercentage:0.55}]},
      options:{responsive:true,maintainAspectRatio:false,
        layout:{padding:{top:28,right:16,bottom:4,left:16}},
        plugins:{legend:{display:false},
          tooltip:{backgroundColor:'#F0F4FA',titleColor:'#1e293b',bodyColor:'#475569',borderColor:'rgba(59,130,246,0.2)',borderWidth:1,callbacks:{label:function(ctx){return '  Total: '+fmtMkt3(ctx.raw);}}}},
        scales:{
          x:{ticks:{color:'#475569',font:{size:11,weight:'700'}},grid:{display:false},border:{color:'rgba(59,130,246,0.10)'}},
          y:{ticks:{color:'#475569',font:{size:10},callback:function(v){return fmtMkt3(v);}},grid:{color:'rgba(59,130,246,0.08)'},border:{color:'rgba(59,130,246,0.10)'}}}},
      plugins:[{id:'mso3mktdelta',afterDatasetsDraw:function(chart){
        var ctx3=chart.ctx,meta=chart.getDatasetMeta(0);
        meta.data.forEach(function(bar,i){
          var val=i===0?a25:a26;
          ctx3.save();ctx3.fillStyle='#94A3B8';ctx3.font='700 11px system-ui,sans-serif';
          ctx3.textAlign='center';ctx3.fillText(fmtMkt3(val),bar.x,bar.y-8);ctx3.restore();
        });
        var bar26=meta.data[1];
        if(bar26){
          var cY=(bar26.y+bar26.base)/2+5;
          ctx3.save();ctx3.shadowColor='rgba(0,0,0,0)';ctx3.shadowBlur=0;
          ctx3.fillStyle=dCor3;ctx3.font='900 14px system-ui,sans-serif';
          ctx3.textAlign='center';ctx3.fillText(dStr3,bar26.x,cY);ctx3.restore();
        }
      }}]
    });
  }


  /* HB: OFF! + EXPOSIS — 2 barras FYTD/25 vs FYTD/26 */
  var hbTotalEl=document.getElementById('mso3-hb-total');
  if(hbTotalEl){
    var hb25=((d25['OFF!']||0)+(d25['EXPOSIS']||0));
    var hb26=((d26['OFF!']||0)+(d26['EXPOSIS']||0));
    hb25=Math.round(hb25*100)/100; hb26=Math.round(hb26*100)/100;
    var hbDp=hb25>0?Math.round((hb26-hb25)/hb25*1000)/10:0;
    var hbDstr=(hbDp>=0?'+':'')+hbDp.toFixed(1)+'%';
    var hbCor=hbDp>=0?'#34d399':'#ef4444';
    function fmtHb(v){return isVal?'R$'+v.toFixed(2)+'MM':(v>=1000?(Math.round(v/1000*10)/10)+'M un':Math.round(v)+'K un');}
    hbTotalEl.innerHTML=
      '<div style="font-size:8px;font-weight:700;letter-spacing:.11em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">OFF! + EXPOSIS (HB) &middot; FYTD JUL&ndash;JUN &middot; '+(isVal?'R$ MM':'Unidades')+'</div>'
      +'<div style="position:relative;height:210px;"><canvas id="mso3-hb-canvas"></canvas></div>';
    var prevHb=Chart.getChart('mso3-hb-canvas'); if(prevHb) prevHb.destroy();
    var cvHb=document.getElementById('mso3-hb-canvas');
    cvHb.removeAttribute('width');cvHb.removeAttribute('height');cvHb.style.width='';cvHb.style.height='';
    new Chart(cvHb,{
      type:'bar',
      data:{labels:['FYTD / 25','FYTD / 26'],datasets:[{data:[hb25,hb26],
        backgroundColor:['#94A3B8','#3b82f6'],
        borderColor:['#64748B','#1D4ED8'],
        borderWidth:2,borderRadius:5,barPercentage:0.55}]},
      options:{responsive:true,maintainAspectRatio:false,
        layout:{padding:{top:28,right:16,bottom:4,left:16}},
        plugins:{legend:{display:false},
          tooltip:{callbacks:{label:function(ctx){return '  OFF!+EXPOSIS: '+fmtHb(ctx.raw);}}}},
        scales:{
          x:{ticks:{color:'#475569',font:{size:11,weight:'700'}},grid:{display:false},border:{color:'rgba(59,130,246,0.10)'}},
          y:{ticks:{color:'#475569',font:{size:10},callback:function(v){return fmtHb(v);}},grid:{color:'rgba(59,130,246,0.08)'},border:{color:'rgba(59,130,246,0.10)'}}}},
      plugins:[{id:'mso3hbdelta',afterDatasetsDraw:function(chart){
        var ctx4=chart.ctx,meta=chart.getDatasetMeta(0);
        meta.data.forEach(function(bar,i){
          var val=i===0?hb25:hb26;
          ctx4.save();ctx4.fillStyle='#94A3B8';ctx4.font='700 11px system-ui,sans-serif';
          ctx4.textAlign='center';ctx4.fillText(fmtHb(val),bar.x,bar.y-8);ctx4.restore();
        });
        var bar26=meta.data[1];
        if(bar26){
          var cY=(bar26.y+bar26.base)/2+5;
          ctx4.save();ctx4.shadowColor='rgba(0,0,0,0)';ctx4.shadowBlur=0;
          ctx4.fillStyle=hbCor;ctx4.font='900 14px system-ui,sans-serif';
          ctx4.textAlign='center';ctx4.fillText(hbDstr,bar26.x,cY);ctx4.restore();
        }
      }}]
    });
  }

  /* BRAND GROUPED BAR CHART */
  var tableEl=document.getElementById('mso3-table');
  if(tableEl){
    tableEl.style.display='';
    var barTitle3=isVal?'FYTD JUL&ndash;JUN &middot; R$ MM &middot; 2025 vs 2026':'FYTD JUL&ndash;JUN &middot; UNIDADES &middot; 2025 vs 2026';
    tableEl.innerHTML='<div>'
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.13em;color:#64748b;text-transform:uppercase;margin-bottom:10px;">'+barTitle3+'</div>'
      +'<div style="position:relative;height:210px;"><canvas id="mso3-bar-canvas"></canvas></div>'
      +'</div>';
    var prevBC=Chart.getChart('mso3-bar-canvas'); if(prevBC) prevBC.destroy();
    var cvBar=document.getElementById('mso3-bar-canvas');
    cvBar.removeAttribute('width');cvBar.removeAttribute('height');cvBar.style.width='';cvBar.style.height='';
    /* chartBrands3: inclui ALL OTHERS CAMP no gráfico de barras */
    var chartBrands3 = MSO_BRANDS; // todas as marcas, incluindo ALL OTHERS CAMP
    /* Carregar dados de ALL OTHERS CAMP para d25/d26 */
    if(nbv && nbv['ALL OTHERS CAMP']){
      d25['ALL OTHERS CAMP'] = isVal ? nbv['ALL OTHERS CAMP'].fytd25_val : nbv['ALL OTHERS CAMP'].fytd25_un;
      d26['ALL OTHERS CAMP'] = isVal ? nbv['ALL OTHERS CAMP'].fytd26_val : nbv['ALL OTHERS CAMP'].fytd26_un;
    }
    var barLabels3=chartBrands3.map(function(b){return b==='SUPER REPELEX'?'S.REPELEX':(b);});
    var bV25=[],bV26=[],bCols=[],bDs=[],bDstrs=[];
    chartBrands3.forEach(function(b){
      var v25=d25[b]||0,v26=d26[b]||0,cor=colors[b]||'#e2e8f0',dt=calcDelta3(v25,v26);
      bV25.push(v25);bV26.push(v26);bCols.push(cor);bDs.push(dt.raw);bDstrs.push(dt.str);
    });
    new Chart(cvBar,{
      type:'bar',
      data:{labels:barLabels3,datasets:[
        {label:'FYTD/25',data:bV25,backgroundColor:'rgba(148,163,184,0.7)',borderColor:'rgba(148,163,184,0.85)',borderWidth:1,borderRadius:3},
        {label:'FYTD/26',data:bV26,backgroundColor:bCols.map(function(c){return c+'dd';}),borderColor:bCols,borderWidth:1,borderRadius:3}
      ]},
      options:{responsive:true,maintainAspectRatio:false,
        layout:{padding:{top:22,right:8,bottom:4,left:4}},
        plugins:{
          legend:{display:true,position:'top',align:'end',labels:{color:'#475569',font:{size:10},boxWidth:10,padding:12}},
          tooltip:{callbacks:{label:function(ctx){
            var b=chartBrands3[ctx.dataIndex];
            if(ctx.datasetIndex===0) return '  FYTD/25: '+fmtV3(d25[b]||0);
            return '  FYTD/26: '+fmtV3(d26[b]||0)+'   ('+bDstrs[ctx.dataIndex]+' YoY)';
          }}}},
        scales:{
          x:{ticks:{color:'#475569',font:{size:10,weight:'700'}},grid:{display:false},border:{color:'rgba(59,130,246,0.10)'}},
          y:{ticks:{color:'#475569',font:{size:10},callback:function(v){return fmtV3(v);}},grid:{color:'rgba(59,130,246,0.08)'},border:{color:'rgba(59,130,246,0.10)'}}}},
      plugins:[{id:'mso3bardelta',afterDatasetsDraw:function(chart){
        var ctx2=chart.ctx,meta2=chart.getDatasetMeta(1);
        meta2.data.forEach(function(bar,i){
          var str=bDstrs[i]; if(!str) return;
          var d=bDs[i],col=d>=0?'#34d399':'#ef4444';
          ctx2.save();ctx2.fillStyle=col;ctx2.font='700 10px system-ui,sans-serif';
          ctx2.textAlign='center';ctx2.fillText(str,bar.x,bar.y-6);ctx2.restore();
        });
      }}]
    });
  }

  /* DIAGNOSTICO ENRIQUECIDO */
  var insightEl=document.getElementById('mso3-insight');
  if(insightEl&&nbv){
    /* Totais do mercado real (todas as marcas) */
    var mt25d=mt?(isVal?mt.fytd25_val:mt.fytd25_un):totV25;
    var mt26d=mt?(isVal?mt.fytd26_val:mt.fytd26_un):totV26;
    mt25d=Math.round(mt25d*100)/100; mt26d=Math.round(mt26d*100)/100;
    var scj25d=Math.round(totV25*100)/100, scj26d=Math.round(totV26*100)/100;
    /* Deltas */
    var mtDelta=mt25d>0?Math.round((mt26d-mt25d)/mt25d*1000)/10:0;
    var scjDelta=scj25d>0?Math.round((scj26d-scj25d)/scj25d*1000)/10:0;
    var mtCor=mtDelta>=0?'#34d399':'#ef4444';
    var scjCor=scjDelta>=0?'#34d399':'#ef4444';
    /* Share SCJ no mercado total */
    var shr26d=mt26d>0?Math.round(scj26d/mt26d*1000)/10:0;
    var shr25d=mt25d>0?Math.round(scj25d/mt25d*1000)/10:0;
    var shrDelta=Math.round((shr26d-shr25d)*10)/10;
    var shrCor=shrDelta>=0?'#34d399':'#ef4444';
    /* Performance SCJ vs Mercado */
    var vsMarket=Math.round((scjDelta-mtDelta)*10)/10;
    var vsCor=vsMarket>=0?'#34d399':'#ef4444';
    var vsLabel=vsMarket>0.5?'SCJ superou o mercado':vsMarket<-0.5?'SCJ ficou abaixo do mercado':'SCJ acompanhou o mercado';
    var unitLbl=isVal?'R$ MM':'Mil Un';
    /* HB OFF!+EXPOSIS — variaveis para bloco diagnostico */
    var hb25d=Math.round(((d25['OFF!']||0)+(d25['EXPOSIS']||0))*100)/100;
    var hb26d=Math.round(((d26['OFF!']||0)+(d26['EXPOSIS']||0))*100)/100;
    var hbDeltaD=hb25d>0?Math.round((hb26d-hb25d)/hb25d*1000)/10:0;
    var hbCorD=hbDeltaD>=0?'#34d399':'#ef4444';
    var shrHb26=mt26d>0?Math.round(hb26d/mt26d*1000)/10:0;
    var shrHb25=mt25d>0?Math.round(hb25d/mt25d*1000)/10:0;
    var shrHbDelta=Math.round((shrHb26-shrHb25)*10)/10;
    var shrHbCor=shrHbDelta>=0?'#34d399':'#ef4444';
    var vsHb=Math.round((hbDeltaD-mtDelta)*10)/10;
    var vsHbCor=vsHb>=0?'#34d399':'#ef4444';
    var vsHbLabel=vsHb>0.5?'HB superou o mercado':vsHb<-0.5?'HB ficou abaixo do mercado':'HB acompanhou o mercado';
    /* Linha por marca com share no mercado */
    var lines3=MSO_BRANDS.map(function(b){
      var bd=nbv[b]; if(!bd) return null;
      var cor=colors[b]||'#e2e8f0';
      var v25=isVal?bd.fytd25_val:bd.fytd25_un, v26=isVal?bd.fytd26_val:bd.fytd26_un;
      var pct=v25>0?Math.round((v26-v25)/v25*1000)/10:0;
      var cc=pct>=0?'#34d399':'#ef4444';
      var trend=pct>2?'&#8599;':(pct<-2?'&#8600;':'&#8594;');
      var shrB=mt26d>0?Math.round(v26/mt26d*1000)/10:0;
      return '<div style="display:flex;align-items:center;gap:5px;padding:3px 0;border-bottom:0.5px solid rgba(147,187,235,0.25);">'
        +'<span style="width:5px;height:5px;border-radius:50%;background:'+cor+';flex-shrink:0;"></span>'
        +'<span style="color:'+cor+';font-weight:700;min-width:95px;font-size:11px;">'+b+'</span>'
        +'<span style="color:#e2e8f0;font-size:11px;">FYTD/26: <strong>'+fmtV3(v26)+'</strong></span>'
        +'<span style="color:#475569;margin:0 3px;">·</span>'
        +'<span style="color:#64748b;font-size:11px;">FYTD/25: '+fmtV3(v25)+'</span>'
        +'<span style="color:'+cc+';font-weight:700;font-size:11px;margin-left:5px;">'
          +'<span style="font-size:10px;">'+trend+'</span> '+(pct>=0?'+':'')+pct.toFixed(1)+'%'
        +'</span>'
        +'<span style="color:#334155;font-size:10px;margin-left:auto;background:rgba(45,90,142,0.08);padding:1px 5px;border-radius:3px;">shr '+shrB.toFixed(1)+'%</span>'
        +'</div>';
    }).filter(Boolean);
    insightEl.innerHTML=
      '<div style="padding:10px 4px;">'
      /* Titulo */
      +'<div style="font-size:9px;font-weight:700;letter-spacing:.14em;color:#1D6FA8;text-transform:uppercase;margin-bottom:12px;">&#128202; DIAGNOSTICO &middot; '+mkt+' &middot; '+unitLbl+' FYTD JUL&ndash;JUN/26</div>'
      /* Bloco 1: Mercado Total */
      +'<div style="margin-bottom:10px;padding-bottom:9px;border-bottom:0.5px solid rgba(147,187,235,0.30);">'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:5px;">&#127758; Mercado Total (todas as marcas)</div>'
        +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
          +'<span style="font-size:11px;color:#94a3b8;">FYTD/25: <strong style="color:#e2e8f0;">'+fmtV3(mt25d)+'</strong></span>'
          +'<span style="color:#334155;">&#8594;</span>'
          +'<span style="font-size:11px;color:#94a3b8;">FYTD/26: <strong style="color:#e2e8f0;">'+fmtV3(mt26d)+'</strong></span>'
          +'<span style="background:'+mtCor+'1a;color:'+mtCor+';font-weight:700;font-size:11px;padding:2px 8px;border-radius:4px;border:0.5px solid '+mtCor+'44;">'
            +(mtDelta>=0?'&#9650; +':'&#9660; ')+Math.abs(mtDelta).toFixed(1)+'%'
          +'</span>'
        +'</div>'
      +'</div>'
      /* Bloco 2: SCJ vs Mercado */
      +'<div style="margin-bottom:10px;padding-bottom:9px;border-bottom:0.5px solid rgba(147,187,235,0.30);">'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:5px;">&#128293; OFF! + EXPOSIS (HB) &middot; FYTD JUL&ndash;JUN &middot; '+unitLbl+'</div>'
        +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;">'
          +'<span style="font-size:11px;color:#94a3b8;">FYTD/25: <strong style="color:#3b82f6;">'+fmtV3(hb25d)+'</strong></span>'
          +'<span style="color:#334155;">&#8594;</span>'
          +'<span style="font-size:11px;color:#94a3b8;">FYTD/26: <strong style="color:#3b82f6;">'+fmtV3(hb26d)+'</strong></span>'
          +'<span style="background:'+hbCorD+'1a;color:'+hbCorD+';font-weight:700;font-size:11px;padding:2px 8px;border-radius:4px;border:0.5px solid '+hbCorD+'44;">'
            +(hbDeltaD>=0?'&#9650; +':'&#9660; ')+Math.abs(hbDeltaD).toFixed(1)+'%'
          +'</span>'
        +'</div>'
        +'<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:5px;">'
          +'<span style="font-size:11px;color:#64748b;">Share FYTD/25: <strong style="color:#cbd5e1;">'+shrHb25.toFixed(1)+'%</strong></span>'
          +'<span style="color:#1e293b;">|</span>'
          +'<span style="font-size:11px;color:#64748b;">Share FYTD/26: <strong style="color:#3b82f6;">'+shrHb26.toFixed(1)+'%</strong></span>'
          +'<span style="color:'+shrHbCor+';font-weight:700;font-size:11px;">'
            +(shrHbDelta>=0?'&#9650; +':'&#9660; ')+Math.abs(shrHbDelta).toFixed(1)+'pp'
          +'</span>'
        +'</div>'
              +'</div>'
      /* Bloco 3: Por Marca */
      +'<div>'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:.1em;color:#475569;text-transform:uppercase;margin-bottom:6px;">&#128200; Por Marca &middot; participacao no mercado total</div>'
        +'<div style="font-size:11px;color:#D1D5DB;">'+lines3.join('')+'</div>'
      +'</div>'
      +'</div>';
  }
}

/* ═══════════ END MSO3 ═══════════ */

// ── Avg Price: pricing trend insight ──
function renderAvgInsight(){
  var el = document.getElementById('avg-insight');
  if(!el) return;
  var _avgSel = document.getElementById('avgMarketSel');
  var mktLabel = (_avgSel && _avgSel.selectedIndex >= 0) ? _avgSel.options[_avgSel.selectedIndex].text : avgMarket;
  var d = AVG_DATA[avgMarket] || AVG_DATA['farmasul'];
  if(!d) return;
  var diagLabel = mktLabel;
  var meses = (typeof AVG_MESES !== 'undefined') ? AVG_MESES : [];
  var produtos = Object.keys(d);
  var lines = [];
  var recentFalling = 0;
  var lblFirst = meses[0] || 'Jul/25';
  var lblLast  = meses[meses.length-1] || 'Abr/26';
  produtos.forEach(function(p){
    var vals = d[p].filter(Boolean);
    if(!vals.length) return;
    var first = vals[0], last = vals[vals.length-1];
    var trend = Math.round((last-first)/first*100);
    /* Tendencia recente: ultimos 3 meses vs 3 anteriores */
    var rLen = Math.min(3, Math.floor(vals.length/2));
    var recAvg = vals.slice(-rLen).reduce(function(a,b){return a+b;},0)/rLen;
    var priAvg = vals.slice(-rLen*2,-rLen).reduce(function(a,b){return a+b;},0)/rLen;
    var recTrend = priAvg>0 ? Math.round((recAvg-priAvg)/priAvg*100) : 0;
    if(recTrend < -5) recentFalling++;
    var col  = trend>=0?'#34d399':'#ef4444';
    var rCol = recTrend>0?'#34d399':recTrend<-5?'#ef4444':'#fbbf24';
    var rArrow = recTrend>0?'↑':recTrend<0?'↓':'→';
    lines.push('• <strong style="color:#1e293b;">'+p+'</strong>'
      +'<span style="color:#64748b;"> '+lblFirst+':</span> R$'+first.toFixed(2)
      +' → <span style="color:#64748b;">'+lblLast+':</span> <strong style="color:'+col+';">R$'+last.toFixed(2)+'</strong> <span style="color:'+col+';">'+(trend>=0?'+':'')+trend+'%</span>'
      +'  <span style="color:'+rCol+';font-size:9px;">recente: '+rArrow+(recTrend>=0?'+':'')+recTrend+'%</span>');
  });
  var summary = recentFalling>1
    ? '⚠️ <strong style="color:#fbbf24;">'+recentFalling+' produtos com tendência recente de queda</strong> em <strong style="color:#1e293b;">'+diagLabel+'</strong>.'
    : recentFalling===1
    ? '⚠️ <strong style="color:#fbbf24;">1 produto com tendência recente de queda</strong> em <strong style="color:#1e293b;">'+diagLabel+'</strong>.'
    : '✅ Tendência recente estável/alta em <strong style="color:#1e293b;">'+diagLabel+'</strong>.';
  el.innerHTML = '<strong style="color:#1D6FA8;font-size:10px;letter-spacing:0.08em;">📊 DIAGNÓSTICO PREÇO MÉDIO · '+diagLabel+'</strong>'
    +'<br><span style="color:#64748b;font-size:9px;">Referência: '+lblFirst+' (início da série) → '+lblLast+' (atual) · Recente = últ 3 meses vs 3 ant.</span>'
    +'<br>'+summary+'<br>'+lines.join('<br>');
}
