var nielsenMarket = 'farmasul';
var nielsenLineChart = null;

var nielsenCompModo = 'fytd26';
var nielsenFytdChart = null;
var nielsenCompChart = null;

/* ── BUG FIX: guard contra múltiplas chamadas simultâneas ──────────
   CAUSA RAIZ: ao abrir arquivo salvo, initNielsenCharts() era chamada
   3 vezes em sequência rápida:
     1) window.load (~400ms)
     2) override: detecção do painel ativo (500ms)
     3) override: chamada incondicional extra (800ms)
   Os setTimeout aninhados (150ms + 300ms) se sobrepunham, cada render
   destruindo o gráfico do anterior → Nielsen ficava em branco.
   SOLUÇÃO: número de série (_nielsenInitSeq) — apenas a ÚLTIMA chamada
   executa; todas as anteriores cancelam ao verificar o seq.         */
var _nielsenInitSeq = 0;
function initNielsenCharts(){
  var _mySeq = ++_nielsenInitSeq;
  console.log('[Nielsen] initNielsenCharts chamada seq=' + _mySeq);
  setTimeout(function(){
    if(_mySeq !== _nielsenInitSeq){
      console.log('[Nielsen] seq=' + _mySeq + ' supersedida por seq=' + _nielsenInitSeq + ' — cancelada');
      return; // chamada mais recente já está rodando — abortar esta
    }
    console.log('[Nielsen] renderizando gráficos seq=' + _mySeq);
    setAvgMarket('tbr_farma');
    renderMSO();
    setVendaOffMarket('T.BR Farma');
    setTimeout(function(){
      if(_mySeq !== _nielsenInitSeq) return; // supersedida — abortar
      renderMSOArea();
      setTimeout(function(){
        if(_mySeq !== _nielsenInitSeq) return;
        renderAvgInsight();
        renderEletricosCard();
        console.log('[Nielsen] renderização completa seq=' + _mySeq);
      }, 200);
    }, 300);
  }, 150);
}

