function renderEletricosCard(){
  var sel = document.getElementById('eletMarketSel');
  var mkt = (sel ? sel.value : null) || 'T.BR Farma';
  var d = ELET_MKT_DATA[mkt];
  if(!d) return;
  var _E26 = nqIsOld(mkt) || (typeof NQ_FY!=='undefined'&&NQ_FY==='FY26');
  var _ER = !nqIsOld(mkt) && typeof NQ_FY!=='undefined' && NQ_FY==='ROLL';
  var _EC = !nqIsOld(mkt) && typeof NQ_FY!=='undefined' && NQ_FY==='CAL';
  var _E = _E26 ? {p:'FY25',c:'FY26'} : (_EC ? {p:nqCalP().perP,c:nqCalP().perC} : (_ER ? {p:'12M ant.',c:'Últ. 12M'} : {p:'FYTD26',c:'FYTD27'}));
  (function(o){ var s=function(id,t){var e=document.getElementById(id); if(e) e.textContent=t;};
    s('elet-mk-lbl', o?'MERCADO ELÉTRICO LÍQUIDO — FYTD Jul–Jun · R$MM':(_EC?'MERCADO ELÉTRICO LÍQUIDO — '+nqCalP().perC.toUpperCase()+' · R$MM':(_ER?'MERCADO ELÉTRICO LÍQUIDO — ÚLTIMOS 12 MESES · R$MM':'MERCADO ELÉTRICO LÍQUIDO — FYTD Jul–Out · R$MM'))); s('elet-mk-p',_E.p); s('elet-mk-c',_E.c);
    s('elet-mkm-lbl', o?'EVOLUÇÃO MENSAL MERCADO — R$MM · FY26':'EVOLUÇÃO MENSAL MERCADO — R$MM · Nov/25–Out/26'); s('elet-bar-lbl', _E.p+' vs '+_E.c);
    s('elet-evol-lbl', o?'EVOLUÇÃO MENSAL — Jul/25 a Jun/26':'EVOLUÇÃO MENSAL — Nov/25 a Out/26'); })(_E26);
  var _et=document.getElementById('elet-card-title'); if(_et) _et.textContent = nqIsOld(mkt) ? '$ Share por Fabricante — FY25 vs FY26 · base anterior' : (_E26 ? '$ Share por Fabricante — FY25 vs FY26 (Jul–Jun)' : _EC ? '$ Share por Fabricante — '+nqCalP().perP+' vs '+nqCalP().perC+' (ano-calendário)' : (_ER ? '$ Share por Fabricante — 12M ant. vs Últ. 12M ('+nqL12().perC+')' : '$ Share por Fabricante — FYTD26 vs FYTD27 (Jul–Out)'));

  // ── Headline ──
  var hl = document.getElementById('elet-headline');
  if(hl){
    var scjD = d.fytd26[0] - d.fytd25[0], rkD = d.fytd26[3] - d.fytd25[3];
    var scjCol = scjD>=0?'#34d399':'#ef4444', rkCol = rkD>=0?'#34d399':'#ef4444';
    var scjSign = scjD>=0?'▲':'▼', rkSign = rkD>=0?'▲':'▼';
    hl.innerHTML = '<strong style="color:#e2e8f0;">'+mkt+'</strong>'
      +' &nbsp;·&nbsp; SCJ <span style="color:'+scjCol+';font-weight:700;">'+scjSign+Math.abs(scjD).toFixed(2)+'pp</span>'
      +' &nbsp;|&nbsp; RECKITT <span style="color:'+rkCol+';font-weight:700;">'+rkSign+Math.abs(rkD).toFixed(2)+'pp</span>'
      +' &nbsp;|&nbsp; SCJ: <span style="color:#fbbf24;font-weight:700;">'+d.fytd26[0].toFixed(2)+'%</span>'
      +' <span style="color:'+scjCol+';font-size:11px;">'+scjSign+Math.abs(scjD).toFixed(2)+'pp vs '+_E.p+'</span>'
      +(nqIsOld(mkt)?' &nbsp;|&nbsp; SBP migrou <span style="color:#fbbf24;font-weight:600;">35ML→32.9ML</span>':'');
  }

  // ── Label & sub ──
  var lbl = document.getElementById('elet-mkt-label');
  if(lbl) lbl.textContent = '⚡ REPELENTES ELÉTRICOS — '+d.label;
  var sub = document.getElementById('elet-mkt-sub');
  if(sub) sub.textContent = d.sub;

  // ── KPI chips ──
  var kpis = document.getElementById('elet-kpis');
  if(kpis){
    var chipLabels = ['SC JOHNSON','EXPOSIS','RAID (SCJ)','RECKITT','SBP (Reckitt)'];
    kpis.innerHTML = d.brands.map(function(b,i){
      var v26=d.fytd26[i], v25=d.fytd25[i], delta=v26-v25;
      var col=d.colors[i];
      var dCol=delta>=0?'#34d399':'#ef4444', dSign=delta>=0?'▲':'▼';
      return '<div style="background:#161B22;border-radius:10px;padding:12px 14px;">'
        +'<div style="font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d6b63;margin-bottom:6px;">'+chipLabels[i]+'</div>'
        +'<div style="display:flex;align-items:baseline;gap:6px;">'
        +'<span style="font-size:22px;font-weight:800;color:'+col+';line-height:1;">'+v26.toFixed(2)+'%</span>'
        +'<span style="font-size:10px;font-weight:700;color:'+dCol+';">'+dSign+Math.abs(delta).toFixed(2)+'pp</span>'
        +'</div>'
        +'<div style="font-size:10px;color:#94A3B8;margin-top:3px;">'+_E.p+': '+v25.toFixed(2)+'%</div>'
        +'</div>';
    }).join('');
  }

  // ── Mercado Elétrico FYTD ──
  if(d.mkt_fy25 !== undefined){
    var fmtMM = function(v){ return v >= 1000 ? 'R$'+(v/1000).toFixed(2)+'B' : 'R$'+v.toFixed(2)+'MM'; };
    var v25 = d.mkt_fy25, v26 = d.mkt_fy26;
    var pct = v25 > 0 ? ((v26-v25)/v25*100) : 0;
    var pctCol = pct >= 0 ? '#34d399' : '#ef4444';
    var el25 = document.getElementById('elet-mkt-val25');
    var el26 = document.getElementById('elet-mkt-val26');
    var elD  = document.getElementById('elet-mkt-delta');
    var elArr= document.getElementById('elet-mkt-arrow');
    if(el25) el25.textContent = fmtMM(v25);
    if(el26) el26.textContent = fmtMM(v26);
    if(elD)  elD.innerHTML = '<span style="color:'+pctCol+';font-weight:800;">'+(pct>=0?'+':'')+pct.toFixed(1)+'%</span>';
    if(elArr) elArr.style.color = pctCol;

    // Mini barra comparativa
    var mbCtx = document.getElementById('elet-mkt-bar');
    if(mbCtx){
      if(mbCtx._ch){ try{mbCtx._ch.destroy();}catch(e){} }
      var maxV = Math.max(v25, v26) * 1.15;
      mbCtx._ch = new Chart(mbCtx, {
        type:'bar',
        data:{
          labels:[_E.p,_E.c],
          datasets:[{
            data:[v25, v26],
            backgroundColor:['rgba(107,114,128,0.4)', pct>=0?'rgba(251,191,36,0.7)':'rgba(239,68,68,0.7)'],
            borderColor:['rgba(107,114,128,0.6)', pct>=0?'#fbbf24':'#ef4444'],
            borderWidth:1, borderRadius:4
          }]
        },
        options:{
          responsive:true, maintainAspectRatio:false,
          plugins:{legend:{display:false}, tooltip:{callbacks:{label:function(c){return fmtMM(c.parsed.y);}}}},
          scales:{
            x:{grid:{display:false}, ticks:{color:'#6B7280',font:{size:10}}},
            y:{display:false, suggestedMax:maxV}
          }
        }
      });
    }

    // Mini linha mensal do mercado
    var mlCtx = document.getElementById('elet-mkt-line');
    if(mlCtx && d.mkt_monthly){
      if(mlCtx._ch){ try{mlCtx._ch.destroy();}catch(e){} }
      mlCtx._ch = new Chart(mlCtx, {
        type:'line',
        data:{
          labels:(_E26?['Jul','Ago','Set','Out','Nov','Dez','Jan','Fev','Mar','Abr','Mai','Jun']:NQ_ROLL_LABELS),
          datasets:[{
            data: d.mkt_monthly,
            borderColor:'#fbbf24', backgroundColor:'rgba(251,191,36,0.06)',
            borderWidth:2, pointRadius:3, pointBackgroundColor:'#fbbf24',
            tension:0.35, spanGaps:false, fill:true
          }]
        },
        options:{
          responsive:true, maintainAspectRatio:false,
          plugins:{legend:{display:false}, tooltip:{callbacks:{label:function(c){return c.parsed.y!==null?fmtMM(c.parsed.y):'—';}}}},
          scales:{
            x:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:9}}},
            y:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:9},callback:function(v){return 'R$'+v+'MM';}}, suggestedMin:0}
          }
        }
      });
    }
  }

  // ── Bar chart: FYTD25 vs FYTD26 ──
  var bCtx = document.getElementById('elet-bar-chart');
  if(bCtx){
    if(bCtx._ch){ try{bCtx._ch.destroy();}catch(e){} }
    var bgColors = d.colors.map(function(c){ return c+'B3'; });
    bCtx._ch = new Chart(bCtx, {
      type:'bar',
      data:{
        labels: d.brands,
        datasets:[
          { label:_E.p, data:d.fytd25, backgroundColor:'rgba(148,163,184,0.22)', borderColor:'rgba(148,163,184,0.4)', borderWidth:1, borderRadius:3 },
          { label:_E.c, data:d.fytd26, backgroundColor:bgColors, borderColor:d.colors, borderWidth:1, borderRadius:3 }
        ]
      },
      options:{
        responsive:true, maintainAspectRatio:false,
        plugins:{ legend:{display:false}, tooltip:{callbacks:{label:function(c){return c.dataset.label+': '+c.parsed.y.toFixed(2)+'%';}}} },
        scales:{
          x:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:10}}},
          y:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:10},callback:function(v){return v+'%';}}, suggestedMin:0}
        }
      }
    });
  }

  // ── Line chart: evolução mensal FY26 ──
  var lCtx = document.getElementById('elet-line-chart');
  if(!lCtx) return;
  if(lCtx._ch){ try{lCtx._ch.destroy();}catch(e){} }
  var labels = _E26 ? ['Jul/25','Ago/25','Set/25','Out/25','Nov/25','Dez/25','Jan/26','Fev/26','Mar/26','Abr/26','Mai/26','Jun/26'] : NQ_ROLL_LABELS;
  var datasets = d.brands.map(function(b,i){
    return { label:b, data:d.monthly[i], borderColor:d.colors[i],
             backgroundColor:d.colors[i].replace('#','rgba(').replace(/^rgba\((..)(..)(..)$/, function(_,r,g,bl){
               return 'rgba('+parseInt(r,16)+','+parseInt(g,16)+','+parseInt(bl,16)+',0.05)';
             }),
             borderWidth:2.5, pointRadius:3, pointBackgroundColor:d.colors[i], tension:0.35, spanGaps:false };
  });
  lCtx._ch = new Chart(lCtx, {
    type:'line',
    data:{ labels:labels, datasets:datasets },
    options:{
      responsive:true, maintainAspectRatio:false,
      plugins:{legend:{display:false}, tooltip:{callbacks:{label:function(c){return c.dataset.label+': '+(c.parsed.y!==null?c.parsed.y.toFixed(2)+'%':'—');}}}},
      scales:{
        x:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:10}}},
        y:{grid:{color:'rgba(255,255,255,0.04)'}, ticks:{color:'#6B7280',font:{size:10},callback:function(v){return v.toFixed(1)+'%';}}, suggestedMin:0}
      }
    }
  });

  // ── Legenda inline ──
  var legEl = document.getElementById('elet-legend');
  if(legEl){
    legEl.innerHTML = d.brands.map(function(b,i){
      return '<span style="display:flex;align-items:center;gap:4px;font-size:10px;color:#D1D5DB;">'
        +'<span style="width:16px;height:2px;background:'+d.colors[i]+';display:inline-block;border-radius:1px;"></span>'+b+'</span>';
    }).join('');
  }

  // ── Diagnóstico ──
  var diagEl = document.getElementById('elet-diag');
  if(diagEl){
    var NAMES = ['SCJ','EXPOSIS','RAID','RECKITT','SBP'];
    var COLS  = d.colors;
    function pp(val){ return (val>=0?'▲':'▼')+Math.abs(val).toFixed(2)+'pp'; }
    function colored(val,pos){ return '<b style="color:'+(val>=0?'#34d399':'#ef4444')+';">'+pp(val)+'</b>'; }

    var scjD=d.fytd26[0]-d.fytd25[0], rkD=d.fytd26[3]-d.fytd25[3];
    var expD=d.fytd26[1]-d.fytd25[1], raD=d.fytd26[2]-d.fytd25[2], sbpD=d.fytd26[4]-d.fytd25[4];

    // Tendência no último mês vs início
    var mon = d.monthly;
    var lastI = -1;
    for(var x=mon[0].length-1;x>=0;x--){ if(mon[0][x]!==null){ lastI=x; break; } }
    var scjTrend = lastI>0 ? mon[0][lastI]-mon[0][0] : null;

    // Narrativa
    var lines = [];

    // Linha 1 — SCJ
    lines.push('📊 <b style="color:#fbbf24;">SCJ</b> '+(_E26?'fechou FY26':(_EC?'ficou em '+nqCalP().perC:_ER?'ficou nos últimos 12 meses ('+nqL12().perC+')':'está no FYTD27 (Jul–Out/26)'))+' com <b style="color:'+COLS[0]+';">'+d.fytd26[0].toFixed(2)+'%</b> de share no mercado Elétrico em <b>'+mkt+'</b> '+colored(scjD)+' vs '+_E.p+' (era '+d.fytd25[0].toFixed(2)+'%).');

    // Linha 2 — RECKITT
    lines.push('🔴 <b style="color:#f87171;">RECKITT</b> terminou em <b style="color:'+COLS[3]+';">'+d.fytd26[3].toFixed(2)+'%</b> '+colored(rkD)+'.');

    // Linha 3 — Marcas
    lines.push('&nbsp;&nbsp;&nbsp;&nbsp;EXPOSIS <b style="color:'+COLS[1]+';">'+d.fytd26[1].toFixed(2)+'%</b> '+colored(expD)
      +' &nbsp;·&nbsp; RAID <b style="color:'+COLS[2]+';">'+d.fytd26[2].toFixed(2)+'%</b> '+colored(raD)
      +' &nbsp;·&nbsp; SBP <b style="color:'+COLS[4]+';">'+d.fytd26[4].toFixed(2)+'%</b> '+colored(sbpD)+'.');

    // Linha 4 — Interpretação estratégica
    if(scjD>0 && rkD<0)       lines.push('✅ SCJ ganhou share às custas de RECKITT — posicionamento favorável em '+mkt+'.');
    else if(scjD<0 && rkD>0)  lines.push('⚠️ RECKITT avançou sobre SCJ em '+mkt+' — atenção à pressão competitiva.');
    else if(scjD>0 && rkD>0)  lines.push('📈 Ambos SCJ e RECKITT cresceram — ganho conjunto sobre outras marcas/canais em '+mkt+'.');
    else if(scjD<0 && rkD<0)  lines.push('📉 SCJ e RECKITT perderam share simultaneamente em '+mkt+' — possível entrada de novos players ou canal.');

    // Linha 5 — Tendência mensal
    if(scjTrend!==null){
      var tDir = scjTrend>=0?'crescente':'decrescente';
      var tCol = scjTrend>=0?'#34d399':'#ef4444';
      lines.push('📉 Tendência mensal SCJ em '+mkt+': <b style="color:'+tCol+';">'+tDir+'</b> ('+labels[0]+'→'+labels[lastI]+': '+(scjTrend>=0?'+':'')+scjTrend.toFixed(2)+'pp).');
    }

    diagEl.innerHTML = lines.join('<br>');
    diagEl.style.display = 'block';
  }
}

function eletSetMarket(){
  renderEletricosCard();
}

function eletSetEmb(){
  var v = (document.getElementById('eletEmbSel')||{}).value || 'todos';
  var scjCol  = document.getElementById('elet-emb-scj');
  var rkCol   = document.getElementById('elet-emb-reckitt');
  var grid    = scjCol && scjCol.parentElement;
  if(!scjCol || !rkCol) return;
  if(v==='scj'){
    scjCol.style.display=''; rkCol.style.display='none';
    if(grid) grid.style.gridTemplateColumns='1fr';
  } else if(v==='reckitt'){
    scjCol.style.display='none'; rkCol.style.display='';
    if(grid) grid.style.gridTemplateColumns='1fr';
  } else {
    scjCol.style.display=''; rkCol.style.display='';
    if(grid) grid.style.gridTemplateColumns='1fr 1fr';
  }
}

