function setSJCEstoqueView(v, btn){
  ['barras','linha','tend','cobertura'].forEach(function(id){
    var el = document.getElementById('sjc-estoque-'+id);
    if(el) el.style.display = 'none';
  });
  var el = document.getElementById('sjc-estoque-'+v);
  if(el) el.style.display = '';
  if(btn){
    btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){ b.classList.remove('active','blue'); });
    btn.classList.add('active','blue');
  }
  if(v==='barras') renderSJCEstoqueBarras();
  if(v==='linha')  renderSJCEstoqueLinha();
  if(v==='cobertura') renderSJCCobertura();
}

var sjcEdMode = 'rec';
var sjcRankMode2 = 'rec';

function setSJCEdMode(mode, btn){
  sjcEdMode = mode;
  document.querySelectorAll('[onclick*="setSJCEdMode"]').forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn) btn.classList.add('active','blue');
  renderSJCEdBars();
}

function renderSJCEdBars(){
  var isVol = sjcEdMode === 'vol';
  renderBars('sjc-ed-bars', SJC_RANK.map(function(r){
    return {nome:r.nome, val:isVol?r.vol:r.rec, color:r.color,
      extraFields:[{label:'Volume: ',val:r.vol.toLocaleString('pt-BR')+' un'},{label:'Receita: ',val:fmtNum(r.rec)}]};
  }), {isVol:isVol});
}

function setSJCRankMode2(mode, btn){
  sjcRankMode2 = mode;
  document.querySelectorAll('[onclick*="setSJCRankMode2"]').forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn) btn.classList.add('active','blue');
  renderSJCRank2();
}

function renderSJCRank2(){
  var isVol = sjcRankMode2 === 'vol';
  renderBars('sjc-rank-bars2', SJC_RANK.map(function(r){
    return {nome:r.nome, val:isVol?r.vol:r.rec, color:r.color,
      extraFields:[{label:'Volume: ',val:r.vol.toLocaleString('pt-BR')+' un'},{label:'Receita: ',val:fmtNum(r.rec)}]};
  }), {isVol:isVol});
}

var sjcBarMode = 'vol';
var sjcMetaMetric = 'rec';

function setSJCBarMode(mode, btn){
  sjcBarMode = mode;
  var btns = document.querySelectorAll('[onclick*="setSJCBarMode"]');
  btns.forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn){ btn.classList.add('active','blue'); }
  renderSJCAnoBars();
}

function renderSJCAnoBars(){
  var isVol = sjcBarMode === 'vol';
  var sum = function(arr){ return arr.reduce(function(s,v){ return s+(v||0); }, 0); };
  var vals = isVol
    ? [sum(SJC_VOL_24), sum(SJC_VOL), sum(SJC_VOL_26)]
    : [sum(SJC_REC_24), sum(SJC_REC), sum(SJC_REC_26)];
  renderAnoChart('sjc-ano-chart', ['2024','2025','2026*'], vals, isVol);
}

function setSJCMetaMetric(mode, btn){
  sjcMetaMetric = mode;
  var btns = document.querySelectorAll('[onclick*="setSJCMetaMetric"]');
  btns.forEach(function(b){ b.classList.remove('active','blue'); });
  if(btn){ btn.classList.add('active','blue'); }
  renderSJCMeta();
}

function renderSJCMeta(){
  var isVol = sjcMetaMetric === 'vol';
  var r24 = isVol ? SJC_VOL_24 : SJC_REC_24;
  var r25 = isVol ? SJC_VOL    : SJC_REC;
  var r26 = isVol ? SJC_VOL_26 : SJC_REC_26;
  renderMetaTable('sjc-meta-wrap', MESES, r24, r25, r26, isVol);
}

function renderSJCEstoqueBarras(){
  var el = document.getElementById('sjc-estoque-bars');
  if(!el) return;
  var data = SJC_ESTOQUE;
  var totalEst = data.reduce(function(s,d){return s+d.estoque;},0);
  var totalGiro= data.reduce(function(s,d){return s+d.giro;},0);
  var nAt   = data.filter(function(d){return d.risco==='atencao';}).length;
  var nCrit = data.filter(function(d){return d.risco==='critico';}).length;
  var kEst  = document.getElementById('sjc-kpi-est');   if(kEst)  kEst.textContent  = totalEst.toLocaleString('pt-BR');
  var kGiro = document.getElementById('sjc-kpi-giro');  if(kGiro) kGiro.textContent = totalGiro.toLocaleString('pt-BR');
  var kAt   = document.getElementById('sjc-kpi-at');    if(kAt)   kAt.textContent   = nAt;
  var kCrit = document.getElementById('sjc-kpi-crit');  if(kCrit) kCrit.textContent = nCrit;
  var kSkus = document.getElementById('sjc-kpi-skus');  if(kSkus) kSkus.textContent = data.length+' SKUs ativos';
  var kAtSub= document.getElementById('sjc-kpi-at-sub');if(kAtSub)kAtSub.textContent= nAt>0?nAt+' SKU(s) entre 15–30d':'Todos OK';
  var dias  = totalGiro > 0 ? Math.round(totalEst / totalGiro * 30) : 0;
  var kDias = document.getElementById('sjc-kpi-dias'); if(kDias) kDias.textContent = dias;
  var maxEst = Math.max.apply(null, data.map(function(d){return d.estoque;}));
  var h = '';
  data.forEach(function(d){
    var cor = d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';
    var bg  = d.risco==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
              d.risco==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = Math.min(100,Math.round(d.estoque/maxEst*100));
    var cobStr = d.cob>=999?'S/Giro':d.cob+'d';
    var alerta = d.risco!=='ok'?'<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:6px;">'+(d.risco==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>':'';
    h += '<div style="padding:8px 10px;border-radius:6px;margin-bottom:4px;'+bg+'">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">'
        +'<span style="font-size:11px;color:#1e293b;font-weight:600;overflow:hidden;text-overflow:ellipsis;max-width:340px;">'+d.sku+'</span>'+alerta
        +'<span style="font-size:11px;font-weight:700;color:'+cor+';margin-left:8px;white-space:nowrap;">'+d.estoque.toLocaleString('pt-BR')+'</span>'
      +'</div>'
      +'<div style="height:5px;background:rgba(255,255,255,0.10);border-radius:3px;overflow:hidden;">'
        +'<div style="height:100%;width:'+pct+'%;background:'+cor+';border-radius:3px;opacity:0.7;"></div>'
      +'</div>'
      +'<div style="display:flex;justify-content:space-between;margin-top:3px;">'
        +'<span style="font-size:9px;color:#475569;font-weight:600;">'+d.marca+'</span>'
        +'<span style="font-size:9px;color:#475569;">Giro: '+d.giro+'/30d · Cob: '+cobStr+'</span>'
      +'</div></div>';
  });
  el.innerHTML = h || '<div style="color:#94A3B8;font-size:12px;padding:20px;text-align:center;">Sem dados</div>';
}

function renderSJCEstoqueLinha(){
  var existing = Chart.getChart(document.getElementById('sjc-estoque-chart'));
  if(existing) existing.destroy();
  var data = SJC_ESTOQUE;
  var labels = data.map(function(d){return d.sku.length>18?d.sku.substring(0,18)+'…':d.sku;});
  new Chart(document.getElementById('sjc-estoque-chart'),{
    type:'bar',
    data:{labels:labels, datasets:[
      {label:'Estoque', data:data.map(function(d){return d.estoque;}), backgroundColor:'rgba(52,211,153,0.6)', borderColor:'#34d399', borderWidth:1.5, borderRadius:8, order:2},
      {label:'Giro 30d', data:data.map(function(d){return d.giro;}), type:'line', borderColor:'#fbbf24', backgroundColor:'transparent', borderWidth:2, pointRadius:3, tension:0.3, order:1},
    ]},
    options:{responsive:true,maintainAspectRatio:false,
      plugins:{legend:{display:true,position:'top',labels:{color:'#334155',font:{size:10},boxWidth:10}},
        tooltip:{backgroundColor:'#0a1218',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.1)',borderWidth:1,padding:10}},
      scales:{x:{grid:{display:false},ticks:{color:'#4a6b65',font:{size:9},maxRotation:45},border:{display:false}},
        y:{grid:{color:'rgba(255,255,255,0.04)'},ticks:{color:'#4a6b65',font:{size:9}},border:{display:false},beginAtZero:true}}}
  });
}

﻿function renderSJCCobertura(){
  var el = document.getElementById('sjc-cob-table');
  if(!el) return;
  var data = typeof SJC_COBERTURA !== 'undefined' ? SJC_COBERTURA : [];
  if(!data.length){ el.innerHTML='<p style="color:#94A3B8;font-size:11px;">Dados não disponíveis.</p>'; return; }

  var ORDEM_MARCAS = ['LYSOFORM','GLADE','PATO','EXPOSIS','OUTROS'];
  var CORES_MARCA  = {LYSOFORM:'#22d3ee',GLADE:'#a78bfa',PATO:'#fbbf24',EXPOSIS:'#34d399',OUTROS:'#94A3B8'};

  var grupos = {};
  data.forEach(function(d){ var m=d.marca||'OUTROS'; if(!grupos[m]) grupos[m]=[]; grupos[m].push(d); });
  Object.keys(grupos).forEach(function(m){ grupos[m].sort(function(a,b){ return (b.pct||0)-(a.pct||0); }); });

  var html = '<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  html += '<thead><tr style="border-bottom:1px solid rgba(255,255,255,0.13);">'
    + '<th style="text-align:left;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">SKU</th>'
    + '<th style="text-align:center;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;white-space:nowrap;">LOJAS C/ ESTOQUE</th>'
    + '<th style="padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">COBERTURA</th>'
    + '<th style="text-align:right;padding:6px 8px;font-size:9px;font-weight:700;letter-spacing:0.1em;color:#3d4451;">ESTOQUE</th>'
    + '</tr></thead><tbody>';

  ORDEM_MARCAS.forEach(function(marca){
    var itens = grupos[marca];
    if(!itens || !itens.length) return;
    var cor = CORES_MARCA[marca] || '#94A3B8';
    var mkOk   = itens.filter(function(d){ return (d.pct||0) >= 80; }).length;
    var mkAt   = itens.filter(function(d){ return (d.pct||0) >= 50 && (d.pct||0) < 80; }).length;
    var mkCrit = itens.filter(function(d){ return (d.pct||0) < 50; }).length;

    html += '<tr style="background:'+cor+'18;border-top:2px solid '+cor+'40;">'
      + '<td colspan="4" style="padding:6px 10px;">'
      + '<span style="font-size:11px;font-weight:800;color:'+cor+';letter-spacing:0.08em;">'+marca+'</span>'
      + '<span style="font-size:9px;color:#64748b;margin-left:10px;">'+itens.length+' SKUs</span>'
      + (mkOk   ? '<span style="font-size:9px;color:#34d399;margin-left:10px;">&#10003; '+mkOk+' OK</span>' : '')
      + (mkAt   ? '<span style="font-size:9px;color:#fbbf24;margin-left:8px;">&#9888; '+mkAt+' ATEN&Ccedil;&Atilde;O</span>' : '')
      + (mkCrit ? '<span style="font-size:9px;color:#22d3ee;margin-left:8px;">&#9889; '+mkCrit+' CR&Iacute;TICO</span>' : '')
      + '</td></tr>';

    itens.forEach(function(d, i){
      var pct      = d.pct || 0;
      var pctColor = pct >= 80 ? '#34d399' : pct >= 50 ? '#fbbf24' : '#22d3ee';
      var rowBg    = i % 2 === 0 ? 'rgba(255,255,255,0.025)' : 'transparent';
      var riscoBadge = (d.risco === 'critico' || d.risco === 'atencao')
        ? '<span style="font-size:8px;font-weight:700;margin-left:5px;padding:1px 4px;border-radius:3px;background:'+(d.risco==='critico'?'rgba(251,113,113,0.15)':'rgba(251,191,36,0.15)')+';color:'+(d.risco==='critico'?'#06b6d4':'#fbbf24')+';"> '+(d.risco==='critico'?'CRITICO':'ATENCAO')+'</span>'
        : '';
      html += '<tr style="background:'+rowBg+';border-bottom:1px solid rgba(255,255,255,0.05);">'
        + '<td style="padding:5px 8px 5px 18px;color:#1e293b;font-weight:600;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="'+d.sku+'">'+d.sku+riscoBadge+'</td>'
        + '<td style="text-align:center;padding:5px 8px;color:#1e293b;font-weight:700;font-variant-numeric:tabular-nums;">'+d.lojas+' / '+d.total+'</td>'
        + '<td style="padding:5px 12px;min-width:130px;"><div style="display:flex;align-items:center;gap:8px;"><div style="flex:1;background:rgba(245,225,164,0.07);border-radius:4px;height:8px;"><div style="width:'+Math.min(100,pct)+'%;background:'+pctColor+';border-radius:4px;height:8px;"></div></div><span style="color:'+pctColor+';font-weight:700;min-width:38px;text-align:right;font-size:11px;">'+pct+'%</span></div></td>'
        + '<td style="text-align:right;padding:5px 8px;color:#1e293b;font-weight:600;font-variant-numeric:tabular-nums;">'+d.estoque.toLocaleString('pt-BR')+'</td>'
        + '</tr>';
    });
  });

  html += '</tbody></table>';
  el.innerHTML = html;
}


function initCaroline(){
  // Compute aggregates from SJC constants
  var totalVol24 = SJC_VOL_24.reduce(function(s,v){return s+(v||0);},0);
  var totalVol   = (typeof SJC_VOL!=='undefined'?SJC_VOL:SJC_VOL_24).reduce(function(s,v){return s+(v||0);},0);
  var totalRec24 = SJC_REC_24.reduce(function(s,v){return s+(v||0);},0);
  var totalRec   = (typeof SJC_REC!=='undefined'?SJC_REC:SJC_REC_24).reduce(function(s,v){return s+(v||0);},0);
  var vol26 = SJC_VOL_26.filter(Boolean).reduce(function(s,v){return s+v;},0);
  var rec26 = SJC_REC_26.filter(Boolean).reduce(function(s,v){return s+v;},0);
  var varVol2425 = ((totalVol-totalVol24)/totalVol24*100).toFixed(1);
  var varRec2425 = ((totalRec-totalRec24)/totalRec24*100).toFixed(1);
  renderKPIs('sj-caroline-kpis',[
    {label:'Volume 2024',    val:totalVol24.toLocaleString('pt-BR'), sub:'Conveniência Jan–Dez', color:'#D1D5DB', spark:SJC_VOL_24},
    {label:'Volume 2025',    val:totalVol.toLocaleString('pt-BR'),   sub:'Total anual', color:'#2dd4bf', delta:(varVol2425>=0?'▲':'▼')+Math.abs(varVol2425)+'% vs 2024', deltaUp:varVol2425>=0, spark:SJC_VOL},
    {label:'Volume 2026',    val:vol26.toLocaleString('pt-BR'),      sub:'Jan–Abr parcial',      color:'#34d399', spark:SJC_VOL_26},
    {label:'Receita 2024',   val:fmtNum(totalRec24),                 sub:'Total anual',           color:'#D1D5DB', spark:SJC_REC_24},
    {label:'Receita 2025',   val:fmtNum(totalRec),                   sub:'Total anual', color:'#2dd4bf', delta:(varRec2425>=0?'▲':'▼')+Math.abs(varRec2425)+'% vs 2024', deltaUp:varRec2425>=0, spark:SJC_REC},
    {label:'Receita 2026',   val:fmtNum(rec26),                      sub:'Jan–Abr parcial',       color:'#34d399', spark:SJC_REC_26},
  ]);
  renderSJCLine();
  renderSJCRank();
  renderDonut('sjc-donut','sjc-donut-legend',SJC_CATS);
  renderSJCEstoqueBarras();
  renderSJCAnoBars();
  renderSJCMeta();
  renderSJCEdBars();
  renderEDShare('São João','caroline-sj');
  setTimeout(function(){ var el=document.getElementById('ed-caroline-sj-wrap'); if(el&&!el.innerHTML.trim()) renderEDShare('São João','caroline-sj'); },500);
  renderSJCRank2();
}

function renderSJCLine(){
  var isVol = sjcLineMode === 'vol';
  renderLineChart('sjc-line',[
    {label:'2024', data: isVol ? SJC_VOL_24 : SJC_REC_24, color:'#D1D5DB'},
    {label:'2025', data: isVol ? SJC_VOL    : SJC_REC,    color:'#2dd4bf'},
    {label:'2026', data: isVol ? SJC_VOL_26 : SJC_REC_26, color:'#34d399', dashed:true},
  ],'sjc-line-legend', isVol);
}
function setSJCLineMode(m,btn){
  sjcLineMode=m;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderSJCLine();
}

function renderSJCRank(){
  var isVol = sjcRankMode === 'vol';
  renderBars('sjc-rank-bars', SJC_RANK.map(function(r){
    return {nome:r.nome, val:isVol?r.vol:r.rec, color:r.color,
      extraFields:[{label:'Volume: ',val:r.vol.toLocaleString('pt-BR')+' un'},{label:'Receita: ',val:fmtNum(r.rec)}]};
  }), {isVol:isVol});
}
function setSJCRankMode(m,btn){
  sjcRankMode=m;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  renderSJCRank();
}


