var sjEstoqueView = 'barras';
var sjEstoqueChart = null;

function renderSJEstoqueBarras(){
  var el = document.getElementById('sj-estoque-bars');
  if(!el) return;
  var html = '';
  SJ_ESTOQUE.forEach(function(d, i){
    var cor = d.risco==='critico' ? '#06b6d4' : d.risco==='atencao' ? '#fbbf24' : '#34d399';
    var bg  = d.risco==='critico' ? 'rgba(251,113,113,0.06);border-left:2px solid #06b6d4' :
              d.risco==='atencao' ? 'rgba(251,191,36,0.06);border-left:2px solid #fbbf24'  :
              d.intoc             ? 'rgba(251,191,36,0.03);border-left:2px solid rgba(251,191,36,0.3)' : '';
    var pct = Math.min(100, Math.round(d.estoque / Math.max(1, Math.max.apply(null, SJ_ESTOQUE.map(function(x){return x.estoque;}))) * 100));
    var cobLabel = d.cob >= 999 ? 'sem giro' : d.cob+'d';
    var alerta = d.risco!=='ok' ? (' <span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;">⚠ '+cobLabel+'</span>') : '';
    var intocBadge = d.intoc ? ' <span class="intoc-badge">🏆</span>' : '';
    html += '<div class="bar-item" style="'+bg+'" onclick="this.classList.toggle(\'selected\')">';
    html += '<div class="bar-item-header">';
    html += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(i+1)+'</span>';
    html += '<span class="bar-name">'+d.sku+intocBadge+alerta+'</span>';
    html += '<span class="u-lbl-muted">'+d.estoque.toLocaleString('pt-BR')+' un</span>';
    html += '<span class="bar-val" style="color:'+cor+'">'+cobLabel+' cob.</span>';
    html += '</div>';
    html += '<div class="bar-track">';
    html += '<div class="bar-fill" style="width:0%;background:'+cor+';box-shadow:0 0 6px '+cor+'44;" data-pct="'+pct+'"></div>';
    html += '</div>';
    html += '<div class="bar-expand">';
    html += '<div class="expand-item">Estoque: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    html += '<div class="expand-item">Venda Set/26: <span class="expand-val" style="color:#D1D5DB">'+d.venda.toLocaleString('pt-BR')+' un/mês</span></div>';
    html += '<div class="expand-item">Venda/dia: <span class="expand-val" style="color:#D1D5DB">'+Math.round(d.venda/30)+' un</span></div>';
    html += '<div class="expand-item">Cobertura: <span class="expand-val" style="color:'+cor+'">'+cobLabel+'</span></div>';
    html += '</div></div>';
  });
  el.innerHTML = html;
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width = bar.getAttribute('data-pct')+'%';
    });
  }, 80);
}

function renderSJEstoqueLinha(){
  var ctx = document.getElementById('sj-estoque-chart');
  if(!ctx) return;
  if(sjEstoqueChart) sjEstoqueChart.destroy();

  // Apenas SKUs com venda > 0, ordenados por cobertura
  var skus = SJ_ESTOQUE.filter(function(d){return d.venda>0;}).slice(0,12);
  var labels = skus.map(function(d){return d.sku.length>20?d.sku.substring(0,20)+'…':d.sku;});

  // Projeção: estoque nos próximos 3 meses (90 dias)
  // Linha de estoque atual, linha de venda acumulada
  var estoqueAtual = skus.map(function(d){return d.estoque;});
  var cobertura    = skus.map(function(d){return d.cob>=999?null:d.cob;});
  var cores        = skus.map(function(d){
    return d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';
  });

  sjEstoqueChart = new Chart(ctx,{
    type:'bar',
    data:{
      labels: labels,
      datasets:[
        {
          label:'Estoque Atual (un)',
          data: estoqueAtual,
          backgroundColor: cores.map(function(c){return c+'88';}),
          borderColor: cores,
          borderWidth: 2,
          borderRadius: 5,
          yAxisID:'y',
        },
        {
          label:'Cobertura (dias)',
          data: cobertura,
          type:'line',
          borderColor:'#2dd4bf',
          backgroundColor:'transparent',
          pointBackgroundColor: cores,
          pointRadius: 6,
          pointBorderWidth: 2,
          borderWidth: 2,
          tension: 0.3,
          yAxisID:'y2',
        }
      ]
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      plugins:{
        legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
        tooltip:{
          backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',
          borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
          callbacks:{
            label:function(c){
              if(c.datasetIndex===0) return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';
              return ' Cobertura: '+(c.raw!=null?c.raw+'d':'—');
            }
          }
        },
        annotation:{
          annotations:{
            linha30:{type:'line',yMin:30,yMax:30,yScaleID:'y2',borderColor:'#fbbf24',borderWidth:1.5,borderDash:[6,4],
              label:{content:'30 dias',display:true,color:'#fbbf24',font:{size:9}}},
            linha15:{type:'line',yMin:15,yMax:15,yScaleID:'y2',borderColor:'#06b6d4',borderWidth:1.5,borderDash:[6,4],
              label:{content:'15 dias (crítico)',display:true,color:'#06b6d4',font:{size:9}}}
          }
        }
      },
      scales:{
        x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
        y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},
           ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},
           title:{display:true,text:'Estoque (un)',color:'#475569',font:{size:9}}},
        y2:{position:'right',grid:{display:false},
            ticks:{color:'#2dd4bf',font:{size:9},callback:function(v){return v+'d';}},
            title:{display:true,text:'Cobertura (dias)',color:'#2dd4bf',font:{size:9}},
            min:0, max:120}
      }
    }
  });
}

function setSJEstoqueView(view, btn){
  sjEstoqueView = view;
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  document.getElementById('sj-estoque-barras').style.display = view==='barras'?'block':'none';
  document.getElementById('sj-estoque-linha').style.display  = view==='linha'?'block':'none';
  var tendEl_sj = document.getElementById('sj-estoque-tend');
  if(tendEl_sj) tendEl_sj.style.display = view==='tend'?'block':'none';
  var cobEl = document.getElementById('sj-estoque-cobertura');
  if(cobEl) cobEl.style.display = view==='cobertura'?'block':'none';
  var sjImpEl = document.getElementById('sj-estoque-importancia');
  if(sjImpEl) sjImpEl.style.display = view==='importancia'?'block':'none';
  if(view==='linha') renderSJEstoqueLinha();
  else if(view==='cobertura') renderCoberturaSKUBarsUnified('sj-cob-table', SJ_COBERTURA, 'São João (01/11/26)');
  else if(view==='importancia'){ renderSJImpCluster(); }
}

