var olView = 'prsc';
var olSort = 'prop';

function initOL(){
  setTimeout(function(){ renderOLDiag('prsc'); }, 300);
  setOLView('prsc', null);
  if(typeof initOLTabs==='function') setTimeout(initOLTabs, 80);
  if(typeof renderProvYoYCard==="function") setTimeout(renderProvYoYCard, 300);
  if(typeof renderGCCard==='function') setTimeout(function(){ renderGCCard(_gcMarca, null); }, 250);
}

function setOLView(v, btn){
  olView = v;
  if(btn){ btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');}); btn.classList.add('active','blue'); }
  renderOL();
  renderOLDiag(v);
}
function renderOL(){
  var d = OL_DATA[olView];
  var kc = document.getElementById('ol-kpis');
  if(kc){
    var catVar  = ((d.catAtual-d.catAnt)/d.catAnt*100).toFixed(1);
    var propVar = ((d.propAtual-d.propAnt)/d.propAnt*100).toFixed(1);
    var positVar= d.posit26-d.posit25;
    var kpis = [
      {tag:'PDVs TOTAL',       val:d.pdvsTotal.toLocaleString('pt-BR'), sub:'Carteira '+d.label, color:'#2dd4bf', delta:''},
      {tag:'POSITIVACAO FY26', val:d.posit26.toLocaleString('pt-BR'),   sub:'FY25: '+d.posit25.toLocaleString('pt-BR'), color:positVar>=0?'#34d399':'#ef4444', delta:(positVar>=0?'▲':'▼')+Math.abs(positVar)+' vs FY25'},
      {tag:'CATEGORIA FY26',   val:'R$'+Math.round(d.catAtual/1000)+'K', sub:'FY25: R$'+Math.round(d.catAnt/1000)+'K', color:catVar>=0?'#34d399':'#ef4444', delta:(catVar>=0?'▲':'▼')+Math.abs(catVar)+'%'},
      {tag:'PROPRIO FY26',     val:'R$'+Math.round(d.propAtual/1000)+'K',sub:'FY25: R$'+Math.round(d.propAnt/1000)+'K',color:propVar>=0?'#34d399':'#ef4444',delta:(propVar>=0?'▲':'▼')+Math.abs(propVar)+'%'},
      {tag:'SHARE ATUAL',      val:d.shareAtual.toFixed(1)+'%',         sub:'FY25: '+d.shareAnt.toFixed(1)+'%',        color:'#fbbf24', delta:(d.shareVar>=0?'▲':'▼')+Math.abs(d.shareVar).toFixed(1)+' pp'},
    ];
    kc.innerHTML = kpis.map(function(k){
      var dc = k.delta.includes('▲')?'#34d399':'#ef4444';
      return '<div style="background:#161B22;padding:14px 16px;position:relative;overflow:hidden;"><div class="u-kpi-lbl">'+k.tag+'</div><div style="font-size:20px;font-weight:800;color:'+k.color+';line-height:1;">'+k.val+'</div><div style="font-size:10px;color:#3d4451;margin-top:4px;">'+k.sub+'</div>'+(k.delta?'<div style="font-size:10px;font-weight:700;color:'+dc+';margin-top:4px;">'+k.delta+'</div>':'')+'</div>';
    }).join('');
  }

  var sorted = d.clientes.slice().sort(function(a,b){
    if(olSort==='cat')   return b.catAtual-a.catAtual;
    if(olSort==='share') return b.shareAtual-a.shareAtual;
    if(olSort==='posit') return b.posit26-a.posit26;
    return b.propAtual-a.propAtual;
  });

  // Tabela
  var tbl = document.getElementById('ol-table');
  if(tbl){
    var h = '<table class="meta-table"><thead><tr><th>Cliente</th><th style="text-align:right">PDVs</th><th style="text-align:right">Posit FY25</th><th style="text-align:right">Posit FY26</th><th style="text-align:right">Cat FY25</th><th style="text-align:right">Cat FY26</th><th style="text-align:right">Proprio FY25</th><th style="text-align:right">Proprio FY26</th><th style="text-align:right">Share FY25</th><th style="text-align:right">Share FY26</th><th style="text-align:right">Var pp</th></tr></thead><tbody>';
    sorted.forEach(function(c){
      var sc=c.shareVar>=0?'#34d399':'#ef4444';
      var vc=c.posit26>=c.posit25?'#34d399':'#ef4444';
      // Montar badges de UF com share vs Nielsen
      var ufBadges = '';
      if(c.ufs && c.ufs.length){
        ufBadges = c.ufs.map(function(u){
          var diff = u.share - u.nielsen;
          var dc = diff>=0?'#34d399':'#ef4444';
          var arrow = diff>=0?'▲':'▼';
          var ufColor = UF_COLORS[u.uf]||'#888';
          return '<span style="display:inline-flex;flex-direction:column;gap:1px;background:' + ufColor + '11;border:0.5px solid ' + ufColor + '33;border-radius:5px;padding:3px 7px;margin-right:4px;margin-bottom:3px;">'
            + '<span style="display:flex;align-items:center;gap:4px;">'
            + '<span style="font-size:9px;font-weight:800;color:' + ufColor + '">' + u.uf + '</span>'
            + '<span style="font-size:8px;color:#94A3B8;">ED:</span>'
            + '<span style="font-size:9px;color:#fbbf24;font-weight:700;">' + u.share.toFixed(1) + '%</span>'
            + '</span>'
            + '<span style="display:flex;align-items:center;gap:4px;">'
            + '<span style="font-size:8px;color:#94A3B8;width:16px;"> </span>'
            + '<span style="font-size:8px;color:#94A3B8;">Nielsen:</span>'
            + '<span style="font-size:8px;color:#D1D5DB;">' + u.nielsen.toFixed(1) + '%</span>'
            + '<span style="font-size:8px;font-weight:700;color:' + dc + ';">' + arrow + Math.abs(diff).toFixed(1) + 'pp</span>'
            + '</span>'
            + '</span>';
        }).join('');
      }
      h+='<tr><td style="font-weight:700;color:#D1D5DB;">'+c.nome+'<div style="margin-top:3px;">'+ufBadges+'</div></td><td style="text-align:right;color:#D1D5DB;">'+c.pdvs+'</td><td style="text-align:right;color:#94A3B8;">'+c.posit25+'</td><td style="text-align:right;color:'+vc+';">'+c.posit26+'</td><td style="text-align:right;color:#94A3B8;">R$'+Math.round(c.catAnt/1000)+'K</td><td style="text-align:right;color:#D1D5DB;">R$'+Math.round(c.catAtual/1000)+'K</td><td style="text-align:right;color:#94A3B8;">R$'+Math.round(c.propAnt/1000)+'K</td><td style="text-align:right;color:#34d399;">R$'+Math.round(c.propAtual/1000)+'K</td><td style="text-align:right;color:#94A3B8;">'+c.shareAnt.toFixed(1)+'%</td><td style="text-align:right;color:#fbbf24;font-weight:700;">'+c.shareAtual.toFixed(1)+'%</td><td style="text-align:right;color:'+sc+';font-weight:700;">'+(c.shareVar>=0?'+':'')+c.shareVar.toFixed(1)+'</td></tr>';
    });
    tbl.innerHTML = h+'</tbody></table>';
  }

  // Barras share FY25 vs FY26
  var bars = document.getElementById('ol-share-bars');
  if(bars){
    var rows = [];
    sorted.forEach(function(c,i){
      var sc=c.shareVar>=0?'#34d399':'#ef4444';
      var p25=Math.round(c.shareAnt), p26=Math.round(c.shareAtual);
      rows.push(
        '<div class="bar-item" data-togglesel="1">'
        +'<div class="bar-item-header">'
        +'<span class="bar-rank" style="background:#2dd4bf22;color:#2dd4bf;">'+(i+1)+'</span>'
        +'<span class="bar-name">'+c.nome+'</span>'
        +'<span style="font-size:10px;color:#94A3B8;margin-right:4px;">FY25: '+c.shareAnt.toFixed(1)+'%</span>'
        +'<span class="bar-val" style="color:#fbbf24">FY26: '+c.shareAtual.toFixed(1)+'% <span style="color:'+sc+';font-size:10px;">'+(c.shareVar>=0?'▲':'▼')+Math.abs(c.shareVar).toFixed(1)+' pp</span></span>'
        +'</div>'
        +'<div style="display:flex;flex-direction:column;gap:3px;margin-top:4px;">'
        +'<div style="display:flex;align-items:center;gap:6px;"><span style="font-size:9px;color:#3d4451;width:40px;">FY25</span><div style="flex:1;background:rgba(255,255,255,0.04);border-radius:3px;height:5px;"><div style="width:'+p25+'%;height:100%;background:#2dd4bf55;border-radius:3px;"></div></div><span style="font-size:9px;color:#2dd4bf;width:36px;text-align:right;">'+c.shareAnt.toFixed(1)+'%</span></div>'
        +'<div style="display:flex;align-items:center;gap:6px;"><span style="font-size:9px;color:#3d4451;width:40px;">FY26</span><div style="flex:1;background:rgba(255,255,255,0.04);border-radius:3px;height:5px;"><div class="bar-fill" style="width:0%;height:100%;background:#fbbf24;border-radius:3px;" data-pct="'+p26+'"></div></div><span style="font-size:9px;color:#fbbf24;width:36px;text-align:right;">'+c.shareAtual.toFixed(1)+'%</span></div>'
        +'</div>'
        +(function(){
          var exp = '<div class="bar-expand"><div class="expand-item">Proprio FY26: <span class="expand-val" style="color:#34d399">R$ '+Math.round(c.propAtual/1000)+'K</span></div><div class="expand-item">Categoria FY26: <span class="expand-val" style="color:#D1D5DB">R$ '+Math.round(c.catAtual/1000)+'K</span></div><div class="expand-item">Positivacao FY26: <span class="expand-val" style="color:#3b82f6">'+c.posit26+' PDVs</span></div>';
          if(c.ufs&&c.ufs.length){
            exp += '<div class="expand-item" style="margin-top:4px;border-top:0.5px solid rgba(255,255,255,0.09);padding-top:4px;">Nielsen SCJ FYTD26:';
            c.ufs.forEach(function(u){
              var diff=u.share-u.nielsen; var dc=diff>=0?'#34d399':'#ef4444';
              exp+=' <span style="color:'+(UF_COLORS[u.uf]||'#888')+';font-weight:700;">'+u.uf+'</span> <span style="color:#fbbf24">'+u.share.toFixed(1)+'%</span> vs <span style="color:#94A3B8">'+u.nielsen+'%</span> <span style="color:'+dc+';">'+(diff>=0?'+':'')+diff.toFixed(1)+'pp</span>';
            });
            exp+='</div>';
          }
          exp+='</div>';
          return exp;
        })()
        +'</div>'
      );
    });
    bars.innerHTML = rows.join('');
    bars.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
    setTimeout(function(){ bars.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';}); },80);
  }
}

