function renderDNBars(containerId, data, modo){
  // modo: 'off' | 'exp'
  var el = document.getElementById(containerId);
  if(!el) return;
  var html = '';
  data.ufs.forEach(function(d, i){
    var color = UF_COLORS[d.uf] || LOJA_COLORS[i];
    var dn    = modo === 'off' ? d.dnOff : d.dnExp;
    var pdvs  = modo === 'off' ? d.off   : d.exp;
    var pct   = Math.round(dn);

    html += '<div class="bar-item" onclick="this.classList.toggle(\'selected\')">';
    html += '<div class="bar-item-header">';
    html += '<span class="uf-badge" style="background:'+color+'22;color:'+color+';font-size:10px;padding:2px 7px;">'+d.uf+'</span>';
    html += '<span class="bar-name">'+d.total.toLocaleString('pt-BR')+' PDVs total</span>';
    html += '<span class="u-lbl-muted">'+pdvs.toLocaleString('pt-BR')+' PDVs</span>';
    html += '<span class="bar-val" style="color:'+color+'">'+dn.toFixed(1)+'% DN</span>';
    html += '</div>';
    html += '<div class="bar-track"><div class="bar-fill" style="width:0%;background:'+color+';box-shadow:0 0 6px '+color+'55;" data-pct="'+pct+'"></div></div>';
    html += '<div class="bar-expand">';
    html += '<div class="expand-item">OFF! PDVs: <span class="expand-val" style="color:#fbbf24">'+d.off.toLocaleString('pt-BR')+' ('+d.dnOff.toFixed(1)+'%)</span></div>';
    html += '<div class="expand-item">EXPOSIS PDVs: <span class="expand-val" style="color:#3b82f6">'+d.exp.toLocaleString('pt-BR')+' ('+d.dnExp.toFixed(1)+'%)</span></div>';
    html += '<div class="expand-item">Total compradores: <span class="expand-val" style="color:'+color+'">'+d.total.toLocaleString('pt-BR')+'</span></div>';
    html += '</div></div>';
  });
  el.innerHTML = html;
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width = bar.getAttribute('data-pct')+'%';
    });
  }, 80);
}

