var nsEstoqueView = 'barras';
var nsEstoqueTab  = 'hb';
var nsEstoqueChart = null;

function renderNsEstoqueBarras(){
  var el = document.getElementById('ns-estoque-bars');
  if(!el) return;
  var data = nsEstoqueTab === 'hb' ? NS_ESTOQUE_HB : NS_ESTOQUE_ED;
  var maxEst = Math.max.apply(null, data.map(function(d){return d.estoque;}));
  var h = '';
  data.forEach(function(d,i){
    var cob_real = calcCob(d.estoque, 'nissei');
    var risco_real = calcRisco(cob_real);
    var cobStr = cobLabel(cob_real);
    var cor = risco_real==='critico'?'#06b6d4':risco_real==='atencao'?'#fbbf24':'#34d399';
    var bg  = risco_real==='critico'?'border-left:2px solid #06b6d4;background:rgba(251,113,113,0.04);':
              risco_real==='atencao'?'border-left:2px solid #fbbf24;background:rgba(251,191,36,0.04);':'';
    var pct = Math.min(100,Math.round(d.estoque/maxEst*100));
    var alerta = risco_real!=='ok'?('<span style="font-size:9px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:1px 5px;margin-left:6px;">'+(risco_real==='critico'?'⚡ CRÍTICO':'⚠ ATENÇÃO')+'</span>'):'';
    h += '<div class="bar-item" style="'+bg+'" data-togglesel="1">';
    h += '<div class="bar-item-header">';
    h += '<span class="bar-rank" style="background:'+cor+'22;color:'+cor+';">'+(i+1)+'</span>';
    h += '<span class="bar-name">'+d.sku+alerta+'</span>';
    h += '<span class="u-lbl-muted">'+d.estoque.toLocaleString('pt-BR')+' un</span>';
    h += '<span class="bar-val" style="color:'+cor+'">'+cobStr+' cob.</span>';
    h += '</div><div class="bar-track"><div class="bar-fill" style="width:0%;background:'+cor+';" data-pct="'+pct+'"></div></div>';
    h += '<div class="bar-expand">';
    h += '<div class="expand-item">Estoque: <span class="expand-val" style="color:'+cor+'">'+d.estoque.toLocaleString('pt-BR')+' un</span></div>';
    h += '<div class="expand-item">Ref. Abr/2025: <span class="expand-val" style="color:#D1D5DB">'+VENDA_REF.nissei.venda_mes.toLocaleString('pt-BR')+' un (total cliente)</span></div>';
    h += '<div class="expand-item">Cobertura Real: <span class="expand-val" style="color:'+cor+'">'+cobStr+'</span></div>';
    h += '</div></div>';
  });
  el.innerHTML = h;
  el.querySelectorAll('[data-togglesel]').forEach(function(r){r.addEventListener('click',function(){this.classList.toggle('selected');});});
  setTimeout(function(){el.querySelectorAll('.bar-fill').forEach(function(bar){bar.style.width=bar.getAttribute('data-pct')+'%';});},80);
}

function setNsEstoqueTab(tab, btn){
  nsEstoqueTab = tab;
  document.querySelectorAll('#ns-est-tab-hb,#ns-est-tab-ed').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');

  if(nsEstoqueView==='barras')  renderNsEstoqueBarras();
  else if(nsEstoqueView==='linha') renderNsEstoqueLinha();
  else if(nsEstoqueView==='tend')  setEstoqueTend('ns', null); /* atualiza Ruptura com dados do comprador */

  /* Atualiza label do header de Ruptura */
  var hdr = document.getElementById('ns-tend-header');
  if(hdr){
    var comp = tab==='hb' ? 'Andre — OFF! &amp; EXPOSIS' : 'Edmar — RAID &amp; Elétricos';
    hdr.innerHTML = '📈 <strong style="color:#fbbf24;">Projeção de Ruptura</strong> — Comprador <strong style="color:#60a5fa;">'+comp+'</strong> · Sazonalidade Inverno';
  }

  updateNsEstoqueKPIs();
}

function updateNsEstoqueKPIs(){
  var isHB = nsEstoqueTab==='hb';
  var data = isHB ? NS_ESTOQUE_HB : NS_ESTOQUE_ED;
  var est  = data.reduce(function(s,d){return s+d.estoque;},0);
  var vnd  = data.reduce(function(s,d){return s+(d.venda_abr||d.venda||0);},0);
  /* dias = estoque total / venda_abr total * 30 (cob field é 0 no NS) */
  var totalVndNs = data.reduce(function(s,d){return s+(d.venda_abr||d.venda||0);},0);
  var cob = totalVndNs>0 ? Math.round(est/totalVndNs*30) : 0;
  var at   = data.filter(function(d){return d.risco==='atencao'||d.risco==='critico';}).length;
  var corAt = at>0?'#fbbf24':'#34d399';
  var el1=document.getElementById('ns-kpi-est'), el2=document.getElementById('ns-kpi-at');
  var el3=document.getElementById('ns-kpi-vnd'), el4=document.getElementById('ns-kpi-cob');
  if(el1) el1.textContent = est.toLocaleString('pt-BR');
  if(el2){el2.textContent = at; el2.style.color=corAt;}
  if(el3) el3.textContent = vnd.toLocaleString('pt-BR');
  if(el4) el4.textContent = cob>0 ? cob+' dias' : '—';
}

function renderNsEstoqueLinha(){
  var ctx = document.getElementById('ns-estoque-chart');
  if(!ctx) return;
  if(nsEstoqueChart) nsEstoqueChart.destroy();
  var data = nsEstoqueTab==='hb' ? NS_ESTOQUE_HB : NS_ESTOQUE_ED;
  var skus = data.filter(function(d){return d.venda>0;}).slice(0,12);
  var labels = skus.map(function(d){return d.sku.length>20?d.sku.substring(0,20)+'…':d.sku;});
  var estoqueAtual = skus.map(function(d){return d.estoque;});
  var cobertura    = skus.map(function(d){return d.cob>=999?null:Math.min(d.cob,120);});
  var cores = skus.map(function(d){return d.risco==='critico'?'#06b6d4':d.risco==='atencao'?'#fbbf24':'#34d399';});
  nsEstoqueChart = new Chart(ctx,{type:'bar',data:{labels:labels,datasets:[
    {label:'Estoque Atual (un)',data:estoqueAtual,backgroundColor:cores.map(function(c){return c+'88';}),borderColor:cores,borderWidth:2,borderRadius:5,yAxisID:'y'},
    {label:'Cobertura (dias)',data:cobertura,type:'line',borderColor:'#2dd4bf',backgroundColor:'transparent',pointBackgroundColor:cores,pointRadius:6,pointBorderWidth:2,borderWidth:2,tension:0.3,yAxisID:'y2'}
  ]},options:{responsive:true,maintainAspectRatio:false,
    plugins:{
      legend:{display:true,position:'top',labels:{color:'#D1D5DB',font:{size:10},boxWidth:10}},
      tooltip:{backgroundColor:'#1F2937',titleColor:'#e2e8f0',bodyColor:'#D1D5DB',borderColor:'rgba(255,255,255,0.13)',borderWidth:1,
        callbacks:{label:function(c){if(c.datasetIndex===0)return ' Estoque: '+c.raw.toLocaleString('pt-BR')+' un';return ' Cobertura: '+(c.raw!=null?c.raw+'d':'-');}}},
      annotation:{annotations:{
        linha30:{type:'line',yMin:30,yMax:30,yScaleID:'y2',borderColor:'#fbbf24',borderWidth:1.5,borderDash:[6,4],label:{content:'30d',display:true,color:'#fbbf24',font:{size:9},position:'start'}},
        linha15:{type:'line',yMin:15,yMax:15,yScaleID:'y2',borderColor:'#06b6d4',borderWidth:1.5,borderDash:[6,4],label:{content:'15d critico',display:true,color:'#06b6d4',font:{size:9},position:'end'}}
      }}
    },
    scales:{
      x:{grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},maxRotation:35}},
      y:{position:'left',grid:{color:'rgba(148,163,184,0.08)'},ticks:{color:'#475569',font:{size:9},callback:function(v){return v>=1000?(v/1000).toFixed(0)+'K':v;}},title:{display:true,text:'Estoque (un)',color:'#475569',font:{size:9}}},
      y2:{position:'right',grid:{display:false},ticks:{color:'#2dd4bf',font:{size:9},callback:function(v){return v+'d';}},title:{display:true,text:'Cobertura (dias)',color:'#2dd4bf',font:{size:9}},min:0,max:120}
    }
  }});
}

function setNsEstoqueView(view, btn){
  btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');});
  btn.classList.add('active','blue');
  nsEstoqueView = view;
  document.getElementById('ns-estoque-barras').style.display = view==='barras'?'block':'none';
  document.getElementById('ns-estoque-linha').style.display  = view==='linha'?'block':'none';
  var tendEl_ns = document.getElementById('ns-estoque-tend');
  if(tendEl_ns) tendEl_ns.style.display = view==='tend'?'block':'none';
  var cobEl = document.getElementById('ns-estoque-cobertura');
  if(cobEl) cobEl.style.display = view==='cobertura'?'block':'none';
  var impEl = document.getElementById('ns-estoque-importancia');
  if(impEl) impEl.style.display = view==='importancia'?'block':'none';
  
  if(view==='linha') renderNsEstoqueLinha();
  else if(view==='barras') renderNsEstoqueBarras();
  else if(view==='cobertura'){
    var fsec = document.getElementById('ns-filial-section');
    if(fsec) fsec.style.display = 'none'; // reset filial view
    renderCoberturaSKUBarsUnified('ns-cob-table', NS_COBERTURA, 'Nissei (12/11/26)');
    // Add "Ver detalhes por filial" toggle below the SKU table
    var el = document.getElementById('ns-cob-table');
    if(el){
      var btn = document.createElement('button');
      btn.textContent = '🏬 Ver cobertura por filial';
      btn.style.cssText = 'margin-top:14px;font-size:10px;color:#60a5fa;background:rgba(96,165,250,0.08);border:0.5px solid rgba(96,165,250,0.3);border-radius:6px;padding:5px 14px;cursor:pointer;';
      btn.onclick = function(){
        var fs = document.getElementById('ns-filial-section');
        if(!fs) return;
        var vis = fs.style.display !== 'none';
        fs.style.display = vis ? 'none' : 'block';
        this.textContent = vis ? '🏬 Ver cobertura por filial' : '🏬 Ocultar cobertura por filial';
        if(!vis) renderNsFilialTable();
      };
      el.appendChild(btn);
    }
  }
  else if(view==='importancia'){ renderNsImpCluster(); }
}

