function _pvImpTable(data, labelKey){
  var maxFat = Math.max.apply(null, data.map(function(d){return d.fat_fev;}));
  var h = '<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  h += '<thead><tr style="color:#94A3B8;border-bottom:1px solid #2a3347;">'
    + '<th style="text-align:left;padding:5px 4px;">'+(labelKey==='tipo'?'Tipo Público':'Equipamento')+'</th>'
    + '<th style="text-align:right;padding:5px 4px;">Fat. Fev-26</th>'
    + '<th style="text-align:right;padding:5px 4px;">Fat. Mar-26</th>'
    + '<th style="text-align:center;padding:5px 4px;">Var.</th>'
    + '<th style="text-align:right;padding:5px 4px;">Vol. Fev</th>'
    + '<th style="text-align:right;padding:5px 4px;">Vol. Mar</th>'
    + '<th style="text-align:center;padding:5px 4px;">Lojas</th>'
    + '<th style="text-align:center;padding:5px 4px;">% Fat</th>'
    + '</tr></thead><tbody>';
  var totFatFev = data.reduce(function(s,d){return s+d.fat_fev;},0);
  data.forEach(function(d,i){
    var lbl = d[labelKey];
    var varColor = d.var_pct < -25 ? '#22d3ee' : d.var_pct < -15 ? '#fbbf24' : '#34d399';
    var pctFat = Math.round(d.fat_fev/totFatFev*100);
    var barW = Math.round(d.fat_fev/maxFat*100);
    var rowBg = i%2===0?'rgba(255,255,255,0.02)':'transparent';
    h += '<tr style="background:'+rowBg+';border-bottom:1px solid rgba(255,255,255,0.04);">'
      + '<td style="padding:5px 4px;color:#e2e8f0;font-weight:600;white-space:nowrap;">'+lbl+'</td>'
      + '<td style="text-align:right;padding:5px 4px;color:#c9d1e0;">R$'+Math.round(d.fat_fev/1000)+'k</td>'
      + '<td style="text-align:right;padding:5px 4px;color:#94a3b8;">R$'+Math.round(d.fat_mar/1000)+'k</td>'
      + '<td style="text-align:center;padding:5px 4px;color:'+varColor+';font-weight:700;">'+d.var_pct+'%</td>'
      + '<td style="text-align:right;padding:5px 4px;color:#c9d1e0;">'+d.vol_fev.toLocaleString('pt-BR')+'</td>'
      + '<td style="text-align:right;padding:5px 4px;color:#94a3b8;">'+d.vol_mar.toLocaleString('pt-BR')+'</td>'
      + '<td style="text-align:center;padding:5px 4px;color:#60a5fa;">'+d.lojas+'</td>'
      + '<td style="padding:5px 8px;min-width:80px;">'
      +   '<div style="display:flex;align-items:center;gap:4px;">'
      +   '<div style="flex:1;background:rgba(94,153,208,0.15);border-radius:3px;height:6px;">'
      +   '<div style="width:'+barW+'%;background:#2dd4bf;border-radius:3px;height:6px;"></div></div>'
      +   '<span style="color:#2dd4bf;font-size:10px;font-weight:600;min-width:28px;">'+pctFat+'%</span></div>'
      + '</td>'
      + '</tr>';
  });
  h += '</tbody></table>';
  return h;
}

function renderPVImpPublico(){
  var el = document.getElementById('pv-imp-publico');
  if(el) el.innerHTML = _pvImpTable(PV_TIPO_PUBLICO, 'tipo');
}
function renderPVImpEquip(){
  var el = document.getElementById('pv-imp-equipamento');
  if(el) el.innerHTML = _pvImpTable(PV_EQUIPAMENTO, 'faixa');
}

