var gamDNIntocSku = 'kids200';
var gchDNIntocSku = 'kids200';

function renderDNIntocBars(containerId, dnData, skuKey){
  var el = document.getElementById(containerId);
  if(!el) return;
  var nomes = {soma:'Somatorio', kids200:'Kids 200ML', spray170:'Spray 170ML', locao200:'Locao 200ML'};
  var allKeys = ['soma','kids200','spray170','locao200'];
  var isGam = containerId.indexOf('gam') > -1;

  // Sub-tabs
  var tabs = allKeys.map(function(k){
    var isActive = k === skuKey;
    var active = isActive ? 'background:rgba(251,191,36,0.15);color:#fbbf24;border-color:rgba(251,191,36,0.3);' : 'background:transparent;color:#94A3B8;';
    var icon = k === 'soma' ? '∑' : '🏆';
    return '<button data-key="' + k + '" data-fn="' + (isGam?'gam':'gch') + '" style="font-size:10px;font-weight:700;padding:4px 12px;border-radius:6px;border:0.5px solid rgba(234,179,8,0.15);cursor:pointer;' + active + '">' + icon + ' ' + nomes[k] + '</button>';
  }).join('');
  var tabsHtml = '<div style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;">' + tabs + '</div>';

  var bodyHtml = '';

  if(skuKey === 'soma'){
    var soma = dnData['soma'];
    // KPIs somatório
    bodyHtml += '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#E4EAF2;border-radius:10px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(94,153,208,0.45);box-shadow:0 2px 8px rgba(10,40,80,0.08);">';
    bodyHtml += '<div style="background:#161B22;padding:14px 16px;position:relative;overflow:hidden;"><div class="u-kpi-lbl">PDVs COM PELO MENOS 1 INTOCAVEL</div><div style="font-size:22px;font-weight:800;color:#fbbf24;line-height:1;">' + soma.algum.toLocaleString('pt-BR') + '</div><div style="font-size:10px;color:#3d4451;margin-top:4px;">' + soma.dnAlgum.toFixed(1) + '% DN · ' + soma.total.toLocaleString('pt-BR') + ' PDVs total</div></div>';
    bodyHtml += '<div style="background:#161B22;padding:14px 16px;position:relative;overflow:hidden;"><div class="u-kpi-lbl">PDVs COM PELO MENOS 2 INTOCAVEIS</div><div style="font-size:22px;font-weight:800;color:#2dd4bf;line-height:1;">' + soma.dois.toLocaleString('pt-BR') + '</div><div style="font-size:10px;color:#3d4451;margin-top:4px;">' + soma.dnDois.toFixed(1) + '% DN</div></div>';
    bodyHtml += '<div style="background:#161B22;padding:14px 16px;position:relative;overflow:hidden;"><div class="u-kpi-lbl">PDVs COM OS 3 INTOCAVEIS</div><div style="font-size:22px;font-weight:800;color:#34d399;line-height:1;">' + soma.todos.toLocaleString('pt-BR') + '</div><div style="font-size:10px;color:#3d4451;margin-top:4px;">' + soma.dnTodos.toFixed(1) + '% DN (full portfolio)</div></div>';
    bodyHtml += '</div>';
    // Barras por UF com somatório
    bodyHtml += '<div style="font-size:10px;font-weight:700;letter-spacing:0.1em;color:#94A3B8;margin-bottom:10px;">PDVs COM PELO MENOS 1 INTOCAVEL POR ESTADO</div>';
    var rows = [];
    soma.ufs.forEach(function(u){
      var color = UF_COLORS[u.uf] || '#888';
      var pct = Math.round(u.dn);
      rows.push(
        '<div class="bar-item" data-togglesel="1">'
        + '<div class="bar-item-header">'
        + '<span class="uf-badge" style="background:' + color + '22;color:' + color + ';font-size:10px;padding:2px 7px;">' + u.uf + '</span>'
        + '<span class="bar-name">' + u.total.toLocaleString('pt-BR') + ' PDVs total</span>'
        + '<span class="u-lbl-muted">' + u.pdvs.toLocaleString('pt-BR') + ' PDVs</span>'
        + '<span class="bar-val" style="color:#fbbf24">' + u.dn.toFixed(1) + '% DN</span>'
        + '</div>'
        + '<div class="bar-track"><div class="bar-fill" style="width:0%;background:#fbbf24;" data-pct="' + pct + '"></div></div>'
        + '</div>'
      );
    });
    bodyHtml += rows.join('');
  } else {
    // SKU individual
    var sku = dnData[skuKey];
    var rows2 = [];
    sku.ufs.forEach(function(u){
      var color = UF_COLORS[u.uf] || '#888';
      var pct = Math.round(u.dn);
      rows2.push(
        '<div class="bar-item" data-togglesel="1">'
        + '<div class="bar-item-header">'
        + '<span class="uf-badge" style="background:' + color + '22;color:' + color + ';font-size:10px;padding:2px 7px;">' + u.uf + '</span>'
        + '<span class="bar-name">' + u.total.toLocaleString('pt-BR') + ' PDVs total</span>'
        + '<span class="u-lbl-muted">' + u.pdvs.toLocaleString('pt-BR') + ' PDVs</span>'
        + '<span class="bar-val" style="color:#fbbf24">' + u.dn.toFixed(1) + '% DN</span>'
        + '</div>'
        + '<div class="bar-track"><div class="bar-fill" style="width:0%;background:#fbbf24;" data-pct="' + pct + '"></div></div>'
        + '<div class="bar-expand">'
        + '<div class="expand-item">PDVs compraram: <span class="expand-val" style="color:#fbbf24">' + u.pdvs.toLocaleString('pt-BR') + '</span></div>'
        + '<div class="expand-item">Potencial: <span class="expand-val" style="color:#34d399">' + (u.total-u.pdvs) + ' PDVs sem o SKU</span></div>'
        + '</div></div>'
      );
    });
    bodyHtml += rows2.join('');
  }

  el.innerHTML = tabsHtml + bodyHtml;
  el.querySelectorAll('button[data-key]').forEach(function(b){
    b.addEventListener('click', function(){
      var k = this.getAttribute('data-key');
      var f = this.getAttribute('data-fn');
      if(f==='gam') setGAMDNIntocSku(k, this);
      else setGCHDNIntocSku(k, this);
    });
  });
  el.querySelectorAll('[data-togglesel]').forEach(function(row){
    row.addEventListener('click', function(){ this.classList.toggle('selected'); });
  });
  setTimeout(function(){
    el.querySelectorAll('.bar-fill').forEach(function(bar){
      bar.style.width = bar.getAttribute('data-pct') + '%';
    });
  }, 80);
}

function setGAMDNIntocSku(sku, btn){
  gamDNIntocSku = sku;
  renderDNIntocBars('gam-dn-bars', DN_INTOC_GAM, sku);
}
