var activePanel='nielsen';
var initialized={};
var activeSelloutClient='saojoao';

// Função para trocar cliente dentro da aba Sell Out
function switchSellOutClient(clientId) {
  activeSelloutClient = clientId;
  // Sync attribution card with client selection
  var _atribMap = {saojoao:'sj', nissei:'nissei', clamed:'clamed', panvel:'panvel'};
  var _atribKey = _atribMap[clientId];
    // Move attribution card to the active client's panel slot
    var _atribSlotMap = {saojoao:(typeof sjModo!=='undefined'&&sjModo==='caroline'?'ed-atrib-slot-caroline':'ed-atrib-slot-sj'), nissei:'ed-atrib-slot-nissei', clamed:'ed-atrib-slot-clamed', panvel:'ed-atrib-slot-panvel'};
    var _atribSlotId = _atribSlotMap[clientId];
    var _atribSlot = _atribSlotId ? document.getElementById(_atribSlotId) : null;
    var _atribCardEl = document.getElementById('ed-atrib-card');
    if(_atribCardEl && _atribSlot) {
      _atribSlot.appendChild(_atribCardEl);
    }

  if(_atribKey && window.edAtribShow) {
    setTimeout(function(){ window.edAtribShow(_atribKey, null); }, 30);
  }
  // Esconder todos os conteúdos de clientes
  var contents = document.querySelectorAll('.sellout-client-content');
  contents.forEach(function(el) {
    el.style.display = 'none';
  });
  
  // Mostrar o selecionado
  var selected = document.getElementById('sellout-content-' + clientId);
  if (selected) {
    selected.style.display = 'block';
  }
  // Mostrar/ocultar filtros compradora no header (SJ e Nissei)
  var _sjRow = document.getElementById('sj-compradora-row');
  if(_sjRow){
    if(clientId === 'saojoao'){
      _sjRow.style.display = 'flex';
      var _mIdx = {'total':0,'isadora':1,'caroline':2};
      var _rBtns = _sjRow.querySelectorAll('.stab');
      _rBtns.forEach(function(b){b.classList.remove('active');});
      var _cur = (typeof sjModo!=='undefined'?sjModo:'total');
      if(_rBtns[_mIdx[_cur]]) _rBtns[_mIdx[_cur]].classList.add('active');
    } else {
      _sjRow.style.display = 'none';
    }
  }
  var _nsRow = document.getElementById('ns-compradora-row');
  if(_nsRow){
    if(clientId === 'nissei'){
      _nsRow.style.display = 'flex';
      var _mIdxNs = {'total':0,'andre':1,'edmar':2};
      var _nsBtns = _nsRow.querySelectorAll('.stab');
      _nsBtns.forEach(function(b){b.classList.remove('active');});
      var _nsCur = (typeof nsComprador!=='undefined'?nsComprador:'total');
      if(_nsBtns[_mIdxNs[_nsCur]]) _nsBtns[_mIdxNs[_nsCur]].classList.add('active');
    } else {
      _nsRow.style.display = 'none';
    }
  }
  
  // Inicializar o cliente se necessário
  // Nota: após upload de Excel, o initialized da sub-chave é deletado,
  // forçando re-render do sub-cliente quando o usuário clicar nele.
  var initKey = 'sellout_' + clientId;
  if(!initialized[initKey]){
    initialized[initKey] = true;
    console.log('[switchSellOutClient] Inicializando:', clientId);
    setTimeout(function(){
      try {
        if(clientId === 'saojoao')    initSJ();
        else if(clientId === 'nissei')   initNissei();
        else if(clientId === 'clamed')   initClamed();
        else if(clientId === 'panvel')   initPanvel();
        else if(clientId === 'ddgam')    initGAM();
        else if(clientId === 'ddgaucha') initGCH();
        else if(clientId === 'ddriomed') initRiomed();
      } catch(e){ console.error('[switchSellOutClient] Erro init', clientId, e); }
    }, 60);
  }
  /* Acumulado FY: renderizar card do cliente ativo */
  if(typeof window._acumTryRender === 'function')
    setTimeout(function(){ window._acumTryRender(clientId, 0); }, 350);
}


function switchClient(id,btn){
  /* Bloqueio de acesso para perfil SCJ */
  if(_loginRole==='scj'){
    /* SCJ vê: apenas Nielsen */
    var scjAllowed = ['nielsen','cpt','3d'];
    if(scjAllowed.indexOf(id)===-1){ showAccessDenied(); return; }
  }
  if(id==='3d'){
    if(_loginUser!=='Giovano' && _loginRole!=='scj'){ return; }
    /* perfil vai no endereço: em file:// a página 3D não consegue ler o login do dashboard */
    var _f3d=document.getElementById('frame-3d'); if(_f3d){ var _s3d=_f3d.getAttribute('data-src')+(_loginRole==='scj'?'?perfil=scj':''); if(_f3d.getAttribute('src')!==_s3d) _f3d.setAttribute('src', _s3d); }
    initialized['3d']=true;
  }
  // Sempre esconder todos os sellout-client-content ao trocar de aba
  document.querySelectorAll('.sellout-client-content').forEach(function(el){el.style.display='none';});
  document.querySelectorAll('.main').forEach(function(p){p.classList.remove('active');});
  document.querySelectorAll('.ctab').forEach(function(b){b.classList.remove('active');});
  var _activePanel = document.getElementById('panel-'+id);
  if(_activePanel) _activePanel.classList.add('active');
  if(btn) btn.classList.add('active');
  activePanel=id;
  // Nielsen theme toggle
  document.body.classList.toggle('nielsen-theme', id==='nielsen');
  // Re-render Nielsen charts when switching to nielsen panel
  if(id==='nielsen'){
    setTimeout(function(){
      if(typeof initNielsenCharts==='function') initNielsenCharts();
      if(typeof renderShrTrend==='function') renderShrTrend();
      if(typeof renderVolMkt==='function') renderVolMkt();
      if(typeof renderDistCard==='function') renderDistCard();
      if(typeof renderMSOSkuJanMar==='function') renderMSOSkuJanMar();
      if(typeof renderSkuShrCard==='function') renderSkuShrCard(); if(typeof renderAreaDecomp==="function")renderAreaDecomp();}, 150);
  }
  // Se voltando para sellout, restaurar o cliente ativo
  if(id==='sellout'){
    var activeEl = document.getElementById('sellout-content-'+activeSelloutClient);
    if(activeEl) activeEl.style.display='block';
    /* Renderizar card acumulado FY do cliente ativo (canvas pode ter 0px enquanto oculto) */
    if(typeof window._acumTryRender === 'function'){
      var _acCl = activeSelloutClient;
      setTimeout(function(){
        requestAnimationFrame(function(){
          requestAnimationFrame(function(){
            window._acumTryRender(_acCl, 0);
          });
        });
      }, 200);
    }
  }
  
  // Se for sellout, inicializar o primeiro cliente (São João)
  if(id === 'sellout' && !initialized[id]){
    initialized[id] = true;
    setTimeout(function(){
      // Inicializar São João como padrão
      initSJ();
    }, 60);
  } else if(id==='cpt'){
    /* Inicializar CPT2 */
    setTimeout(function(){
      if(typeof _cpt2Render === 'function') _cpt2Render();
    }, 80);
  } else if(!initialized[id]){
    initialized[id]=true;
    /* expd precisa de mais tempo para o canvas ganhar dimensões após display:none→block */
    var _delay = 60;
    setTimeout(function(){
      if(id==='saojoao') initSJ();
      else if(id==='ol') initOL();
      else if(id==='nissei') initNissei();
      else if(id==='clamed') initClamed();
      else if(id==='panvel') initPanvel();
      else if(id==='ddgam') initGAM();
      else if(id==='ddgaucha') initGCH();
      else if(id==='ddriomed') initRiomed();
      else if(id==='sellin') initSellin();
      else if(id==='distribuicao') {
        if(typeof window._igRender === 'function') setTimeout(window._igRender, 100);
        if(typeof renderMensalPos === 'function') setTimeout(renderMensalPos, 150);
      }
    }, _delay);
  }
}

function applyFilters(){
  var fc=document.getElementById('filter-count'); if(fc) fc.textContent='Filtro aplicado';
}
function clearFilters(){
  var fa=document.getElementById('f-ano'); if(fa) fa.value='todos';
  var fc=document.getElementById('filter-count'); if(fc) fc.textContent='Exibindo: todos os dados';
}

