/* ── Gradient helpers — global scope ────────────────────────────────────── */
function makeBarGradient(ctx, chartArea, hexColor, alphaTop, alphaBot){
  if(!chartArea) return hexColor;
  var g = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
  var rgb = hexColor.replace('#','');
  var r=parseInt(rgb.slice(0,2),16), gv=parseInt(rgb.slice(2,4),16), b=parseInt(rgb.slice(4,6),16);
  g.addColorStop(0,   'rgba('+r+','+gv+','+b+','+(alphaTop||0.85)+')');
  g.addColorStop(0.5, 'rgba('+r+','+gv+','+b+','+(((alphaTop||0.85)+(alphaBot||0.25))/2)+')');
  g.addColorStop(1,   'rgba('+r+','+gv+','+b+','+(alphaBot||0.25)+')');
  return g;
}
function makeAreaGradient(ctx, chartArea, hexColor){
  if(!chartArea) return 'rgba(245,225,164,0.12)';
  var g = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
  /* Logistics Dark Gold: always gold-tinted fill regardless of brand color */
  g.addColorStop(0,   'rgba(245,225,164,0.40)');
  g.addColorStop(0.55,'rgba(245,225,164,0.12)');
  g.addColorStop(1,   'rgba(245,225,164,0.0)');
  return g;
}

window.addEventListener('load',function(){
  if(document.getElementById('panel-nielsen')&&document.getElementById('panel-nielsen').classList.contains('active')){document.body.classList.add('nielsen-theme');}
  initialized['nielsen']=false;
  // Nielsen is the default active panel -- render all charts after full layout
  requestAnimationFrame(function(){
    setTimeout(function(){
      if(typeof initNielsenCharts==='function') initNielsenCharts();
      if(typeof renderVolMkt==='function') renderVolMkt();
      if(typeof renderDistCard==='function') renderDistCard();
      if(typeof renderShrTrend==='function') renderShrTrend();
      if(typeof renderMSOSkuJanMar==='function') renderMSOSkuJanMar();
      if(typeof renderSkuShrCard==='function') renderSkuShrCard(); if(typeof renderAreaDecomp==="function")renderAreaDecomp();}, 400);
  });
  setTimeout(function(){ if(typeof initOdorBlock==='function') initOdorBlock(); }, 200);
  setTimeout(function(){ if(typeof renderVolMkt==='function'){ renderVolMkt(); setTimeout(function(){ if(window._volLineChart) window._volLineChart.resize(); if(window._volBarChart) window._volBarChart.resize(); }, 300); } }, 2000);
  // Pre-render ED Share cards for all client panels
  setTimeout(function(){
    renderEDShare('São João','sj');
    renderEDShare('Nissei','nissei');
    renderEDShare('Clamed','clamed');
    renderEDShare('Panvel','panvel');
  }, 1000);
});


