/* ═══ SELL IN PASSWORD ═══ */
// Variáveis já declaradas no início

async function sha256(msg){
  var buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(msg));
  return Array.from(new Uint8Array(buf)).map(function(b){return b.toString(16).padStart(2,'0');}).join('');
}

function openSellinPwd(btn){
  console.log('openSellinPwd chamado');
  _sellinPendingBtn = btn;
  var modal = document.getElementById('sellin-pwd-modal');
  if(!modal){
    console.error('Modal não encontrado!');
    return;
  }
  modal.style.display = 'flex';
  var inp = document.getElementById('sellin-pwd-input');
  if(inp){
    inp.value = '';
    setTimeout(function(){ inp.focus(); }, 100);
  }
  var errEl = document.getElementById('sellin-pwd-error');
  if(errEl) errEl.textContent = '';
}

function closeSellinPwd(){
  document.getElementById('sellin-pwd-modal').style.display = 'none';
  _sellinPendingBtn = null;
  document.getElementById('sellin-pwd-input').value = '';
}

function checkSellinPwd(){
  var val = document.getElementById('sellin-pwd-input').value;
  sha256(val).then(function(hash){
    if(hash === _sellinPwdHash){
      _sellinUnlocked = true;
      document.getElementById('sellin-pwd-modal').style.display = 'none';
      if(_sellinPendingBtn) switchClient('sellin', _sellinPendingBtn);
      _sellinPendingBtn = null;
    } else {
      var errEl = document.getElementById('sellin-pwd-error');
      errEl.textContent = '❌ Senha incorreta';
      document.getElementById('sellin-pwd-input').value = '';
      document.getElementById('sellin-pwd-input').focus();
      setTimeout(function(){ errEl.textContent=''; }, 2000);
    }
  });
}

