var sjImpView = 'cluster';
function setSJImpView(v, btn){
  sjImpView = v;
  if(btn && btn.closest){ btn.closest('.toggle-group').querySelectorAll('.tgl').forEach(function(b){b.classList.remove('active','blue');}); btn.classList.add('active','blue'); }
  document.getElementById('sj-imp-cluster').style.display = v==='cluster'?'block':'none';
  document.getElementById('sj-imp-tamanho').style.display = v==='tamanho'?'block':'none';
  if(v==='cluster') renderSJImpCluster(); else renderSJImpTamanho();
}
﻿function buildSJImpTable(data, keyField, colors){
  var totalFevFat = data.reduce(function(s,r){return s+(r.fev_fat||0);},0)||1;
  var totalMarFat = data.reduce(function(s,r){return s+(r.mar_fat||0);},0)||1;
  var totalAbrFat = data.reduce(function(s,r){return s+(r.abr_fat||0);},0)||1;
  var totalMaiFat = data.reduce(function(s,r){return s+(r.mai_fat||0);},0)||1;
  var totalJunFat = data.reduce(function(s,r){return s+(r.jun_fat||0);},0)||1;
  var h = '<table style="width:100%;border-collapse:collapse;font-size:11px;">';
  h += '<thead><tr style="border-bottom:0.5px solid rgba(255,255,255,0.13);">';
  h += '<th style="text-align:left;padding:8px;color:#94A3B8;font-size:9px;font-weight:700;letter-spacing:0.06em;">'+keyField.toUpperCase()+'</th>';
  h += '<th style="text-align:center;padding:8px;color:#94A3B8;font-size:9px;font-weight:700;">LOJAS</th>';
  h += '<th style="text-align:center;padding:8px;color:#94A3B8;font-size:9px;font-weight:700;">% LOJAS</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fbbf24;font-size:9px;font-weight:700;">FAT Fev/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fbbf24;font-size:9px;font-weight:700;">VOL Fev/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fbbf24;font-size:9px;font-weight:700;">% Fat Fev</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fb923c;font-size:9px;font-weight:700;">FAT Mar/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fb923c;font-size:9px;font-weight:700;">VOL Mar/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#fb923c;font-size:9px;font-weight:700;">% Fat Mar</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#34d399;font-size:9px;font-weight:700;">FAT Abr/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#34d399;font-size:9px;font-weight:700;">VOL Abr/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#34d399;font-size:9px;font-weight:700;">% Fat Abr</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#60a5fa;font-size:9px;font-weight:700;">FAT Mai/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#60a5fa;font-size:9px;font-weight:700;">VOL Mai/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#60a5fa;font-size:9px;font-weight:700;">% Fat Mai</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#a78bfa;font-size:9px;font-weight:700;">FAT Jun/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#a78bfa;font-size:9px;font-weight:700;">VOL Jun/26</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#a78bfa;font-size:9px;font-weight:700;">% Fat Jun</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#D1D5DB;font-size:9px;font-weight:700;">M&#233;d/Loja Fev</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#D1D5DB;font-size:9px;font-weight:700;">M&#233;d/Loja Mar</th>';
  h += '<th style="text-align:right;padding:6px 8px;color:#D1D5DB;font-size:9px;font-weight:700;">M&#233;d/Loja Jun</th>';
  h += '</tr></thead><tbody>';
  data.forEach(function(r, i){
    var key = r[keyField==='cluster'?'cl':'tam'];
    var cor = colors[i % colors.length];
    var barW = Math.min(100, Math.round((r.fev_fat)/totalFevFat*100));
    var fmt = function(v){ return Math.round(v||0).toLocaleString('pt-BR'); };
    h += '<tr class="u-row-sep">';
    h += '<td style="padding:8px;"><div style="display:flex;align-items:center;gap:8px;">';
    h += '<div style="width:8px;height:8px;border-radius:2px;background:'+cor+';flex-shrink:0;"></div>';
    h += '<span style="font-weight:700;color:#D1D5DB;">'+key+'</span>';
    h += '<div style="flex:1;max-width:60px;height:3px;background:rgba(255,255,255,0.09);border-radius:2px;overflow:hidden;"><div style="height:100%;width:'+barW+'%;background:'+cor+';border-radius:2px;"></div></div>';
    h += '</div></td>';
    h += '<td style="padding:8px;text-align:center;color:#D1D5DB;font-weight:600;">'+r.lojas+'</td>';
    h += '<td style="padding:8px;text-align:center;color:#D1D5DB;">'+r.pct_lojas+'%</td>';
    // Fev
    h += '<td style="padding:6px 8px;text-align:right;color:#fbbf24;font-weight:600;">R$ '+fmt(r.fev_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#fbbf24;">'+fmt(r.fev_vol)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;"><span style="font-size:10px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:2px 5px;">'+r.pct_fev_fat+'%</span></td>';
    // Mar
    h += '<td style="padding:6px 8px;text-align:right;color:#fb923c;font-weight:600;">R$ '+fmt(r.mar_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#fb923c;">'+fmt(r.mar_vol)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;"><span style="font-size:10px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:2px 5px;">'+r.pct_mar_fat+'%</span></td>';
    // Abr
    h += '<td style="padding:6px 8px;text-align:right;color:#34d399;font-weight:600;">R$ '+fmt(r.abr_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#34d399;">'+fmt(r.abr_vol)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;"><span style="font-size:10px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:2px 5px;">'+(r.pct_abr_fat||0)+'%</span></td>';
    // Mai
    h += '<td style="padding:6px 8px;text-align:right;color:#60a5fa;font-weight:600;">R$ '+fmt(r.mai_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#60a5fa;">'+fmt(r.mai_vol)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;"><span style="font-size:10px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:2px 5px;">'+(r.pct_mai_fat||0)+'%</span></td>';
    // Jun
    h += '<td style="padding:6px 8px;text-align:right;color:#a78bfa;font-weight:600;">R$ '+fmt(r.jun_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#a78bfa;">'+fmt(r.jun_vol)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;"><span style="font-size:10px;font-weight:700;background:'+cor+'22;color:'+cor+';border-radius:3px;padding:2px 5px;">'+(r.pct_jun_fat||0)+'%</span></td>';
    // Medias
    h += '<td style="padding:6px 8px;text-align:right;color:#D1D5DB;">R$ '+fmt(r.med_fev_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#D1D5DB;">R$ '+fmt(r.med_mar_fat)+'</td>';
    h += '<td style="padding:6px 8px;text-align:right;color:#a78bfa;">R$ '+fmt(r.med_jun_fat)+'</td>';
    h += '</tr>';
  });
  h += '</tbody></table>';
  return h;
}

