// ═══ ANIMATED COUNTER ═══
function animateCounter(el, target, prefix, suffix, duration){
  var startTime = null;
  var str = String(target).trim();

  // ── Detect magnitude suffix BEFORE stripping non-numerics ──
  var hasM  = /M$/i.test(str);
  var hasB  = /B$/i.test(str);
  var hasK  = /K$/i.test(str);
  var hasUn = /\s*un$/i.test(str);          // "49.072 un" style

  // Detect currency prefix (R$) embedded in the value string
  var hasCurrency = /R\$/.test(str);

  // Parse: strip everything except digits, comma, dot
  // Handle pt-BR thousands separator: if str has format like "284.382" (no comma)
  // treat the dot as thousands separator → remove it before parsing
  var numStr = str.replace(/[^0-9.,]/g, '');
  // If only dots (no comma), dots are thousands separators in pt-BR
  if(numStr.indexOf(',') === -1 && (numStr.match(/\./g)||[]).length === 1){
    // single dot → could be decimal (e.g. "38.25") or thousands ("1.200")
    // If the decimal part has exactly 3 digits, treat as thousands separator
    var afterDot = numStr.split('.')[1] || '';
    if(afterDot.length === 3) numStr = numStr.replace('.','');
  } else if(numStr.indexOf(',') === -1 && (numStr.match(/\./g)||[]).length > 1){
    // multiple dots → all thousands separators
    numStr = numStr.replace(/\./g,'');
  } else {
    // Has comma: comma is decimal separator, dots are thousands
    numStr = numStr.replace(/\./g,'').replace(',','.');
  }

  var raw = parseFloat(numStr);
  if(isNaN(raw)){ el.textContent = prefix + target + suffix; return; }

  // Restore magnitude lost when suffix was stripped
  if(hasM)     raw *= 1000000;
  else if(hasB) raw *= 1000000000;
  else if(hasK) raw *= 1000;

  var isFloat = (raw % 1 !== 0) && !hasM && !hasK && !hasB;

  function step(ts){
    if(!startTime) startTime = ts;
    var progress = Math.min((ts - startTime) / duration, 1);
    var ease = 1 - Math.pow(1 - progress, 3); // easeOutCubic
    var current = raw * ease;

    var formatted;
    if(hasM || raw >= 1000000){
      // Format as millions with comma decimal separator (pt-BR)
      var mVal = (current / 1000000).toFixed(2).replace('.', ',');
      formatted = (hasCurrency ? 'R$ ' : '') + mVal + 'M';
    } else if(hasK){
      // Keep K suffix with correct rounding
      formatted = (hasCurrency ? 'R$ ' : '') + Math.round(current / 1000) + 'K';
    } else if(hasUn){
      formatted = Math.round(current).toLocaleString('pt-BR') + ' un';
    } else if(raw >= 1000){
      formatted = (hasCurrency ? 'R$ ' : '') + Math.round(current).toLocaleString('pt-BR');
    } else if(isFloat){
      formatted = (hasCurrency ? 'R$ ' : '') + current.toFixed(2).replace('.', ',');
    } else {
      formatted = Math.round(current).toLocaleString('pt-BR');
    }
    el.textContent = prefix + formatted + suffix;
    if(progress < 1) requestAnimationFrame(step);
    else el.classList.remove('animating');
  }
  el.classList.add('animating');
  requestAnimationFrame(step);
}

function renderKPIsAnimated(containerId, kpis){
  var container = document.getElementById(containerId);
  if(!container) return;
  container.innerHTML = kpis.map(function(k){
    var deltaClass = k.deltaUp ? 'delta-up' : 'delta-down';
    var deltaStyle = !k.deltaUp ? ' style="background:rgba(239,68,68,0.12);color:#ef4444;font-weight:700;"' : '';
    var delta = k.delta ? '<div class="kpi-delta '+deltaClass+'"'+deltaStyle+'>'+k.delta+'</div>' : '';
    var spark = (k.spark && typeof makeSparkline === 'function') ? '<div style="position:absolute;bottom:8px;right:10px;opacity:0.6;pointer-events:none;">'+makeSparkline(k.spark,k.color,76,30)+'</div>' : '';
    return '<div class="kpi-cell" style="--accent:'+k.color+';position:relative;">'+spark+
      '<div class="kpi-tag">'+k.label+'</div>' +
      '<div class="kpi-val" data-val="'+k.val+'" data-prefix="" data-suffix="">'+k.val+'</div>' +
      '<div class="kpi-sub">'+k.sub+'</div>' + delta +
      '</div>';
  }).join('');

  // Animate after a short delay
  setTimeout(function(){
    container.querySelectorAll('.kpi-val').forEach(function(el){
      var raw = el.dataset.val;
      animateCounter(el, raw, '', '', 1200);
    });
  }, 100);
}

// Override renderKPIs with animated version
var _origRenderKPIs = renderKPIs;
function makeSparkline(data, color, W, H){
  W = W||80; H = H||30;
  var vals = (data||[]).filter(function(v){return v!=null&&v>0;});
  if(vals.length < 2) return '';
  var mn=Math.min.apply(null,vals), mx=Math.max.apply(null,vals);
  var rng = mx - mn || 1;
  var pts = vals.map(function(v,i){
    var x = (i/(vals.length-1))*W;
    var y = H - ((v-mn)/rng)*(H-4) - 2;
    return x.toFixed(1)+','+y.toFixed(1);
  }).join(' ');
  var lx = W, ly = (H - ((vals[vals.length-1]-mn)/rng)*(H-4) - 2).toFixed(1);
  var rgb = color.replace('#','');
  var r=parseInt(rgb.slice(0,2),16), g=parseInt(rgb.slice(2,4),16), b=parseInt(rgb.slice(4,6),16);
  return '<svg width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" style="overflow:visible;" xmlns="http://www.w3.org/2000/svg">'
    +'<defs><linearGradient id="sg'+r+g+b+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.35"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.0"/>'
    +'</linearGradient></defs>'
    +'<polygon points="0,'+H+' '+pts+' '+W+','+H+'" fill="url(#sg'+r+g+b+')" opacity="0.7"/>'
    +'<polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" opacity="0.85"/>'
    +'<circle cx="'+lx+'" cy="'+ly+'" r="2.5" fill="'+color+'" opacity="1"/>'
    +'</svg>';
}

function renderKPIs(containerId, kpis){
  renderKPIsAnimated(containerId, kpis);
}
// ═══ END ANIMATED COUNTER ═══

